def _derive_resolve_resolution_mode(
    *,
    selected_delegate_public_id: str,
    responding_delegate_public_id: str,
    fanout_after: datetime,
    resolved_at: datetime,
) -> str:
    """Derive ``resolution_mode`` for the resolve transition.

    Enum resolution rules:

    - selected==responding before ``fanout_after`` -> ``pick_one_primary``.
    - selected==responding at or after ``fanout_after`` ->
      ``secondary_after_fanout``.
    - selected!=responding -> ``fanout_first_responder``. The submit layer
      admits this path only at or after ``fanout_after``.

    Lives at the repository module level (not on a service or enum
    class) so the resolve primitive can derive it INSIDE its own
    SELECT-FOR-UPDATE transaction from the immutable fanout timestamp
    and actual responder. This remains honest when a delegate resolves
    exactly as the window opens but before the scanner's status CAS.
    """
    if responding_delegate_public_id != selected_delegate_public_id:
        return "fanout_first_responder"
    if resolved_at < fanout_after:
        return "pick_one_primary"
    return "secondary_after_fanout"


_SQLITE_CONNECT_PRAGMAS: tuple[str, ...] = (
    "PRAGMA foreign_keys=ON",
    "PRAGMA recursive_triggers=ON",
    "PRAGMA journal_mode=WAL",
    "PRAGMA synchronous=NORMAL",
    "PRAGMA busy_timeout=30000",
    "PRAGMA temp_store=MEMORY",
    "PRAGMA cache_size=-65536",
    "PRAGMA wal_autocheckpoint=4000",
    "PRAGMA mmap_size=268435456",
)
"""Per-connection SQLite PRAGMAs for safe writer throughput.

Tuned 2026-05-15 against the live publisher workload. The
"mainstream defaults" alone (``foreign_keys`` / WAL /
``synchronous=NORMAL`` / ``busy_timeout``) give ~50% drop-rate
reduction but the cache + WAL checkpoint + mmap knobs are needed
for another ~50% to land at the ~1250 writes/sec ceiling. Pulling
the tuning out cut DB throughput from ~1258/sec back to ~446/sec
under identical load — measurable regression on the same hardware
the operator actually runs on, so we keep the full pack.

* ``foreign_keys=ON`` — application-level FK enforcement
  (mainstream; SQLite default is OFF).
* ``recursive_triggers=ON`` — SQLite fires a ``BEFORE DELETE``
  trigger on the delete that ``INSERT OR REPLACE`` (``REPLACE
  INTO``) performs to resolve a unique-constraint conflict ONLY
  when this is ON; the default is OFF. Without it a ``REPLACE INTO
  executions`` would physically delete a sealed row and substitute
  a different fill at the same ``scope_sequence`` WITHOUT firing
  ``executions_reject_delete``, silently bypassing the append-only
  ledger. Enabling it closes that vector so REPLACE is rejected on
  every app connection. This is a correctness invariant, not a
  throughput knob, and the ledger's own ingest never uses REPLACE.
* ``journal_mode=WAL`` — concurrent readers + faster commits.
* ``synchronous=NORMAL`` — standard WAL durability tradeoff;
  may lose the most recent committed transactions on host power
  loss, acceptable for live market data (ZMQ feed is the durable
  record + the publisher already accepts drop-oldest at the queue
  level).
* ``busy_timeout=30000`` — wait up to 30s on writer-lock
  contention before raising; prevents transient ``SQLITE_BUSY``
  retries from cascading into writer drops.
* ``temp_store=MEMORY`` — keep CTE / sort intermediates off disk.
* ``cache_size=-65536`` — 64 MB page cache; matches working-set
  size of the publisher / read-paths.
* ``wal_autocheckpoint=4000`` — let WAL grow to ~4 MB before the
  next automatic checkpoint, batching fsyncs at the WAL boundary
  instead of every commit.
* ``mmap_size=268435456`` — 256 MB mmap region for the main DB
  file; SQLite reads served from mmap avoid one userspace copy
  per page on cold reads."""


def _register_sqlite_fk_pragma(engine: Any) -> None:
    """Register per-connection SQLite PRAGMAs for foreign keys + write tuning.

    SQLite disables foreign-key enforcement by default; this event
    listener also applies the wider :data:`_SQLITE_CONNECT_PRAGMAS`
    pack (WAL + ``synchronous=NORMAL`` + cache/mmap sizing) on every
    new connection. WAL is sticky on the DB file so re-applying is a
    no-op after the first connection; ``synchronous`` and the cache
    pragmas are per-connection so the listener must fire on every
    new aiosqlite handle.

    Function name kept for backward compatibility with existing call
    sites + tests; the wider pragma surface is intentional.

    Args:
        engine: Sync or async-sync SQLAlchemy engine to register on.
    """
    if not isinstance(engine, SyncEngine):
        return

    @event.listens_for(engine, "connect")
    def _set_sqlite_pragmas(dbapi_connection: Any, _connection_record: Any) -> None:
        driver_connection = getattr(dbapi_connection, "driver_connection", None)
        if driver_connection is not None and hasattr(driver_connection, "close"):
            _live_aiosqlite_connections[id(driver_connection)] = cast(
                _ClosableConnection, driver_connection
            )
        cursor = dbapi_connection.cursor()
        try:
            for pragma in _SQLITE_CONNECT_PRAGMAS:
                cursor.execute(pragma)
        finally:
            cursor.close()

    @event.listens_for(engine, "close")
    def _forget_sqlite_connection(dbapi_connection: Any, _connection_record: Any) -> None:
        driver_connection = getattr(dbapi_connection, "driver_connection", None)
        if driver_connection is not None:
            _live_aiosqlite_connections.pop(id(driver_connection), None)


class SQLAlchemyRepository(Repository):
    """Async SQLAlchemy repository for SQLite and PostgreSQL.

    Uses SQLAlchemy 2.0 async engine with appropriate connection pooling:
        - SQLite: NullPool or StaticPool for in-memory databases.
        - PostgreSQL: Default pool settings.

    Supports dialect-specific upsert operations with ON CONFLICT handling.

    Attributes:
        db_url: Database connection URL.
        engine: Async SQLAlchemy engine.
        session_factory: Async session factory.
    """

    def __init__(self, db_url: str) -> None:
        """Initialize repository with database URL.

        Pool selection:

        * ``:memory:`` SQLite — :class:`StaticPool`. The single in-memory
          DB instance MUST be shared across every connection or each
          new connection sees an empty schema; ``StaticPool`` reuses
          one connection for the engine's lifetime.
        * File-backed SQLite — SQLAlchemy's default
          :class:`AsyncAdaptedQueuePool`. Earlier revisions forced
          :class:`NullPool` here on the theory that aiosqlite
          serialises writes anyway, but profiling showed the per-commit
          connection release-and-reacquire churn against
          ``NullPool`` dominated publisher CPU. The default queue
          pool keeps connections alive across ``session.commit()``
          which is enough on its own to amortise per-flush cost.
        * Postgres + any other dialect — SQLAlchemy default pool.

        ``pool_pre_ping=True`` is set unconditionally so checkouts issue a
        cheap liveness check before handing a connection to the caller.
        Without it, every connection acquired before a Postgres restart
        (e.g. unattended-upgrades on the host) stays in the pool as a
        dead handle and surfaces as ``Errno 111 / Connection refused``
        cascades on every flush until the process is recreated. The pre-
        ping cost (~one ``SELECT 1`` per checkout) is well under the
        per-flush WAL fsync cost we already pay, so it is invisible on
        the publisher hot path. ``pool_recycle=3600`` is the safety net
        for stale TCP sessions and intermediate firewall idle-out — one
        hour is well below typical conntrack timeouts but long enough
        that the recycle is not load-bearing on a hot system.

        ``StaticPool`` is **not** appropriate for file-backed SQLite
        in this codebase because every test worker spawns multiple
        repositories against the same file and they must each open
        their own connection.

        Args:
            db_url: SQLAlchemy async database URL
                (e.g., 'sqlite+aiosqlite:///./data/db.sqlite').
        """
        self.db_url = db_url
        connect_args: dict[str, Any] = {}
        engine_kwargs: dict[str, Any] = {
            "future": True,
            "pool_pre_ping": True,
            "pool_recycle": 3600,
        }
        if "sqlite" in db_url:
            connect_args = {
                "timeout": 30,
                "check_same_thread": False,
            }
            if ":memory:" in db_url:
                engine_kwargs["poolclass"] = StaticPool
        elif "postgresql" in db_url:
            connect_args["server_settings"] = {"timezone": "UTC"}
            pool_size = os.getenv(_DB_POOL_SIZE_ENV)
            if pool_size is not None:
                engine_kwargs["pool_size"] = int(pool_size)
            max_overflow = os.getenv(_DB_MAX_OVERFLOW_ENV)
            if max_overflow is not None:
                engine_kwargs["max_overflow"] = int(max_overflow)
        self.engine: AsyncEngine = create_async_engine(
            db_url, connect_args=connect_args, **engine_kwargs
        )
        if "sqlite" in db_url:
            _register_sqlite_fk_pragma(self.engine.sync_engine)
        self.session_factory = async_sessionmaker(
            self.engine, expire_on_commit=False, class_=AsyncSession
        )
        self._portfolio_reconciliation_locks: dict[tuple[str, str, str], asyncio.Lock] = {}
        self._spot_asset_precision_evidence_locks: dict[tuple[str, str], asyncio.Lock] = {}
        _live_sqlalchemy_repositories.add(self)
        with suppress(TypeError):
            _live_sqlalchemy_engines.add(self.engine)

    async def create_all(self) -> None:
        """Create all database tables from model metadata."""
        async with self.engine.begin() as conn:
            await conn.run_sync(Base.metadata.create_all)

    @property
    def dialect_name(self) -> str:
        """Return the database dialect name."""
        return self.engine.url.get_dialect().name

    @asynccontextmanager
    async def session(self) -> AsyncIterator[AsyncSession]:
        """Provide async session with automatic rollback on error."""
        session_or_context = self.session_factory()
        if isinstance(session_or_context, AsyncSession):
            session = session_or_context
            try:
                yield session
            except GeneratorExit:
                pass
            except Exception:
                await session.rollback()
                raise
            finally:
                await session.close()
            return
        session_context = cast(AbstractAsyncContextManager[AsyncSession], session_or_context)
        async with session_context as session:
            try:
                yield session
            except GeneratorExit:
                pass
            except Exception:
                await session.rollback()
                raise

    async def get_latest_candle_ids(
        self, as_of: datetime
    ) -> dict[tuple[str, str], tuple[datetime, str]]:
        """Load the latest recent candle public_id per (instrument, timeframe).

        Bounded to candles with ``open_at`` newer than ``_CANDLE_ID_CACHE_LOOKBACK``
        before ``as_of`` so the lookup rides ``ix_candle_instrument_open`` instead
        of scanning the full candles table. See the abstract method for the full
        contract and why omitting older series is safe.
        """
        now = as_of
        open_at_floor = now - _CANDLE_ID_CACHE_LOOKBACK
        async with self.session() as s:
            latest = (
                select(
                    Candle.instrument_public_id,
                    Candle.timeframe,
                    func.max(Candle.open_at).label("max_open_at"),
                )
                .where(
                    Candle.timestamp <= now,
                    Candle.known_to > now,
                    Candle.open_at > open_at_floor,
                )
                .group_by(Candle.instrument_public_id, Candle.timeframe)
                .subquery()
            )
            q = await s.execute(
                select(
                    Candle.instrument_public_id,
                    Candle.timeframe,
                    Candle.open_at,
                    Candle.public_id,
                )
                .where(
                    Candle.timestamp <= now,
                    Candle.known_to > now,
                    Candle.open_at > open_at_floor,
                )
                .join(
                    latest,
                    and_(
                        Candle.instrument_public_id == latest.c.instrument_public_id,
                        Candle.timeframe == latest.c.timeframe,
                        Candle.open_at == latest.c.max_open_at,
                    ),
                )
            )
            return {
                (row.instrument_public_id, row.timeframe): (row.open_at, row.public_id)
                for row in q.all()
            }

    async def ensure_instrument(
        self,
        symbol_public_id: str,
        exchange: str,
        session_id: str,
        sequence_id: int,
        timestamp: datetime,
        source_exchange: str | None = None,
    ) -> tuple[int, str]:
        """Idempotent resolve-or-create for instrument identity.

        Looks up the active Instrument by business key
        (symbol_public_id, exchange) as of *timestamp*.  Returns
        (id, public_id) of the existing row, or inserts a new one
        if none exists.

        ``source_exchange`` (PnL Phase 1 identity mapping) is authored
        by the source-bound paper publisher: when supplied and DIFFERENT
        from the active row's value, the row is revised via SCD2
        close-and-insert under a ``FOR UPDATE`` row lock — same
        ``public_id``, ``requires_ai_review`` preserved, and a
        non-inverting effective timestamp
        (``max(timestamp, existing.timestamp)``). ``None`` NEVER clears
        an existing mapping (callers that don't know the source must
        not erase it).

        The lookup targets the CURRENT active row
        (``known_to == KNOWN_TO_MAX``, clock-free): a caller clock
        lagging a future-stamped current version must still find it —
        an as-of miss here would insert a duplicate active row. After
        an insert race the winner is re-read the same way and, when the
        caller supplied a mapping the winner lacks, reconciled via a
        recursive revision pass so the requested mapping is never
        silently dropped.
        """
        bus_time = timestamp
        async with self.session() as s:
            q = await s.execute(
                select(Instrument)
                .where(
                    Instrument.symbol_public_id == symbol_public_id,
                    Instrument.exchange == exchange,
                    Instrument.known_to == KNOWN_TO_MAX,
                )
                .with_for_update()
            )
            inst = q.scalar_one_or_none()
            if inst is not None:
                if source_exchange is None or inst.source_exchange == source_exchange:
                    return (int(inst.id), str(inst.public_id))
                return await self._revise_instrument_source(
                    s, inst, source_exchange, session_id, sequence_id, bus_time
                )
            new_inst = Instrument(
                symbol_public_id=symbol_public_id,
                exchange=exchange,
                source_exchange=source_exchange,
                session_id=session_id,
                sequence_id=sequence_id,
                timestamp=bus_time,
            )
            s.add(new_inst)
            try:
                await s.commit()
            except IntegrityError as exc:
                await s.rollback()
                q2 = await s.execute(
                    select(Instrument)
                    .where(
                        Instrument.symbol_public_id == symbol_public_id,
                        Instrument.exchange == exchange,
                        Instrument.known_to == KNOWN_TO_MAX,
                    )
                    .with_for_update()
                )
                inst = q2.scalar_one_or_none()
                if inst is None:
                    raise exc
                if source_exchange is not None and inst.source_exchange != source_exchange:
                    return await self._revise_instrument_source(
                        s, inst, source_exchange, session_id, sequence_id, bus_time
                    )
                return (int(inst.id), str(inst.public_id))
            await s.refresh(new_inst)
            return (int(new_inst.id), str(new_inst.public_id))

    @staticmethod
    async def _revise_instrument_source(
        s: AsyncSession,
        inst: Instrument,
        source_exchange: str,
        session_id: str,
        sequence_id: int,
        bus_time: datetime,
    ) -> tuple[int, str]:
        """SCD2-revise an instrument's source mapping (locked row).

        Shared by the direct revision path and the insert-race
        reconcile in :meth:`ensure_instrument` so a concurrent
        source-less winner never silently drops the requested mapping.
        Preserves ``requires_ai_review`` and clamps the effective
        timestamp to ``max(bus_time, inst.timestamp)``.

        Args:
            s: Open session holding the row lock.
            inst: The active row being revised.
            source_exchange: The mapping to author.
            session_id: Bus session for the successor.
            sequence_id: Bus sequence for the successor.
            bus_time: Caller bus timestamp.

        Returns:
            ``(successor_id, public_id)``.
        """
        effective_ts = max(bus_time, inst.timestamp)
        await s.execute(
            update(Instrument).where(Instrument.id == inst.id).values(known_to=effective_ts)
        )
        revised = Instrument(
            public_id=inst.public_id,
            symbol_public_id=inst.symbol_public_id,
            exchange=inst.exchange,
            requires_ai_review=inst.requires_ai_review,
            source_exchange=source_exchange,
            session_id=session_id,
            sequence_id=sequence_id,
            timestamp=effective_ts,
        )
        s.add(revised)
        await s.flush()
        revised_id = revised.id
        await s.commit()
        return (int(revised_id), str(inst.public_id))

    async def resolve_source_instrument_public_id(
        self, instrument_public_id: str
    ) -> InstrumentSourceResolution:
        """Map a paper instrument's identity to its SOURCE instrument.

        Clock-free reads (``known_to == KNOWN_TO_MAX``) — see the
        abstract contract for the rationale.

        Args:
            instrument_public_id: Emission-side instrument identity.

        Returns:
            An :class:`InstrumentSourceResolution` — see the abstract
            contract for the field semantics.
        """
        async with self.session() as s:
            row = (
                await s.execute(
                    select(
                        Instrument.symbol_public_id,
                        Instrument.exchange,
                        Instrument.source_exchange,
                    ).where(
                        Instrument.public_id == instrument_public_id,
                        Instrument.known_to == KNOWN_TO_MAX,
                    )
                )
            ).one_or_none()
            if row is None:
                return {
                    "valuation_public_id": instrument_public_id,
                    "is_paper": False,
                    "mapped": False,
                }
            symbol_public_id, exchange, source_exchange = row
            is_paper = exchange == ExchangeEnum.PAPER.value
            if not is_paper or source_exchange is None:
                return {
                    "valuation_public_id": instrument_public_id,
                    "is_paper": is_paper,
                    "mapped": False,
                }
            source_pid = (
                await s.execute(
                    select(Instrument.public_id).where(
                        Instrument.symbol_public_id == symbol_public_id,
                        Instrument.exchange == source_exchange,
                        Instrument.known_to == KNOWN_TO_MAX,
                    )
                )
            ).scalar_one_or_none()
            if source_pid is None:
                return {
                    "valuation_public_id": instrument_public_id,
                    "is_paper": True,
                    "mapped": False,
                }
            return {
                "valuation_public_id": source_pid,
                "is_paper": True,
                "mapped": True,
            }

    async def get_fill_venue_events_for_order_identity(
        self,
        client_order_id: str,
        wallet_public_id: str,
        mode: str,
        exchange: str,
        exchange_order_id: str | None,
    ) -> list[VenueEventRow]:
        """Read an order's durable fill rows scoped by STABLE identity.

        Args:
            client_order_id: Order correlation id.
            wallet_public_id: Owning wallet (identity scope).
            mode: Execution mode (identity scope).
            exchange: Venue discriminator (identity scope).
            exchange_order_id: Venue order id when known — rows with a
                DIFFERENT id are excluded, id-less rows still count.

        Returns:
            Id-ordered ``fill_observed`` rows; empty when none exist.
        """
        filters = [
            VenueEvent.event_type == "fill_observed",
            VenueEvent.client_order_id == client_order_id,
            VenueEvent.wallet_public_id == wallet_public_id,
            VenueEvent.mode == mode,
            VenueEvent.exchange == exchange,
        ]
        if exchange_order_id is not None:
            filters.append(
                or_(
                    VenueEvent.exchange_order_id.is_(None),
                    VenueEvent.exchange_order_id == exchange_order_id,
                )
            )
        async with self.session() as s:
            result = await s.execute(
                select(VenueEvent).where(*filters).order_by(VenueEvent.id.asc())
            )
            return [self._venue_event_to_row(ve) for ve in result.scalars().all()]

    async def get_active_instrument_quote_currency(self, instrument_public_id: str) -> str | None:
        """Read the CURRENT quote currency for an instrument (clock-free).

        Args:
            instrument_public_id: Instrument identity to resolve.

        Returns:
            The quote currency code, or ``None`` when no active
            instrument/symbol pair exists.
        """
        async with self.session() as s:
            result = await s.execute(
                select(Symbol.quote)
                .join(Instrument, Instrument.symbol_public_id == Symbol.public_id)
                .where(
                    Instrument.public_id == instrument_public_id,
                    Instrument.known_to == KNOWN_TO_MAX,
                    Symbol.known_to == KNOWN_TO_MAX,
                )
            )
            return result.scalar_one_or_none()

    async def get_active_market_snapshot_price(
        self, instrument_public_id: str
    ) -> tuple[float | None, datetime] | None:
        """Read the CURRENT market-snapshot price row (clock-free).

        Args:
            instrument_public_id: Instrument identity to resolve.

        Returns:
            ``(last_price, snapshot_timestamp)`` of the active row, or
            ``None`` when no active row exists.
        """
        async with self.session() as s:
            result = await s.execute(
                select(MarketSnapshot.last_price, MarketSnapshot.timestamp).where(
                    MarketSnapshot.instrument_public_id == instrument_public_id,
                    MarketSnapshot.known_to == KNOWN_TO_MAX,
                )
            )
            row = result.one_or_none()
            if row is None:
                return None
            return (row.last_price, row.timestamp)

    async def revise_instrument(
        self,
        instrument_public_id: str,
        symbol_public_id: str,
        exchange: str,
        session_id: str,
        sequence_id: int,
        timestamp: datetime,
    ) -> int:
        """SCD2 close+insert for instrument business attributes.

        The successor carries ``requires_ai_review`` verbatim and keeps
        ``source_exchange`` when the destination exchange stays paper
        (a re-key away from paper must clear it — the CHECK constrains
        the mapping to paper rows).

        Raises ValueError when no active version exists or when the
        target business key is already occupied by another instrument.
        """
        async with self.session() as s:
            ts_filter, kt_filter = where_active(Instrument, timestamp)
            q = await s.execute(
                select(Instrument).where(
                    Instrument.public_id == instrument_public_id,
                    ts_filter,
                    kt_filter,
                )
            )
            inst = q.scalar_one_or_none()
            if inst is None:
                raise ValueError(f"No active Instrument with public_id={instrument_public_id}")
            if inst.symbol_public_id == symbol_public_id and inst.exchange == exchange:
                return int(inst.id)
            conflict_q = await s.execute(
                select(Instrument).where(
                    Instrument.symbol_public_id == symbol_public_id,
                    Instrument.exchange == exchange,
                    ts_filter,
                    kt_filter,
                )
            )
            conflict = conflict_q.scalar_one_or_none()
            if conflict is not None and conflict.public_id != instrument_public_id:
                raise ValueError(
                    f"Business key ({symbol_public_id}, {exchange}) "
                    f"already occupied by instrument {conflict.public_id}"
                )
            carried_source = inst.source_exchange if exchange == ExchangeEnum.PAPER.value else None
            new_row = await close_and_insert(
                s,
                Instrument,
                [Instrument.public_id == instrument_public_id],
                {
                    "symbol_public_id": symbol_public_id,
                    "exchange": exchange,
                    "requires_ai_review": inst.requires_ai_review,
                    "source_exchange": carried_source,
                    "session_id": session_id,
                    "sequence_id": sequence_id,
                },
                timestamp,
            )
            await s.commit()
            await s.refresh(new_row)
            return int(new_row.id)

    async def revise_instrument_spec(
        self,
        instrument_public_id: str,
        session_id: str,
        sequence_id: int,
        timestamp: datetime,
        spec: InstrumentSpecInput,
    ) -> int:
        """SCD2 close+insert for instrument trading specifications."""
        payload = asdict(spec)
        async with self.session() as s:
            ts_filter, kt_filter = where_active(InstrumentSpec, timestamp)
            q = await s.execute(
                select(InstrumentSpec).where(
                    InstrumentSpec.instrument_public_id == instrument_public_id,
                    ts_filter,
                    kt_filter,
                )
            )
            existing_spec = q.scalar_one_or_none()
            if existing_spec is not None:
                same = all(getattr(existing_spec, k) == v for k, v in payload.items())
                if same:
                    return int(existing_spec.id)
            new_values = {
                "instrument_public_id": instrument_public_id,
                "session_id": session_id,
                "sequence_id": sequence_id,
                **payload,
            }
            new_row = await close_and_insert(
                s,
                InstrumentSpec,
                [InstrumentSpec.instrument_public_id == instrument_public_id],
                new_values,
                timestamp,
            )
            await s.commit()
            await s.refresh(new_row)
            return int(new_row.id)

    async def get_instrument_spec(
        self,
        instrument_public_id: str,
        as_of: datetime,
    ) -> InstrumentSpecRow | None:
        """Return the active InstrumentSpec for an instrument, or None."""
        async with self.session() as s:
            ts_filter, kt_filter = where_active(InstrumentSpec, as_of)
            q = await s.execute(
                select(InstrumentSpec).where(
                    InstrumentSpec.instrument_public_id == instrument_public_id,
                    ts_filter,
                    kt_filter,
                )
            )
            row = q.scalar_one_or_none()
            if row is None:
                return None
            return InstrumentSpecRow(
                instrument_public_id=row.instrument_public_id,
                tick_size=row.tick_size,
                lot_size=row.lot_size,
                min_order_size=row.min_order_size,
                max_order_size=row.max_order_size,
                cost_decimals=row.cost_decimals,
                qty_decimals=row.qty_decimals,
                margin_initial=row.margin_initial,
                position_limit_long=row.position_limit_long,
                position_limit_short=row.position_limit_short,
                status=row.status,
                contract_size=row.contract_size,
                quantity_unit=row.quantity_unit,
                spec_source=row.spec_source,
                spec_version=row.spec_version,
                spec_observed_at=row.spec_observed_at,
                unit_certified=row.unit_certified,
                expiry_at=row.expiry_at,
                instrument_kind=row.instrument_kind,
                funding_type=row.funding_type,
                funding_frequency_hours=row.funding_frequency_hours,
                rollover_rate_long=row.rollover_rate_long,
                rollover_rate_short=row.rollover_rate_short,
                max_funding_rate=row.max_funding_rate,
            )

    async def _acquire_spot_asset_precision_evidence_process_lock(
        self,
        exchange: str,
        asset: str,
    ) -> asyncio.Lock:
        """Acquire this process's lock for one evidence natural key."""
        key = (exchange, asset)
        lock = self._spot_asset_precision_evidence_locks.setdefault(key, asyncio.Lock())
        await lock.acquire()
        return lock

    async def _acquire_spot_asset_precision_evidence_advisory_lock(
        self,
        session: AsyncSession,
        exchange: str,
        asset: str,
    ) -> None:
        """Acquire the cross-process transaction lock before evidence reads."""
        dialect = self.dialect_name
        if dialect == "postgresql":
            await session.execute(
                text("SELECT pg_advisory_xact_lock(hashtext(:identity))"),
                {"identity": f"{exchange}\x1f{asset}"},
            )
            return
        if dialect == "sqlite":
            await session.execute(text("BEGIN IMMEDIATE"))
            return
        raise NotImplementedError(
            f"spot precision evidence lock not implemented for dialect={dialect}"
        )

    @staticmethod
    def _spot_asset_precision_plane_replaces(
        source: str | None,
        version: str | None,
        observed_at: datetime | None,
        plane: str,
    ) -> bool:
        """Validate one plane's provenance and return replacement intent."""
        present = (source is not None, version is not None, observed_at is not None)
        if all(present):
            return True
        if not any(present):
            return False
        raise ValueError(f"{plane} precision evidence provenance must be complete")

    @staticmethod
    def _merge_spot_asset_precision_evidence(
        existing: SpotAssetPrecisionEvidence | None,
        row: SpotAssetPrecisionEvidenceUpsertRow,
        replace_balance: bool,
        replace_fee: bool,
    ) -> _SpotAssetPrecisionEvidenceMerge:
        """Merge plane chronology while ratcheting balance scale with its provenance."""
        current_balance_observed_at = existing.balance_observed_at if existing is not None else None
        incoming_balance_observed_at = row["balance_observed_at"]
        apply_balance = replace_balance and (
            current_balance_observed_at is None
            or (
                incoming_balance_observed_at is not None
                and incoming_balance_observed_at >= current_balance_observed_at
            )
        )
        balance_decimals_max = existing.balance_decimals_max if existing is not None else None
        balance_max_source = existing.balance_max_source if existing is not None else None
        balance_max_version = existing.balance_max_version if existing is not None else None
        balance_max_observed_at = existing.balance_max_observed_at if existing is not None else None
        incoming_balance_decimals = row["balance_decimals"] if replace_balance else None
        incoming_covers_maximum = incoming_balance_decimals is not None and (
            balance_decimals_max is None
            or incoming_balance_decimals > balance_decimals_max
            or (
                incoming_balance_decimals == balance_decimals_max
                and incoming_balance_observed_at is not None
                and (
                    balance_max_observed_at is None
                    or incoming_balance_observed_at >= balance_max_observed_at
                )
            )
        )
        if incoming_covers_maximum:
            balance_decimals_max = incoming_balance_decimals
            balance_max_source = row["balance_source"]
            balance_max_version = row["balance_version"]
            balance_max_observed_at = incoming_balance_observed_at
        if apply_balance:
            balance_decimals = row["balance_decimals"]
            balance_source = row["balance_source"]
            balance_version = row["balance_version"]
            balance_observed_at = incoming_balance_observed_at
        else:
            balance_decimals = existing.balance_decimals if existing is not None else None
            balance_source = existing.balance_source if existing is not None else None
            balance_version = existing.balance_version if existing is not None else None
            balance_observed_at = current_balance_observed_at
        current_fee_observed_at = existing.fee_observed_at if existing is not None else None
        incoming_fee_observed_at = row["fee_observed_at"]
        apply_fee = replace_fee and (
            current_fee_observed_at is None
            or (
                incoming_fee_observed_at is not None
                and incoming_fee_observed_at >= current_fee_observed_at
            )
        )
        if apply_fee:
            fee_decimals = row["fee_decimals"]
            fee_source = row["fee_source"]
            fee_version = row["fee_version"]
            fee_observed_at = incoming_fee_observed_at
        else:
            fee_decimals = existing.fee_decimals if existing is not None else None
            fee_source = existing.fee_source if existing is not None else None
            fee_version = existing.fee_version if existing is not None else None
            fee_observed_at = current_fee_observed_at
        return _SpotAssetPrecisionEvidenceMerge(
            balance_decimals=balance_decimals,
            balance_decimals_max=balance_decimals_max,
            balance_max_source=balance_max_source,
            balance_max_version=balance_max_version,
            balance_max_observed_at=balance_max_observed_at,
            balance_source=balance_source,
            balance_version=balance_version,
            balance_observed_at=balance_observed_at,
            fee_decimals=fee_decimals,
            fee_source=fee_source,
            fee_version=fee_version,
            fee_observed_at=fee_observed_at,
        )

    async def _upsert_spot_asset_precision_evidence_once(
        self,
        row: SpotAssetPrecisionEvidenceUpsertRow,
        replace_balance: bool,
        replace_fee: bool,
    ) -> int:
        """Merge and write one evidence attempt after transaction locking."""
        timestamp = row["timestamp"]
        async with self.session() as session:
            await self._acquire_spot_asset_precision_evidence_advisory_lock(
                session,
                row["exchange"],
                row["asset"],
            )
            result = await session.execute(
                select(SpotAssetPrecisionEvidence)
                .where(
                    SpotAssetPrecisionEvidence.exchange == row["exchange"],
                    SpotAssetPrecisionEvidence.asset == row["asset"],
                    SpotAssetPrecisionEvidence.known_to == KNOWN_TO_MAX,
                )
                .with_for_update()
            )
            existing = result.scalar_one_or_none()
            effective_timestamp = (
                max(timestamp, existing.timestamp) if existing is not None else timestamp
            )
            merged = self._merge_spot_asset_precision_evidence(
                existing,
                row,
                replace_balance,
                replace_fee,
            )
            if existing is not None and (
                existing.balance_decimals == merged.balance_decimals
                and existing.balance_decimals_max == merged.balance_decimals_max
                and existing.balance_max_source == merged.balance_max_source
                and existing.balance_max_version == merged.balance_max_version
                and existing.balance_max_observed_at == merged.balance_max_observed_at
                and existing.balance_source == merged.balance_source
                and existing.balance_version == merged.balance_version
                and existing.balance_observed_at == merged.balance_observed_at
                and existing.fee_decimals == merged.fee_decimals
                and existing.fee_source == merged.fee_source
                and existing.fee_version == merged.fee_version
                and existing.fee_observed_at == merged.fee_observed_at
            ):
                return int(existing.id)
            inserted = await close_and_insert(
                session,
                SpotAssetPrecisionEvidence,
                [
                    SpotAssetPrecisionEvidence.exchange == row["exchange"],
                    SpotAssetPrecisionEvidence.asset == row["asset"],
                ],
                {
                    "exchange": row["exchange"],
                    "asset": row["asset"],
                    "balance_decimals": merged.balance_decimals,
                    "balance_decimals_max": merged.balance_decimals_max,
                    "balance_max_source": merged.balance_max_source,
                    "balance_max_version": merged.balance_max_version,
                    "balance_max_observed_at": merged.balance_max_observed_at,
                    "balance_source": merged.balance_source,
                    "balance_version": merged.balance_version,
                    "balance_observed_at": merged.balance_observed_at,
                    "fee_decimals": merged.fee_decimals,
                    "fee_source": merged.fee_source,
                    "fee_version": merged.fee_version,
                    "fee_observed_at": merged.fee_observed_at,
                    "session_id": row["session_id"],
                    "sequence_id": row["sequence_id"],
                },
                effective_timestamp,
            )
            try:
                await session.commit()
            except IntegrityError as exc:
                if existing is None:
                    raise _SpotAssetPrecisionEvidenceAbsentConflictError(exc) from exc
                raise
            await session.refresh(inserted)
            return int(inserted.id)

    async def _spot_asset_precision_evidence_active_key_exists(
        self,
        exchange: str,
        asset: str,
    ) -> bool:
        """Return whether an active natural-key winner exists after rollback."""
        async with self.session() as session:
            result = await session.execute(
                select(SpotAssetPrecisionEvidence.id).where(
                    SpotAssetPrecisionEvidence.exchange == exchange,
                    SpotAssetPrecisionEvidence.asset == asset,
                    SpotAssetPrecisionEvidence.known_to == KNOWN_TO_MAX,
                )
            )
            return result.scalar_one_or_none() is not None

    async def upsert_spot_asset_precision_evidence(
        self,
        row: SpotAssetPrecisionEvidenceUpsertRow,
    ) -> int:
        """Merge evidence under its natural-key lock and retry insert races."""
        replace_balance = self._spot_asset_precision_plane_replaces(
            row["balance_source"],
            row["balance_version"],
            row["balance_observed_at"],
            "balance",
        )
        replace_fee = self._spot_asset_precision_plane_replaces(
            row["fee_source"],
            row["fee_version"],
            row["fee_observed_at"],
            "fee",
        )
        if not replace_balance and not replace_fee:
            raise ValueError("at least one precision evidence plane must be observed")
        process_lock: asyncio.Lock | None = None
        if self.dialect_name == "sqlite":
            process_lock = await self._acquire_spot_asset_precision_evidence_process_lock(
                row["exchange"],
                row["asset"],
            )
        try:
            try:
                return await self._upsert_spot_asset_precision_evidence_once(
                    row,
                    replace_balance,
                    replace_fee,
                )
            except _SpotAssetPrecisionEvidenceAbsentConflictError as conflict:
                winner_exists = await self._spot_asset_precision_evidence_active_key_exists(
                    row["exchange"],
                    row["asset"],
                )
                if not winner_exists:
                    raise conflict.error from conflict
                return await self._upsert_spot_asset_precision_evidence_once(
                    row,
                    replace_balance,
                    replace_fee,
                )
        finally:
            if process_lock is not None:
                process_lock.release()

    async def get_spot_asset_precision_evidence(
        self,
        exchange: str,
        assets: Sequence[str],
        as_of: datetime,
    ) -> dict[str, SpotAssetPrecisionEvidenceRow]:
        """Batch-read exact asset identities and reject overlapping versions."""
        async with self.session() as s:
            return await self._load_spot_asset_precision_evidence(s, exchange, assets, as_of)

    @staticmethod
    async def _load_spot_asset_precision_evidence(
        s: AsyncSession,
        exchange: str,
        assets: Sequence[str],
        as_of: datetime,
    ) -> dict[str, SpotAssetPrecisionEvidenceRow]:
        """Batch-read precision evidence on the CALLER's session.

        Session-scoped so the spot bundle reads the precision plane inside its
        own snapshot transaction (one consistent instant with the replay range
        and the anchor) while :meth:`get_spot_asset_precision_evidence` keeps
        its own-session contract for every other consumer.
        """
        requested_assets = tuple(dict.fromkeys(assets))
        if not requested_assets:
            return {}
        result = await s.execute(
            select(SpotAssetPrecisionEvidence)
            .where(
                SpotAssetPrecisionEvidence.exchange == exchange,
                SpotAssetPrecisionEvidence.asset.in_(requested_assets),
                *where_active(SpotAssetPrecisionEvidence, as_of),
            )
            .order_by(
                SpotAssetPrecisionEvidence.asset,
                SpotAssetPrecisionEvidence.known_to,
                SpotAssetPrecisionEvidence.timestamp,
                SpotAssetPrecisionEvidence.id,
            )
        )
        evidence: dict[str, SpotAssetPrecisionEvidenceRow] = {}
        for persisted in result.scalars().all():
            if persisted.asset in evidence:
                raise RuntimeError("duplicate spot asset precision evidence")
            balance_certified = persisted.balance_decimals is not None
            evidence[persisted.asset] = SpotAssetPrecisionEvidenceRow(
                exchange=persisted.exchange,
                asset=persisted.asset,
                balance_decimals=(persisted.balance_decimals_max if balance_certified else None),
                balance_source=(
                    persisted.balance_max_source if balance_certified else persisted.balance_source
                ),
                balance_version=(
                    persisted.balance_max_version
                    if balance_certified
                    else persisted.balance_version
                ),
                balance_observed_at=(
                    persisted.balance_max_observed_at
                    if balance_certified
                    else persisted.balance_observed_at
                ),
                fee_decimals=persisted.fee_decimals,
                fee_source=persisted.fee_source,
                fee_version=persisted.fee_version,
                fee_observed_at=persisted.fee_observed_at,
            )
        return evidence

    async def _upsert_batch(
        self,
        model: type[Base],
        rows: list[Any],
        index_elements: list[str],
        session: AsyncSession | None = None,
    ) -> int:
        """Dialect-aware batch upsert with conflict-do-nothing.

        Uses SQLite/PostgreSQL native INSERT ... ON CONFLICT DO NOTHING
        when available, falling back to row-by-row IntegrityError handling.

        When ``session`` is provided the upsert runs on the
        caller-managed session WITHOUT issuing ``commit()`` — the
        caller is responsible for committing. This mirrors the
        :meth:`upsert_ticks` writer-task pattern so trade and
        candle flush paths can amortise the per-batch connection
        acquire across many flushes on one pinned connection.

        Args:
            model: SQLAlchemy model class to insert into.
            rows: List of column-value dicts.
            index_elements: Columns that form the unique constraint.
            session: Optional caller-managed session. When ``None``
                a fresh session opens, the insert commits inline,
                and the session closes before returning.

        Raises:
            ExecutionPhysicalMutationError: If ``model`` resolves to an
                append-only immutable-ledger table (e.g.
                :class:`~snapper.data.models.Execution`). A
                conflict-do-nothing insert could commit an arbitrary
                caller-chosen ``scope_sequence``, opening a gap below the
                counted watermark that the range proof cannot detect on
                the insert side. Guarding here — before the statement is
                built and before the empty-rows shortcut — covers both the
                native ``on_conflict_do_nothing`` path and the row-by-row
                integrity fallback, since both flow through this method.

        Returns:
            Number of rows successfully inserted.
        """
        _guard_immutable_ledger(
            model,
            "physical execution upsert is refused: a conflict-do-nothing "
            "insert could commit an arbitrary caller-chosen scope_sequence, "
            "opening a gap below the counted watermark the range proof "
            "cannot catch on the insert side",
        )
        self._ensure_public_ids(rows)
        stmt = self._build_conflict_do_nothing_statement(model, rows, index_elements)
        if stmt is not None:
            return await self._execute_upsert_statement(stmt, session)
        return await self._upsert_rows_with_integrity_fallback(model, rows, session)

    @staticmethod
    def _ensure_public_ids(rows: list[Any]) -> None:
        """Fill missing public identifiers before an insert attempt.

        Args:
            rows: Mutable row dictionaries accepted by SQLAlchemy insert
                statements.
        """
        for row in rows:
            if "public_id" not in row:
                row["public_id"] = str(uuid7())

    def _build_conflict_do_nothing_statement(
        self,
        model: type[Base],
        rows: list[Any],
        index_elements: list[str],
    ) -> Any | None:
        """Build a native conflict-do-nothing statement when supported.

        This builder carries no immutable-ledger guard of its own by
        design. It is a pure statement factory with no sole append-only
        harm — ``on_conflict_do_nothing`` can neither delete a sealed row
        nor free ``max(scope_sequence)`` — and its only caller is
        :meth:`_upsert_batch`, which refuses immutable-ledger targets
        before this method runs. Adding a second guard here would be a
        redundant call-site check, not an independent theorem.

        Args:
            model: SQLAlchemy model class to insert into.
            rows: Column-value dictionaries to insert.
            index_elements: Columns that form the unique constraint.

        Returns:
            SQLAlchemy insert statement for native dialects, otherwise
            ``None`` so callers can use the portable fallback.
        """
        name = self.dialect_name
        if name == "sqlite":
            stmt_sq = sqlite_insert(model).values(rows)
            return stmt_sq.on_conflict_do_nothing(index_elements=index_elements)
        if name.startswith("postgres"):
            stmt_pg = pg_insert(model).values(rows)
            return stmt_pg.on_conflict_do_nothing(index_elements=index_elements)
        return None

    async def _execute_upsert_statement(self, stmt: Any, session: AsyncSession | None) -> int:
        """Execute a native upsert statement in caller-owned or local scope.

        Args:
            stmt: SQLAlchemy native insert statement.
            session: Optional caller-managed session.

        Returns:
            Number of rows reported as inserted.
        """
        if session is not None:
            return await self._execute_statement_count(session, stmt)
        async with self.session() as s:
            inserted = await self._execute_statement_count(s, stmt)
            await s.commit()
            return inserted

    @staticmethod
    async def _execute_statement_count(session: AsyncSession, stmt: Any) -> int:
        """Execute a statement and normalize rowcount.

        Args:
            session: Active async SQLAlchemy session.
            stmt: SQLAlchemy statement to execute.

        Returns:
            Integer rowcount with ``None`` normalized to zero.
        """
        result = await session.execute(stmt)
        return int(cast(Any, result).rowcount or 0)

    async def _upsert_rows_with_integrity_fallback(
        self,
        model: type[Base],
        rows: list[Any],
        session: AsyncSession | None,
    ) -> int:
        """Insert rows one by one while ignoring integrity duplicates.

        Args:
            model: SQLAlchemy model class to insert into.
            rows: Column-value dictionaries to insert.
            session: Optional caller-managed session.

        Returns:
            Number of rows successfully inserted.
        """
        if session is not None:
            return await self._insert_rows_ignoring_integrity_errors(model, rows, session)
        async with self.session() as s:
            inserted = await self._insert_rows_ignoring_integrity_errors(model, rows, s)
            await s.commit()
            return inserted

    @staticmethod
    async def _insert_rows_ignoring_integrity_errors(
        model: type[Base], rows: list[Any], session: AsyncSession
    ) -> int:
        """Insert rows inside savepoints and skip duplicate failures.

        Args:
            model: SQLAlchemy model class to insert into.
            rows: Column-value dictionaries to insert.
            session: Active async SQLAlchemy session.

        Returns:
            Number of rows successfully inserted.
        """
        inserted = 0
        for row in rows:
            try:
                async with session.begin_nested():
                    await session.execute(insert(model).values(**row))
                inserted += 1
            except IntegrityError:
                continue
        return inserted

    async def upsert_candles(
        self, rows: list[CandleUpsertRow], session: AsyncSession | None = None
    ) -> int:
        """Close-old + insert-new (SCD Type 2) for candle rows.

        When a candle with the same (instrument_public_id, timeframe, open_at)
        already exists as an active row (known_to == KNOWN_TO_MAX), the old row
        is closed by setting its known_to to now, and a new row is inserted
        carrying the same public_id.  This preserves full history of
        intra-interval updates.

        Rows without ``public_id`` get a generated UUID7 automatically.

        ``session`` semantics mirror :meth:`upsert_ticks` and
        :meth:`upsert_trades`: when provided, the insert runs on the
        caller-managed session without committing so a writer task
        can keep a pinned :class:`AsyncConnection` across many
        flushes; when ``None`` the method opens its own session and
        commits inline.
        """
        if not rows:
            return 0
        for r in rows:
            if "public_id" not in r:
                r["public_id"] = str(uuid7())
            if "known_to" not in r:
                r["known_to"] = KNOWN_TO_MAX
        if session is not None:
            unique_rows, sequential_rows = self._split_candle_rows_by_duplicate_key(rows)
            existing_by_key = await self._load_existing_candles_for_rows(session, unique_rows)
            count = await self._upsert_unique_candle_rows(session, unique_rows, existing_by_key)
            for r in sequential_rows:
                if await self._upsert_candle_row(session, r):
                    count += 1
            return count
        async with self.session() as s:
            unique_rows, sequential_rows = self._split_candle_rows_by_duplicate_key(rows)
            existing_by_key = await self._load_existing_candles_for_rows(s, unique_rows)
            count = await self._upsert_unique_candle_rows(s, unique_rows, existing_by_key)
            for r in sequential_rows:
                if await self._upsert_candle_row(s, r):
                    count += 1
            await s.commit()
        return count

    @staticmethod
    def _candle_natural_key(row: CandleUpsertRow) -> _CandleNaturalKey:
        """Return the SCD2 natural key for a candle upsert row."""
        return row["instrument_public_id"], row["timeframe"], row["open_at"]

    @staticmethod
    def _candle_row_matches(existing: Candle, row: CandleUpsertRow) -> bool:
        """Return True when every business column of ``row`` equals ``existing``.

        Used to make a re-upsert of identical data a true no-op: when the
        active version already carries the same OHLCV/vwap/trade values AND the
        same provenance (``source``/``complete``/``price_basis``), the SCD2
        close-old + insert-new churn is skipped. Comparing provenance means a
        synthesized re-roll that corrects an OHLCV-equal row's completeness
        still versions, and so does a re-mark that changes only which price
        the identical-looking numbers were derived from.

        The stored layer types these columns as ``Float`` (open, high, low,
        close, volume, vwap) and ``Integer`` (trades), so the incoming
        ``CandleUpsertRow`` already carries Python ``float``/``int`` values
        matching the column types.  Comparison is exact equality on those
        stored values — no rounding or float coercion is introduced, so a
        genuine correction in any column still falls through to a new
        version.
        """
        return (
            existing.open == row["open"]
            and existing.high == row["high"]
            and existing.low == row["low"]
            and existing.close == row["close"]
            and existing.volume == row["volume"]
            and existing.vwap == row["vwap"]
            and existing.trades == row["trades"]
            and existing.source == row.get("source", "native")
            and existing.complete == row.get("complete", True)
            and existing.price_basis == row.get("price_basis")
        )

    @classmethod
    def _split_candle_rows_by_duplicate_key(
        cls,
        rows: list[CandleUpsertRow],
    ) -> tuple[list[CandleUpsertRow], list[CandleUpsertRow]]:
        """Separate rows safe for batch lookup from duplicate-key rows.

        Rows sharing a natural key in the same incoming batch must keep
        the old sequential close+insert flow because earlier rows can
        create the version that later rows need to close.
        """
        seen: set[_CandleNaturalKey] = set()
        duplicate_keys: set[_CandleNaturalKey] = set()
        for row in rows:
            key = cls._candle_natural_key(row)
            if key in seen:
                duplicate_keys.add(key)
            seen.add(key)
        if not duplicate_keys:
            return rows, []
        unique_rows = [row for row in rows if cls._candle_natural_key(row) not in duplicate_keys]
        sequential_rows = [row for row in rows if cls._candle_natural_key(row) in duplicate_keys]
        return unique_rows, sequential_rows

    @classmethod
    async def _load_existing_candles_for_rows(
        cls,
        session: AsyncSession,
        rows: list[CandleUpsertRow],
    ) -> dict[_CandleNaturalKey, Candle]:
        """Load existing SCD2 candle versions for unique-key rows in one query."""
        if not rows:
            return {}
        row_by_key = {cls._candle_natural_key(row): row for row in rows}
        keys = list(row_by_key)
        existing_by_key: dict[_CandleNaturalKey, Candle] = {}
        for offset in range(0, len(keys), _CANDLE_LOOKUP_CHUNK_SIZE):
            key_chunk = keys[offset : offset + _CANDLE_LOOKUP_CHUNK_SIZE]
            row_chunk = [row_by_key[key] for key in key_chunk]
            min_timestamp = min(row["timestamp"] for row in row_chunk)
            max_timestamp = max(row["timestamp"] for row in row_chunk)
            result = await session.execute(
                select(Candle)
                .where(
                    tuple_(Candle.instrument_public_id, Candle.timeframe, Candle.open_at).in_(
                        key_chunk
                    ),
                    Candle.timestamp <= max_timestamp,
                    Candle.known_to > min_timestamp,
                )
                .with_for_update()
            )
            for candle in result.scalars().all():
                key = (candle.instrument_public_id, candle.timeframe, candle.open_at)
                row = row_by_key[key]
                bus_time = row["timestamp"]
                if candle.timestamp <= bus_time and candle.known_to > bus_time:
                    existing_by_key[key] = candle
        return existing_by_key

    @classmethod
    async def _upsert_unique_candle_rows(
        cls,
        session: AsyncSession,
        rows: list[CandleUpsertRow],
        existing_by_key: dict[_CandleNaturalKey, Candle],
    ) -> int:
        """Close matched candle rows and stage inserts for unique-key rows.

        When the active version already holds identical business values the
        row is a no-op: neither the close-update nor the insert runs and it is
        not counted, so re-loading unchanged data does not create a new
        SCD2 version.
        """
        count = 0
        for row in rows:
            existing = existing_by_key.get(cls._candle_natural_key(row))
            if existing is not None:
                if cls._candle_row_matches(existing, row):
                    continue
                await session.execute(
                    update(Candle).where(Candle.id == existing.id).values(known_to=row["timestamp"])
                )
                row["public_id"] = existing.public_id
            session.add(Candle(**row))
            count += 1
        return count

    @classmethod
    async def _upsert_candle_row(
        cls,
        session: AsyncSession,
        row: CandleUpsertRow,
    ) -> bool:
        """Run the sequential SCD2 close+insert path for one candle row.

        Returns ``True`` when a row was inserted and ``False`` when the row
        was a no-op because the active version already held identical
        business values (so the caller skips counting it).
        """
        bus_time = row["timestamp"]
        existing = (
            (
                await session.execute(
                    select(Candle)
                    .where(
                        Candle.instrument_public_id == row["instrument_public_id"],
                        Candle.timeframe == row["timeframe"],
                        Candle.open_at == row["open_at"],
                        Candle.timestamp <= bus_time,
                        Candle.known_to > bus_time,
                    )
                    .with_for_update()
                )
            )
            .scalars()
            .first()
        )
        if existing:
            if cls._candle_row_matches(existing, row):
                return False
            await session.execute(
                update(Candle).where(Candle.id == existing.id).values(known_to=bus_time)
            )
            row["public_id"] = existing.public_id
        session.add(Candle(**row))
        return True

    async def upsert_shadow_candles(
        self, rows: list[ShadowCandleUpsertRow], session: AsyncSession | None = None
    ) -> int:
        """Close-old + insert-new for shadow candle rows.

        Args:
            rows: Shadow candle rows keyed by instrument, timeframe, open time,
                and source. ``public_id`` and ``known_to`` are filled when absent.
            session: Optional caller-managed session. When ``None``, this method
                opens and commits its own session.

        Returns:
            Number of inserted shadow candle versions. Re-upserting an identical
            active row returns zero for that row.
        """
        if not rows:
            return 0
        for row in rows:
            if "public_id" not in row:
                row["public_id"] = str(uuid7())
            if "known_to" not in row:
                row["known_to"] = KNOWN_TO_MAX
        if session is not None:
            count = 0
            for row in rows:
                if await self._upsert_shadow_candle_row(session, row):
                    count += 1
            return count
        async with self.session() as s:
            count = 0
            for row in rows:
                if await self._upsert_shadow_candle_row(s, row):
                    count += 1
            await s.commit()
            return count

    @staticmethod
    def _shadow_candle_row_matches(existing: ShadowCandle, row: ShadowCandleUpsertRow) -> bool:
        """Return True when the active shadow candle already carries row values.

        Args:
            existing: Active persisted shadow candle version.
            row: Incoming shadow candle row.

        Returns:
            True when every OHLCV, provenance, and completeness value matches.
        """
        return (
            existing.open == row["open"]
            and existing.high == row["high"]
            and existing.low == row["low"]
            and existing.close == row["close"]
            and existing.volume == row["volume"]
            and existing.vwap == row["vwap"]
            and existing.trades == row["trades"]
            and existing.source == row.get("source", "native")
            and existing.complete == row.get("complete", True)
        )

    @classmethod
    async def _upsert_shadow_candle_row(
        cls,
        session: AsyncSession,
        row: ShadowCandleUpsertRow,
    ) -> bool:
        """Run the sequential shadow candle SCD2 close+insert path.

        Args:
            session: Active async SQLAlchemy session.
            row: Shadow candle row to insert or revise.

        Returns:
            True when a new version was inserted, false when the active version
            was identical and no-oped.
        """
        bus_time = row["timestamp"]
        source = row.get("source", "native")
        existing = (
            (
                await session.execute(
                    select(ShadowCandle)
                    .where(
                        ShadowCandle.instrument_public_id == row["instrument_public_id"],
                        ShadowCandle.timeframe == row["timeframe"],
                        ShadowCandle.open_at == row["open_at"],
                        ShadowCandle.source == source,
                        ShadowCandle.timestamp <= bus_time,
                        ShadowCandle.known_to > bus_time,
                    )
                    .with_for_update()
                )
            )
            .scalars()
            .first()
        )
        if existing:
            if cls._shadow_candle_row_matches(existing, row):
                return False
            await session.execute(
                update(ShadowCandle).where(ShadowCandle.id == existing.id).values(known_to=bus_time)
            )
            row["public_id"] = existing.public_id
        session.add(ShadowCandle(**row))
        return True

    async def upsert_trades(
        self,
        rows: list[TradeUpsertRow],
        session: AsyncSession | None = None,
        *,
        enqueue_integrity_work: bool = False,
    ) -> int:
        """Insert trades with dialect-specific conflict handling.

        Mirrors :meth:`upsert_ticks` ``session`` semantics: when a
        caller-managed session is supplied the insert runs without
        committing so the writer task can batch many flushes onto a
        single pinned :class:`AsyncConnection`. Omit ``session`` for
        ad-hoc / test paths that want an inline commit. Historical
        replay callers set ``enqueue_integrity_work`` so the trade and
        exact monitor obligations share that transaction.
        """
        if not rows:
            return 0
        if not enqueue_integrity_work:
            return await self._upsert_batch(
                Trade,
                rows,
                ["instrument_public_id", "trade_id", "executed_at"],
                session=session,
            )
        if session is not None:
            inserted = await self._upsert_batch(
                Trade,
                rows,
                ["instrument_public_id", "trade_id", "executed_at"],
                session=session,
            )
            await self._enqueue_trade_integrity_work(session, rows)
            return inserted
        async with self.session() as owned_session:
            inserted = await self._upsert_batch(
                Trade,
                rows,
                ["instrument_public_id", "trade_id", "executed_at"],
                session=owned_session,
            )
            await self._enqueue_trade_integrity_work(owned_session, rows)
            await owned_session.commit()
            return inserted

    @staticmethod
    async def _enqueue_trade_integrity_work(
        session: AsyncSession,
        rows: list[TradeUpsertRow],
    ) -> None:
        """Enqueue exact historical trade identities before their commit."""
        work_items: list[TradeIntegrityWorkItemInsertRow] = []
        for row in rows:
            trade_id = row.get("trade_id")
            work_items.append(
                TradeIntegrityWorkItemInsertRow(
                    public_id=row["public_id"],
                    instrument_public_id=row["instrument_public_id"],
                    trade_id=trade_id,
                    executed_at=row["executed_at"],
                    m1_pending=trade_id is not None,
                    m2_pending=True,
                )
            )
        await session.execute(insert(TradeIntegrityWorkItem), work_items)

    async def run_trade_integrity_monitor(
        self,
        *,
        monitor: TradeIntegrityMonitor,
        now: datetime,
        sweep_limit: int,
        worklog_limit: int,
    ) -> TradeIntegrityRunResult:
        """Run one bounded M1 or M2 pass and commit its durable state."""
        request = TradeIntegrityPassRequest(
            monitor=monitor,
            now=now,
            sweep_limit=sweep_limit,
            worklog_limit=worklog_limit,
        )
        async with self.session() as session:
            return await run_trade_integrity_monitor_pass(
                session,
                self.dialect_name,
                request,
            )

    async def upsert_ticks(
        self, rows: list[TickUpsertRow], session: AsyncSession | None = None
    ) -> int:
        """Insert ticks via append-only Core bulk INSERT.

        Replaces the prior ORM ``s.add_all([Tick(**r) for r in rows])``
        path. Append-only ticks do not need the identity-map, dirty
        tracking, or per-row constructor work that the ORM provides;
        ``insert(Tick).values(rows)`` emits a single SQL statement with
        all rows inline and is materially cheaper at publisher rates.

        When ``session`` is provided the caller owns the transaction —
        no commit fires inside this method. Publisher writer tasks
        rely on this to amortise per-flush connection-acquire cost
        across many batches. When ``session`` is ``None`` (tests,
        bulk imports) a fresh session is opened, the insert commits,
        and the session closes before returning.

        Args:
            rows: Tick rows to insert. ``public_id`` is auto-filled
                when missing.
            session: Optional caller-managed session. When ``None``,
                a fresh session opens and commits inline.

        Returns:
            Number of rows inserted.
        """
        if not rows:
            return 0
        for r in rows:
            if "public_id" not in r:
                r["public_id"] = str(uuid7())
        if session is not None:
            await session.execute(insert(Tick), list(rows))
            return len(rows)
        async with self.session() as s:
            await s.execute(insert(Tick), list(rows))
            await s.commit()
            return len(rows)

    async def insert_order(
        self,
        row: OrderInsertRow | None = None,
        **kwargs: Unpack[OrderInsertRow],
    ) -> tuple[int, str]:
        """Insert new order record and return (id, public_id) tuple."""
        if row is not None and kwargs:
            raise ValueError("insert_order accepts either row or keyword fields, not both")
        order_row = row if row is not None else kwargs
        mode = order_row.get("mode", "live")
        operator_public_id = order_row.get("operator_public_id")
        time_in_force = order_row.get("time_in_force")
        leverage = order_row.get("leverage")
        reduce_only = order_row.get("reduce_only", False)
        plan_public_id = order_row.get("plan_public_id")
        async with self.session() as s:
            order = Order(
                instrument_public_id=order_row["instrument_public_id"],
                mode=mode,
                wallet_public_id=order_row["wallet_public_id"],
                operator_public_id=operator_public_id,
                client_order_id=order_row["client_order_id"],
                exchange_order_id=order_row["exchange_order_id"],
                created_at=order_row["created_at"],
                updated_at=None,
                timestamp=order_row["timestamp"],
                side=order_row["side"],
                order_type=order_row["order_type"],
                price=order_row["price"],
                size=order_row["size"],
                filled_size=0.0,
                average_price=None,
                status=order_row["status"],
                time_in_force=time_in_force,
                error=None,
                leverage=leverage,
                reduce_only=reduce_only,
                plan_public_id=plan_public_id,
                session_id=order_row["session_id"],
                sequence_id=order_row["sequence_id"],
            )
            s.add(order)
            await s.commit()
            await s.refresh(order)
            return (order.id, order.public_id)

    async def update_order(
        self,
        order_id: int,
        status: str,
        updated_at: datetime,
        session_id: str,
        sequence_id: int,
        timestamp: datetime,
        exchange_order_id: str | None = None,
        error: str | None = None,
        filled_size: float | None = None,
        average_price: float | None = None,
    ) -> int:
        """Close old order version and insert new one (SCD Type 2).

        Fill-truth semantics (PnL Phase 1): when ``filled_size`` is
        provided the call is a FILL update and both fill columns are
        authoritative — ``filled_size`` is written verbatim and
        ``average_price`` is written as given; when the venue reported
        no average (``None``) the successor's average is derived as the
        VWAP of this order's active execution rows, but ONLY when their
        summed delta size matches the supplied cumulative (a missed
        frame makes the VWAP a lie — the successor then carries an
        explicit NULL, never a stale predecessor average or a
        last-delta price). When ``filled_size`` is ``None`` the call is
        a status-only transition (cancel/expire/reject) and BOTH fill
        columns carry forward from the closed version — a stray
        ``average_price`` argument without its cumulative is
        contradictory input and is ignored.

        The close and the successor use
        ``max(timestamp, old_row.timestamp)`` so a caller clock that
        lags the row's bus time cannot create an inverted validity
        interval. The successor id is read after ``flush`` (before
        commit) so callers can re-point
        ``PendingOrderState.db_order_id`` without a post-commit refresh
        window.

        Returns:
            The new (successor) row's integer primary key.
        """
        async with self.session() as s:
            old_order = (
                (await s.execute(select(Order).where(Order.id == order_id).with_for_update()))
                .scalars()
                .one()
            )
            effective_ts = max(timestamp, old_order.timestamp)
            if filled_size is not None:
                new_filled = filled_size
                new_average = average_price
                if new_average is None:
                    new_average = await self._derive_average_price_from_executions(
                        s, old_order.public_id, filled_size
                    )
            else:
                new_filled = old_order.filled_size
                new_average = old_order.average_price
            await s.execute(update(Order).where(Order.id == order_id).values(known_to=effective_ts))
            new_order = Order(
                public_id=old_order.public_id,
                instrument_public_id=old_order.instrument_public_id,
                mode=old_order.mode,
                wallet_public_id=old_order.wallet_public_id,
                operator_public_id=old_order.operator_public_id,
                client_order_id=old_order.client_order_id,
                exchange_order_id=exchange_order_id or old_order.exchange_order_id,
                created_at=old_order.created_at,
                updated_at=updated_at,
                timestamp=effective_ts,
                side=old_order.side,
                order_type=old_order.order_type,
                price=old_order.price,
                size=old_order.size,
                filled_size=new_filled,
                average_price=new_average,
                status=status,
                time_in_force=old_order.time_in_force,
                error=error,
                leverage=old_order.leverage,
                reduce_only=old_order.reduce_only,
                plan_public_id=old_order.plan_public_id,
                session_id=session_id,
                sequence_id=sequence_id,
            )
            s.add(new_order)
            await s.flush()
            new_id = new_order.id
            await s.commit()
            return new_id

    @staticmethod
    async def _derive_average_price_from_executions(
        s: AsyncSession, order_public_id: str, cumulative_size: float
    ) -> float | None:
        """Derive an order's average price as VWAP of its executions.

        Used by :meth:`update_order` on fill updates where the venue
        frame carried no ``average_price`` (some venues report only
        ``last_qty``/``last_price``). The VWAP over the order's ACTIVE
        execution rows (statuses ``filled``/``partial``) is trustworthy
        only when the summed delta sizes reproduce the venue's
        cumulative — a missed frame would skew the average, so a
        mismatch yields ``None`` (an explicit unknown).

        Args:
            s: Open session of the enclosing ``update_order`` call.
            order_public_id: Stable order identity linking executions.
            cumulative_size: Venue-reported cumulative filled size.

        Returns:
            The VWAP as ``float``, or ``None`` when no executions
            exist, the total is non-positive, or the sum does not
            match the cumulative.
        """
        result = await s.execute(
            select(
                func.sum(Execution.price * Execution.size),
                func.sum(Execution.size),
            ).where(
                Execution.order_public_id == order_public_id,
                Execution.status.in_(("filled", "partial")),
                Execution.known_to == KNOWN_TO_MAX,
            )
        )
        notional, total = result.one()
        if total is None or float(total) <= 0.0:
            return None
        if not math.isclose(float(total), cumulative_size, rel_tol=1e-9, abs_tol=1e-12):
            return None
        return float(notional) / float(total)

    @staticmethod
    def _execution_scope_wallet_key(wallet_public_id: str) -> str:
        """Canonicalize a wallet identity for scope comparison when possible.

        Mirrors the execution fence key logic: alias UUID spellings must
        compare equal to their canonical form (PostgreSQL stores wallets
        in a native ``uuid`` column, so an alias-spelled caller refers to
        the same stored identity); a non-UUID identity compares raw.
        """
        try:
            return str(UUID(wallet_public_id))
        except ValueError:
            return wallet_public_id

    async def _resolve_execution_scope(
        self,
        s: AsyncSession,
        order_public_id: str,
        wallet_public_id: str,
    ) -> tuple[str, str]:
        """Resolve one fill's immutable ``(exchange, mode)`` scope, fail-closed.

        One indexed two-table SELECT against the ACTIVE (``known_to`` open)
        Order and Instrument versions — stable across SCD2 versions because
        ``update_order`` copies ``mode``/``instrument_public_id``/
        ``wallet_public_id`` verbatim to every successor. Refusals are
        per-row and pre-persistence, which is what keeps the ledger free of
        unresolvable rows and boundary captures free of lineage scans.

        Raises:
            ExecutionScopeResolutionError: ``dangling_execution_order_lineage``
                when no active order version exists,
                ``crossed_wallet_execution_lineage`` when the active order is
                owned by another wallet, and
                ``dangling_execution_instrument_lineage`` when the order's
                instrument has no active version.
        """
        lineage = (
            await s.execute(
                select(Order.mode, Order.wallet_public_id, Instrument.exchange)
                .select_from(Order)
                .outerjoin(
                    Instrument,
                    and_(
                        Instrument.public_id == Order.instrument_public_id,
                        Instrument.known_to == KNOWN_TO_MAX,
                    ),
                )
                .where(
                    Order.public_id == order_public_id,
                    Order.known_to == KNOWN_TO_MAX,
                )
            )
        ).first()
        if lineage is None:
            raise ExecutionScopeResolutionError("dangling_execution_order_lineage")
        if self._execution_scope_wallet_key(
            str(lineage.wallet_public_id)
        ) != self._execution_scope_wallet_key(wallet_public_id):
            raise ExecutionScopeResolutionError("crossed_wallet_execution_lineage")
        if lineage.exchange is None:
            raise ExecutionScopeResolutionError("dangling_execution_instrument_lineage")
        return str(lineage.exchange), str(lineage.mode)

    async def insert_execution(
        self,
        row: ExecutionInsertRow | None = None,
        **kwargs: Unpack[ExecutionInsertRow],
    ) -> int:
        """Insert execution record and return generated ID.

        Statement order inside the one insert transaction — PostgreSQL:
        ``SET TRANSACTION ISOLATION LEVEL READ COMMITTED`` -> scope
        resolve -> fence lock -> committed ``max+1`` read -> ``INSERT``
        -> ``COMMIT``; SQLite: ``BEGIN IMMEDIATE`` -> scope resolve ->
        (fence no-op) -> committed ``max+1`` read -> ``INSERT`` ->
        ``COMMIT``. Both dialect-specific openers are emitted by
        :meth:`_begin_execution_insert_transaction` as the transaction's
        FIRST statement.

        The wallet identity is validated and canonicalized ONCE at the
        top, and the CANONICAL spelling is used for lineage resolution,
        the fence key, the ``max+1`` read, and the persisted row — SQLite
        stores ``UUIDColumn`` values verbatim, so a caller's alias
        spelling would otherwise split one logical wallet into several
        counter scopes invisible to the canonical watermark capture.

        The scope resolve (:meth:`_resolve_execution_scope`) runs before
        the lock, so it never lengthens the fence hold — its result is
        version-stable — and its fail-closed refusals keep unresolvable
        rows out of the ledger entirely. ``scope_sequence`` is then
        allocated as the committed per-scope maximum plus one WHILE HOLDING
        the per-wallet execution fence: the previous same-wallet writer's
        transaction-scoped fence released only at commit or abort, so the
        max read here is THE committed scope maximum (never stale), and a
        rollback discards the assignment leaving no gap (a column write,
        not a sequence — no database sequence property is load-bearing).
        Allocation order therefore equals commit order by construction,
        which is what makes the unlocked capture in
        :meth:`get_spot_execution_watermark` a sealed committed prefix.
        The insert side deliberately has NO lock timeout: a fill must never
        be dropped, and the capture no longer holds the fence at all.

        Isolation is EXPLICIT, never inherited: the engine picks up
        whatever ``default_transaction_isolation`` the PostgreSQL role or
        database configures, and the resolve SELECT runs BEFORE the fence
        wait — under an inherited REPEATABLE READ it would pin a snapshot
        that, after waiting out another writer, reads a STALE committed
        maximum; the UNIQUE backstop would reject the duplicate, but the
        fill-persistence caller swallows that error AFTER publication,
        permanently omitting the fill. The explicit first statement
        removes the failure mode instead of relying on server
        configuration.

        Raises:
            ExecutionScopeResolutionError: When the wallet identity is
                malformed (``invalid_execution_wallet_identity``) or the
                fill's active Order -> Instrument lineage is missing or
                contradictory (see :meth:`_resolve_execution_scope`); the
                row is refused before persistence.
        """
        if row is not None and kwargs:
            raise ValueError("insert_execution accepts either row or keyword fields, not both")
        execution_row = row if row is not None else kwargs
        try:
            wallet_public_id = str(UUID(execution_row["wallet_public_id"]))
        except ValueError as exc:
            raise ExecutionScopeResolutionError("invalid_execution_wallet_identity") from exc
        operator_public_id = execution_row.get("operator_public_id")
        exec_id = execution_row.get("exec_id")
        trade_id = execution_row.get("trade_id")
        liquidity_role = execution_row.get("liquidity_role", "unknown")
        price_decimal = execution_row.get("price_decimal")
        size_decimal = execution_row.get("size_decimal")
        fee_decimal = execution_row.get("fee_decimal")
        counter_amount_decimal = execution_row.get("counter_amount_decimal")
        numeric_provenance = execution_row.get("numeric_provenance", "legacy_float")
        async with self.session() as s:
            await self._begin_execution_insert_transaction(s)
            scope_exchange, scope_mode = await self._resolve_execution_scope(
                s,
                execution_row["order_public_id"],
                wallet_public_id,
            )
            await self._acquire_execution_fence_lock(s, wallet_public_id)
            next_scope_sequence = (
                await s.execute(
                    select(func.coalesce(func.max(Execution.scope_sequence), 0) + 1).where(
                        Execution.wallet_public_id == wallet_public_id,
                        Execution.exchange == scope_exchange,
                        Execution.mode == scope_mode,
                    )
                )
            ).scalar_one()
            execution = Execution(
                order_public_id=execution_row["order_public_id"],
                wallet_public_id=wallet_public_id,
                operator_public_id=operator_public_id,
                exchange=scope_exchange,
                mode=scope_mode,
                scope_sequence=int(next_scope_sequence),
                exec_id=exec_id,
                trade_id=trade_id,
                timestamp=execution_row["timestamp"],
                side=execution_row["side"],
                status=execution_row["status"],
                price=execution_row["price"],
                size=execution_row["size"],
                fee=execution_row["fee"],
                fee_asset=execution_row["fee_asset"],
                price_decimal=price_decimal,
                size_decimal=size_decimal,
                fee_decimal=fee_decimal,
                counter_amount_decimal=counter_amount_decimal,
                numeric_provenance=numeric_provenance,
                session_id=execution_row["session_id"],
                sequence_id=execution_row["sequence_id"],
                liquidity_role=liquidity_role,
            )
            s.add(execution)
            await s.commit()
            await s.refresh(execution)
            return execution.id

    async def _resolve_active_instrument(
        self,
        session: AsyncSession,
        native_symbol: str,
        exchange: str,
        as_of: datetime,
    ) -> Instrument | None:
        """Resolve active Instrument from native symbol and exchange.

        Collapses the legacy Symbol→Instrument lookup waterfall into
        a single joined query. Every market-data read API
        (``get_candles`` / ``get_ticks`` /
        :meth:`iter_ticks` / :meth:`iter_trades`) hit this method
        twice: one SELECT to look up the Symbol's ``public_id``,
        then another to fetch the matching active Instrument row.
        The JOIN below resolves both in one round-trip.

        Args:
            session: Active database session.
            native_symbol: Canonical symbol string (e.g. 'BTC-USD').
            exchange: Exchange name.
            as_of: Point-in-time for temporal query.

        Returns:
            Active Instrument or None if symbol/instrument not found.
        """
        s_ts, s_kt = where_active(Symbol, as_of)
        i_ts, i_kt = where_active(Instrument, as_of)
        q_inst = await session.execute(
            select(Instrument)
            .join(Symbol, Symbol.public_id == Instrument.symbol_public_id)
            .where(
                Symbol.native_symbol == native_symbol,
                s_ts,
                s_kt,
                Instrument.exchange == exchange,
                i_ts,
                i_kt,
            )
        )
        return q_inst.scalars().first()

    async def get_candles(
        self,
        instrument: str,
        timeframe: str,
        start: datetime | None,
        end: datetime | None,
        exchange: AllExchange,
        as_of: datetime,
        limit: int | None = None,
        order: str = "asc",
        complete: bool | None = None,
    ) -> list[CandleRow]:
        """Retrieve active candles for instrument.

        Supports two modes:
        - Range mode: start and end both provided.
        - Latest-as-of mode: start/end are None, limit provided.

        ``complete=True`` adds the final-bar predicate so latest-N
        reads return an exact count of complete bars even when
        intermediate persists left provisional rows; ``None`` keeps
        the legacy unfiltered read.
        """
        async with self.session() as s:
            inst = await self._resolve_active_instrument(s, instrument, exchange, as_of)
            if inst is None:
                return []
            q = select(
                Candle.open_at,
                Candle.timeframe,
                Candle.open,
                Candle.high,
                Candle.low,
                Candle.close,
                Candle.volume,
                Candle.vwap,
                Candle.trades,
                Candle.source,
                Candle.complete,
                Candle.public_id,
                Candle.timestamp,
                Candle.session_id,
                Candle.sequence_id,
            ).where(
                Candle.instrument_public_id == inst.public_id,
                Candle.timeframe == timeframe,
                Candle.timestamp <= as_of,
                Candle.known_to > as_of,
            )
            if start is not None and end is not None:
                q = q.where(Candle.open_at >= start, Candle.open_at <= end)
            if complete is not None:
                q = q.where(Candle.complete.is_(complete))
            order_col = Candle.open_at.desc() if order == "desc" else Candle.open_at.asc()
            q = q.order_by(order_col)
            if limit is not None:
                q = q.limit(limit)
            rows = (await s.execute(q)).all()
            return [
                {
                    "open_at": r.open_at,
                    "timeframe": r.timeframe,
                    "open": r.open,
                    "high": r.high,
                    "low": r.low,
                    "close": r.close,
                    "volume": r.volume,
                    "vwap": r.vwap,
                    "trades": r.trades,
                    "source": r.source,
                    "complete": r.complete,
                    "public_id": r.public_id,
                    "timestamp": r.timestamp,
                    "session_id": r.session_id,
                    "sequence_id": r.sequence_id,
                }
                for r in rows
            ]

    async def get_latest_candles_for_instruments(
        self,
        instrument_public_ids: Sequence[str],
        timeframe: str,
        as_of: datetime,
        limit_per_instrument: int,
        open_at_floor: datetime | None = None,
    ) -> dict[str, list[CandleRow]]:
        """Latest-N active candles for several instruments in one session.

        Reuses the exact ``get_candles`` latest-as-of predicate, including
        the ``where_active`` SCD2 pair, so temporal semantics are
        unchanged. The optional ``open_at_floor`` bounds the index descent
        the same way ``_CANDLE_ID_CACHE_LOOKBACK`` bounds
        :meth:`get_latest_candle_ids`; ``None`` reproduces the unbounded
        read exactly.

        Args:
            instrument_public_ids: Instruments to read. Empty is valid.
            timeframe: Candle timeframe.
            as_of: Snapshot time threading the temporal query.
            limit_per_instrument: Max rows per instrument.
            open_at_floor: Inclusive lower bound on ``open_at``; ``None``
                for an unbounded read.

        Returns:
            Mapping from instrument public ID to rows in DESCENDING
            ``open_at`` order. Instruments with no qualifying row are
            omitted rather than mapped to an empty list.
        """
        if not instrument_public_ids:
            return {}
        result: dict[str, list[CandleRow]] = {}
        async with self.session() as s:
            for instrument_public_id in instrument_public_ids:
                q = select(
                    Candle.open_at,
                    Candle.timeframe,
                    Candle.open,
                    Candle.high,
                    Candle.low,
                    Candle.close,
                    Candle.volume,
                    Candle.vwap,
                    Candle.trades,
                    Candle.source,
                    Candle.complete,
                    Candle.public_id,
                    Candle.timestamp,
                    Candle.session_id,
                    Candle.sequence_id,
                ).where(
                    Candle.instrument_public_id == instrument_public_id,
                    Candle.timeframe == timeframe,
                    Candle.timestamp <= as_of,
                    Candle.known_to > as_of,
                )
                if open_at_floor is not None:
                    q = q.where(Candle.open_at >= open_at_floor)
                q = q.order_by(Candle.open_at.desc()).limit(limit_per_instrument)
                rows = (await s.execute(q)).all()
                if rows:
                    result[instrument_public_id] = [_candle_row_from_result(r) for r in rows]
        return result

    async def get_ticks(
        self,
        instrument: str,
        start: datetime,
        end: datetime,
        exchange: AllExchange,
        as_of: datetime,
        limit: int = DEFAULT_HIGH_CARDINALITY_LIMIT,
    ) -> list[TickRow]:
        """Retrieve ticks for instrument within time range, capped at ``limit``."""
        async with self.session() as s:
            inst = await self._resolve_active_instrument(s, instrument, exchange, as_of)
            if inst is None:
                return []
            q = await s.execute(
                select(
                    Tick.timestamp,
                    Tick.bid,
                    Tick.ask,
                    Tick.last,
                    Tick.volume,
                    Tick.public_id,
                    Tick.session_id,
                    Tick.sequence_id,
                )
                .where(
                    Tick.instrument_public_id == inst.public_id,
                    Tick.timestamp >= start,
                    Tick.timestamp <= end,
                    Tick.timestamp <= as_of,
                    Tick.known_to > as_of,
                )
                .order_by(Tick.timestamp.asc())
                .limit(limit)
            )
            rows = q.all()
            return [
                {
                    "timestamp": r.timestamp,
                    "bid": r.bid,
                    "ask": r.ask,
                    "last": r.last,
                    "volume": r.volume,
                    "public_id": r.public_id,
                    "session_id": r.session_id,
                    "sequence_id": r.sequence_id,
                }
                for r in rows
            ]

    async def iter_ticks(
        self,
        instrument: str,
        start: datetime,
        end: datetime,
        exchange: AllExchange,
        as_of: datetime,
    ) -> AsyncIterator[TickRow]:
        """Stream ticks for instrument in time range without materialising the full result.

        Use this for multi-day replays / backtests where
        :meth:`get_ticks` would OOM. Yields rows in
        ``Tick.timestamp ASC`` order; the SQLAlchemy ``stream`` cursor
        yields ``_HIGH_CARDINALITY_STREAM_CHUNK_SIZE`` rows per
        round-trip so the per-row Python overhead amortises while RSS
        stays flat.
        """
        async with self.session() as s:
            inst = await self._resolve_active_instrument(s, instrument, exchange, as_of)
            if inst is None:
                return
            stmt = (
                select(
                    Tick.timestamp,
                    Tick.bid,
                    Tick.ask,
                    Tick.last,
                    Tick.volume,
                    Tick.public_id,
                    Tick.session_id,
                    Tick.sequence_id,
                )
                .where(
                    Tick.instrument_public_id == inst.public_id,
                    Tick.timestamp >= start,
                    Tick.timestamp <= end,
                    Tick.timestamp <= as_of,
                    Tick.known_to > as_of,
                )
                .order_by(Tick.timestamp.asc())
                .execution_options(yield_per=_HIGH_CARDINALITY_STREAM_CHUNK_SIZE)
            )
            stream = await s.stream(stmt)
            async for r in stream:
                yield {
                    "timestamp": r.timestamp,
                    "bid": r.bid,
                    "ask": r.ask,
                    "last": r.last,
                    "volume": r.volume,
                    "public_id": r.public_id,
                    "session_id": r.session_id,
                    "sequence_id": r.sequence_id,
                }

    async def iter_trades(
        self,
        instrument: str,
        start: datetime,
        end: datetime,
        exchange: AllExchange,
        as_of: datetime,
    ) -> AsyncIterator[TradeRow]:
        """Stream trades for instrument in time range without materialising the full result.

        Companion to :meth:`iter_ticks` for the equally-high-cardinality
        Trade table. Yields rows in ``executed_at`` order so PostgreSQL
        can prune daily partitions. The primary-key ``id`` is a secondary
        sort key so trades sharing an event time always stream in a stable
        order; without it, ties reorder across queries and the order-dependent
        float accumulation of trade-built candle vwap/volume drifts by a ULP,
        making the candle backfill non-idempotent.
        """
        async with self.session() as s:
            inst = await self._resolve_active_instrument(s, instrument, exchange, as_of)
            if inst is None:
                return
            event_time = Trade.executed_at
            stmt = (
                select(
                    Trade.timestamp,
                    Trade.executed_at,
                    Trade.price,
                    Trade.size,
                    Trade.side,
                    Trade.trade_id,
                )
                .where(
                    Trade.instrument_public_id == inst.public_id,
                    event_time >= start,
                    event_time <= end,
                    Trade.timestamp <= as_of,
                    Trade.known_to > as_of,
                )
                .order_by(event_time.asc(), Trade.id.asc())
                .execution_options(yield_per=_HIGH_CARDINALITY_STREAM_CHUNK_SIZE)
            )
            stream = await s.stream(stmt)
            async for r in stream:
                yield {
                    "timestamp": r.timestamp,
                    "executed_at": r.executed_at,
                    "price": r.price,
                    "size": r.size,
                    "side": r.side,
                    "trade_id": r.trade_id,
                }

    async def iter_exchange_trades(
        self,
        exchange: str,
        start: datetime,
        end: datetime,
        as_of: datetime,
        instrument_public_ids: list[str] | None = None,
    ) -> AsyncIterator[tuple[str, TradeRow]]:
        """Stream trades for an exchange in grouped deterministic order.

        The stream is ordered by instrument first so callers can fold one
        bounded in-memory builder at a time, then by event time and primary
        key so trade-built candle arithmetic is reproducible across reruns.
        When ``instrument_public_ids`` is provided, it is treated as the
        already-resolved exchange instrument set and avoids extra temporal
        joins on the high-cardinality read path.
        """
        if instrument_public_ids is not None and not instrument_public_ids:
            return
        async with self.session() as s:
            event_time = Trade.executed_at
            stmt = select(
                Trade.instrument_public_id,
                Trade.timestamp,
                Trade.executed_at,
                Trade.price,
                Trade.size,
                Trade.side,
                Trade.trade_id,
            ).where(
                event_time >= start,
                event_time <= end,
                Trade.timestamp <= as_of,
                Trade.known_to > as_of,
            )
            if instrument_public_ids is None:
                s_ts, s_kt = where_active(Symbol, as_of)
                i_ts, i_kt = where_active(Instrument, as_of)
                stmt = (
                    stmt.join(Instrument, Instrument.public_id == Trade.instrument_public_id)
                    .join(Symbol, Symbol.public_id == Instrument.symbol_public_id)
                    .where(
                        Instrument.exchange == exchange,
                        s_ts,
                        s_kt,
                        i_ts,
                        i_kt,
                    )
                )
            else:
                stmt = stmt.where(Trade.instrument_public_id.in_(tuple(instrument_public_ids)))
            stmt = stmt.order_by(
                Trade.instrument_public_id.asc(),
                event_time.asc(),
                Trade.id.asc(),
            ).execution_options(yield_per=_HIGH_CARDINALITY_STREAM_CHUNK_SIZE)
            stream = await s.stream(stmt)
            async for r in stream:
                yield (
                    r.instrument_public_id,
                    {
                        "timestamp": r.timestamp,
                        "executed_at": r.executed_at,
                        "price": r.price,
                        "size": r.size,
                        "side": r.side,
                        "trade_id": r.trade_id,
                    },
                )

    async def iter_market_snapshots(
        self,
        instrument_public_ids: list[str],
        start: datetime,
        end: datetime,
        as_of: datetime,
    ) -> AsyncIterator[MarketSnapshotRow]:
        """Stream market snapshots in time order without materialising the full result.

        Companion to :meth:`iter_ticks` and :meth:`iter_trades` for
        the snapshot table. Paper-mode ticker replays over long
        windows used to materialise the entire range via
        :meth:`get_market_snapshots`; that bounded-list contract
        remains for UI / one-shot lookups while large-window replays
        prefer this streaming variant. ``yield_per`` chunks rows from
        the database so RSS stays flat across multi-day windows.

        Args:
            instrument_public_ids: Instruments to include.
            start: Lower bound (inclusive, event time).
            end: Upper bound (inclusive, event time).
            as_of: SCD2 ``known_to`` cutoff (bitemporal read).

        Yields:
            Snapshot rows in ``timestamp ASC`` order. Empty input
            list short-circuits without opening a session.
        """
        if not instrument_public_ids:
            return
        async with self.session() as s:
            stmt = (
                select(
                    MarketSnapshot.timestamp,
                    MarketSnapshot.instrument_public_id,
                    MarketSnapshot.bid,
                    MarketSnapshot.bid_volume,
                    MarketSnapshot.ask,
                    MarketSnapshot.ask_volume,
                    MarketSnapshot.last_price,
                    MarketSnapshot.volume_24h,
                    MarketSnapshot.vwap_24h,
                    MarketSnapshot.low_24h,
                    MarketSnapshot.high_24h,
                )
                .where(
                    MarketSnapshot.instrument_public_id.in_(instrument_public_ids),
                    MarketSnapshot.timestamp >= start,
                    MarketSnapshot.timestamp <= end,
                    MarketSnapshot.timestamp <= as_of,
                    MarketSnapshot.known_to > as_of,
                )
                .order_by(MarketSnapshot.timestamp.asc())
                .execution_options(yield_per=_HIGH_CARDINALITY_STREAM_CHUNK_SIZE)
            )
            stream = await s.stream(stmt)
            async for r in stream:
                yield {
                    "ts": r.timestamp,
                    "instrument_public_id": r.instrument_public_id,
                    "bid": r.bid,
                    "bid_volume": r.bid_volume,
                    "ask": r.ask,
                    "ask_volume": r.ask_volume,
                    "last": r.last_price,
                    "volume": r.volume_24h,
                    "vwap": r.vwap_24h,
                    "low": r.low_24h,
                    "high": r.high_24h,
                }

    async def get_market_snapshots(
        self,
        instrument_public_ids: list[str],
        start: datetime,
        end: datetime,
        as_of: datetime,
    ) -> list[MarketSnapshotRow]:
        """Retrieve active market snapshots for instruments in time range."""
        now = as_of
        async with self.session() as s:
            q = await s.execute(
                select(
                    MarketSnapshot.timestamp,
                    MarketSnapshot.instrument_public_id,
                    MarketSnapshot.bid,
                    MarketSnapshot.bid_volume,
                    MarketSnapshot.ask,
                    MarketSnapshot.ask_volume,
                    MarketSnapshot.last_price,
                    MarketSnapshot.volume_24h,
                    MarketSnapshot.vwap_24h,
                    MarketSnapshot.low_24h,
                    MarketSnapshot.high_24h,
                )
                .where(
                    MarketSnapshot.instrument_public_id.in_(instrument_public_ids),
                    MarketSnapshot.timestamp >= start,
                    MarketSnapshot.timestamp <= end,
                    MarketSnapshot.timestamp <= now,
                    MarketSnapshot.known_to > now,
                )
                .order_by(MarketSnapshot.timestamp.asc())
            )
            rows = q.all()
            return [
                {
                    "ts": r.timestamp,
                    "instrument_public_id": r.instrument_public_id,
                    "bid": r.bid,
                    "bid_volume": r.bid_volume,
                    "ask": r.ask,
                    "ask_volume": r.ask_volume,
                    "last": r.last_price,
                    "volume": r.volume_24h,
                    "vwap": r.vwap_24h,
                    "low": r.low_24h,
                    "high": r.high_24h,
                }
                for r in rows
            ]

    async def upsert_market_snapshots(self, rows: list[MarketSnapshotUpsertRow]) -> int:
        """SCD2 close+insert for market snapshots.

        One active row per instrument_public_id.  Closes the existing
        active snapshot and inserts a new version with the same public_id.

        Bulk-loads existing SCD2 versions for the incoming batch in chunks
        of ``_SNAPSHOT_LOOKUP_CHUNK_SIZE`` instruments — replaces the legacy
        per-row SELECT/UPDATE/INSERT N+1 path on the publisher hot loop.
        Rows that share an instrument_public_id within the same incoming
        batch fall back to the sequential close+insert flow because earlier
        rows in the same call may create the version a later row needs to
        close.
        """
        if not rows:
            return 0
        for r in rows:
            if "public_id" not in r:
                r["public_id"] = str(uuid7())
            if "known_to" not in r:
                r["known_to"] = KNOWN_TO_MAX
        async with self.session() as s:
            unique_rows, sequential_rows = self._split_snapshot_rows_by_duplicate_key(rows)
            existing_by_key = await self._load_existing_snapshots_for_rows(s, unique_rows)
            count = await self._upsert_unique_snapshot_rows(s, unique_rows, existing_by_key)
            for r in sequential_rows:
                await self._upsert_snapshot_row(s, r)
                count += 1
            await s.commit()
        return count

    @staticmethod
    def _snapshot_natural_key(row: MarketSnapshotUpsertRow) -> _SnapshotNaturalKey:
        """Return the SCD2 natural key for a market-snapshot upsert row."""
        return row["instrument_public_id"]

    @classmethod
    def _split_snapshot_rows_by_duplicate_key(
        cls,
        rows: list[MarketSnapshotUpsertRow],
    ) -> tuple[list[MarketSnapshotUpsertRow], list[MarketSnapshotUpsertRow]]:
        """Separate rows safe for batch lookup from duplicate-key rows.

        Rows sharing a natural key in the same incoming batch must keep
        the sequential close+insert flow because earlier rows can create
        the version that later rows need to close.
        """
        seen: set[_SnapshotNaturalKey] = set()
        duplicate_keys: set[_SnapshotNaturalKey] = set()
        for row in rows:
            key = cls._snapshot_natural_key(row)
            if key in seen:
                duplicate_keys.add(key)
            seen.add(key)
        if not duplicate_keys:
            return rows, []
        unique_rows = [row for row in rows if cls._snapshot_natural_key(row) not in duplicate_keys]
        sequential_rows = [row for row in rows if cls._snapshot_natural_key(row) in duplicate_keys]
        return unique_rows, sequential_rows

    @classmethod
    async def _load_existing_snapshots_for_rows(
        cls,
        session: AsyncSession,
        rows: list[MarketSnapshotUpsertRow],
    ) -> dict[_SnapshotNaturalKey, MarketSnapshot]:
        """Load existing SCD2 snapshot versions for unique-key rows in one query."""
        if not rows:
            return {}
        row_by_key = {cls._snapshot_natural_key(row): row for row in rows}
        keys = list(row_by_key)
        existing_by_key: dict[_SnapshotNaturalKey, MarketSnapshot] = {}
        for offset in range(0, len(keys), _SNAPSHOT_LOOKUP_CHUNK_SIZE):
            key_chunk = keys[offset : offset + _SNAPSHOT_LOOKUP_CHUNK_SIZE]
            row_chunk = [row_by_key[key] for key in key_chunk]
            min_timestamp = min(row["timestamp"] for row in row_chunk)
            max_timestamp = max(row["timestamp"] for row in row_chunk)
            result = await session.execute(
                select(MarketSnapshot)
                .where(
                    MarketSnapshot.instrument_public_id.in_(key_chunk),
                    MarketSnapshot.timestamp <= max_timestamp,
                    MarketSnapshot.known_to > min_timestamp,
                )
                .with_for_update()
            )
            for snap in result.scalars().all():
                key = snap.instrument_public_id
                row = row_by_key[key]
                bus_time = row["timestamp"]
                if snap.timestamp <= bus_time and snap.known_to > bus_time:
                    existing_by_key[key] = snap
        return existing_by_key

    @classmethod
    async def _upsert_unique_snapshot_rows(
        cls,
        session: AsyncSession,
        rows: list[MarketSnapshotUpsertRow],
        existing_by_key: dict[_SnapshotNaturalKey, MarketSnapshot],
    ) -> int:
        """Close matched snapshot rows and stage inserts for unique-key rows."""
        for row in rows:
            existing = existing_by_key.get(cls._snapshot_natural_key(row))
            if existing is not None:
                await session.execute(
                    update(MarketSnapshot)
                    .where(MarketSnapshot.id == existing.id)
                    .values(known_to=row["timestamp"])
                )
                row["public_id"] = existing.public_id
            session.add(MarketSnapshot(**row))
        return len(rows)

    @classmethod
    async def _upsert_snapshot_row(
        cls,
        session: AsyncSession,
        row: MarketSnapshotUpsertRow,
    ) -> None:
        """Run the sequential SCD2 close+insert path for one snapshot row."""
        bus_time = row["timestamp"]
        existing = (
            (
                await session.execute(
                    select(MarketSnapshot)
                    .where(
                        MarketSnapshot.instrument_public_id == row["instrument_public_id"],
                        MarketSnapshot.timestamp <= bus_time,
                        MarketSnapshot.known_to > bus_time,
                    )
                    .with_for_update()
                )
            )
            .scalars()
            .first()
        )
        if existing:
            await session.execute(
                update(MarketSnapshot)
                .where(MarketSnapshot.id == existing.id)
                .values(known_to=bus_time)
            )
            row["public_id"] = existing.public_id
        session.add(MarketSnapshot(**row))

    async def get_exchanges(self, as_of: datetime) -> list[str]:
        """Return distinct exchange names from active symbol aliases."""
        async with self.session() as s:
            result = await s.execute(
                select(distinct(SymbolAlias.exchange))
                .where(*where_active(SymbolAlias, as_of))
                .order_by(SymbolAlias.exchange)
            )
            return list(result.scalars().all())

    async def get_exchange_instruments(self, exchange: str, as_of: datetime) -> list[str]:
        """Return distinct native symbols available on a given exchange."""
        async with self.session() as s:
            result = await s.execute(
                select(distinct(Symbol.native_symbol))
                .select_from(SymbolAlias)
                .join(Symbol, Symbol.public_id == SymbolAlias.symbol_public_id)
                .where(
                    SymbolAlias.exchange == exchange,
                    *where_active(SymbolAlias, as_of),
                    *where_active(Symbol, as_of),
                )
                .order_by(Symbol.native_symbol)
            )
            return list(result.scalars().all())

    async def get_exchange_instruments_detail(
        self,
        exchange: str,
        as_of: datetime,
    ) -> list[InstrumentDetailRow]:
        """Return capability-aware instrument rows for a given exchange.

        Single joined query over four temporal tables at ``as_of``:

        1. ``Symbol`` (native symbol + asset type)
        2. ``SymbolExchangeCapability`` (can_trade + can_market_data)
        3. ``Instrument`` (instrument_public_id) — outer joined so that
           capability rows without a synced Instrument row still surface
           (``instrument_public_id`` defaults to ``symbol_public_id`` so
           the frontend still has a stable identifier).
        4. ``InstrumentSpec`` (instrument_kind + expiry_at) — outer joined
           so specs that don't exist yet (FCM catalog load lag) do not
           hide the instrument.

        ``where_active`` predicates apply to each table so all rows come
        from the same point-in-time snapshot.
        """
        async with self.session() as s:
            sym_ts, sym_kt = where_active(Symbol, as_of)
            cap_ts, cap_kt = where_active(SymbolExchangeCapability, as_of)
            inst_ts, inst_kt = where_active(Instrument, as_of)
            spec_ts, spec_kt = where_active(InstrumentSpec, as_of)
            query = (
                select(
                    Symbol.public_id.label("symbol_public_id"),
                    Symbol.native_symbol.label("symbol"),
                    SymbolExchangeCapability.can_trade.label("can_trade"),
                    SymbolExchangeCapability.can_market_data.label("can_market_data"),
                    Instrument.public_id.label("instrument_public_id"),
                    InstrumentSpec.instrument_kind.label("instrument_kind"),
                    InstrumentSpec.expiry_at.label("expiry_at"),
                )
                .select_from(SymbolExchangeCapability)
                .join(
                    Symbol,
                    Symbol.public_id == SymbolExchangeCapability.symbol_public_id,
                )
                .outerjoin(
                    Instrument,
                    (Instrument.symbol_public_id == Symbol.public_id)
                    & (Instrument.exchange == SymbolExchangeCapability.exchange)
                    & inst_ts
                    & inst_kt,
                )
                .outerjoin(
                    InstrumentSpec,
                    (InstrumentSpec.instrument_public_id == Instrument.public_id)
                    & spec_ts
                    & spec_kt,
                )
                .where(
                    SymbolExchangeCapability.exchange == exchange,
                    cap_ts,
                    cap_kt,
                    sym_ts,
                    sym_kt,
                )
                .order_by(Symbol.native_symbol)
            )
            result = await s.execute(query)
            rows: list[InstrumentDetailRow] = []
            for row in result.mappings().all():
                symbol_pid = str(row["symbol_public_id"])
                instrument_pid = row["instrument_public_id"]
                instrument_resolved = instrument_pid is not None
                rows.append(
                    {
                        "instrument_public_id": (
                            str(instrument_pid) if instrument_resolved else symbol_pid
                        ),
                        "symbol_public_id": symbol_pid,
                        "symbol": str(row["symbol"]),
                        "exchange": exchange,
                        "can_trade": bool(row["can_trade"]),
                        "can_market_data": bool(row["can_market_data"]),
                        "instrument_resolved": instrument_resolved,
                        "instrument_kind": row["instrument_kind"],
                        "expiry_at": row["expiry_at"],
                    }
                )
            return rows

    async def get_signals(
        self,
        since: datetime,
        limit: int,
        as_of: datetime,
        instrument: str | None = None,
        strategy: str | None = None,
        exchange: str | None = None,
        wallet_public_ids: list[str] | None = None,
    ) -> list[SignalRow]:
        """Retrieve signals with optional filters."""
        async with self.session() as s:
            query = (
                select(Signal, Instrument, Symbol)
                .join(
                    Instrument,
                    and_(
                        Signal.instrument_public_id == Instrument.public_id,
                        *where_active(Instrument, as_of),
                    ),
                )
                .join(
                    Symbol,
                    and_(
                        Instrument.symbol_public_id == Symbol.public_id,
                        *where_active(Symbol, as_of),
                    ),
                )
                .where(
                    Signal.fired_at >= since,
                    *where_active(Signal, as_of),
                )
            )
            if wallet_public_ids is not None:
                query = query.where(Signal.wallet_public_id.in_(wallet_public_ids))
            if instrument:
                s_ts, s_kt = where_active(Symbol, as_of)
                sym_subq = (
                    select(Symbol.public_id)
                    .where(Symbol.native_symbol == instrument, s_ts, s_kt)
                    .scalar_subquery()
                )
                query = query.where(Instrument.symbol_public_id == sym_subq)
            if strategy:
                query = query.where(Signal.strategy_name == strategy)
            if exchange:
                query = query.where(Instrument.exchange == exchange)
            query = query.order_by(desc(Signal.fired_at)).limit(limit)
            result = await s.execute(query)
            return [
                {
                    "public_id": sig.public_id,
                    "timestamp": sig.timestamp,
                    "session_id": sig.session_id,
                    "sequence_id": sig.sequence_id,
                    "instrument": sym.native_symbol,
                    "exchange": inst.exchange,
                    "side": sig.side,
                    "strength": sig.strength,
                    "reason": sig.reason,
                    "strategy_name": sig.strategy_name,
                    "price": sig.price,
                    "fired_at": sig.fired_at,
                    "wallet_public_id": sig.wallet_public_id,
                    "operator_public_id": sig.operator_public_id,
                }
                for sig, inst, sym in result.all()
            ]

    async def get_orders(
        self,
        limit: int,
        offset: int,
        as_of: datetime,
        symbol: str | None = None,
        exchange: str | None = None,
        status: str | None = None,
        wallet_public_ids: list[str] | None = None,
    ) -> list[OrderRow]:
        """Retrieve orders with optional filters and pagination.

        ``status`` is pushed INTO SQL — post-fetch filtering broke
        pagination because limit/offset clipped before the filter could
        discard non-matching rows. ``OrderRow`` carries ``plan_public_id``
        so the MCP ``get_order_status`` tool can resolve the parent
        execution plan without a second round-trip.
        """
        async with self.session() as s:
            query = (
                select(Order, Instrument, Symbol)
                .join(
                    Instrument,
                    and_(
                        Order.instrument_public_id == Instrument.public_id,
                        *where_active(Instrument, as_of),
                    ),
                )
                .join(
                    Symbol,
                    and_(
                        Instrument.symbol_public_id == Symbol.public_id,
                        *where_active(Symbol, as_of),
                    ),
                )
                .where(*where_active(Order, as_of))
            )
            if wallet_public_ids is not None:
                query = query.where(Order.wallet_public_id.in_(wallet_public_ids))
            if symbol:
                s_ts, s_kt = where_active(Symbol, as_of)
                sym_subq = (
                    select(Symbol.public_id)
                    .where(Symbol.native_symbol == symbol, s_ts, s_kt)
                    .scalar_subquery()
                )
                query = query.where(Instrument.symbol_public_id == sym_subq)
            if exchange:
                query = query.where(Instrument.exchange == exchange)
            if status is not None:
                query = query.where(Order.status == status)
            query = query.order_by(desc(Order.created_at)).offset(offset).limit(limit)
            result = await s.execute(query)
            return [
                {
                    "public_id": order.public_id,
                    "timestamp": order.timestamp,
                    "session_id": order.session_id,
                    "sequence_id": order.sequence_id,
                    "instrument": sym.native_symbol,
                    "exchange": inst.exchange,
                    "mode": order.mode,
                    "client_order_id": order.client_order_id or "",
                    "exchange_order_id": order.exchange_order_id,
                    "created_at": order.created_at,
                    "updated_at": order.updated_at,
                    "side": order.side,
                    "order_type": order.order_type,
                    "price": order.price,
                    "size": order.size,
                    "filled_size": order.filled_size,
                    "average_price": order.average_price,
                    "status": order.status,
                    "time_in_force": order.time_in_force,
                    "error": order.error,
                    "leverage": order.leverage,
                    "reduce_only": order.reduce_only,
                    "wallet_public_id": order.wallet_public_id,
                    "operator_public_id": order.operator_public_id,
                    "plan_public_id": order.plan_public_id,
                }
                for order, inst, sym in result.all()
            ]

    async def get_orders_total_count(
        self,
        as_of: datetime,
        symbol: str | None = None,
        exchange: str | None = None,
        status: str | None = None,
        wallet_public_ids: list[str] | None = None,
    ) -> int:
        """Count orders matching :meth:`get_orders` filter shape."""
        async with self.session() as s:
            query = (
                select(func.count(Order.id))
                .select_from(Order)
                .join(
                    Instrument,
                    and_(
                        Order.instrument_public_id == Instrument.public_id,
                        *where_active(Instrument, as_of),
                    ),
                )
                .where(*where_active(Order, as_of))
            )
            if wallet_public_ids is not None:
                query = query.where(Order.wallet_public_id.in_(wallet_public_ids))
            if symbol:
                s_ts, s_kt = where_active(Symbol, as_of)
                sym_subq = (
                    select(Symbol.public_id)
                    .where(Symbol.native_symbol == symbol, s_ts, s_kt)
                    .scalar_subquery()
                )
                query = query.where(Instrument.symbol_public_id == sym_subq)
            if exchange:
                query = query.where(Instrument.exchange == exchange)
            if status is not None:
                query = query.where(Order.status == status)
            result = await s.execute(query)
            count = result.scalar_one_or_none()
            return int(count or 0)

    async def get_order_by_command_public_id(
        self,
        command_public_id: str,
        as_of: datetime,
    ) -> OrderRow | None:
        """Resolve an order via its command's scoped client_order_id.

        The executor echoes the command's ``client_order_id`` onto the
        orders row for EVERY origin surface (strategy emits stamp
        ``client_order_id = venue_client_id = order_public_id``; manual
        REST/MCP mint a fresh UUID7), so the cid join resolves
        plan-less strategy commands that the historical
        ``plan_public_id`` join could never match (NULL == NULL). The
        cid is scoped defence-in-depth by wallet, mode, and the
        instrument's exchange — ``uq_orders_client_oid`` only enforces
        active uniqueness per ``(instrument, mode, cid)`` and MCP
        authorizes the command's wallet before returning the order.
        The current SYMBOL SPELLING is deliberately not compared:
        stable instrument identity survives symbol renames. A cancel
        command's public_id resolves the ORIGINAL order (cancels
        deliberately reuse its cid) — documented, expected behaviour.
        """
        async with self.session() as s:
            query = (
                select(Order, Instrument, Symbol)
                .select_from(TradeCommand)
                .join(
                    Order,
                    and_(
                        Order.client_order_id == TradeCommand.client_order_id,
                        Order.wallet_public_id == TradeCommand.wallet_public_id,
                        Order.mode == TradeCommand.mode,
                        *where_active(Order, as_of),
                    ),
                )
                .join(
                    Instrument,
                    and_(
                        Order.instrument_public_id == Instrument.public_id,
                        Instrument.exchange == TradeCommand.exchange,
                        *where_active(Instrument, as_of),
                    ),
                )
                .join(
                    Symbol,
                    and_(
                        Instrument.symbol_public_id == Symbol.public_id,
                        *where_active(Symbol, as_of),
                    ),
                )
                .where(
                    TradeCommand.public_id == command_public_id,
                    *where_active(TradeCommand, as_of),
                )
                .order_by(desc(Order.created_at), desc(Order.id))
                .limit(1)
            )
            result = await s.execute(query)
            row = result.first()
            if row is None:
                return None
            order, inst, sym = row
            return {
                "public_id": order.public_id,
                "timestamp": order.timestamp,
                "session_id": order.session_id,
                "sequence_id": order.sequence_id,
                "instrument": sym.native_symbol,
                "exchange": inst.exchange,
                "mode": order.mode,
                "client_order_id": order.client_order_id or "",
                "exchange_order_id": order.exchange_order_id,
                "created_at": order.created_at,
                "updated_at": order.updated_at,
                "side": order.side,
                "order_type": order.order_type,
                "price": order.price,
                "size": order.size,
                "filled_size": order.filled_size,
                "average_price": order.average_price,
                "status": order.status,
                "time_in_force": order.time_in_force,
                "error": order.error,
                "leverage": order.leverage,
                "reduce_only": order.reduce_only,
                "wallet_public_id": order.wallet_public_id,
                "operator_public_id": order.operator_public_id,
                "plan_public_id": order.plan_public_id,
            }

    async def get_trade_command_by_public_id(
        self,
        command_public_id: str,
        as_of: datetime,
    ) -> TradeCommandRow | None:
        """Fetch a single trade-command row by public_id."""
        async with self.session() as s:
            result = await s.execute(
                select(TradeCommand)
                .where(
                    TradeCommand.public_id == command_public_id,
                    *where_active(TradeCommand, as_of),
                )
                .limit(1)
            )
            cmd = result.scalars().first()
            if cmd is None:
                return None
            return self._trade_command_to_row(cmd)

