    async def ensure_paired_execution_halt(self, row: PairedExecutionHaltInsertRow) -> bool:
        """Insert a paired-execution halt unless an active one already exists.

        Idempotent across racing coordinators that each observe the same
        broken / compensating group on a later scan: the active-unique
        ``uq_peh_scope`` index admits exactly one active halt per
        ``(wallet_public_id, strategy_id, group_key)`` scope. On an
        ``IntegrityError`` the method re-checks for an active halt with that
        scope; if one exists the error was the expected active-unique
        collision and ``False`` is returned, but ANY other integrity failure
        (a malformed row violating a different constraint) is RE-RAISED
        rather than silently swallowed. Mirrors
        :meth:`ensure_paired_execution_group`. Returns ``True`` iff this call
        created the halt.
        """
        async with self.session() as s:
            s.add(PairedExecutionHalt(**row))
            try:
                await s.commit()
            except IntegrityError:
                await s.rollback()
                active_result = await s.execute(
                    select(PairedExecutionHalt.id).where(
                        PairedExecutionHalt.wallet_public_id == row.get("wallet_public_id"),
                        PairedExecutionHalt.strategy_id == row.get("strategy_id"),
                        PairedExecutionHalt.group_key == row.get("group_key"),
                        PairedExecutionHalt.known_to == KNOWN_TO_MAX,
                    )
                )
                active = active_result.first()
                if active is None:
                    raise
                return False
            return True

    async def cas_paired_execution_group_status(
        self,
        public_id: str,
        expected_status: str,
        new_status: str,
        bus_time: datetime,
        session_id: str,
        sequence_id: int,
        updates: PairedExecutionGroupFieldUpdate | None = None,
    ) -> bool:
        """CAS a paired-execution group status via SCD2 close-and-insert.

        ``updates`` may only carry mutable group fields
        (``failure_reason`` / ``halted_at``); any other key — a typo or a
        forbidden SCD2 column such as ``status`` / ``public_id`` /
        ``known_to`` — raises ``ValueError`` before any row is touched, so
        a bad caller can never silently drop a write or corrupt the SCD2
        chain.
        """
        if updates is not None:
            unknown = set(updates) - self._PEG_UPDATABLE_FIELDS
            if unknown:
                raise ValueError(f"unknown paired-execution group update fields: {sorted(unknown)}")
        async with self.session() as s:
            existing = (
                (
                    await s.execute(
                        select(PairedExecutionGroup)
                        .where(
                            PairedExecutionGroup.public_id == public_id,
                            *where_active(PairedExecutionGroup, bus_time),
                        )
                        .with_for_update()
                    )
                )
                .scalars()
                .first()
            )
            if existing is None:
                return False
            if existing.status != expected_status:
                return False
            await s.execute(
                update(PairedExecutionGroup)
                .where(PairedExecutionGroup.id == existing.id)
                .values(known_to=bus_time)
            )
            new_row = PairedExecutionGroup(
                public_id=existing.public_id,
                wallet_public_id=existing.wallet_public_id,
                operator_public_id=existing.operator_public_id,
                strategy_id=existing.strategy_id,
                policy=existing.policy,
                expected_leg_count=existing.expected_leg_count,
                group_key=existing.group_key,
                status=new_status,
                assembly_deadline=existing.assembly_deadline,
                fill_deadline=existing.fill_deadline,
                failure_reason=existing.failure_reason,
                halted_at=existing.halted_at,
                created_at=existing.created_at,
                session_id=session_id,
                sequence_id=sequence_id,
                timestamp=bus_time,
            )
            if updates is not None:
                for key, value in updates.items():
                    setattr(new_row, key, value)
            s.add(new_row)
            await s.commit()
            return True

    async def cas_paired_execution_leg_status(
        self,
        public_id: str,
        expected_status: str,
        new_status: str,
        bus_time: datetime,
        session_id: str,
        sequence_id: int,
        updates: PairedExecutionLegFieldUpdate | None = None,
    ) -> bool:
        """CAS a paired-execution leg status via SCD2 close-and-insert.

        ``updates`` may only carry mutable leg fields (venue ids and the
        signed fill / compensation accounting); any other key — a typo or
        a forbidden SCD2 / identity column — raises ``ValueError`` before
        any row is touched, so a bad caller can never silently drop a
        write or corrupt the SCD2 chain.
        """
        if updates is not None:
            unknown = set(updates) - self._PEL_UPDATABLE_FIELDS
            if unknown:
                raise ValueError(f"unknown paired-execution leg update fields: {sorted(unknown)}")
        async with self.session() as s:
            existing = (
                (
                    await s.execute(
                        select(PairedExecutionLeg)
                        .where(
                            PairedExecutionLeg.public_id == public_id,
                            *where_active(PairedExecutionLeg, bus_time),
                        )
                        .with_for_update()
                    )
                )
                .scalars()
                .first()
            )
            if existing is None:
                return False
            if existing.status != expected_status:
                return False
            await s.execute(
                update(PairedExecutionLeg)
                .where(PairedExecutionLeg.id == existing.id)
                .values(known_to=bus_time)
            )
            new_row = PairedExecutionLeg(
                public_id=existing.public_id,
                group_public_id=existing.group_public_id,
                leg_index=existing.leg_index,
                exchange=existing.exchange,
                mode=existing.mode,
                instrument=existing.instrument,
                shard_key=existing.shard_key,
                side=existing.side,
                target_qty=existing.target_qty,
                signal_public_id=existing.signal_public_id,
                command_public_id=existing.command_public_id,
                client_order_id=existing.client_order_id,
                exchange_order_id=existing.exchange_order_id,
                status=new_status,
                filled_signed_qty=existing.filled_signed_qty,
                compensated_signed_qty=existing.compensated_signed_qty,
                compensation_seq=existing.compensation_seq,
                last_venue_event_id=existing.last_venue_event_id,
                wallet_public_id=existing.wallet_public_id,
                operator_public_id=existing.operator_public_id,
                created_at=existing.created_at,
                session_id=session_id,
                sequence_id=sequence_id,
                timestamp=bus_time,
            )
            if updates is not None:
                for key, value in updates.items():
                    setattr(new_row, key, value)
            s.add(new_row)
            await s.commit()
            return True

    async def project_paired_execution_leg_fill(
        self,
        client_order_id: str,
        filled_signed_qty: float,
        new_status: str,
        bus_time: datetime,
        session_id: str,
        sequence_id: int,
        exchange_order_id: str | None = None,
        last_venue_event_id: int | None = None,
    ) -> PairedFillProjection:
        """Project a venue fill onto the CURRENT active paired-execution leg.

        Resolves the leg by its ``client_order_id`` (the leg's ORIGINAL order
        id; a non-grouped fill matches no leg and returns
        :attr:`PairedFillProjection.NO_MATCH`, the signal the live hook uses to
        then try the compensation projection). Guards the CURRENT active row
        (``known_to == KNOWN_TO_MAX``) under ``FOR UPDATE`` and applies MONOTONIC
        cumulative accounting: ``filled_signed_qty`` is replaced only when the
        incoming signed cumulative MAGNITUDE strictly exceeds the stored one, so
        a duplicate / out-of-order replay never regresses the leg. On apply it
        SCD2 close-and-inserts the successor carrying the new
        ``filled_signed_qty`` / ``status`` / ``exchange_order_id`` /
        ``last_venue_event_id`` (and all other columns forward). Returns
        :attr:`PairedFillProjection.ORIGINAL_APPLIED` iff a successor was
        written, :attr:`~PairedFillProjection.ORIGINAL_NOOP` when a leg matched
        but the monotonic guard left it unchanged, and
        :attr:`~PairedFillProjection.NO_MATCH` when no leg owns the order.

        A late ORIGINAL fill that arrives AFTER the leg went post-break is
        NOT dropped — the monotonic update still applies
        (real venue exposure only grows), and the successor status follows
        :meth:`_late_original_fill_status`: a ``flattened`` / ``broken`` leg whose
        ``open_qty`` reappears goes back to ``filled`` so the compensation sweep
        re-flattens the residual on the next ``compensation_seq``; a
        ``compensating`` leg (a flatten is in flight) keeps ``compensating`` to
        avoid a double-flatten; ``cancelled`` / ``expired`` / ``rejected`` keep
        their status (the sweep already flattens those); and
        ``manual_intervention`` keeps its status (the operator owns it). A normal
        in-flight leg uses the venue ``new_status`` as before.

        A late growing fill that lands while the leg's GROUP is already
        ``completed`` additionally reopens the group to
        ``compensating`` in the SAME transaction whenever the leg's resulting
        ``open_qty`` is non-zero — the guard scanner never lists completed
        groups (terminal-status listing is unbounded), so without the reopen
        the re-exposed leg would be invisible forever. LOCK ORDER: the
        completion DAL locks group THEN legs, so the reopen path here also
        locks the GROUP FIRST and only then the leg
        (:meth:`_project_original_fill_grouped`); the common path keeps
        today's leg-only lock (:meth:`_project_original_fill_fast`) and never
        waits on a group lock, so no lock cycle exists. The fast path detects
        a completed group with a NON-LOCKING read just before writing and
        retries once through the group-first path, closing the race where the
        group completes between the read and the leg lock.

        Unlike the generic :func:`close_and_insert` helper (which matches the
        predecessor with a temporal ``timestamp <= bus_time`` filter and so
        silently skips a future-stamped row), this method matches the CURRENT
        active row regardless of its ``timestamp`` — recovery deliberately
        re-projects a leg armed by a sibling coordinator whose clock ran
        slightly ahead. To keep the SCD2 validity intervals non-inverted in
        that clock-skew case, the close / successor bus time is clamped to
        ``max(bus_time, existing.timestamp)``: the predecessor's ``known_to``
        is never set before its own ``timestamp`` and the successor is never
        backdated before its predecessor. In the normal case
        (``bus_time >= existing.timestamp``) the clamp is a no-op.
        """
        result = await self._project_original_fill_fast(
            client_order_id,
            filled_signed_qty,
            new_status,
            bus_time,
            session_id,
            sequence_id,
            exchange_order_id,
            last_venue_event_id,
        )
        if result is not None:
            return result
        return await self._project_original_fill_grouped(
            client_order_id,
            filled_signed_qty,
            new_status,
            bus_time,
            session_id,
            sequence_id,
            exchange_order_id,
            last_venue_event_id,
        )

    async def _project_original_fill_fast(
        self,
        client_order_id: str,
        filled_signed_qty: float,
        new_status: str,
        bus_time: datetime,
        session_id: str,
        sequence_id: int,
        exchange_order_id: str | None,
        last_venue_event_id: int | None,
    ) -> PairedFillProjection | None:
        """Apply an original fill under the leg-only lock, or defer to the group path.

        This is the common path and keeps the pre-5d.3 locking exactly: the
        CURRENT active leg is locked ``FOR UPDATE`` by ``client_order_id`` and
        no group lock is ever taken, so it can never participate in a lock
        cycle with the completion DAL (which locks group then legs). Just
        before writing, when the resulting ``open_qty`` is non-zero, the
        group's status is read WITHOUT a lock; a ``completed`` group means the
        write must also reopen the group, which requires the group-first lock
        order — so this path returns ``None`` (nothing written, the session
        discards the close) and the caller retries through
        :meth:`_project_original_fill_grouped`. Every other outcome is final.
        """
        async with self.session() as s:
            existing = await self._lock_leg_by_client_order_id(s, client_order_id)
            if existing is None:
                return PairedFillProjection.NO_MATCH
            if abs(filled_signed_qty) <= abs(existing.filled_signed_qty):
                return PairedFillProjection.ORIGINAL_NOOP
            open_qty = filled_signed_qty - existing.compensated_signed_qty
            if abs(open_qty) >= self._PEC_QTY_EPSILON:
                group_status = (
                    await s.execute(
                        select(PairedExecutionGroup.status).where(
                            PairedExecutionGroup.public_id == existing.group_public_id,
                            PairedExecutionGroup.known_to == KNOWN_TO_MAX,
                        )
                    )
                ).scalar_one_or_none()
                if group_status == PairedExecutionGroupStatusEnum.COMPLETED.value:
                    return None
            await self._write_original_fill_successor(
                s,
                existing,
                filled_signed_qty,
                new_status,
                bus_time,
                session_id,
                sequence_id,
                exchange_order_id,
                last_venue_event_id,
            )
            await s.commit()
            return PairedFillProjection.ORIGINAL_APPLIED

    async def _project_original_fill_grouped(
        self,
        client_order_id: str,
        filled_signed_qty: float,
        new_status: str,
        bus_time: datetime,
        session_id: str,
        sequence_id: int,
        exchange_order_id: str | None,
        last_venue_event_id: int | None,
    ) -> PairedFillProjection:
        """Apply an original fill under the group-first lock, reopening if completed.

        The completed-group reopen path: an UNLOCKED peek resolves the leg (and
        its immutable ``group_public_id``), the GROUP is locked ``FOR UPDATE``
        FIRST (matching the completion DAL's lock order, so the two can never
        deadlock), then the leg is locked and every guard re-validated against
        the locked rows. When the locked group is (still) ``completed`` and the
        leg's resulting ``open_qty`` is non-zero, the group is SCD2-reopened to
        ``compensating`` in the same transaction — stamping ``failure_reason``
        / ``halted_at`` if unset — so the next scanner cycle re-halts the scope
        and re-flattens the residual. A group that is no longer ``completed``
        under the lock needs no successor (the scanner already sees it); the
        leg write proceeds either way.
        """
        async with self.session() as s:
            peek = await self._lock_leg_by_client_order_id(s, client_order_id, lock=False)
            if peek is None:
                return PairedFillProjection.NO_MATCH
            group = (
                (
                    await s.execute(
                        select(PairedExecutionGroup)
                        .where(
                            PairedExecutionGroup.public_id == peek.group_public_id,
                            PairedExecutionGroup.known_to == KNOWN_TO_MAX,
                        )
                        .with_for_update()
                    )
                )
                .scalars()
                .first()
            )
            existing = await self._lock_leg_by_client_order_id(s, client_order_id)
            if existing is None:
                return PairedFillProjection.NO_MATCH
            if abs(filled_signed_qty) <= abs(existing.filled_signed_qty):
                return PairedFillProjection.ORIGINAL_NOOP
            await self._write_original_fill_successor(
                s,
                existing,
                filled_signed_qty,
                new_status,
                bus_time,
                session_id,
                sequence_id,
                exchange_order_id,
                last_venue_event_id,
            )
            open_qty = filled_signed_qty - existing.compensated_signed_qty
            if (
                group is not None
                and group.status == PairedExecutionGroupStatusEnum.COMPLETED.value
                and abs(open_qty) >= self._PEC_QTY_EPSILON
            ):
                group_bus_time = max(bus_time, group.timestamp)
                await s.execute(
                    update(PairedExecutionGroup)
                    .where(PairedExecutionGroup.id == group.id)
                    .values(known_to=group_bus_time)
                )
                s.add(
                    PairedExecutionGroup(
                        public_id=group.public_id,
                        wallet_public_id=group.wallet_public_id,
                        operator_public_id=group.operator_public_id,
                        strategy_id=group.strategy_id,
                        policy=group.policy,
                        expected_leg_count=group.expected_leg_count,
                        group_key=group.group_key,
                        status=PairedExecutionGroupStatusEnum.COMPENSATING.value,
                        assembly_deadline=group.assembly_deadline,
                        fill_deadline=group.fill_deadline,
                        failure_reason=group.failure_reason or "late fill after completion",
                        halted_at=group.halted_at or group_bus_time,
                        created_at=group.created_at,
                        session_id=session_id,
                        sequence_id=sequence_id,
                        timestamp=group_bus_time,
                    )
                )
            await s.commit()
            return PairedFillProjection.ORIGINAL_APPLIED

    @staticmethod
    async def _lock_leg_by_client_order_id(
        s: AsyncSession, client_order_id: str, lock: bool = True
    ) -> PairedExecutionLeg | None:
        """Resolve the CURRENT active leg for an original order id, optionally locked.

        Shared by the fast and group-first fill paths. Raises the
        data-integrity ``ValueError`` when two active legs share the
        ``client_order_id`` (the active-unique invariant the fill projection
        has guarded since 5a); returns ``None`` when no leg owns the order.
        ``lock=False`` is the group-first path's unlocked peek (it only needs
        the immutable ``group_public_id`` before taking the group lock).
        """
        stmt = (
            select(PairedExecutionLeg)
            .where(
                PairedExecutionLeg.client_order_id == client_order_id,
                PairedExecutionLeg.known_to == KNOWN_TO_MAX,
            )
            .limit(2)
        )
        if lock:
            stmt = stmt.with_for_update()
        matches = (await s.execute(stmt)).scalars().all()
        if len(matches) > 1:
            raise ValueError(
                "paired-execution data integrity: "
                f"{len(matches)} active legs share client_order_id {client_order_id}"
            )
        return matches[0] if matches else None

    async def _write_original_fill_successor(
        self,
        s: AsyncSession,
        existing: PairedExecutionLeg,
        filled_signed_qty: float,
        new_status: str,
        bus_time: datetime,
        session_id: str,
        sequence_id: int,
        exchange_order_id: str | None,
        last_venue_event_id: int | None,
    ) -> None:
        """Close the locked leg and stage its original-fill SCD2 successor.

        Shared write half of the fast and group-first fill paths: picks the
        successor status via :meth:`_late_original_fill_status`, clamps the
        close / successor bus time to ``max(bus_time, existing.timestamp)``
        and carries the venue ids forward when the caller omitted them. The
        caller commits (its transaction may also carry a group reopen).
        """
        successor_status = self._late_original_fill_status(
            existing.status,
            filled_signed_qty,
            existing.compensated_signed_qty,
            new_status,
        )
        effective_bus_time = max(bus_time, existing.timestamp)
        await s.execute(
            update(PairedExecutionLeg)
            .where(PairedExecutionLeg.id == existing.id)
            .values(known_to=effective_bus_time)
        )
        s.add(
            self._leg_successor(
                existing,
                status=successor_status,
                filled_signed_qty=filled_signed_qty,
                exchange_order_id=(
                    exchange_order_id
                    if exchange_order_id is not None
                    else existing.exchange_order_id
                ),
                last_venue_event_id=(
                    last_venue_event_id
                    if last_venue_event_id is not None
                    else existing.last_venue_event_id
                ),
                session_id=session_id,
                sequence_id=sequence_id,
                timestamp=effective_bus_time,
            )
        )

    @classmethod
    def _late_original_fill_status(
        cls,
        existing_status: str,
        filled_signed_qty: float,
        compensated_signed_qty: float,
        normal_status: str,
    ) -> str:
        """Pick a leg's successor status for a (possibly late) ORIGINAL fill.

        A fill on a leg still in a normal in-flight state (``pending`` / ``armed``
        / ``working`` / ``partially_filled``) uses the venue ``normal_status``
        (``filled`` / ``partially_filled``) as before. A LATE fill that grows
        exposure on a leg already in a fill-terminal state instead
        transitions per the safe re-entry FSM:

        - ``flattened`` / ``broken`` → ``filled`` when ``open_qty`` reappears (so
          the compensation sweep re-flattens the residual on the next
          ``compensation_seq``), else the status is kept.
        - ``compensating`` → kept: a flatten order is in flight, so re-flattening
          now would double-flatten; the residual is settled when that flatten
          terminalizes (:meth:`_apply_leg_compensation`).
        - ``cancelled`` / ``expired`` / ``rejected`` → kept: those are already
          flatten-eligible, so the sweep flattens the grown exposure.
        - ``manual_intervention`` → kept: an operator owns the leg; auto-flatten
          must never override an escalation.
        """
        if existing_status not in cls._PEL_FILL_TERMINAL_STATUSES:
            return normal_status
        if existing_status in cls._PEL_LATE_FILL_REOPEN_STATUSES:
            open_qty = filled_signed_qty - compensated_signed_qty
            if abs(open_qty) >= cls._PEC_QTY_EPSILON:
                return PairedExecutionLegStatusEnum.FILLED.value
        return existing_status

    async def project_paired_execution_compensation_fill(
        self,
        flatten_client_order_id: str,
        bus_time: datetime,
        session_id: str,
        sequence_id: int,
        flatten_terminal: bool = False,
    ) -> PairedFillProjection:
        """Project a reduce-only FLATTEN order's venue event onto its leg's compensation.

        Routes BOTH a flatten order's fill (live fill hook) and its venue terminal
        — cancel / expire / reject (live terminal hook) — since each
        carries the flatten's FRESH ``client_order_id`` and a command whose
        ``supersedes_command_id`` is the leg's ORIGINAL command, so it matches NO
        leg by ``client_order_id`` (the original projection returns ``NO_MATCH``
        and the hook routes here). This resolves the active flatten ``TradeCommand``
        by ``client_order_id`` (a ``reduce_only`` ``submit`` with a non-null
        ``supersedes_command_id``; ``NO_MATCH`` when none, so an ordinary
        reduce-only order that supersedes nothing — or a non-flatten original
        terminal — is ignored), follows ``supersedes_command_id`` to the leg whose
        ``command_public_id`` matches (``NO_MATCH`` when the superseded command is
        not a leg's), then recomputes ``compensated_signed_qty`` and settles the
        leg status from the AUTHORITATIVE ``venue_events`` via
        :meth:`_apply_leg_compensation` (the event is only a trigger — the
        recompute is event-agnostic and replay-safe). ``flatten_terminal`` is set
        by the live terminal hook so a cancel / expire / reject MESSAGE settles its
        leg even before the executor's durable terminal row is visible (it
        publishes the message BEFORE recording the row, and a not-tradeable reject
        records no row at all); the hint only escalates terminality for the order
        the event names, so it cannot reopen a leg whose newer flatten is still
        live. Raises on a data-integrity duplicate (two active commands sharing the
        flatten id); the superseded original command is active-unique on the leg,
        so at most one leg matches. The result is
        :attr:`PairedFillProjection.COMPENSATION_APPLIED` /
        :attr:`~PairedFillProjection.COMPENSATION_NOOP` /
        :attr:`~PairedFillProjection.NO_MATCH`.
        """
        async with self.session() as s:
            commands = (
                (
                    await s.execute(
                        select(TradeCommand)
                        .where(
                            TradeCommand.client_order_id == flatten_client_order_id,
                            TradeCommand.known_to == KNOWN_TO_MAX,
                            TradeCommand.command_type == "submit",
                            TradeCommand.reduce_only.is_(True),
                            TradeCommand.supersedes_command_id.isnot(None),
                        )
                        .limit(2)
                    )
                )
                .scalars()
                .all()
            )
            if len(commands) > 1:
                raise ValueError(
                    "paired-execution data integrity: "
                    f"{len(commands)} active flatten commands share "
                    f"client_order_id {flatten_client_order_id}"
                )
            command = commands[0] if commands else None
            if command is None:
                return PairedFillProjection.NO_MATCH
            leg = (
                (
                    await s.execute(
                        select(PairedExecutionLeg)
                        .where(
                            PairedExecutionLeg.command_public_id == command.supersedes_command_id,
                            PairedExecutionLeg.known_to == KNOWN_TO_MAX,
                        )
                        .with_for_update()
                    )
                )
                .scalars()
                .first()
            )
            if leg is None:
                return PairedFillProjection.NO_MATCH
            return await self._apply_leg_compensation(
                s,
                leg,
                bus_time,
                session_id,
                sequence_id,
                trigger_client_order_id=flatten_client_order_id,
                trigger_terminal=flatten_terminal,
            )

    async def reproject_paired_execution_leg_compensation(
        self,
        leg_public_id: str,
        bus_time: datetime,
        session_id: str,
        sequence_id: int,
    ) -> PairedFillProjection:
        """Recompute one leg's compensated qty from venue_events on startup recovery.

        The live compensation-fill projection only runs on the live fill path, so
        a flatten order that filled while the coordinator was DOWN would recover
        with a stale ``compensated_signed_qty``. This pass re-derives it from the
        AUTHORITATIVE ``venue_events`` for the leg resolved by ``public_id``
        (current-active, ``FOR UPDATE``), mirroring the original-fill recovery
        parity. A leg already projected live is a ``COMPENSATION_NOOP``; a
        downtime flatten fill is restored. Returns ``NO_MATCH`` when the leg is
        gone. The leg ``public_id`` is active-unique, so at most one row matches.
        """
        async with self.session() as s:
            leg = (
                (
                    await s.execute(
                        select(PairedExecutionLeg)
                        .where(
                            PairedExecutionLeg.public_id == leg_public_id,
                            PairedExecutionLeg.known_to == KNOWN_TO_MAX,
                        )
                        .with_for_update()
                    )
                )
                .scalars()
                .first()
            )
            if leg is None:
                return PairedFillProjection.NO_MATCH
            return await self._apply_leg_compensation(s, leg, bus_time, session_id, sequence_id)

    async def _apply_leg_compensation(
        self,
        s: AsyncSession,
        leg: PairedExecutionLeg,
        bus_time: datetime,
        session_id: str,
        sequence_id: int,
        trigger_client_order_id: str | None = None,
        trigger_terminal: bool = False,
    ) -> PairedFillProjection:
        """Recompute and persist a leg's ``compensated_signed_qty`` from venue_events.

        Shared by the live compensation-fill projection and startup recovery, on a
        leg already locked ``FOR UPDATE``. ``compensated_signed_qty`` is the SIGNED
        sum (buy +, sell −) of EVERY reduce-only flatten command superseding the
        leg's ORIGINAL command, NEGATED so it moves toward ``filled_signed_qty``
        under the guard's ``open_qty = filled_signed_qty − compensated_signed_qty``
        convention (a net-long leg flattens by SELLING, so its flatten fills are
        negative and ``compensated`` grows positive toward the positive
        ``filled``). The sign uses the COMMAND side, not the venue-event side, so a
        mislabelled venue echo cannot invert it. Each flatten order contributes its
        MAX cumulative fill (replay-safe and additive across re-compensation
        rounds, unlike a single monotonic scalar whose round-2 order restarts at
        zero). The successor status (when the leg is ``compensating``) is chosen
        by :meth:`_compensation_successor_status`: ``flattened`` when the open
        residual collapses to zero (within :data:`_PEC_QTY_EPSILON`); else, when
        the CURRENT-``compensation_seq`` flatten order has TERMINALIZED (fully
        filled or venue cancel / expire / reject) while exposure remains —
        because a late ORIGINAL fill grew ``filled`` past what that round
        flattened — back to ``filled`` so the sweep re-flattens the residual on
        the NEXT ``compensation_seq``; else ``compensating``
        is kept (a flatten is still in flight — re-flattening now would
        double-flatten). ``manual_intervention`` and every non-``compensating``
        status are carried forward UNCHANGED (auto-flatten must never override an
        operator escalation). Writes an SCD2 successor (bus time clamped to
        ``max(bus_time, leg.timestamp)``) only when the value or status actually
        changes, else returns ``COMPENSATION_NOOP``.

        Settling on the CURRENT-seq flatten's terminality (not the triggering
        event) inherently ignores a STALE terminal for an older round: a late
        duplicate cancel for ``flatten:1`` arriving after ``flatten:2`` is in
        flight recomputes accounting but never reopens, so it cannot cause a
        double-flatten.

        FAILS CLOSED on corruption rather than mis-accounting real money: two
        active flatten commands sharing a ``client_order_id`` would each read the
        SAME venue max-cumulative and double-count it (falsely zeroing ``open_qty``
        and FLATTENING the leg), and an unexpected command ``side`` would be
        silently treated as a buy — both raise ``ValueError`` here instead.
        """
        original_command_id = leg.command_public_id
        if original_command_id is None:
            return PairedFillProjection.COMPENSATION_NOOP
        flatten_orders = (
            await s.execute(
                select(
                    TradeCommand.client_order_id,
                    TradeCommand.side,
                    TradeCommand.idempotency_key,
                    TradeCommand.quantity,
                ).where(
                    TradeCommand.supersedes_command_id == original_command_id,
                    TradeCommand.known_to == KNOWN_TO_MAX,
                    TradeCommand.command_type == "submit",
                    TradeCommand.reduce_only.is_(True),
                )
            )
        ).all()
        current_seq_key = (
            f"paired:{leg.group_public_id}:{leg.public_id}:flatten:{leg.compensation_seq}"
        )
        compensated = 0.0
        seen_orders: set[str] = set()
        current_flatten: tuple[str, float, float] | None = None
        for client_order_id, side, idempotency_key, quantity in flatten_orders:
            if client_order_id in seen_orders:
                raise ValueError(
                    "paired-execution data integrity: duplicate active flatten "
                    f"client_order_id {client_order_id} supersedes command "
                    f"{original_command_id}"
                )
            seen_orders.add(client_order_id)
            if side == TradeSideEnum.SELL.value:
                direction = 1.0
            elif side == TradeSideEnum.BUY.value:
                direction = -1.0
            else:
                raise ValueError(
                    "paired-execution data integrity: flatten command "
                    f"{client_order_id} has unexpected side {side!r}"
                )
            cum_fill = await self._max_cumulative_fill(s, client_order_id)
            if idempotency_key == current_seq_key:
                current_flatten = (client_order_id, quantity, cum_fill)
            if cum_fill <= 0.0:
                continue
            compensated += direction * cum_fill
        current_flatten_terminal = await self._current_flatten_is_terminal(
            s, current_flatten, trigger_client_order_id, trigger_terminal
        )
        new_status = self._compensation_successor_status(leg, compensated, current_flatten_terminal)
        if (
            abs(compensated - leg.compensated_signed_qty) < self._PEC_QTY_EPSILON
            and new_status == leg.status
        ):
            return PairedFillProjection.COMPENSATION_NOOP
        effective_bus_time = max(bus_time, leg.timestamp)
        await s.execute(
            update(PairedExecutionLeg)
            .where(PairedExecutionLeg.id == leg.id)
            .values(known_to=effective_bus_time)
        )
        s.add(
            self._leg_successor(
                leg,
                status=new_status,
                filled_signed_qty=leg.filled_signed_qty,
                exchange_order_id=leg.exchange_order_id,
                last_venue_event_id=leg.last_venue_event_id,
                session_id=session_id,
                sequence_id=sequence_id,
                timestamp=effective_bus_time,
                compensated_signed_qty=compensated,
            )
        )
        await s.commit()
        return PairedFillProjection.COMPENSATION_APPLIED

    def _compensation_successor_status(
        self,
        leg: PairedExecutionLeg,
        compensated: float,
        current_flatten_terminal: bool,
    ) -> str:
        """Pick a compensating leg's successor status from its recomputed exposure.

        Only a ``compensating`` leg transitions (every other status is carried
        forward, so an operator ``manual_intervention`` is never auto-cleared).
        For a ``compensating`` leg: a zero open residual settles to ``flattened``;
        otherwise, if the CURRENT-``compensation_seq`` flatten order has
        terminalized while exposure remains, the leg reopens to ``filled`` so the
        sweep re-flattens the residual on the next round; otherwise the flatten is
        still in flight and ``compensating`` is kept (re-flattening now would
        double-flatten).
        """
        if leg.status != PairedExecutionLegStatusEnum.COMPENSATING.value:
            return leg.status
        open_qty = leg.filled_signed_qty - compensated
        if abs(open_qty) < self._PEC_QTY_EPSILON:
            return PairedExecutionLegStatusEnum.FLATTENED.value
        if current_flatten_terminal:
            return PairedExecutionLegStatusEnum.FILLED.value
        return leg.status

    async def _current_flatten_is_terminal(
        self,
        s: AsyncSession,
        current_flatten: tuple[str, float, float] | None,
        trigger_client_order_id: str | None,
        trigger_terminal: bool,
    ) -> bool:
        """Return whether the leg's CURRENT-seq flatten order has terminalized.

        Terminal when, for the current-seq flatten order
        (``current_flatten = (client_order_id, quantity, max_cum_fill)``): the
        TRIGGERING live event is itself this order's terminal (``trigger_terminal``
        for the matching ``client_order_id``) — which closes the executor's
        publish-BEFORE-record window where a reject message reaches the trader
        before its durable ``order_rejected`` row — OR the AUTHORITATIVE
        ``venue_events`` already record it as fully filled (max cumulative fill
        reached its ``quantity`` within :data:`_PEC_QTY_EPSILON`) or carry a
        durable ``order_terminal`` (cancel / expire) / ``order_rejected`` event.
        The DB clause makes the determination identical live and on restart /
        scanner-backstop recovery (where no live message exists), and replay-safe;
        the trigger clause only ever ESCALATES terminality for the current-seq
        order, so it cannot reopen a leg whose newer flatten is still live.

        RESIDUAL (accepted, fail-safe): a flatten rejected LOCALLY as not-tradeable
        records NO durable ``venue_events`` row (only the exchange / exception
        reject paths do) and fires only a live message. If that message is also
        missed (coordinator down), no durable terminality signal exists and the leg
        stays ``compensating`` + HALTED until an operator / reconciliation resolves
        it. This is CORRECT rather than a wedge: a flatten is only not-tradeable
        when its instrument was delisted / halted mid-compensation, in which case
        the exposure cannot be auto-flattened at the venue at all and MUST go to an
        operator — so halting is the right terminal state, not a lost reopen.
        """
        if current_flatten is None:
            return False
        client_order_id, quantity, cum_fill = current_flatten
        if trigger_terminal and trigger_client_order_id == client_order_id:
            return True
        if cum_fill >= quantity - self._PEC_QTY_EPSILON:
            return True
        terminal_event = await s.execute(
            select(VenueEvent.id)
            .where(
                VenueEvent.client_order_id == client_order_id,
                VenueEvent.event_type.in_(
                    (
                        "order_terminal",
                        "order_rejected",
                        "order_breaker_open",
                        "order_interlock_blocked",
                    )
                ),
            )
            .limit(1)
        )
        return terminal_event.first() is not None

    @staticmethod
    async def _max_cumulative_fill(s: AsyncSession, client_order_id: str) -> float:
        """Return the MAX cumulative ``fill_observed`` size for an order, or 0.0.

        Session-bound twin of :meth:`get_max_cumulative_fill_venue_event` used
        inside the compensation recompute so the leg lock and the venue-event read
        share one transaction. Selects the greatest non-null ``cum_fill_size`` so
        an out-of-order executor write can never make the recompute read a smaller
        cumulative than was actually filled.
        """
        result = await s.execute(
            select(VenueEvent.cum_fill_size)
            .where(
                VenueEvent.client_order_id == client_order_id,
                VenueEvent.event_type == "fill_observed",
                VenueEvent.cum_fill_size.isnot(None),
            )
            .order_by(VenueEvent.cum_fill_size.desc(), VenueEvent.id.desc())
            .limit(1)
        )
        row = result.first()
        if row is None:
            return 0.0
        return float(row[0])

    async def project_paired_execution_leg_terminal(
        self,
        client_order_id: str,
        new_status: str,
        bus_time: datetime,
        session_id: str,
        sequence_id: int,
        exchange_order_id: str | None = None,
    ) -> bool:
        """Project a venue terminal (reject / cancel / expire) onto the active leg.

        Resolves the leg by its ``client_order_id`` (a non-grouped terminal
        matches no leg and is a no-op). Guards the CURRENT active row
        (``known_to == KNOWN_TO_MAX``) under ``FOR UPDATE`` and raises on >1
        active legs sharing the id (the same data-integrity guard the fill
        projection uses). Skips a leg already FILLED or already in a
        fill-terminal state (``_PEL_TERMINAL_PROJECT_SKIP_STATUSES``): a fully
        filled order needs no breakage, and a re-delivered terminal event is a
        no-op. Otherwise it SCD2 close-and-inserts the successor carrying the new
        terminal ``status`` while PRESERVING ``filled_signed_qty`` /
        ``compensated_signed_qty`` (a partially-filled leg that then cancels keeps
        its real exposure for the compensator) and every other column forward.
        The close / successor bus time is clamped to
        ``max(bus_time, existing.timestamp)`` for the same clock-skew SCD2
        non-inversion reason as the fill projection. Returns ``True`` iff a
        successor was written.
        """
        async with self.session() as s:
            matches = (
                (
                    await s.execute(
                        select(PairedExecutionLeg)
                        .where(
                            PairedExecutionLeg.client_order_id == client_order_id,
                            PairedExecutionLeg.known_to == KNOWN_TO_MAX,
                        )
                        .with_for_update()
                        .limit(2)
                    )
                )
                .scalars()
                .all()
            )
            if len(matches) > 1:
                raise ValueError(
                    "paired-execution data integrity: "
                    f"{len(matches)} active legs share client_order_id {client_order_id}"
                )
            existing = matches[0] if matches else None
            if existing is None:
                return False
            if existing.status in self._PEL_TERMINAL_PROJECT_SKIP_STATUSES:
                return False
            effective_bus_time = max(bus_time, existing.timestamp)
            await s.execute(
                update(PairedExecutionLeg)
                .where(PairedExecutionLeg.id == existing.id)
                .values(known_to=effective_bus_time)
            )
            s.add(
                self._leg_successor(
                    existing,
                    status=new_status,
                    filled_signed_qty=existing.filled_signed_qty,
                    exchange_order_id=(
                        exchange_order_id
                        if exchange_order_id is not None
                        else existing.exchange_order_id
                    ),
                    last_venue_event_id=existing.last_venue_event_id,
                    session_id=session_id,
                    sequence_id=sequence_id,
                    timestamp=effective_bus_time,
                )
            )
            await s.commit()
            return True

    @staticmethod
    def _leg_successor(
        existing: PairedExecutionLeg,
        *,
        status: str,
        filled_signed_qty: float,
        exchange_order_id: str | None,
        last_venue_event_id: int | None,
        session_id: str,
        sequence_id: int,
        timestamp: datetime,
        compensation_seq: int | None = None,
        compensated_signed_qty: float | None = None,
    ) -> PairedExecutionLeg:
        """Build an SCD2 successor leg row carrying every column forward.

        Shared by the fill, terminal, flatten-claim and compensation-fill
        projections: every immutable / carried column (identity, group, venue,
        side, target, signal/command ids) is copied from ``existing`` and only
        the explicitly-overridden ``status`` / ``filled_signed_qty`` / venue ids
        / provenance / ``timestamp`` differ. ``compensated_signed_qty`` is
        carried forward unless an override is given (the
        compensation-fill projection writes the recomputed value);
        ``compensation_seq`` is carried forward unless an override is given (the
        flatten claim bumps it). The caller closes ``existing``
        and adds this row.
        """
        return PairedExecutionLeg(
            public_id=existing.public_id,
            group_public_id=existing.group_public_id,
            leg_index=existing.leg_index,
            exchange=existing.exchange,
            mode=existing.mode,
            instrument=existing.instrument,
            shard_key=existing.shard_key,
            side=existing.side,
            target_qty=existing.target_qty,
            signal_public_id=existing.signal_public_id,
            command_public_id=existing.command_public_id,
            client_order_id=existing.client_order_id,
            exchange_order_id=exchange_order_id,
            status=status,
            filled_signed_qty=filled_signed_qty,
            compensated_signed_qty=(
                existing.compensated_signed_qty
                if compensated_signed_qty is None
                else compensated_signed_qty
            ),
            compensation_seq=(
                existing.compensation_seq if compensation_seq is None else compensation_seq
            ),
            last_venue_event_id=last_venue_event_id,
            wallet_public_id=existing.wallet_public_id,
            operator_public_id=existing.operator_public_id,
            created_at=existing.created_at,
            session_id=session_id,
            sequence_id=sequence_id,
            timestamp=timestamp,
        )

    @staticmethod
    def _paired_execution_leg_set_is_complete(
        legs: list[PairedExecutionLeg],
        group: PairedExecutionGroup,
    ) -> bool:
        """Return whether a group's active legs form its complete leg set.

        Complete means exactly ``expected_leg_count`` active legs with
        indices ``0 .. n-1``, each carrying a ``command_public_id``, whose
        canonical sorted ``{exchange}:{instrument}:{mode}`` key equals the
        group's ``group_key``. The index, command and key checks together
        reject a partial set, a duplicate-index set (e.g. two legs of the
        same instrument), and a wrong-instrument set, so a mismatched group
        can never arm and dispatch one leg naked.
        """
        if len(legs) != group.expected_leg_count:
            return False
        if sorted(leg.leg_index for leg in legs) != list(range(group.expected_leg_count)):
            return False
        if any(leg.command_public_id is None for leg in legs):
            return False
        reconstructed = compute_paired_group_key(
            [(leg.exchange, leg.instrument, leg.mode) for leg in legs]
        )
        return reconstructed == group.group_key

    async def ensure_paired_execution_group(self, row: PairedExecutionGroupInsertRow) -> bool:
        """Insert a paired-execution group unless an active one already exists.

        Idempotent across racing coordinators that each own a leg of the
        same group: the active-unique ``public_id`` index admits exactly one
        active group row. On an ``IntegrityError`` the method re-checks for an
        active group with the same ``public_id``; if one exists the error was
        the expected active-unique collision and ``False`` is returned, but
        ANY other integrity failure (a malformed row violating a different
        constraint) is RE-RAISED rather than silently swallowed. Swallowing a
        non-collision error would leave no group row, so the legs' commands
        would later pass the outbox gate as ungrouped and dispatch naked.
        Returns ``True`` iff this call created the group.
        """
        async with self.session() as s:
            s.add(PairedExecutionGroup(**row))
            try:
                await s.commit()
            except IntegrityError:
                await s.rollback()
                active_result = await s.execute(
                    select(PairedExecutionGroup.id).where(
                        PairedExecutionGroup.public_id == row.get("public_id"),
                        PairedExecutionGroup.known_to == KNOWN_TO_MAX,
                    )
                )
                active = active_result.first()
                if active is None:
                    raise
                return False
            return True

    async def try_arm_paired_execution_group_if_complete(
        self,
        group_public_id: str,
        bus_time: datetime,
        session_id: str,
        sequence_id: int,
    ) -> bool:
        """Validate a group's full leg set and CAS ``assembling -> armed``.

        Locks the active group ``FOR UPDATE`` then arms it iff: status is
        ``assembling``; ``bus_time <= assembly_deadline``; and the active
        legs form the complete, command-bearing, key-matching leg set
        (:meth:`_paired_execution_leg_set_is_complete`). Any failed check
        returns ``False`` without arming, upholding the safety invariant
        that no grouped command dispatches until every sibling leg is
        durably registered with a command. The ``FOR UPDATE`` lock
        serialises concurrent arm attempts from sibling coordinators; a
        loser sees ``armed`` and returns ``False``. Returns ``True`` iff
        this call armed the group.
        """
        async with self.session() as s:
            group = (
                (
                    await s.execute(
                        select(PairedExecutionGroup)
                        .where(
                            PairedExecutionGroup.public_id == group_public_id,
                            *where_active(PairedExecutionGroup, bus_time),
                        )
                        .with_for_update()
                    )
                )
                .scalars()
                .first()
            )
            if group is None:
                return False
            if group.status != PairedExecutionGroupStatusEnum.ASSEMBLING:
                return False
            if bus_time > group.assembly_deadline:
                return False
            legs = (
                (
                    await s.execute(
                        select(PairedExecutionLeg).where(
                            PairedExecutionLeg.group_public_id == group_public_id,
                            *where_active(PairedExecutionLeg, bus_time),
                        )
                    )
                )
                .scalars()
                .all()
            )
            if not self._paired_execution_leg_set_is_complete(list(legs), group):
                return False
            await s.execute(
                update(PairedExecutionGroup)
                .where(PairedExecutionGroup.id == group.id)
                .values(known_to=bus_time)
            )
            s.add(
                PairedExecutionGroup(
                    public_id=group.public_id,
                    wallet_public_id=group.wallet_public_id,
                    operator_public_id=group.operator_public_id,
                    strategy_id=group.strategy_id,
                    policy=group.policy,
                    expected_leg_count=group.expected_leg_count,
                    group_key=group.group_key,
                    status=PairedExecutionGroupStatusEnum.ARMED,
                    assembly_deadline=group.assembly_deadline,
                    fill_deadline=group.fill_deadline,
                    failure_reason=group.failure_reason,
                    halted_at=group.halted_at,
                    created_at=group.created_at,
                    session_id=session_id,
                    sequence_id=sequence_id,
                    timestamp=bus_time,
                )
            )
            await s.commit()
            return True

    async def get_paired_execution_group(
        self,
        public_id: str,
        as_of: datetime,
    ) -> PairedExecutionGroupRow | None:
        """Return the active paired-execution group by public_id."""
        async with self.session() as s:
            result = await s.execute(
                select(PairedExecutionGroup).where(
                    PairedExecutionGroup.public_id == public_id,
                    *where_active(PairedExecutionGroup, as_of),
                )
            )
            group = result.scalars().first()
            if group is None:
                return None
            return self._paired_execution_group_row_to_dict(group)

    async def get_paired_execution_legs(
        self,
        group_public_id: str,
        as_of: datetime,
    ) -> list[PairedExecutionLegRow]:
        """Return active paired-execution legs for a group ordered by leg index."""
        async with self.session() as s:
            result = await s.execute(
                select(PairedExecutionLeg)
                .where(
                    PairedExecutionLeg.group_public_id == group_public_id,
                    *where_active(PairedExecutionLeg, as_of),
                )
                .order_by(PairedExecutionLeg.leg_index)
            )
            return [self._paired_execution_leg_row_to_dict(leg) for leg in result.scalars().all()]

    async def get_current_paired_execution_legs(
        self,
        group_public_id: str,
    ) -> list[PairedExecutionLegRow]:
        """Return the CURRENT active legs for a group ordered by leg index.

        Guards on the current active row (``known_to == KNOWN_TO_MAX``), not a
        temporal ``as_of`` view, so startup recovery rebuilding the in-memory
        shard-halt mirror sees an owned leg even if a sibling coordinator stamped
        it with a slightly future ``timestamp`` under clock skew — a temporal
        ``get_paired_execution_legs(now)`` read would exclude such a leg and leave
        its shard un-halted until the scanner catches up. Mirrors the
        current-active guard :meth:`get_active_paired_execution_halt` uses.
        """
        async with self.session() as s:
            result = await s.execute(
                select(PairedExecutionLeg)
                .where(
                    PairedExecutionLeg.group_public_id == group_public_id,
                    PairedExecutionLeg.known_to == KNOWN_TO_MAX,
                )
                .order_by(PairedExecutionLeg.leg_index)
            )
            return [self._paired_execution_leg_row_to_dict(leg) for leg in result.scalars().all()]

    async def list_active_paired_execution_legs_for_shards(
        self,
        shard_keys: list[str],
        as_of: datetime,
    ) -> list[PairedExecutionLegRow]:
        """Return active paired-execution legs whose shard key is in the input set.

        Intended for the guard scanner: callers pass the bounded set of
        shard keys they own. The result is unbounded only in the number of
        active legs on those shards, which the arming barrier and
        compensation keep small.
        """
        if not shard_keys:
            return []
        async with self.session() as s:
            result = await s.execute(
                select(PairedExecutionLeg)
                .where(
                    PairedExecutionLeg.shard_key.in_(shard_keys),
                    *where_active(PairedExecutionLeg, as_of),
                )
                .order_by(PairedExecutionLeg.group_public_id, PairedExecutionLeg.leg_index)
            )
            return [self._paired_execution_leg_row_to_dict(leg) for leg in result.scalars().all()]

    async def list_active_paired_execution_groups(
        self,
        statuses: list[str],
        as_of: datetime,
    ) -> list[PairedExecutionGroupRow]:
        """Return active paired-execution groups matching the status set.

        Intended for the guard scanner with NON-terminal statuses
        (``assembling`` / ``armed`` / ``broken`` / ``compensating``), which
        bounds the result to in-flight groups. Terminal groups stay
        SCD2-active until the completion path closes them, so listing by a
        terminal status is unbounded over a long deployment. Ordered by
        ``created_at`` then ``id`` for a deterministic page.
        """
        if not statuses:
            return []
        async with self.session() as s:
            result = await s.execute(
                select(PairedExecutionGroup)
                .where(
                    PairedExecutionGroup.status.in_(statuses),
                    *where_active(PairedExecutionGroup, as_of),
                )
                .order_by(PairedExecutionGroup.created_at, PairedExecutionGroup.id)
            )
            return [
                self._paired_execution_group_row_to_dict(group) for group in result.scalars().all()
            ]

    async def list_current_paired_execution_groups(
        self, statuses: list[str]
    ) -> list[PairedExecutionGroupRow]:
        """Return CURRENT active groups matching the status set.

        Guards on the current active row (``known_to == KNOWN_TO_MAX``), not a
        temporal ``as_of`` view, so startup recovery does not skip a current
        ``armed`` / ``broken`` / ``compensating`` group stamped with a slightly
        future ``timestamp`` under clock skew — pairing with
        :meth:`get_current_paired_execution_legs` so the group and its legs use
        the same current-active read. Ordered by ``created_at`` then ``id`` for a
        deterministic page.
        """
        if not statuses:
            return []
        async with self.session() as s:
            result = await s.execute(
                select(PairedExecutionGroup)
                .where(
                    PairedExecutionGroup.status.in_(statuses),
                    PairedExecutionGroup.known_to == KNOWN_TO_MAX,
                )
                .order_by(PairedExecutionGroup.created_at, PairedExecutionGroup.id)
            )
            return [
                self._paired_execution_group_row_to_dict(group) for group in result.scalars().all()
            ]

    async def get_active_paired_execution_halt(
        self,
        wallet_public_id: str,
        strategy_id: str,
        group_key: str,
    ) -> PairedExecutionHaltRow | None:
        """Return the CURRENT active halt for a wallet-strategy-group scope.

        Guards on the current active row (``known_to == KNOWN_TO_MAX``), not a
        temporal ``as_of`` view: the live ``_on_signal`` fast-reject must see a
        halt the instant it is projected, even if a sibling coordinator stamped
        it with a slightly future ``timestamp`` under clock skew — a temporal
        ``where_active(now)`` read would exclude such a halt and fail OPEN.
        Mirrors the current-active guard the trade-command CAS uses. Returns
        ``None`` when no active halt covers the scope.
        """
        async with self.session() as s:
            result = await s.execute(
                select(PairedExecutionHalt).where(
                    PairedExecutionHalt.wallet_public_id == wallet_public_id,
                    PairedExecutionHalt.strategy_id == strategy_id,
                    PairedExecutionHalt.group_key == group_key,
                    PairedExecutionHalt.known_to == KNOWN_TO_MAX,
                )
            )
            halt = result.scalars().first()
            if halt is None:
                return None
            return self._paired_execution_halt_row_to_dict(halt)

    async def list_active_paired_execution_halts(self) -> list[PairedExecutionHaltRow]:
        """Return every CURRENT active paired-execution halt.

        Lists current-active rows (``known_to == KNOWN_TO_MAX``), matching
        :meth:`get_active_paired_execution_halt`, so startup recovery can rebuild
        the in-memory shard-halt mirror from the authoritative durable halts: a
        halt closed by ``clear_paired_execution_halt`` is excluded, so a
        deliberately-cleared pair is never re-halted on restart. Bounded by the
        number of pairs currently in failure / compensation. Ordered by
        ``created_at`` then ``id`` for a deterministic page.
        """
        async with self.session() as s:
            result = await s.execute(
                select(PairedExecutionHalt)
                .where(PairedExecutionHalt.known_to == KNOWN_TO_MAX)
                .order_by(PairedExecutionHalt.created_at, PairedExecutionHalt.id)
            )
            return [
                self._paired_execution_halt_row_to_dict(halt) for halt in result.scalars().all()
            ]

    async def clear_paired_execution_halt(self, public_id: str, bus_time: datetime) -> bool:
        """Close an active paired-execution halt without inserting a successor row."""
        async with self.session() as s:
            existing = (
                (
                    await s.execute(
                        select(PairedExecutionHalt)
                        .where(
                            PairedExecutionHalt.public_id == public_id,
                            *where_active(PairedExecutionHalt, bus_time),
                        )
                        .with_for_update()
                    )
                )
                .scalars()
                .first()
            )
            if existing is None:
                return False
            await s.execute(
                update(PairedExecutionHalt)
                .where(PairedExecutionHalt.id == existing.id)
                .values(known_to=bus_time)
            )
            await s.commit()
            return True

    async def clear_paired_execution_halt_if_scope_quiet(
        self,
        wallet_public_id: str,
        strategy_id: str,
        group_key: str,
        bus_time: datetime,
    ) -> bool:
        """Close a scope's active halt iff NO group in the scope is still exposed.

        The quiet-halt sweep's clear: in ONE transaction, checks
        for any CURRENT active group on the ``(wallet, strategy, group_key)``
        scope whose status is still exposed (``broken`` / ``compensating`` /
        ``manual_intervention``) and, only when none exists, closes the scope's
        CURRENT active halt row. A completed group no longer matches the
        exposed set, so the halt clears on the first sweep after the scope's
        LAST group completes; a sibling group still failing keeps the halt in
        force (it covers that group too — the scope is active-unique). Both
        reads guard on ``known_to == KNOWN_TO_MAX`` (not a temporal view) so a
        future-stamped row under clock skew cannot make the scope look quiet,
        and the close time is clamped to ``max(bus_time, halt.timestamp)`` so
        the SCD2 interval never inverts. Running it from a periodic sweep
        (rather than once at completion) makes the clear idempotent and
        crash-retryable: a coordinator dying between completing the group and
        clearing the halt just leaves the clear for the next cycle. Returns
        ``True`` iff this call closed the halt.

        The scope's group rows are read ``FOR UPDATE NOWAIT`` (ordered by id so
        two sweeping coordinators cannot deadlock each other): the quiet
        decision must be made against rows a concurrent late-fill REOPEN
        (which flips a completed group back to ``compensating`` under the same
        group lock) cannot change mid-transaction. Plain ``FOR UPDATE`` would
        be unsound under the SCD2 close-and-insert pattern — a clear WAITING on
        the reopen's lock would, after the wait, re-check and SKIP the closed
        predecessor row while the reopen's freshly INSERTED ``compensating``
        successor stays invisible to its snapshot, so the scope would look
        quiet exactly when it is not. ``NOWAIT`` makes the race fail-safe
        instead: ANY lock conflict (or other database error) aborts this clear
        with ``False`` — the halt stays and the next cycle retries. The lock
        order (groups, then the halt row; never legs) cannot cycle with the
        completion DAL (group → legs) or the reopen path (group → leg). A
        reopen that lands strictly AFTER this clear commits remains exposed
        without a halt for at most one scan cycle — the halts sweep re-halts a
        ``compensating`` group on the next pass; that residual ordering is
        inherent to clearing at all and self-heals.
        """
        async with self.session() as s:
            try:
                scope_groups = (
                    (
                        await s.execute(
                            select(PairedExecutionGroup)
                            .where(
                                PairedExecutionGroup.wallet_public_id == wallet_public_id,
                                PairedExecutionGroup.strategy_id == strategy_id,
                                PairedExecutionGroup.group_key == group_key,
                                PairedExecutionGroup.known_to == KNOWN_TO_MAX,
                            )
                            .order_by(PairedExecutionGroup.id)
                            .with_for_update(nowait=True)
                        )
                    )
                    .scalars()
                    .all()
                )
            except DBAPIError:
                return False
            if any(group.status in self._PEG_EXPOSED_STATUSES for group in scope_groups):
                return False
            halt = (
                (
                    await s.execute(
                        select(PairedExecutionHalt)
                        .where(
                            PairedExecutionHalt.wallet_public_id == wallet_public_id,
                            PairedExecutionHalt.strategy_id == strategy_id,
                            PairedExecutionHalt.group_key == group_key,
                            PairedExecutionHalt.known_to == KNOWN_TO_MAX,
                        )
                        .with_for_update()
                    )
                )
                .scalars()
                .first()
            )
            if halt is None:
                return False
            await s.execute(
                update(PairedExecutionHalt)
                .where(PairedExecutionHalt.id == halt.id)
                .values(known_to=max(bus_time, halt.timestamp))
            )
            await s.commit()
            return True

    def _paired_execution_leg_is_settled_flat(self, leg: PairedExecutionLeg) -> bool:
        """Return whether a leg is settled with zero open exposure.

        Settled-flat means the leg carries a terminal status (a member of
        :data:`_PEL_SETTLED_STATUSES` — ``flattened`` / ``cancelled`` /
        ``expired`` / ``rejected`` / ``filled``) AND its open exposure
        ``|filled_signed_qty − compensated_signed_qty|`` is below
        :data:`_PEC_QTY_EPSILON`. ``filled``-with-zero-open is reachable (a
        reopened leg whose old flatten's late fill report zeroes the residual)
        and counts. A ``pending`` / ``working`` / ``compensating`` /
        ``manual_intervention`` leg is never settled-flat. Shared by the
        automatic completion predicate and the operator attestation predicate.
        """
        if leg.status not in self._PEL_SETTLED_STATUSES:
            return False
        open_qty = leg.filled_signed_qty - leg.compensated_signed_qty
        return abs(open_qty) < self._PEC_QTY_EPSILON

    def _paired_execution_group_is_settled_for_completion(
        self,
        group: PairedExecutionGroup,
        legs: Sequence[PairedExecutionLeg],
        expected_status: str,
    ) -> bool:
        """Return whether a group's locked legs satisfy the status-specific settled predicate.

        The per-status completion gate of
        :meth:`complete_paired_execution_group_if_settled`, evaluated on legs
        already locked ``FOR UPDATE``: for ``armed`` the legs must form the
        COMPLETE validated leg set (:meth:`_paired_execution_leg_set_is_complete`
        — never a vacuous or partial set) and every leg must be fully
        ``filled``; for ``broken`` / ``compensating`` every leg must be
        settled-flat (:meth:`_paired_execution_leg_is_settled_flat`). Callers
        guarantee ``legs`` is non-empty, so the all-legs checks are never
        vacuously true.
        """
        if expected_status == PairedExecutionGroupStatusEnum.ARMED.value:
            if not self._paired_execution_leg_set_is_complete(list(legs), group):
                return False
            return not any(leg.status != PairedExecutionLegStatusEnum.FILLED.value for leg in legs)
        return all(self._paired_execution_leg_is_settled_flat(leg) for leg in legs)

    @staticmethod
    async def _paired_execution_group_has_held_original(
        s: AsyncSession, group_public_id: str
    ) -> bool:
        """Return whether a current-active HELD ``created`` ORIGINAL command carries the group.

        Probes, inside the caller's transaction, for a CURRENT active
        ``created`` trade command (``supersedes_command_id IS NULL``) whose
        ``correlation_id`` is the group's public id. Completing or attesting a
        group over such a command would leave it held by the outbox gate
        forever (the gate releases grouped commands only for ARMED groups),
        polluting every outbox poll page — and a held original means the group
        was not truly settled. COMPENSATION commands (cancel / flatten, which
        supersede an original) are deliberately excluded: the outbox dispatches
        them regardless of group status.
        """
        held = (
            await s.execute(
                select(TradeCommand.id)
                .where(
                    TradeCommand.correlation_id == group_public_id,
                    TradeCommand.status == TradeCommandStatusEnum.CREATED.value,
                    TradeCommand.supersedes_command_id.is_(None),
                    TradeCommand.known_to == KNOWN_TO_MAX,
                )
                .limit(1)
            )
        ).first()
        return held is not None

    @staticmethod
    async def _close_paired_execution_group_as_completed(
        s: AsyncSession,
        group: PairedExecutionGroup,
        failure_reason: str | None,
        bus_time: datetime,
        session_id: str,
        sequence_id: int,
    ) -> None:
        """SCD2-close a locked group and insert its ``completed`` successor row.

        The shared row-transition tail of
        :meth:`complete_paired_execution_group_if_settled` and
        :meth:`terminalize_paired_execution_group`, on a group already locked
        ``FOR UPDATE`` inside the caller's transaction (the caller commits).
        The close / successor time is clamped to ``max(bus_time,
        group.timestamp)`` so the successor never precedes the row it closes.
        Every group attribute is carried forward unchanged except ``status``
        (forced to ``completed``) and ``failure_reason`` (the caller-supplied
        value: the prior reason for automatic completion, the attestation-
        stamped reason for operator terminalization).
        """
        effective_bus_time = max(bus_time, group.timestamp)
        await s.execute(
            update(PairedExecutionGroup)
            .where(PairedExecutionGroup.id == group.id)
            .values(known_to=effective_bus_time)
        )
        s.add(
            PairedExecutionGroup(
                public_id=group.public_id,
                wallet_public_id=group.wallet_public_id,
                operator_public_id=group.operator_public_id,
                strategy_id=group.strategy_id,
                policy=group.policy,
                expected_leg_count=group.expected_leg_count,
                group_key=group.group_key,
                status=PairedExecutionGroupStatusEnum.COMPLETED.value,
                assembly_deadline=group.assembly_deadline,
                fill_deadline=group.fill_deadline,
                failure_reason=failure_reason,
                halted_at=group.halted_at,
                created_at=group.created_at,
                session_id=session_id,
                sequence_id=sequence_id,
                timestamp=effective_bus_time,
            )
        )

    async def complete_paired_execution_group_if_settled(
        self,
        group_public_id: str,
        expected_status: str,
        bus_time: datetime,
        session_id: str,
        sequence_id: int,
    ) -> bool:
        """CAS a fully-settled group to ``completed`` under a group-then-legs lock.

        The completion check, in ONE transaction: locks the CURRENT
        active group ``FOR UPDATE`` (group THEN legs — the lock order every
        group-touching paired DAL shares), verifies ``status ==
        expected_status``, locks the CURRENT active legs, and verifies the
        status-specific settled predicate:

        - ``armed`` (the happy path): the legs form the COMPLETE validated leg
          set (:meth:`_paired_execution_leg_set_is_complete` — never a vacuous
          or partial set) and every leg is fully ``filled``. The exposure is
          INTENDED (the strategy holds the pair), so completion involves no
          halt or flatten logic.
        - ``broken`` / ``compensating``: at least one leg exists and EVERY leg
          is settled — a terminal status (``flattened`` / ``cancelled`` /
          ``expired`` / ``rejected`` / ``filled``) with zero open exposure
          (``|filled_signed_qty − compensated_signed_qty| <`` epsilon).
          ``filled``-with-zero-open is reachable (a reopened leg whose old
          flatten's late fill report zeroes the residual) and counts. A
          ``pending`` / ``working`` / ``compensating`` / ``manual_intervention``
          leg blocks completion; ``manual_intervention`` GROUPS are never
          completed automatically (`expected_status` rejects them).

        Additionally requires NO current-active HELD ``created`` ORIGINAL trade
        command (``supersedes_command_id IS NULL``) carrying this group as its
        ``correlation_id``: completing the group would leave such a command held
        by the outbox gate forever (the gate releases grouped commands only for
        ARMED groups), polluting every outbox poll page — and a held original
        means the group was not truly settled. COMPENSATION commands (cancel /
        flatten, which supersede an original) are deliberately excluded: the
        outbox dispatches them regardless of group status, so one that is
        momentarily ``created`` must only delay completion by its dispatch, not
        block it on a stale row. The group close / successor time is clamped to ``max(bus_time,
        group.timestamp)``. Completing settled BROKEN groups (e.g. a
        zero-exposure assembly-timeout break whose legs were all cancelled)
        deliberately terminalizes them so they stop bloating every scanner
        listing and the pair scope quiets. Returns ``True`` iff this call
        completed the group. Raises ``ValueError`` for an ``expected_status``
        outside the completable set (armed / broken / compensating).
        """
        if expected_status not in self._PEG_COMPLETABLE_STATUSES:
            raise ValueError(
                f"paired-execution group completion from {expected_status!r} is not allowed"
            )
        async with self.session() as s:
            group = (
                (
                    await s.execute(
                        select(PairedExecutionGroup)
                        .where(
                            PairedExecutionGroup.public_id == group_public_id,
                            PairedExecutionGroup.known_to == KNOWN_TO_MAX,
                        )
                        .with_for_update()
                    )
                )
                .scalars()
                .first()
            )
            if group is None or group.status != expected_status:
                return False
            legs = (
                (
                    await s.execute(
                        select(PairedExecutionLeg)
                        .where(
                            PairedExecutionLeg.group_public_id == group_public_id,
                            PairedExecutionLeg.known_to == KNOWN_TO_MAX,
                        )
                        .with_for_update()
                    )
                )
                .scalars()
                .all()
            )
            if not legs:
                return False
            if not self._paired_execution_group_is_settled_for_completion(
                group, legs, expected_status
            ):
                return False
            if await self._paired_execution_group_has_held_original(s, group_public_id):
                return False
            await self._close_paired_execution_group_as_completed(
                s, group, group.failure_reason, bus_time, session_id, sequence_id
            )
            await s.commit()
            return True

    async def list_recent_completed_paired_execution_groups(
        self, completed_after: datetime
    ) -> list[PairedExecutionGroupRow]:
        """Return CURRENT active ``completed`` groups whose completion is recent.

        Startup recovery's bounded window over completed groups: a
        late original fill that landed while the coordinator was DOWN must
        reopen its completed group, but the live reopen trigger never fires for
        events already persisted and listing ALL completed groups is unbounded
        over a deployment's lifetime. The completion successor's ``timestamp``
        IS the completion time, so filtering ``timestamp > completed_after``
        (backed by the ``ix_peg_status_timestamp`` index) bounds the replay to
        groups completed within the recovery window; an older late fill is
        reconciliation / operator territory. Ordered by ``created_at`` then
        ``id`` for a deterministic page.
        """
        async with self.session() as s:
            result = await s.execute(
                select(PairedExecutionGroup)
                .where(
                    PairedExecutionGroup.status == PairedExecutionGroupStatusEnum.COMPLETED.value,
                    PairedExecutionGroup.known_to == KNOWN_TO_MAX,
                    PairedExecutionGroup.timestamp > completed_after,
                )
                .order_by(PairedExecutionGroup.created_at, PairedExecutionGroup.id)
            )
            return [
                self._paired_execution_group_row_to_dict(group) for group in result.scalars().all()
            ]

    async def get_current_paired_execution_group(
        self, public_id: str
    ) -> PairedExecutionGroupRow | None:
        """Return the CURRENT active group by public_id, or None.

        Guards on the current active row (``known_to == KNOWN_TO_MAX``), not a
        temporal ``as_of`` view, so the operator surface never 404s a group a
        sibling coordinator stamped with a slightly future ``timestamp`` under
        clock skew — pairing with :meth:`get_current_paired_execution_legs`.
        """
        async with self.session() as s:
            result = await s.execute(
                select(PairedExecutionGroup).where(
                    PairedExecutionGroup.public_id == public_id,
                    PairedExecutionGroup.known_to == KNOWN_TO_MAX,
                )
            )
            group = result.scalars().first()
            if group is None:
                return None
            return self._paired_execution_group_row_to_dict(group)

    def _paired_execution_group_is_attestable(
        self,
        group: PairedExecutionGroup,
        legs: Sequence[PairedExecutionLeg],
    ) -> bool:
        """Return whether a locked group may be operator-attested as resolved.

        The attestable predicate of :meth:`terminalize_paired_execution_group`,
        evaluated on rows already locked ``FOR UPDATE``: the group must be
        ``manual_intervention`` (the operator owns it outright), OR
        ``compensating`` with at least one current ``manual_intervention`` leg
        — the re-attestation path after a late original fill reopened an
        already-terminalized group whose manual leg cannot re-enter
        automation. In BOTH cases every leg must be either settled-flat
        (:meth:`_paired_execution_leg_is_settled_flat`) or
        ``manual_intervention``: an operator must never attest over a sibling
        leg's in-flight automation. A group with NO current legs is never
        attestable: a vacuous attestation would clear the scope's halt while
        erasing the operator-visible incident.
        """
        if not legs:
            return False
        manual_legs = [
            leg
            for leg in legs
            if leg.status == PairedExecutionLegStatusEnum.MANUAL_INTERVENTION.value
        ]
        group_is_manual = group.status == PairedExecutionGroupStatusEnum.MANUAL_INTERVENTION.value
        group_is_reopened_manual = (
            group.status == PairedExecutionGroupStatusEnum.COMPENSATING.value and bool(manual_legs)
        )
        if not (group_is_manual or group_is_reopened_manual):
            return False
        for leg in legs:
            if leg.status == PairedExecutionLegStatusEnum.MANUAL_INTERVENTION.value:
                continue
            if not self._paired_execution_leg_is_settled_flat(leg):
                return False
        return True

    async def terminalize_paired_execution_group(
        self,
        public_id: str,
        attested_by: str,
        bus_time: datetime,
        session_id: str,
        sequence_id: int,
    ) -> PairedGroupTerminalizeOutcome:
        """Record an operator attestation that a manual group is resolved at the venue.

        The OPERATOR counterpart of the automatic
        :meth:`complete_paired_execution_group_if_settled` (which deliberately
        refuses ``manual_intervention``): in ONE transaction it locks the
        CURRENT active group ``FOR UPDATE`` (group THEN legs — the shared lock
        order), validates the attestable predicate, and SCD2-closes the group
        into ``completed`` with the attestation stamped into ``failure_reason``
        as a bounded, parseable ``terminalized_by=<user_public_id>`` suffix
        (truncating the prior reason to fit the 512-char column). The next
        scanner cycle's quiet-halt sweep then clears the scope's durable halt
        and every coordinator's in-memory mirror — no cross-process call.

        Attestable means: the group is ``manual_intervention`` (the operator
        owns it outright), OR it is ``compensating`` with at least one current
        ``manual_intervention`` leg — the re-attestation path after a late
        original fill reopened an already-terminalized group whose manual leg
        cannot re-enter automation. In BOTH cases every leg must be either
        settled (a terminal status at zero open exposure) or
        ``manual_intervention``: an operator must never attest over a sibling
        leg's in-flight automation (a live original or an unfinished flatten),
        so such a group returns ``NOT_TERMINALIZABLE`` until the live hooks
        settle the sibling. Legs are NEVER mutated — their statuses and signed
        accounting remain the true books; the completed group is purely the
        attestation record. A group with NO current legs is never attestable:
        a vacuous attestation would clear the scope's halt while erasing the
        operator-visible incident, so corruption stays surfaced instead. The
        held-created-ORIGINAL guard mirrors
        :meth:`complete_paired_execution_group_if_settled` (an attested group
        must never strand a gate-held command in the outbox backlog), and the
        attesting subject is clamped to 64 chars so the stamp suffix can never
        consume the whole 512-char column.
        """
        async with self.session() as s:
            group = (
                (
                    await s.execute(
                        select(PairedExecutionGroup)
                        .where(
                            PairedExecutionGroup.public_id == public_id,
                            PairedExecutionGroup.known_to == KNOWN_TO_MAX,
                        )
                        .with_for_update()
                    )
                )
                .scalars()
                .first()
            )
            if group is None:
                return PairedGroupTerminalizeOutcome.NOT_FOUND
            legs = (
                (
                    await s.execute(
                        select(PairedExecutionLeg)
                        .where(
                            PairedExecutionLeg.group_public_id == public_id,
                            PairedExecutionLeg.known_to == KNOWN_TO_MAX,
                        )
                        .with_for_update()
                    )
                )
                .scalars()
                .all()
            )
            if not self._paired_execution_group_is_attestable(group, legs):
                return PairedGroupTerminalizeOutcome.NOT_TERMINALIZABLE
            if await self._paired_execution_group_has_held_original(s, public_id):
                return PairedGroupTerminalizeOutcome.NOT_TERMINALIZABLE
            suffix = f"; terminalized_by={attested_by[:64]}"
            base = group.failure_reason or "manual intervention"
            stamped = base[: max(0, 512 - len(suffix))] + suffix
            await self._close_paired_execution_group_as_completed(
                s, group, stamped, bus_time, session_id, sequence_id
            )
            await s.commit()
            return PairedGroupTerminalizeOutcome.TERMINALIZED

    @staticmethod
    def _venue_event_to_row(ve: VenueEvent) -> VenueEventRow:
        """Project a VenueEvent ORM row into the VenueEventRow TypedDict shape."""
        return {
            "id": ve.id,
            "public_id": ve.public_id,
            "timestamp": ve.timestamp,
            "session_id": ve.session_id,
            "sequence_id": ve.sequence_id,
            "event_type": ve.event_type,
            "shard_key": ve.shard_key,
            "wallet_public_id": ve.wallet_public_id,
            "command_public_id": ve.command_public_id,
            "exchange": ve.exchange,
            "instrument": ve.instrument,
            "mode": ve.mode,
            "exchange_order_id": ve.exchange_order_id,
            "client_order_id": ve.client_order_id,
            "venue_client_id": ve.venue_client_id,
            "side": ve.side,
            "status": ve.status,
            "fill_price": ve.fill_price,
            "fill_size": ve.fill_size,
            "cum_fill_size": ve.cum_fill_size,
            "fee": ve.fee,
            "fee_asset": ve.fee_asset,
            "exec_id": ve.exec_id,
            "trade_id": ve.trade_id,
            "error": ve.error,
            "venue_timestamp": ve.venue_timestamp,
            "received_at": ve.received_at,
            "liquidity_role": getattr(ve, "liquidity_role", "unknown"),
            "paired_group_id": ve.paired_group_id,
        }

    async def get_venue_events_after(self, shard_key: str, after_id: int) -> list[VenueEventRow]:
        """Return venue events for a shard after the given watermark (id)."""
        async with self.session() as s:
            result = await s.execute(
                select(VenueEvent)
                .where(VenueEvent.shard_key == shard_key, VenueEvent.id > after_id)
                .order_by(VenueEvent.id)
            )
            return [self._venue_event_to_row(ve) for ve in result.scalars().all()]

    async def get_max_cumulative_fill_venue_event(
        self, client_order_id: str
    ) -> VenueEventRow | None:
        """Return the ``fill_observed`` venue event with the MAX cumulative fill for an order.

        Selects the row with the greatest non-null ``cum_fill_size`` (tie-broken by
        highest ``id``) among the append-only ``fill_observed`` events for
        ``client_order_id``. Recovery fill parity reads the AUTHORITATIVE
        ``venue_events`` — the executor writes them fail-closed with the cumulative
        ``cum_fill_size`` BEFORE publishing — so a leg whose order filled while the
        coordinator was down is re-projected on restart. Selecting by MAX cumulative
        (NOT latest ``id``) ensures an out-of-order executor write can never make
        recovery read a smaller cumulative than was actually filled. Returns ``None``
        when no cumulative fill event exists for the order.
        """
        async with self.session() as s:
            result = await s.execute(
                select(VenueEvent)
                .where(
                    VenueEvent.client_order_id == client_order_id,
                    VenueEvent.event_type == "fill_observed",
                    VenueEvent.cum_fill_size.isnot(None),
                )
                .order_by(VenueEvent.cum_fill_size.desc(), VenueEvent.id.desc())
                .limit(1)
            )
            ve = result.scalars().first()
            if ve is None:
                return None
            return self._venue_event_to_row(ve)

    async def get_fill_venue_events_for_order(self, client_order_id: str) -> list[VenueEventRow]:
        """Return all cumulative ``fill_observed`` venue events for an order.

        Rows with a non-null ``cum_fill_size``, ordered by
        ``(cum_fill_size asc, id asc)`` so callers can walk the order's
        durable fill history monotonically regardless of out-of-order
        executor writes. Recovery reads this to seed the dual watermarks
        honestly and to republish recorded-but-unpublished fills under
        their ORIGINAL exec ids (every downstream consumer dedupes by
        exec id, so republishing is idempotent). Served by
        ``ix_venue_events_cid_event_type``; no ``known_to`` filter is
        needed because venue events are never closed.

        Args:
            client_order_id: Client order id whose fill history to read.

        Returns:
            Ordered fill rows; empty list when none exist.
        """
        async with self.session() as s:
            result = await s.execute(
                select(VenueEvent)
                .where(
                    VenueEvent.client_order_id == client_order_id,
                    VenueEvent.event_type == "fill_observed",
                    VenueEvent.cum_fill_size.isnot(None),
                )
                .order_by(VenueEvent.cum_fill_size.asc(), VenueEvent.id.asc())
            )
            return [self._venue_event_to_row(ve) for ve in result.scalars().all()]

    async def get_consumed_fill_venue_event_id(
        self,
        *,
        shard_key: str,
        client_order_id: str,
        exec_id: str | None,
        cum_fill_size: float,
        trade_id: str | None = None,
    ) -> int | None:
        """Return the durable id of a consumed ``fill_observed`` venue event.

        Checkpoint uses this to bound the recovery watermark to the fill the
        coordinator just applied, never the shard DB-max (which can be ahead of
        the in-memory snapshot because the executor commits a venue event BEFORE
        publishing it). Matches by ``exec_id`` when the fill carries one
        (``ExecutionData.trade_id`` is the venue exec id, persisted as
        ``VenueEvent.exec_id``); id-less venues fall back to the cumulative fill
        size within the order. Scoped to the shard and order, returning the
        LOWEST matching id so a later duplicate can never inflate the watermark.
        Returns ``None`` when no matching event exists, so the caller leaves the
        watermark unadvanced and recovery re-applies the fill idempotently.

        Args:
            shard_key: Shard the fill belongs to.
            client_order_id: Client order id of the fill.
            exec_id: Venue execution id when present (``ExecutionData.trade_id``).
            cum_fill_size: Cumulative fill size, used for id-less venues.
            trade_id: Venue trade id fallback matched against
                ``VenueEvent.trade_id`` when no exec id exists — the
                execution-replay recovery path carries both identifiers
                because some venues populate only one of them.

        Returns:
            Lowest matching ``VenueEvent.id``, or ``None`` if no match.
        """
        async with self.session() as s:
            query = select(func.min(VenueEvent.id)).where(
                VenueEvent.shard_key == shard_key,
                VenueEvent.client_order_id == client_order_id,
                VenueEvent.event_type == "fill_observed",
            )
            if exec_id is not None:
                query = query.where(VenueEvent.exec_id == exec_id)
            elif trade_id is not None:
                query = query.where(VenueEvent.trade_id == trade_id)
            else:
                query = query.where(
                    VenueEvent.cum_fill_size.isnot(None),
                    func.abs(VenueEvent.cum_fill_size - cum_fill_size) < 1e-9,
                )
            result = await s.execute(query)
            return result.scalar()

    async def get_latest_venue_event_id(self, shard_key: str) -> int | None:
        """Return the highest VenueEvent.id for a shard, or None if empty.

        Full-replay recovery seeds its consumed watermark from this: the
        replayed snapshot is built from the durable execution plane (DB truth,
        not an in-memory projection), so the shard DB-max is the honest
        watermark there and a later non-fill checkpoint must not regress it to
        zero and re-replay the whole shard.

        Args:
            shard_key: Shard to query.

        Returns:
            Highest id value, or None if no events exist.
        """
        async with self.session() as s:
            result = await s.execute(
                select(func.max(VenueEvent.id)).where(VenueEvent.shard_key == shard_key)
            )
            return result.scalar()

    async def get_shard_keys_with_fills(self) -> list[str]:
        """Return distinct shard keys that have any ``fill_observed`` venue event.

        Recovery's venue-plane gap pass (R9) iterates these to find shards
        whose recorded fills were never consumed and were not covered by
        checkpoint or execution recovery — including shards with ZERO
        execution rows, which the execution-replay pass never visits (it
        returns early on an empty executions table).

        Returns:
            Distinct ``shard_key`` values bearing fill events.
        """
        async with self.session() as s:
            result = await s.execute(
                select(VenueEvent.shard_key)
                .where(VenueEvent.event_type == "fill_observed")
                .distinct()
            )
            return list(result.scalars().all())

    async def shard_has_fill_gap(self, shard_key: str, as_of: datetime) -> bool:
        """Return True when a shard's recorded fills exceed its consumed fills.

        The R9 gap signal: the executor commits a ``fill_observed`` venue
        event BEFORE publishing the fill, and the ``executions`` row only
        after a successful publish, so recorded durable quantity that has no
        matching consumed (published) quantity means a fill was dropped on
        the publish/consume path. Comparison is on GROSS filled quantity, not
        net position, so the absorption case (a later cumulative fill carries
        an earlier unpublished fill's quantity under one execution row) shows
        equal totals and is correctly NOT a gap.

        ``recorded`` sums ``fill_size`` over fills deduped by identity
        (``exec_id``, else ``trade_id``, else the row's unique ``public_id``
        so id-less rows are never collapsed); duplicate redelivered rows share
        an identity and collapse via ``MAX``. The identity is additionally
        scoped by the row's FULL ``wallet_public_id``: venue execution ids
        are only unique per venue account, so suffix-twin wallets sharing a
        shard string can legally carry the same ``exec_id`` for two DIFFERENT
        fills — collapsing them would under-count recorded quantity and hide
        a real gap (the one direction this detector must never miss). Mixed
        wallets then read recorded > consumed (consumed is scoped to the one
        sampled wallet), forcing the rebuild path whose foreign-wallet check
        fails the certification. ``consumed`` sums
        ``executions.size`` for the shard's orders, resolved
        ``client_order_id`` -> current SCD2 ``orders.public_id`` and further
        scoped to the shard's own ``wallet_public_id`` and ``mode`` (read from
        the shard's venue rows) so a same-id order on a foreign shard cannot
        inflate consumed — ``client_order_id`` is a globally-unique ``uuid7``
        in practice, this scoping is defence-in-depth. An unresolved client
        order id contributes zero (so its quantity reads as a gap — the safe
        direction). Over-detection only triggers an exact-by-construction
        rebuild; only under-detection would drop a fill, and a deduped durable
        sum cannot under-count venue truth.

        Args:
            shard_key: Shard to evaluate.
            as_of: Temporal anchor for the orders/executions join.

        Returns:
            True if recorded gross quantity exceeds consumed by more than eps.
        """
        async with self.session() as s:
            scope_row = (
                await s.execute(
                    select(VenueEvent.wallet_public_id, VenueEvent.mode)
                    .where(
                        VenueEvent.shard_key == shard_key,
                        VenueEvent.event_type == "fill_observed",
                    )
                    .limit(1)
                )
            ).first()
            if scope_row is None:
                return False
            shard_wallet_public_id, shard_mode = scope_row
            fill_identity = venue_event_fill_identity()
            invalid_identity_id = await s.scalar(
                select(VenueEvent.id)
                .where(
                    VenueEvent.shard_key == shard_key,
                    VenueEvent.event_type == "fill_observed",
                    fill_identity.is_(None),
                )
                .limit(1)
            )
            if invalid_identity_id is not None:
                return True
            recorded_per_identity = (
                select(func.max(VenueEvent.fill_size).label("s"))
                .where(
                    VenueEvent.shard_key == shard_key,
                    VenueEvent.event_type == "fill_observed",
                    VenueEvent.fill_size.isnot(None),
                )
                .group_by(VenueEvent.wallet_public_id, fill_identity)
                .subquery()
            )
            recorded_result = await s.execute(
                select(func.coalesce(func.sum(recorded_per_identity.c.s), 0.0))
            )
            recorded_total = recorded_result.scalar() or 0.0
            shard_client_order_ids = (
                select(VenueEvent.client_order_id)
                .where(
                    VenueEvent.shard_key == shard_key,
                    VenueEvent.event_type == "fill_observed",
                    VenueEvent.client_order_id.isnot(None),
                )
                .distinct()
            )
            consumed_result = await s.execute(
                select(func.coalesce(func.sum(Execution.size), 0.0))
                .select_from(Execution)
                .join(
                    Order,
                    and_(
                        Execution.order_public_id == Order.public_id,
                        *where_active(Order, as_of),
                    ),
                )
                .where(
                    Order.client_order_id.in_(shard_client_order_ids),
                    Order.wallet_public_id == shard_wallet_public_id,
                    Order.mode == shard_mode,
                    *where_active(Execution, as_of),
                )
            )
            consumed_total = consumed_result.scalar() or 0.0
            return recorded_total - consumed_total > 1e-9

    async def shard_has_accruals(
        self, wallet_public_id: str, exchange: str, mode: str, as_of: datetime
    ) -> bool:
        """Return True when the wallet/exchange/mode has any accrual ledger row.

        The R9 venue-event rebuild reconstructs cash from
        ``initial_cash + fill_flows`` and cannot reconstruct funding accrued
        before the checkpoint, so it is gated to non-funding (spot) shards.
        Funding is per (wallet, exchange, mode); any matching ``accrual_ledger``
        row means the shard's cash carries funding and the rebuild is skipped
        (status-quo recovery), so the gate needs no instrument resolution.

        Args:
            wallet_public_id: Owning wallet.
            exchange: Shard exchange.
            mode: Execution mode (``live``/``paper``).
            as_of: Temporal anchor.

        Returns:
            True if any active accrual ledger row exists for the scope.
        """
        async with self.session() as s:
            result = await s.execute(
                select(func.count())
                .select_from(AccrualLedger)
                .where(
                    AccrualLedger.wallet_public_id == wallet_public_id,
                    AccrualLedger.exchange == exchange,
                    AccrualLedger.mode == mode,
                    *where_active(AccrualLedger, as_of),
                )
            )
            return (result.scalar() or 0) > 0

    async def shard_has_any_accruals(
        self,
        wallet_public_id: str,
        instrument_public_id: str,
        mode: str,
        state_at: datetime,
    ) -> bool:
        """Return accrual existence through a durable projection-state boundary.

        Current-version visibility remains clock-free: ``known_to`` is
        matched only against its sentinel, never against the recovery
        clock. The ``accrued_at <= state_at`` condition instead compares
        two durable economic instants and asks whether the projected
        state could have folded the accrual.

        The accrual ledger carries no strategy-tag identity. Tagged
        siblings therefore share this predicate's scope, so an accrual
        through the state boundary disables cash comparison for all of
        them, a residual fail-open direction for certification.

        Args:
            wallet_public_id: Owning wallet.
            instrument_public_id: Durable instrument identity.
            mode: Execution mode (``live``/``paper``).
            state_at: Inclusive durable state instant being certified.

        Returns:
            True if a current accrual row exists through ``state_at``.
        """
        async with self.session() as s:
            result = await s.execute(
                select(
                    exists().where(
                        AccrualLedger.wallet_public_id == wallet_public_id,
                        AccrualLedger.instrument_public_id == instrument_public_id,
                        AccrualLedger.mode == mode,
                        AccrualLedger.known_to == KNOWN_TO_MAX,
                        AccrualLedger.accrued_at <= state_at,
                    )
                )
            )
            return bool(result.scalar())

    async def has_order_submit_evidence(self, client_order_id: str) -> bool:
        """Return True when durable evidence shows the submit may have reached the venue.

        Probes the append-only ``venue_events`` for any
        ``_ORDER_SUBMIT_EVIDENCE_EVENT_TYPES`` row of the client order
        id — the duplicate-submit guard's durable check,
        covering crash-replay where a fresh executor process has no
        in-memory pending state. Served by
        ``ix_venue_events_cid_event_type``; no ``known_to`` filter is
        needed because venue events are never closed.

        Residual gap, documented deliberately: a crash after the venue
        accepted the order but before the ``order_accepted`` row
        committed (and before recon healed it) leaves no durable trace
        — only a venue lookup by client id could close that window.

        Args:
            client_order_id: Client order id of the replayed command.

        Returns:
            True when at least one evidence event exists.
        """
        async with self.session() as s:
            result = await s.execute(
                select(VenueEvent.id)
                .where(
                    VenueEvent.client_order_id == client_order_id,
                    VenueEvent.event_type.in_(_ORDER_SUBMIT_EVIDENCE_EVENT_TYPES),
                )
                .limit(1)
            )
            return result.first() is not None

    async def has_venue_event(self, client_order_id: str, event_type: str) -> bool:
        """Return True when a venue event of the given type exists for the order.

        Targeted single-type probe (vs the multi-type
        :meth:`has_order_submit_evidence`) used by write-side dedupe: the
        executor's ``order_accepted`` heal retry checks whether the
        supposedly-failed insert actually committed (timeout-after-commit
        race) before inserting again, keeping the append-only plane free of
        avoidable duplicates. Served by ``ix_venue_events_cid_event_type``;
        no ``known_to`` filter is needed because venue events are never
        closed.

        Args:
            client_order_id: Client order id to probe.
            event_type: Exact venue event type to look for.

        Returns:
            True when at least one matching event exists.
        """
        async with self.session() as s:
            result = await s.execute(
                select(VenueEvent.id)
                .where(
                    VenueEvent.client_order_id == client_order_id,
                    VenueEvent.event_type == event_type,
                )
                .limit(1)
            )
            return result.first() is not None

    async def get_order_lifecycle_events(self, client_order_ids: list[str]) -> list[VenueEventRow]:
        """Return lifecycle venue events for a batch of client order ids.

        Feeds the coordinator's trade-command lifecycle fold: all
        ``_ORDER_LIFECYCLE_EVENT_TYPES`` rows for the given ids, globally
        ordered by ``id`` (the append-only plane's only total order) so the
        fold replays venue truth in observation order. The IN list is
        chunked to keep statement size bounded; active command sets are
        small, so a single chunk is the common case. Served by
        ``ix_venue_events_cid_event_type``.

        Args:
            client_order_ids: Client order ids of the active command set.

        Returns:
            Ordered lifecycle rows; empty list for an empty id set.
        """
        if not client_order_ids:
            return []
        rows: list[VenueEventRow] = []
        async with self.session() as s:
            for start in range(0, len(client_order_ids), _ORDER_LIFECYCLE_LOOKUP_CHUNK_SIZE):
                chunk = client_order_ids[start : start + _ORDER_LIFECYCLE_LOOKUP_CHUNK_SIZE]
                result = await s.execute(
                    select(VenueEvent).where(
                        VenueEvent.client_order_id.in_(chunk),
                        VenueEvent.event_type.in_(_ORDER_LIFECYCLE_EVENT_TYPES),
                    )
                )
                rows.extend(self._venue_event_to_row(ve) for ve in result.scalars().all())
        rows.sort(key=lambda r: r["id"])
        return rows

    async def upsert_checkpoint(self, row: CheckpointUpsertRow) -> int:
        """SCD2 upsert for trade projection checkpoint.

        Returns the new row id. Legacy-default: missing
        ``wallet_public_id`` collapses to empty string for
        NOT-NULL-compliant inserts on legacy fixtures.
        """
        async with self.session() as s:
            new_values: dict[str, Any] = {k: v for k, v in row.items() if k != "bus_time"}
            new_values.setdefault("wallet_public_id", "")
            obj = await close_and_insert(
                s,
                TradeProjectionCheckpoint,
                [TradeProjectionCheckpoint.shard_key == row["shard_key"]],
                new_values,
                row["bus_time"],
            )
            await s.commit()
            await s.refresh(obj)
            return int(obj.id)

    @staticmethod
    def _position_identity_filters(
        instrument_public_id: str, mode: str, wallet_public_id: str
    ) -> list[ColumnElement[bool]]:
        """Build the identity predicate for one position projection row.

        Args:
            instrument_public_id: Instrument identity.
            mode: Trading mode (live/paper).
            wallet_public_id: Wallet identity.

        Returns:
            Filters matching the (instrument, mode, wallet) identity.
        """
        return [
            Position.instrument_public_id == instrument_public_id,
            Position.mode == mode,
            Position.wallet_public_id == wallet_public_id,
        ]

    async def _position_projection_close_and_insert(
        self, s: AsyncSession, row: PositionProjectionUpsertRow
    ) -> int:
        """Close the current position version and insert its successor.

        Selects the CURRENT version by the current-version sentinel
        filter under ``FOR UPDATE`` instead of the generic bus-time
        ``close_and_insert`` helper: the trader's bus clock can lag a
        previously stored row timestamp (the Phase-0 clock-skew bug
        class), and a bus-time-scoped select would miss the active row
        and collide with the partial unique index. The effective
        timestamp is clamped to ``max(bus_time, existing.timestamp)``
        so successors never travel back in time; the successor carries
        the predecessor's ``public_id``.

        Args:
            s: Open session owned by the caller.
            row: Full-state snapshot for the identity.

        Returns:
            The new active row id (flushed, not committed).
        """
        existing = (
            (
                await s.execute(
                    select(Position)
                    .where(
                        Position.known_to == KNOWN_TO_MAX,
                        *self._position_identity_filters(
                            row["instrument_public_id"], row["mode"], row["wallet_public_id"]
                        ),
                    )
                    .with_for_update()
                )
            )
            .scalars()
            .first()
        )
        effective = row["bus_time"]
        new_values: dict[str, Any] = {k: v for k, v in row.items() if k != "bus_time"}
        if existing is not None:
            if existing.timestamp > effective:
                effective = existing.timestamp
            new_values["public_id"] = existing.public_id
            await s.execute(
                update(Position).where(Position.id == existing.id).values(known_to=effective)
            )
        new_values["timestamp"] = effective
        new_values["known_to"] = KNOWN_TO_MAX
        obj = Position(**new_values)
        s.add(obj)
        await s.flush()
        return int(obj.id)

    async def upsert_position_projection(self, row: PositionProjectionUpsertRow) -> int:
        """Clock-safe SCD2 upsert for one truthful position identity.

        A concurrent first insert losing the partial-unique race is
        retried exactly once by re-reading the winner inside a fresh
        transaction — the second pass finds the winner's active row and
        closes it like any other update. Callers serialize writes per
        identity (the trader holds a per-identity lock and shard
        ownership keeps foreign processes away); the race retry only
        covers the empty-identity first insert, not sustained
        concurrent writers.

        Args:
            row: Full-state snapshot for the identity.

        Returns:
            The new active row id.
        """
        async with self.session() as s:
            try:
                new_id = await self._position_projection_close_and_insert(s, row)
                await s.commit()
            except IntegrityError:
                await s.rollback()
                new_id = await self._position_projection_close_and_insert(s, row)
                await s.commit()
            return new_id

    async def close_position_projection(
        self, instrument_public_id: str, mode: str, wallet_public_id: str, bus_time: datetime
    ) -> bool:
        """Close the active position row WITHOUT writing a successor.

        Used when every component shard of the identity is proven flat
        — the position disappears from the active surface while SCD2
        history stays queryable via ``as_of``. The close timestamp is
        clamped to ``max(bus_time, existing.timestamp)`` (same clock-
        skew defense as the upsert). Callers MUST serialize this with
        the upsert per identity (trader per-identity lock + shard
        ownership): a concurrent close/upsert pair violates that
        contract and has NO ordering guarantee — the close may miss a
        successor committed after its snapshot.

        Args:
            instrument_public_id: Instrument identity.
            mode: Trading mode (live/paper).
            wallet_public_id: Wallet identity.
            bus_time: Bus time of the proving event.

        Returns:
            True when an active row was closed, False when none existed.
        """
        async with self.session() as s:
            existing = (
                (
                    await s.execute(
                        select(Position)
                        .where(
                            Position.known_to == KNOWN_TO_MAX,
                            *self._position_identity_filters(
                                instrument_public_id, mode, wallet_public_id
                            ),
                        )
                        .with_for_update()
                    )
                )
                .scalars()
                .first()
            )
            if existing is None:
                return False
            effective = bus_time if bus_time > existing.timestamp else existing.timestamp
            await s.execute(
                update(Position).where(Position.id == existing.id).values(known_to=effective)
            )
            await s.commit()
            return True

    @staticmethod
    def _venue_account_identity_filters(
        wallet_public_id: str, exchange: str, mode: str
    ) -> list[ColumnElement[bool]]:
        """Build the identity predicate for one venue account-state row.

        Args:
            wallet_public_id: Full wallet identity (UUID).
            exchange: Venue name (lowercase).
            mode: Trading mode (live/paper).

        Returns:
            Filters matching the (wallet, exchange, mode) identity.
        """
        return [
            VenueAccountState.wallet_public_id == wallet_public_id,
            VenueAccountState.exchange == exchange,
            VenueAccountState.mode == mode,
        ]

    @staticmethod
    def _venue_account_rollup_status(balance_status: str, position_status: str) -> str:
        """Derive the coherent roll-up status from the two component statuses.

        Fail-closed and never caller-supplied: an ``observed`` roll-up requires
        the balance observed AND positions observed or structurally absent
        (``not_applicable``); ``simulated`` follows a simulated (paper) balance;
        ``unsupported`` a wholly unsupported venue; every other combination —
        including a balance observed while positions errored — is ``error`` so
        the roll-up can never over-claim truth a component did not provide.

        Args:
            balance_status: The balance component status.
            position_status: The position component status.

        Returns:
            The roll-up status (observed/simulated/unsupported/error).
        """
        if balance_status == "observed" and position_status in (
            "observed",
            "not_applicable",
        ):
            return "observed"
        if balance_status == "simulated":
            return "simulated"
        if balance_status == "unsupported" and position_status in (
            "unsupported",
            "not_applicable",
        ):
            return "unsupported"
        return "error"

    async def _write_venue_account_snapshot(
        self, s: AsyncSession, attempt: VenueAccountAttemptRow
    ) -> int:
        """Append the attempt observation and SCD2-materialize the state.

        The repository — not the caller — owns coherence and provenance. The
        roll-up status is DERIVED from the two component statuses. Each
        component (balance, positions) is resolved INDEPENDENTLY three ways: a
        freshly observed/simulated component uses this attempt's payload and
        stamps its own observation as the source; a TRANSIENT ``error`` retains
        the last good payload AND its true source id from the locked
        predecessor (stale-visible, never re-attributed to this attempt); a
        STRUCTURALLY absent component (``not_applicable``) or unavailable one
        (``unsupported``) is CLEARED to NULL — the truth is "nothing here", so
        a prior observed payload must never linger under an authoritative
        ``observed`` roll-up. The active row is selected ``FOR UPDATE`` by the
        sentinel-active filter and the effective timestamp clamped to
        ``max(bus_time, existing.timestamp)`` (clock-skew defense); the
        successor carries the predecessor's ``public_id``.

        Args:
            s: Open session owned by the caller.
            attempt: The raw outcome of one account-observation attempt.

        Returns:
            The new active state row id (flushed, not committed).
        """
        status = self._venue_account_rollup_status(
            attempt["balance_status"], attempt["position_status"]
        )
        balance_fresh = attempt["balance_status"] in ("observed", "simulated")
        position_fresh = attempt["position_status"] == "observed"
        obs = VenueAccountObservation(
            wallet_public_id=attempt["wallet_public_id"],
            exchange=attempt["exchange"],
            mode=attempt["mode"],
            attempt_status=status,
            balance_status=attempt["balance_status"],
            position_status=attempt["position_status"],
            balances_json=attempt["balances_json"] if balance_fresh else None,
            open_positions_json=(attempt["open_positions_json"] if position_fresh else None),
            balance_observed_at=(attempt["balance_observed_at"] if balance_fresh else None),
            position_observed_at=(attempt["position_observed_at"] if position_fresh else None),
            error=attempt["error"],
            session_id=attempt["session_id"],
            sequence_id=attempt["sequence_id"],
            timestamp=attempt["bus_time"],
            known_to=KNOWN_TO_MAX,
        )
        s.add(obs)
        await s.flush()
        obs_id = int(obs.id)
        existing = (
            (
                await s.execute(
                    select(VenueAccountState)
                    .where(
                        VenueAccountState.known_to == KNOWN_TO_MAX,
                        *self._venue_account_identity_filters(
                            attempt["wallet_public_id"],
                            attempt["exchange"],
                            attempt["mode"],
                        ),
                    )
                    .with_for_update()
                )
            )
            .scalars()
            .first()
        )
        if balance_fresh:
            balances_json = attempt["balances_json"]
            balance_observed_at = attempt["balance_observed_at"]
            balance_payload_source_observation_id: int | None = obs_id
            authoritative_until = attempt["authoritative_until"]
        elif attempt["balance_status"] == "error" and existing is not None:
            balances_json = existing.balances_json
            balance_observed_at = existing.balance_observed_at
            balance_payload_source_observation_id = existing.balance_payload_source_observation_id
            authoritative_until = existing.authoritative_until
        else:
            balances_json = None
            balance_observed_at = None
            balance_payload_source_observation_id = None
            authoritative_until = None
        if position_fresh:
            open_positions_json = attempt["open_positions_json"]
            position_observed_at = attempt["position_observed_at"]
            position_payload_source_observation_id: int | None = obs_id
        elif attempt["position_status"] == "error" and existing is not None:
            open_positions_json = existing.open_positions_json
            position_observed_at = existing.position_observed_at
            position_payload_source_observation_id = existing.position_payload_source_observation_id
        else:
            open_positions_json = None
            position_observed_at = None
            position_payload_source_observation_id = None
        effective = attempt["bus_time"]
        new_values: dict[str, Any] = {
            "wallet_public_id": attempt["wallet_public_id"],
            "exchange": attempt["exchange"],
            "mode": attempt["mode"],
            "sync_status": status,
            "balance_status": attempt["balance_status"],
            "position_status": attempt["position_status"],
            "valuation_status": attempt["valuation_status"],
            "balances_json": balances_json,
            "open_positions_json": open_positions_json,
            "balance_observed_at": balance_observed_at,
            "position_observed_at": position_observed_at,
            "current_attempt_observation_id": obs_id,
            "balance_payload_source_observation_id": balance_payload_source_observation_id,
            "position_payload_source_observation_id": position_payload_source_observation_id,
            "authoritative_until": authoritative_until,
            "error": attempt["error"],
            "session_id": attempt["session_id"],
            "sequence_id": attempt["sequence_id"],
        }
        if existing is not None:
            if existing.timestamp > effective:
                effective = existing.timestamp
            new_values["public_id"] = existing.public_id
            await s.execute(
                update(VenueAccountState)
                .where(VenueAccountState.id == existing.id)
                .values(known_to=effective)
            )
        new_values["timestamp"] = effective
        new_values["known_to"] = KNOWN_TO_MAX
        obj = VenueAccountState(**new_values)
        s.add(obj)
        await s.flush()
        return int(obj.id)

    async def record_venue_account_snapshot(self, attempt: VenueAccountAttemptRow) -> int:
        """Atomically append an account observation and upsert its SCD2 state.

        Both writes commit in ONE transaction so a state row can never
        reference a missing observation and a failed materialization leaves
        no orphan attempt. A concurrent first insert losing the identity's
        partial-unique race is retried exactly once (fresh objects) — the
        second pass finds the winner's active row and closes it. Callers
        serialize writes per identity (one account observer per
        wallet/exchange); the retry only covers the empty-identity first
        insert.

        Args:
            attempt: The raw outcome of one account-observation attempt.

        Returns:
            The new active state row id.
        """
        canonical_attempt = attempt.copy()
        canonical_attempt["wallet_public_id"] = _canonicalize_reconciliation_wallet_public_id(
            attempt["wallet_public_id"]
        )
        async with self.session() as s:
            try:
                state_id = await self._write_venue_account_snapshot(s, canonical_attempt)
                await s.commit()
            except IntegrityError:
                await s.rollback()
                state_id = await self._write_venue_account_snapshot(s, canonical_attempt)
                await s.commit()
            return state_id

    @staticmethod
    def _venue_account_state_to_row(state: VenueAccountState) -> VenueAccountStateRow:
        """Project a VenueAccountState ORM row to its read TypedDict.

        Args:
            state: The active ORM row.

        Returns:
            The read row dict.
        """
        return {
            "wallet_public_id": state.wallet_public_id,
            "exchange": state.exchange,
            "mode": state.mode,
            "sync_status": state.sync_status,
            "balance_status": state.balance_status,
            "position_status": state.position_status,
            "valuation_status": state.valuation_status,
            "balances_json": state.balances_json,
            "open_positions_json": state.open_positions_json,
            "balance_observed_at": state.balance_observed_at,
            "position_observed_at": state.position_observed_at,
            "current_attempt_observation_id": state.current_attempt_observation_id,
            "balance_payload_source_observation_id": (state.balance_payload_source_observation_id),
            "position_payload_source_observation_id": (
                state.position_payload_source_observation_id
            ),
            "authoritative_until": state.authoritative_until,
            "error": state.error,
            "public_id": state.public_id,
            "timestamp": state.timestamp,
            "session_id": state.session_id,
            "sequence_id": state.sequence_id,
        }

    async def get_venue_account_states(
        self, wallet_public_ids: list[str] | None = None
    ) -> list[VenueAccountStateRow]:
        """Return the active venue account-truth rows, optionally wallet-scoped.

        Sentinel-active read (``known_to == KNOWN_TO_MAX``), never a
        caller-clock ``as_of`` scan — a venue account state has no truthful
        historical projection, only its current observation. The partial
        unique index guarantees at most one active row per identity, so no
        read-time duplicate collapse is needed. ``None`` applies NO wallet
        filter (the ADMIN-unscoped view, mirroring ``get_positions``); a
        non-empty list scopes to those wallets; an EMPTY list scopes to
        nothing (a caller with no accessible wallets — never an unfiltered
        scan, since the ``server.scoping`` primitives return ``None`` only
        for an admin with no explicit scope).

        Args:
            wallet_public_ids: Full wallet identities to include, or ``None``
                for no wallet filter (admin-unscoped). An empty list yields an
                empty result.

        Returns:
            Active account-state rows, ordered by exchange then mode.

        Raises:
            ValueError: If a supplied wallet identity is malformed. Alias UUID
                spellings are canonicalized before filtering.
        """
        canonical_wallet_public_ids = (
            None
            if wallet_public_ids is None
            else [
                _canonicalize_reconciliation_wallet_public_id(wallet_public_id)
                for wallet_public_id in wallet_public_ids
            ]
        )
        async with self.session() as s:
            query = select(VenueAccountState).where(VenueAccountState.known_to == KNOWN_TO_MAX)
            if canonical_wallet_public_ids is not None:
                query = query.where(
                    VenueAccountState.wallet_public_id.in_(canonical_wallet_public_ids)
                )
            query = query.order_by(VenueAccountState.exchange, VenueAccountState.mode)
            rows = (await s.execute(query)).scalars().all()
            return [self._venue_account_state_to_row(r) for r in rows]

    async def get_venue_account_state_version(self, state_id: int) -> VenueAccountStateRow | None:
        """Return one immutable SCD2 state version without an active-row filter."""
        async with self.session() as s:
            row = await s.get(VenueAccountState, state_id)
            return None if row is None else self._venue_account_state_to_row(row)

    @staticmethod
    def _spot_anchor_to_row(
        anchor: PortfolioSpotReconciliationAnchor,
    ) -> SpotReconciliationAnchorRow:
        """Project one immutable anchor ORM row to its typed boundary."""
        return {
            "public_id": anchor.public_id,
            "wallet_public_id": anchor.wallet_public_id,
            "exchange": anchor.exchange,
            "mode": anchor.mode,
            "venue_account_state_public_id": anchor.venue_account_state_public_id,
            "balance_observation_id": anchor.balance_observation_id,
            "source_watermark_kind": anchor.source_watermark_kind,
            "source_watermark": anchor.source_watermark,
            "balances_json": anchor.balances_json,
            "first_request_started_at": anchor.first_request_started_at,
            "first_request_completed_at": anchor.first_request_completed_at,
            "second_request_started_at": anchor.second_request_started_at,
            "second_request_completed_at": anchor.second_request_completed_at,
            "boundary_status": anchor.boundary_status,
            "inventory_status": anchor.inventory_status,
            "margin_status": anchor.margin_status,
            "provenance": anchor.provenance,
            "session_id": anchor.session_id,
            "sequence_id": anchor.sequence_id,
            "timestamp": anchor.timestamp,
            "source_chain_tip": anchor.source_chain_tip,
            "venue_cursor_kind": anchor.venue_cursor_kind,
            "venue_cursor_scheme": anchor.venue_cursor_scheme,
            "venue_cursor_value": anchor.venue_cursor_value,
            "venue_cursor_requested_at": anchor.venue_cursor_requested_at,
            "venue_cursor_observed_at": anchor.venue_cursor_observed_at,
            "venue_cursor_confirmed_at": anchor.venue_cursor_confirmed_at,
            "source_watermark_requested_at": anchor.source_watermark_requested_at,
            "source_watermark_captured_at": anchor.source_watermark_captured_at,
        }

    @staticmethod
    def _spot_anchor_unique_object(pairs: list[tuple[str, object]]) -> dict[str, object]:
        """Decode a JSON object while rejecting duplicate asset keys."""
        result: dict[str, object] = {}
        for key, value in pairs:
            if key in result:
                raise ValueError("duplicate anchor balance asset")
            result[key] = value
        return result

    @staticmethod
    def _normalized_spot_anchor_balance(asset: object, value: object) -> tuple[str, str]:
        """Validate and normalize one exact-decimal anchor balance."""
        if not isinstance(asset, str) or not asset or asset.strip() != asset:
            raise ValueError("anchor balance asset is invalid")
        if not isinstance(value, str) or not value:
            raise ValueError("anchor balance must be an exact decimal string")
        try:
            amount = Decimal(value)
        except Exception as exc:
            raise ValueError("anchor balance decimal is malformed") from exc
        exponent = amount.as_tuple().exponent
        if not amount.is_finite() or not isinstance(exponent, int) or abs(exponent) > 256:
            raise ValueError("anchor balance decimal is not finite or bounded")
        rendered = format(amount, "f")
        if "." in rendered:
            rendered = rendered.rstrip("0").rstrip(".")
        return asset, "0" if rendered in ("", "-0") else rendered

    @staticmethod
    def _validate_spot_anchor_balances_json(raw: str) -> None:
        """Require canonical sorted asset-to-exact-decimal-string evidence."""
        parsed_object: object = json.loads(
            raw,
            object_pairs_hook=SQLAlchemyRepository._spot_anchor_unique_object,
        )
        if not isinstance(parsed_object, dict) or not parsed_object:
            raise ValueError("anchor balances must be a non-empty object")
        parsed = cast(dict[object, object], parsed_object)
        normalized = dict(
            SQLAlchemyRepository._normalized_spot_anchor_balance(asset, value)
            for asset, value in parsed.items()
        )
        canonical = json.dumps(normalized, allow_nan=False, separators=(",", ":"), sort_keys=True)
        if raw != canonical:
            raise ValueError("anchor balances must use canonical sorted decimal strings")

    async def record_spot_reconciliation_anchor(self, anchor: SpotReconciliationAnchorRow) -> int:
        """Insert an immutable bootstrap anchor or accept its exact replay.

        On the INSERT path the committed execution tip is re-read inside the same
        transaction and the anchor is refused unless its ``source_watermark``
        still equals ``max(scope_sequence)`` for the scope, so a caller-fabricated
        or stale watermark can never be sealed. The re-read is not fenced against
        ingest, so a fill MAY commit between it and this insert — such a fill
        allocates ``> W`` and lands in the replay range, which is exactly where
        it belongs; the freshness of ``W`` itself is the pure module's quiescence
        obligation, not this guard's. An exact idempotent replay still succeeds
        after the tip has legitimately advanced, because the re-read guards only
        new inserts.
        """
        canonical_anchor = anchor.copy()
        canonical_anchor["wallet_public_id"] = _canonicalize_reconciliation_wallet_public_id(
            anchor["wallet_public_id"]
        )
        self._validate_spot_anchor_balances_json(canonical_anchor["balances_json"])
        identity = (
            canonical_anchor["wallet_public_id"],
            canonical_anchor["exchange"],
            canonical_anchor["mode"],
        )
        lock = self._portfolio_reconciliation_locks.setdefault(identity, asyncio.Lock())
        async with lock, self.session() as s:
            existing = (
                (
                    await s.execute(
                        select(PortfolioSpotReconciliationAnchor)
                        .where(
                            PortfolioSpotReconciliationAnchor.known_to == KNOWN_TO_MAX,
                            PortfolioSpotReconciliationAnchor.wallet_public_id
                            == canonical_anchor["wallet_public_id"],
                            PortfolioSpotReconciliationAnchor.exchange
                            == canonical_anchor["exchange"],
                            PortfolioSpotReconciliationAnchor.mode == canonical_anchor["mode"],
                        )
                        .with_for_update()
                    )
                )
                .scalars()
                .first()
            )
            if existing is not None:
                if self._spot_anchor_to_row(existing) != canonical_anchor:
                    raise RuntimeError("conflicting spot reconciliation bootstrap anchor")
                return int(existing.id)
            committed_tip = int(
                (
                    await s.execute(
                        select(func.max(Execution.scope_sequence)).where(
                            Execution.wallet_public_id == canonical_anchor["wallet_public_id"],
                            Execution.exchange == canonical_anchor["exchange"],
                            Execution.mode == canonical_anchor["mode"],
                        )
                    )
                ).scalar()
                or 0
            )
            if committed_tip != canonical_anchor["source_watermark"]:
                raise RuntimeError(
                    "spot reconciliation anchor watermark is not the committed execution tip"
                )
            row = PortfolioSpotReconciliationAnchor(**canonical_anchor, known_to=KNOWN_TO_MAX)
            s.add(row)
            try:
                await s.commit()
            except IntegrityError:
                await s.rollback()
                winner_result = await s.execute(
                    select(PortfolioSpotReconciliationAnchor).where(
                        PortfolioSpotReconciliationAnchor.known_to == KNOWN_TO_MAX,
                        PortfolioSpotReconciliationAnchor.wallet_public_id
                        == canonical_anchor["wallet_public_id"],
                        PortfolioSpotReconciliationAnchor.exchange == canonical_anchor["exchange"],
                        PortfolioSpotReconciliationAnchor.mode == canonical_anchor["mode"],
                    )
                )
                winner = winner_result.scalars().first()
                if winner is None or self._spot_anchor_to_row(winner) != canonical_anchor:
                    raise RuntimeError("conflicting spot reconciliation bootstrap anchor") from None
                return int(winner.id)
            await s.refresh(row)
            return int(row.id)

    async def get_spot_reconciliation_anchor(
        self, wallet_public_id: str, exchange: str, mode: str
    ) -> SpotReconciliationAnchorRow | None:
        """Return one active immutable bootstrap anchor by account identity.

        Alias UUID spellings are canonicalized before filtering; malformed
        wallet identities raise ``ValueError`` like reconciliation writers.
        """
        wallet_public_id = _canonicalize_reconciliation_wallet_public_id(wallet_public_id)
        async with self.session() as s:
            anchor = (
                (
                    await s.execute(
                        select(PortfolioSpotReconciliationAnchor).where(
                            PortfolioSpotReconciliationAnchor.known_to == KNOWN_TO_MAX,
                            PortfolioSpotReconciliationAnchor.wallet_public_id == wallet_public_id,
                            PortfolioSpotReconciliationAnchor.exchange == exchange,
                            PortfolioSpotReconciliationAnchor.mode == mode,
                        )
                    )
                )
                .scalars()
                .first()
            )
            return None if anchor is None else self._spot_anchor_to_row(anchor)

    async def get_spot_execution_watermark(
        self, wallet_public_id: str, exchange: str, mode: str, as_of: datetime
    ) -> tuple[int, datetime]:
        """Capture the unlocked scoped ``max(scope_sequence)`` append boundary.

        The capture takes NO lock, and this time that is CORRECT for a
        provable reason (the predecessor's lock-free contract over
        ``max(Execution.id)`` was a defect; the fenced rework that fixed it
        is superseded by the counter): ``scope_sequence`` is allocated as
        the committed per-scope maximum plus one while HOLDING the
        per-wallet execution fence inside :meth:`insert_execution`, so per
        scope the values EVER COMMITTED are exactly ``{1..K}``, at most
        one assignment is in flight (the fence holder, whose value is
        ``K+1``), and every future assignment is strictly greater. This
        speaks about allocated values, NOT about rows still stored: rows
        can leave the table, so the stored set is at most a SUBSET of
        ``{1..K}`` and must never be assumed contiguous. The sealed prefix
        additionally REQUIRES that ``K`` never decrease, which the fence
        does NOT provide — ``K`` is derived from the table on every
        insert, so deleting a scope's tip lowers it and the next insert
        re-mints a value at or below a captured watermark, silently
        replacing a certified fill. That premise is upheld by refusing to
        delete executions at all through supported paths (the archiver
        refuses ``--purge`` for this table, and restore is refused
        likewise); both are load-bearing for THIS contract rather than
        defense in depth. Given them, an unlocked read of the committed
        maximum is a sealed prefix — no row at or below the returned
        watermark can ever commit after the capture.
        The capture is no longer a serialization point at all: it cannot
        stall, cannot block ingest, and needs no ``lock_timeout``, no
        fence acquisition, and no id-sequence cache probe (no
        ``Execution.id`` property is load-bearing anymore).

        Scope membership is the stored immutable ``exchange``/``mode``
        columns — no Order/Instrument joins and no ``known_to`` filter
        (append-only doctrine; see the module docstring) — so the read is
        index-only on ``uq_executions_scope_sequence``. Lineage integrity
        is enforced per-row at ingest (:meth:`insert_execution` refuses
        unresolvable or crossed rows before persistence), and the
        append-only ``known_to``-still-open assertion moves to the S4c-4
        replay bundle, range-local, where the exact range is re-read
        anyway — the total-unique index already refuses a supersede at
        write time.

        ``as_of`` no longer defines scope membership; it is echoed back
        verbatim as the instant the S4c-4 replay bundle must pin its
        temporal reads to (instrument identity, specs, asset precisions),
        so the certificate's supporting evidence is read at one instant.
        An account with no execution history yields watermark ``0`` — an
        honest boundary the anchor plane then refuses to seal (its CHECK
        requires ``source_watermark >= 1``; a scope must trade once before
        it can anchor). Alias UUID spellings are canonicalized before
        filtering; malformed wallet identities raise ``ValueError`` like
        reconciliation writers.
        """
        wallet_public_id = _canonicalize_reconciliation_wallet_public_id(wallet_public_id)
        async with self.session() as s:
            watermark = (
                await s.execute(
                    select(func.max(Execution.scope_sequence)).where(
                        Execution.wallet_public_id == wallet_public_id,
                        Execution.exchange == exchange,
                        Execution.mode == mode,
                    )
                )
            ).scalar()
            return (0 if watermark is None else int(watermark)), as_of

    async def get_spot_execution_chain_tip(
        self,
        wallet_public_id: str,
        exchange: str,
        mode: str,
        from_watermark: int,
        from_tip: str,
        to_watermark: int,
    ) -> str:
        """Fold the scope's executions in ``(from_watermark, to_watermark]`` onto ``from_tip``.

        See the abstract declaration. The contiguity assertion is sound because
        executions are append-only (delete refused through every supported
        path), so per scope the values committed are ``{1..K}`` and a value
        missing from the half-open range is a purge or a tamper, not a normal
        state — it fails closed. Records are projected inside the read session
        so their loaded columns are accessed before the entities detach; the
        fold itself is pure.

        RAW plane, and deliberately so: the chain is TAMPER evidence over what
        the ledger physically holds, not a statement about what counts
        economically. An annulled row keeps contributing its link exactly as
        before, so a correction can never move a tip and no tip comparison can
        be made to agree by appending a manifest row.
        """
        wallet_public_id = _canonicalize_reconciliation_wallet_public_id(wallet_public_id)
        async with self.session() as s:
            return await self._fold_execution_chain_tip(
                s, wallet_public_id, exchange, mode, from_watermark, from_tip, to_watermark
            )

    @classmethod
    async def _fold_execution_chain_tip(
        cls,
        s: AsyncSession,
        wallet_public_id: str,
        exchange: str,
        mode: str,
        from_watermark: int,
        from_tip: str,
        to_watermark: int,
    ) -> str:
        """Fold the chain range on the CALLER's session (pre-canonicalized wallet).

        Session-scoped so the spot bundle folds inside its own snapshot
        transaction; :meth:`get_spot_execution_chain_tip` keeps the own-session
        contract for every other consumer.
        """
        if from_watermark < 0 or to_watermark < from_watermark:
            raise ExecutionChainError(
                f"invalid chain range: from_watermark={from_watermark} to_watermark={to_watermark}"
            )
        executions = (
            (
                await s.execute(
                    select(Execution)
                    .where(
                        Execution.wallet_public_id == wallet_public_id,
                        Execution.exchange == exchange,
                        Execution.mode == mode,
                        Execution.scope_sequence > from_watermark,
                        Execution.scope_sequence <= to_watermark,
                    )
                    .order_by(Execution.scope_sequence.asc())
                )
            )
            .scalars()
            .all()
        )
        expected = to_watermark - from_watermark
        if len(executions) != expected:
            raise ExecutionChainError(
                f"non-contiguous execution range for scope "
                f"({wallet_public_id}, {exchange}, {mode}): expected {expected} row(s) in "
                f"({from_watermark}, {to_watermark}], found {len(executions)}"
            )
        records = [cls._execution_chain_record(execution) for execution in executions]
        return extend_execution_chain(from_tip, records)

    async def get_spot_execution_witness_rows(
        self,
        wallet_public_id: str,
        exchange: str,
        mode: str,
        upto_watermark: int,
        from_watermark: int = 0,
    ) -> list[SpotExecutionWitnessRow]:
        """Read the range ``(from_watermark, upto_watermark]`` for a witness join.

        See the abstract declaration. Contiguity is required (append-only, delete
        refused through every supported path), so a missing sequence value is a
        purge or a tamper and fails closed. Columns are read inside the session
        before the entities detach; the projection is pure.
        """
        wallet_public_id = _canonicalize_reconciliation_wallet_public_id(wallet_public_id)
        async with self.session() as s:
            executions = (
                (
                    await s.execute(
                        select(Execution)
                        .where(
                            Execution.wallet_public_id == wallet_public_id,
                            Execution.exchange == exchange,
                            Execution.mode == mode,
                            Execution.scope_sequence > from_watermark,
                            Execution.scope_sequence <= upto_watermark,
                        )
                        .order_by(Execution.scope_sequence.asc())
                    )
                )
                .scalars()
                .all()
            )
            if len(executions) != upto_watermark - from_watermark:
                raise ExecutionChainError(
                    f"non-contiguous execution range for scope "
                    f"({wallet_public_id}, {exchange}, {mode}): expected "
                    f"{upto_watermark - from_watermark} row(s) in "
                    f"({from_watermark}, {upto_watermark}], found {len(executions)}"
                )
            rows: list[SpotExecutionWitnessRow] = [
                {"scope_sequence": int(execution.scope_sequence), "exec_id": execution.exec_id}
                for execution in executions
            ]
        return rows

    @staticmethod
    def _spot_bundle_unavailable(error: str) -> SpotReconciliationBundle:
        """Return the fail-closed empty spot bundle carrying one named reason."""
        return SpotReconciliationBundle(
            anchor=None,
            replay=[],
            instruments_by_public_id={},
            specs_by_instrument_public_id={},
            asset_precisions={},
            previously_confirmed_assets=frozenset(),
            range_complete=False,
            boundary_chain_tip=None,
            error=error,
        )

    @staticmethod
    def _spot_confirmed_assets_from_state(
        state: PortfolioReconciliationState | None,
        anchor_public_id: str,
        anchor_assets: frozenset[str],
    ) -> frozenset[str]:
        """Derive the previously confirmed assets from the active state row.

        Eligible only when the state's last FULL outcome came from the current
        anchor epoch with its detail evidence still the retained one; assets
        whose actual reading was ``absent_as_zero`` never confirm. Ineligible
        or absent state yields the anchor keys alone (the honest first-run
        value). A malformed retained payload raises ``ValueError`` so the
        caller refuses by name rather than silently shrinking the tripwire.
        """
        if (
            state is None
            or state.method != "spot_execution_replay"
            or state.last_full_outcome not in ("matched", "mismatched")
            or state.detail_source_observation_id is None
            or state.detail_source_observation_id != state.last_full_observation_id
            or state.anchor_public_id != anchor_public_id
            or state.actual_json is None
        ):
            return anchor_assets

        def _reject_duplicates(pairs: list[tuple[str, JsonValue]]) -> dict[str, JsonValue]:
            mapping: dict[str, JsonValue] = {}
            for key, value in pairs:
                if key in mapping:
                    raise ValueError(f"duplicate confirmed-asset key: {key!r}")
                mapping[key] = value
            return mapping

        payload = json.loads(
            state.actual_json,
            object_pairs_hook=_reject_duplicates,
        )
        assets = payload.get("assets")
        if not isinstance(assets, dict):
            raise ValueError("confirmed-asset payload has no assets object")
        confirmed: set[str] = set()
        for asset, detail in assets.items():
            if not isinstance(detail, dict) or not isinstance(detail.get("absent_as_zero"), bool):
                raise ValueError(f"confirmed-asset detail malformed for {asset!r}")
            if detail["absent_as_zero"] is False:
                confirmed.add(asset)
        return frozenset(confirmed) | anchor_assets

    async def get_spot_reconciliation_bundle(
        self,
        wallet_public_id: str,
        exchange: str,
        mode: str,
        as_of: datetime,
        boundary_watermark: int,
        venue_assets: frozenset[str],
    ) -> SpotReconciliationBundle:
        """Load the spot evaluator's inputs in one repeatable snapshot.

        See the abstract declaration. Two temporal instants are load-bearing:
        every read here pins to the capture-echoed ``as_of`` (the boundary
        contract), while the evaluator judges freshness against its own
        ``now`` — a spec revised between them reads clean here yet fails
        freshness there, which is fail-closed. ``range_complete`` is the
        counted contiguity proof over the sealed allocation (committed max+1
        under the ingest fence), replacing any in-transaction tip recheck; the
        chain fold verifies the range against the anchor tip and the newest
        matched checkpoint of the current anchor epoch, so a rolled-back or
        diverged ledger refuses by name before any evaluation.
        """
        wallet_public_id = _canonicalize_reconciliation_wallet_public_id(wallet_public_id)
        if mode != "live" or not exchange or exchange.strip().lower() != exchange:
            return self._spot_bundle_unavailable("invalid_spot_bundle_identity")
        if self.dialect_name not in ("postgresql", "sqlite"):
            return self._spot_bundle_unavailable("unsupported_spot_bundle_dialect")
        async with self.session() as s, s.begin():
            if self.dialect_name == "postgresql":
                await s.execute(text("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY"))
            anchor_orm = (
                (
                    await s.execute(
                        select(PortfolioSpotReconciliationAnchor).where(
                            PortfolioSpotReconciliationAnchor.known_to == KNOWN_TO_MAX,
                            PortfolioSpotReconciliationAnchor.wallet_public_id == wallet_public_id,
                            PortfolioSpotReconciliationAnchor.exchange == exchange,
                            PortfolioSpotReconciliationAnchor.mode == mode,
                        )
                    )
                )
                .scalars()
                .first()
            )
            if anchor_orm is None:
                return SpotReconciliationBundle(
                    anchor=None,
                    replay=[],
                    instruments_by_public_id={},
                    specs_by_instrument_public_id={},
                    asset_precisions={},
                    previously_confirmed_assets=frozenset(),
                    range_complete=False,
                    boundary_chain_tip=None,
                    error=None,
                )
            anchor = self._spot_anchor_to_row(anchor_orm)
            anchor_watermark = anchor["source_watermark"]
            if anchor_watermark < 1 or anchor_watermark > boundary_watermark:
                return self._spot_bundle_unavailable("invalid_spot_bundle_watermarks")
            try:
                self._validate_spot_anchor_balances_json(anchor["balances_json"])
                anchor_assets = frozenset(json.loads(anchor["balances_json"]))
            except ValueError:
                return self._spot_bundle_unavailable("corrupt_spot_anchor_balances")

            replay_result = await s.execute(
                select(
                    Execution,
                    Order.public_id.label("order_public_id"),
                    Order.mode.label("order_mode"),
                    Instrument.public_id.label("instrument_public_id"),
                    Instrument.exchange.label("instrument_exchange"),
                    Symbol.native_symbol.label("native_symbol"),
                    Symbol.base.label("base_asset"),
                    Symbol.quote.label("quote_asset"),
                )
                .outerjoin(
                    Order,
                    and_(
                        Execution.order_public_id == Order.public_id,
                        *where_active(Order, as_of),
                    ),
                )
                .outerjoin(
                    Instrument,
                    and_(
                        Order.instrument_public_id == Instrument.public_id,
                        *where_active(Instrument, as_of),
                    ),
                )
                .outerjoin(
                    Symbol,
                    and_(
                        Instrument.symbol_public_id == Symbol.public_id,
                        *where_active(Symbol, as_of),
                    ),
                )
                .where(
                    Execution.wallet_public_id == wallet_public_id,
                    Execution.exchange == exchange,
                    Execution.mode == mode,
                    Execution.scope_sequence > anchor_watermark,
                    Execution.scope_sequence <= boundary_watermark,
                )
                .order_by(Execution.scope_sequence.asc())
            )
            replay: list[SpotReplayExecutionSourceRow] = []
            instruments: dict[str, SpotInstrumentIdentitySourceRow] = {}
            seen_sequences: set[int] = set()
            for (
                execution,
                order_public_id,
                order_mode,
                instrument_public_id,
                instrument_exchange,
                native_symbol,
                base_asset,
                quote_asset,
            ) in replay_result.all():
                if execution.scope_sequence in seen_sequences:
                    return self._spot_bundle_unavailable("ambiguous_spot_instrument_identity")
                seen_sequences.add(execution.scope_sequence)
                if execution.known_to != KNOWN_TO_MAX:
                    return self._spot_bundle_unavailable("unstable_spot_replay_range")
                if order_public_id is None:
                    return self._spot_bundle_unavailable("missing_spot_execution_order_identity")
                if (
                    instrument_public_id is None
                    or not native_symbol
                    or not base_asset
                    or not quote_asset
                ):
                    return self._spot_bundle_unavailable("missing_spot_instrument_identity")
                if instrument_exchange != execution.exchange or order_mode != execution.mode:
                    return self._spot_bundle_unavailable("conflicting_spot_instrument_identity")
                identity: SpotInstrumentIdentitySourceRow = {
                    "instrument_public_id": instrument_public_id,
                    "symbol": native_symbol,
                    "base_asset": base_asset,
                    "quote_asset": quote_asset,
                }
                if (known := instruments.get(instrument_public_id)) is not None and (
                    known != identity
                ):
                    return self._spot_bundle_unavailable("conflicting_spot_instrument_identity")
                instruments[instrument_public_id] = identity
                replay.append(
                    {
                        "scope_sequence": int(execution.scope_sequence),
                        "wallet_public_id": execution.wallet_public_id,
                        "exchange": execution.exchange,
                        "mode": execution.mode,
                        "status": execution.status,
                        "instrument_public_id": instrument_public_id,
                        "symbol": native_symbol,
                        "base_asset": base_asset,
                        "quote_asset": quote_asset,
                        "side": execution.side,
                        "price": execution.price,
                        "size": execution.size,
                        "fee": execution.fee,
                        "fee_asset": execution.fee_asset,
                        "price_decimal": execution.price_decimal,
                        "size_decimal": execution.size_decimal,
                        "fee_decimal": execution.fee_decimal,
                        "counter_amount_decimal": execution.counter_amount_decimal,
                        "numeric_provenance": execution.numeric_provenance,
                    }
                )
            range_complete = len(replay) == boundary_watermark - anchor_watermark
            replay = await self._effective_spot_replay_rows(
                s,
                _SpotReplayEffectiveRequest(
                    wallet_public_id=wallet_public_id,
                    exchange=exchange,
                    mode=mode,
                    anchor_watermark=anchor_watermark,
                    boundary_watermark=boundary_watermark,
                    replay=replay,
                ),
            )

            state = (
                (
                    await s.execute(
                        select(PortfolioReconciliationState).where(
                            PortfolioReconciliationState.known_to == KNOWN_TO_MAX,
                            PortfolioReconciliationState.wallet_public_id == wallet_public_id,
                            PortfolioReconciliationState.exchange == exchange,
                            PortfolioReconciliationState.mode == mode,
                        )
                    )
                )
                .scalars()
                .first()
            )
            checkpoint_observation = (
                (
                    await s.execute(
                        select(PortfolioReconciliationObservation)
                        .where(
                            PortfolioReconciliationObservation.wallet_public_id == wallet_public_id,
                            PortfolioReconciliationObservation.exchange == exchange,
                            PortfolioReconciliationObservation.mode == mode,
                            PortfolioReconciliationObservation.method == "spot_execution_replay",
                            PortfolioReconciliationObservation.evaluation_status == "matched",
                            PortfolioReconciliationObservation.anchor_public_id
                            == anchor["public_id"],
                            PortfolioReconciliationObservation.source_chain_tip.is_not(None),
                            PortfolioReconciliationObservation.source_watermark.is_not(None),
                        )
                        .order_by(PortfolioReconciliationObservation.id.desc())
                        .limit(1)
                    )
                )
                .scalars()
                .first()
            )
            checkpoint: tuple[int, str] | None = None
            if (
                checkpoint_observation is not None
                and checkpoint_observation.source_chain_tip is not None
                and checkpoint_observation.source_watermark is not None
            ):
                checkpoint = (
                    int(checkpoint_observation.source_watermark),
                    checkpoint_observation.source_chain_tip,
                )
            try:
                if checkpoint is not None:
                    checkpoint_watermark, checkpoint_tip = checkpoint
                    if boundary_watermark < checkpoint_watermark:
                        return self._spot_bundle_unavailable("execution_chain_regressed")
                    derived_checkpoint = await self._fold_execution_chain_tip(
                        s,
                        wallet_public_id,
                        exchange,
                        mode,
                        anchor_watermark,
                        anchor["source_chain_tip"],
                        checkpoint_watermark,
                    )
                    if derived_checkpoint != checkpoint_tip:
                        return self._spot_bundle_unavailable("execution_chain_diverged")
                    boundary_chain_tip = await self._fold_execution_chain_tip(
                        s,
                        wallet_public_id,
                        exchange,
                        mode,
                        checkpoint_watermark,
                        checkpoint_tip,
                        boundary_watermark,
                    )
                else:
                    boundary_chain_tip = await self._fold_execution_chain_tip(
                        s,
                        wallet_public_id,
                        exchange,
                        mode,
                        anchor_watermark,
                        anchor["source_chain_tip"],
                        boundary_watermark,
                    )
            except ExecutionChainError:
                return self._spot_bundle_unavailable("execution_chain_broken")

            spec_result = await s.execute(
                select(InstrumentSpec).where(
                    InstrumentSpec.instrument_public_id.in_(tuple(instruments)),
                    *where_active(InstrumentSpec, as_of),
                )
            )
            specs: dict[str, InstrumentSpecRow | None] = dict.fromkeys(instruments)
            for spec in spec_result.scalars().all():
                if specs.get(spec.instrument_public_id) is not None:
                    return self._spot_bundle_unavailable("duplicate_spot_instrument_spec")
                specs[spec.instrument_public_id] = self._instrument_spec_row(spec)

            replay_assets = {row["base_asset"] for row in replay}
            replay_assets |= {row["quote_asset"] for row in replay}
            replay_assets |= {row["fee_asset"] for row in replay if row["fee_asset"]}
            precision_assets = sorted(anchor_assets | venue_assets | replay_assets)
            asset_precisions = await self._load_spot_asset_precision_evidence(
                s, exchange, precision_assets, as_of
            )
            try:
                previously_confirmed = self._spot_confirmed_assets_from_state(
                    state, anchor["public_id"], anchor_assets
                )
            except ValueError:
                return self._spot_bundle_unavailable("corrupt_confirmed_asset_source")

        return SpotReconciliationBundle(
            anchor=anchor,
            replay=replay,
            instruments_by_public_id=instruments,
            specs_by_instrument_public_id=specs,
            asset_precisions=asset_precisions,
            previously_confirmed_assets=previously_confirmed,
            range_complete=range_complete,
            boundary_chain_tip=boundary_chain_tip,
            error=None,
        )

    @staticmethod
    async def _effective_spot_replay_rows(
        s: AsyncSession,
        request: _SpotReplayEffectiveRequest,
    ) -> list[SpotReplayExecutionSourceRow]:
        """Fold the validated manifest into one already counted replay range.

        Runs strictly AFTER the counted-contiguity proof, which is the whole
        reason the exclusion is a post-filter and not a ``WHERE`` clause: a
        predicate inside the range query would shrink the row count and make a
        purged or tampered ledger indistinguishable from a corrected one. The
        physical range is proven first, then the fold consumes only what is
        still economically effective.

        It consumes the SAME validated fold the P&L certification does — bind by
        coordinate AND immutable id AND canonical digest, then refuse any
        contradicted annulment — rather than trusting the manifest's coordinate
        on its own. A scope-sequence match alone would let this plane suppress a
        booking on evidence the certification plane would have refused, which is
        precisely the divergence a single shared theorem exists to prevent. Any
        invalid or contradicted binding raises rather than silently dropping a
        row, so a reconciliation run fails closed instead of certifying balances
        against a manifest it could not prove.

        The range's rows are re-read here rather than threaded down from the
        caller's projection because the fold binds ORM executions, and the
        caller's transaction is a pinned snapshot, so the second read is the
        same rows at the same instant. The manifest is narrowed through
        :func:`execution_annulment_knowledge_filters`, so a capture pinned to a
        historical instant additionally requires each correction to carry a
        durability observation at or before it.

        Args:
            s: The session holding the bundle's snapshot transaction.
            request: The replay range and the horizon its corrections are
                already known at.

        Returns:
            The replay rows that are still economically effective, in the
            caller's ascending scope-sequence order.

        Raises:
            ExecutionChainError: If any manifest binding covering this range is
                dangling, scope-crossed, duplicated, digest-mismatched, or
                contradicted by a durable fill witness.
        """
        if not request.replay:
            return request.replay
        annulment_rows = list(
            (
                await s.execute(
                    select(ExecutionAnnulment)
                    .where(
                        ExecutionAnnulment.wallet_public_id == request.wallet_public_id,
                        ExecutionAnnulment.exchange == request.exchange,
                        ExecutionAnnulment.mode == request.mode,
                        *execution_annulment_knowledge_filters(_resolved_knowledge_horizon(None)),
                    )
                    .order_by(ExecutionAnnulment.scope_sequence.asc())
                )
            )
            .scalars()
            .all()
        )
        if not annulment_rows:
            return request.replay
        range_rows = (
            (
                await s.execute(
                    select(Execution).where(
                        Execution.wallet_public_id == request.wallet_public_id,
                        Execution.exchange == request.exchange,
                        Execution.mode == request.mode,
                        Execution.scope_sequence > request.anchor_watermark,
                        Execution.scope_sequence <= request.boundary_watermark,
                    )
                )
            )
            .scalars()
            .all()
        )
        witnesses = await SQLAlchemyRepository._read_execution_annulment_contradiction_witnesses(
            s,
            [annulment.target_execution_public_id for annulment in annulment_rows],
        )
        fold = SQLAlchemyRepository._validated_execution_annulment_fold(
            _ExecutionAnnulmentFoldRequest(
                annulment_rows=annulment_rows,
                executions_by_coordinate={
                    (execution.exchange, int(execution.scope_sequence)): execution
                    for execution in range_rows
                },
                witnesses_by_execution_public_id=witnesses,
            )
        )
        annulled_sequences = {applied["scope_sequence"] for applied in fold.applied}
        return [row for row in request.replay if row["scope_sequence"] not in annulled_sequences]

    @staticmethod
    def _execution_chain_record(execution: Execution) -> ExecutionChainRecord:
        """Project one ORM execution onto its canonical tamper-evidence chain record."""
        return ExecutionChainRecord(
            scope_sequence=execution.scope_sequence,
            public_id=execution.public_id,
            order_public_id=execution.order_public_id,
            wallet_public_id=execution.wallet_public_id,
            operator_public_id=execution.operator_public_id,
            exchange=execution.exchange,
            mode=execution.mode,
            exec_id=execution.exec_id,
            trade_id=execution.trade_id,
            side=execution.side,
            status=execution.status,
            fee_asset=execution.fee_asset,
            price_decimal=execution.price_decimal,
            size_decimal=execution.size_decimal,
            fee_decimal=execution.fee_decimal,
            counter_amount_decimal=execution.counter_amount_decimal,
            numeric_provenance=execution.numeric_provenance,
            liquidity_role=execution.liquidity_role,
            timestamp=execution.timestamp,
            executed_at=execution.executed_at,
        )

    @staticmethod
    def _portfolio_reconciliation_method_config_to_row(
        config: PortfolioReconciliationMethodConfig,
    ) -> PortfolioReconciliationMethodConfigRow:
        """Project one active method-config model to its typed boundary."""
        return {
            "wallet_public_id": config.wallet_public_id,
            "exchange": config.exchange,
            "mode": config.mode,
            "method": config.method,
            "classified_after_observation_id": config.classified_after_observation_id,
            "public_id": config.public_id,
            "timestamp": config.timestamp,
            "session_id": config.session_id,
            "sequence_id": config.sequence_id,
        }

    async def _load_active_portfolio_reconciliation_method_config(
        self,
        s: AsyncSession,
        wallet_public_id: str,
        exchange: str,
        mode: str,
        *,
        lock: bool,
    ) -> PortfolioReconciliationMethodConfig | None:
        """Load exactly one sentinel-active config and reject corruption."""
        query = select(PortfolioReconciliationMethodConfig).where(
            PortfolioReconciliationMethodConfig.known_to == KNOWN_TO_MAX,
            PortfolioReconciliationMethodConfig.wallet_public_id == wallet_public_id,
            PortfolioReconciliationMethodConfig.exchange == exchange,
            PortfolioReconciliationMethodConfig.mode == mode,
        )
        if lock:
            query = query.with_for_update()
        rows = (await s.execute(query)).scalars().all()
        if len(rows) > 1:
            raise RuntimeError("duplicate active portfolio reconciliation method config")
        if not rows:
            return None
        row = rows[0]
        if (
            row.wallet_public_id != wallet_public_id
            or row.exchange != exchange
            or row.mode != "live"
            or row.method not in _PORTFOLIO_REAL_RECONCILIATION_METHODS
        ):
            raise RuntimeError("invalid active portfolio reconciliation method config")
        return row

    async def get_active_portfolio_reconciliation_method_config(
        self,
        wallet_public_id: str,
        exchange: str,
        mode: str,
    ) -> PortfolioReconciliationMethodConfigRow | None:
        """Return one sentinel-active operator-authored method config.

        Alias UUID spellings are canonicalized before filtering; malformed
        wallet identities raise ``ValueError`` like reconciliation writers.
        """
        wallet_public_id = _canonicalize_reconciliation_wallet_public_id(wallet_public_id)
        async with self.session() as s:
            try:
                config = await self._load_active_portfolio_reconciliation_method_config(
                    s,
                    wallet_public_id,
                    exchange,
                    mode,
                    lock=False,
                )
            except RuntimeError:
                return None
            return (
                None
                if config is None
                else self._portfolio_reconciliation_method_config_to_row(config)
            )

    async def _require_active_portfolio_wallet(
        self,
        s: AsyncSession,
        wallet_public_id: str,
    ) -> Wallet:
        """Require exactly one sentinel-active wallet after advisory locking."""
        rows = (
            (
                await s.execute(
                    select(Wallet).where(
                        Wallet.public_id == wallet_public_id,
                        Wallet.known_to == KNOWN_TO_MAX,
                    )
                )
            )
            .scalars()
            .all()
        )
        if len(rows) != 1:
            raise RuntimeError("active wallet is absent or ambiguous")
        return rows[0]

    async def _begin_portfolio_reconciliation_write(self, s: AsyncSession) -> None:
        """Acquire SQLite's single-writer transaction before reading state."""
        if self.dialect_name == "sqlite":
            await s.execute(text("BEGIN IMMEDIATE"))

    @staticmethod
    def _unclassified_observation_has_no_retained_evidence(
        row: PortfolioReconciliationObservation,
    ) -> bool:
        """Return whether an unclassified observation is safely non-full."""
        return (
            row.method == "unclassified"
            and row.evaluation_status in ("incomplete", "error")
            and row.venue_account_state_public_id is None
            and row.venue_account_observation_id is None
            and row.account_authoritative_until is None
            and row.source_watermark_kind is None
            and row.source_watermark is None
            and row.anchor_public_id is None
            and row.expected_json is None
            and row.actual_json is None
            and row.difference_json is None
            and row.tolerance_json is None
            and row.resulting_full_mismatch_count == 0
            and row.drift_episode_public_id is None
        )

    @staticmethod
    def _unclassified_state_has_no_retained_evidence(
        row: PortfolioReconciliationState,
    ) -> bool:
        """Return whether an unclassified state can transition to its first config."""
        return unclassified_state_has_no_retained_evidence(
            SQLAlchemyRepository._portfolio_reconciliation_state_to_row(row)
        )

    async def _portfolio_reconciliation_history(
        self,
        s: AsyncSession,
        wallet_public_id: str,
        exchange: str,
        mode: str,
    ) -> tuple[
        list[PortfolioReconciliationObservation],
        list[PortfolioReconciliationState],
        bool,
    ]:
        """Load all method-bearing history and whether episode history exists."""
        identity = (
            PortfolioReconciliationObservation.wallet_public_id == wallet_public_id,
            PortfolioReconciliationObservation.exchange == exchange,
            PortfolioReconciliationObservation.mode == mode,
        )
        observations = list(
            (await s.execute(select(PortfolioReconciliationObservation).where(*identity)))
            .scalars()
            .all()
        )
        states = list(
            (
                await s.execute(
                    select(PortfolioReconciliationState).where(
                        PortfolioReconciliationState.wallet_public_id == wallet_public_id,
                        PortfolioReconciliationState.exchange == exchange,
                        PortfolioReconciliationState.mode == mode,
                    )
                )
            )
            .scalars()
            .all()
        )
        episode_exists = bool(
            await s.scalar(
                select(
                    exists().where(
                        PortfolioDriftEpisode.wallet_public_id == wallet_public_id,
                        PortfolioDriftEpisode.exchange == exchange,
                        PortfolioDriftEpisode.mode == mode,
                    )
                )
            )
        )
        return observations, states, episode_exists

    def _validate_first_portfolio_reconciliation_config_history(
        self,
        observations: list[PortfolioReconciliationObservation],
        states: list[PortfolioReconciliationState],
        episode_exists: bool,
        method: str,
    ) -> None:
        """Allow only matching legacy history or safe unclassified history."""
        methods = {row.method for row in observations} | {row.method for row in states}
        if not methods:
            if episode_exists:
                raise ReconciliationMethodImmutableError(
                    "drift episode history has no matching reconciliation state"
                )
            return
        if methods == {"unclassified"}:
            if (
                episode_exists
                or not all(
                    self._unclassified_observation_has_no_retained_evidence(row)
                    for row in observations
                )
                or not all(self._unclassified_state_has_no_retained_evidence(row) for row in states)
            ):
                raise ReconciliationMethodImmutableError(
                    "unclassified reconciliation history contains retained evidence"
                )
            return
        if methods != {method}:
            raise ReconciliationMethodImmutableError(
                "reconciliation history does not agree with the requested method"
            )

    async def _set_portfolio_reconciliation_method_config_locked(
        self,
        s: AsyncSession,
        wallet_public_id: str,
        exchange: str,
        mode: str,
        method: str,
        session_id: str,
        sequence_id: int,
        timestamp: datetime,
    ) -> PortfolioReconciliationMethodConfig:
        """Apply one config write while the wallet advisory lock is held."""
        normalized_exchange = exchange.strip().lower()
        if not normalized_exchange or normalized_exchange != exchange or mode != "live":
            raise ValueError("reconciliation method config identity is invalid")
        if method not in _PORTFOLIO_REAL_RECONCILIATION_METHODS:
            raise ValueError("reconciliation method config requires a real method")
        existing = await self._load_active_portfolio_reconciliation_method_config(
            s,
            wallet_public_id,
            normalized_exchange,
            mode,
            lock=True,
        )
        if existing is not None and existing.method == method:
            return existing
        observations, states, episode_exists = await self._portfolio_reconciliation_history(
            s,
            wallet_public_id,
            normalized_exchange,
            mode,
        )
        active_state = next((row for row in states if row.known_to == KNOWN_TO_MAX), None)
        classified_after_observation_id = (
            None if active_state is None else active_state.current_observation_id
        )
        history_exists = bool(observations or states or episode_exists)
        if existing is not None:
            if history_exists:
                raise ReconciliationMethodImmutableError(
                    "reconciliation method is immutable after history exists"
                )
            effective = max(timestamp, existing.timestamp)
            await s.execute(
                update(PortfolioReconciliationMethodConfig)
                .where(PortfolioReconciliationMethodConfig.id == existing.id)
                .values(known_to=effective)
            )
            public_id = existing.public_id
        else:
            self._validate_first_portfolio_reconciliation_config_history(
                observations,
                states,
                episode_exists,
                method,
            )
            effective = timestamp
            public_id = str(uuid7())
        config = PortfolioReconciliationMethodConfig(
            wallet_public_id=wallet_public_id,
            exchange=normalized_exchange,
            mode=mode,
            method=method,
            classified_after_observation_id=classified_after_observation_id,
            public_id=public_id,
            session_id=session_id,
            sequence_id=sequence_id,
            timestamp=effective,
            known_to=KNOWN_TO_MAX,
        )
        s.add(config)
        await s.flush()
        return config

    async def set_portfolio_reconciliation_method_config(
        self,
        wallet_public_id: str,
        exchange: str,
        mode: str,
        method: str,
        session_id: str,
        sequence_id: int,
        timestamp: datetime,
    ) -> PortfolioReconciliationMethodConfigRow:
        """Advisory-lock and persist an immutable durable classification."""
        wallet_public_id = _canonicalize_reconciliation_wallet_public_id(wallet_public_id)
        identity = (wallet_public_id, exchange, mode)
        process_lock = self._portfolio_reconciliation_locks.setdefault(identity, asyncio.Lock())
        async with process_lock, self.session() as s:
            await self._begin_portfolio_reconciliation_write(s)
            await self._acquire_wallet_advisory_lock(s, wallet_public_id)
            await self._require_active_portfolio_wallet(s, wallet_public_id)
            config = await self._set_portfolio_reconciliation_method_config_locked(
                s,
                wallet_public_id,
                exchange,
                mode,
                method,
                session_id,
                sequence_id,
                timestamp,
            )
            await s.commit()
            return self._portfolio_reconciliation_method_config_to_row(config)

    @staticmethod
    def _portfolio_reconciliation_identity_filters(
        wallet_public_id: str, exchange: str, mode: str
    ) -> list[ColumnElement[bool]]:
        """Build the identity predicate for one reconciliation state.

        Args:
            wallet_public_id: Full wallet identity.
            exchange: Lowercase venue name.
            mode: Live trading mode.

        Returns:
            Filters matching the wallet, exchange, and mode identity.
        """
        return [
            PortfolioReconciliationState.wallet_public_id == wallet_public_id,
            PortfolioReconciliationState.exchange == exchange,
            PortfolioReconciliationState.mode == mode,
        ]

    @staticmethod
    def _portfolio_reconciliation_observation_is_full_mismatch(
        observation: PortfolioReconciliationObservation,
    ) -> bool:
        """Return whether an observation is a complete full mismatch.

        Args:
            observation: Stored reconciliation evidence to validate.

        Returns:
            Whether the observation carries a mismatched outcome and every
            required account-provenance, authority, and comparison field.
        """
        required_evidence = (
            observation.venue_account_state_public_id,
            observation.venue_account_observation_id,
            observation.account_authoritative_until,
            observation.source_watermark_kind,
            observation.source_watermark,
            observation.expected_json,
            observation.actual_json,
            observation.difference_json,
            observation.tolerance_json,
        )
        return (observation.evaluation_status, None in required_evidence) == (
            "mismatched",
            False,
        )

    @classmethod
    def _portfolio_reconciliation_episode_observation_is_consistent(
        cls,
        observation: PortfolioReconciliationObservation,
        episode: PortfolioDriftEpisode,
        mismatch_count: int,
    ) -> bool:
        """Return whether full mismatch evidence belongs to an episode.

        Args:
            observation: Stored episode-lineage observation.
            episode: Episode expected to own the observation.
            mismatch_count: Required resulting mismatch count.

        Returns:
            Whether identity, episode lineage, count, and full evidence agree.
        """
        return (
            observation.wallet_public_id,
            observation.exchange,
            observation.mode,
            observation.drift_episode_public_id,
            observation.resulting_full_mismatch_count,
            cls._portfolio_reconciliation_observation_is_full_mismatch(observation),
        ) == (
            episode.wallet_public_id,
            episode.exchange,
            episode.mode,
            episode.public_id,
            mismatch_count,
            True,
        )

    @staticmethod
    def _validate_portfolio_reconciliation_episode_state_consistency(
        episode: PortfolioDriftEpisode,
        state: PortfolioReconciliationState,
    ) -> None:
        """Validate that active episode lineage equals its owning state.

        Args:
            episode: Active open drift episode.
            state: Active reconciliation state naming the episode.

        Returns:
            None.

        Raises:
            RuntimeError: If the episode identity, mismatch count, last full
                observation, or retained detail source disagrees with state.
        """
        if (
            episode.public_id,
            episode.latest_full_mismatch_count,
            episode.last_observation_id,
            episode.details_source_observation_id,
        ) != (
            state.open_drift_episode_public_id,
            state.consecutive_full_mismatches,
            state.last_full_observation_id,
            state.detail_source_observation_id,
        ):
            raise RuntimeError("active drift episode lineage does not match reconciliation state")

    async def _validate_portfolio_reconciliation_episode_opened_at(
        self,
        s: AsyncSession,
        episode: PortfolioDriftEpisode,
        trigger: PortfolioReconciliationObservation,
    ) -> None:
        """Validate the episode opening time against its trigger evidence.

        Args:
            s: Open transaction session.
            episode: Episode whose opening time is being validated.
            trigger: Genuine third-mismatch trigger observation.

        Returns:
            None.

        Raises:
            RuntimeError: If the opening time differs from the clock-clamped
                observation time at the trigger's monotonic evaluation key.
        """
        expected_opened_at = (
            (
                await s.execute(
                    select(PortfolioReconciliationObservation.timestamp)
                    .where(
                        PortfolioReconciliationObservation.wallet_public_id
                        == episode.wallet_public_id,
                        PortfolioReconciliationObservation.exchange == episode.exchange,
                        PortfolioReconciliationObservation.mode == episode.mode,
                        or_(
                            PortfolioReconciliationObservation.session_id < trigger.session_id,
                            and_(
                                PortfolioReconciliationObservation.session_id == trigger.session_id,
                                PortfolioReconciliationObservation.sequence_id
                                <= trigger.sequence_id,
                            ),
                        ),
                    )
                    .order_by(
                        PortfolioReconciliationObservation.timestamp.desc(),
                        PortfolioReconciliationObservation.id.desc(),
                    )
                    .limit(1)
                )
            )
            .scalars()
            .one()
        )
        if episode.opened_at != expected_opened_at:
            raise RuntimeError("active drift episode opened_at is inconsistent")

    async def _validate_portfolio_reconciliation_episode_trigger(
        self,
        s: AsyncSession,
        episode: PortfolioDriftEpisode,
        trigger: PortfolioReconciliationObservation,
    ) -> None:
        """Validate an episode's trigger identity, evidence, and opening time.

        Args:
            s: Open transaction session.
            episode: Episode whose trigger is being validated.
            trigger: Referenced trigger observation.

        Returns:
            None.

        Raises:
            RuntimeError: If trigger evidence or opening time is inconsistent.
        """
        if not self._portfolio_reconciliation_episode_observation_is_consistent(
            trigger, episode, 3
        ):
            raise RuntimeError("active drift episode trigger observation is inconsistent")
        await self._validate_portfolio_reconciliation_episode_opened_at(s, episode, trigger)

    async def _validate_locked_drift_episode(
        self,
        s: AsyncSession,
        episode: PortfolioDriftEpisode,
        state: PortfolioReconciliationState,
        identity: _PortfolioReconciliationIdentity,
    ) -> None:
        """Validate every observation referenced by a locked drift episode."""
        wallet_public_id, exchange, mode = identity
        observation_ids = {
            episode.trigger_observation_id,
            episode.last_observation_id,
            episode.details_source_observation_id,
        }
        observation_result = await s.execute(
            select(PortfolioReconciliationObservation).where(
                PortfolioReconciliationObservation.id.in_(observation_ids)
            )
        )
        observations = observation_result.scalars().all()
        observations_by_id = {int(observation.id): observation for observation in observations}
        if set(observations_by_id) != observation_ids:
            raise RuntimeError("active drift episode references a missing observation")
        for observation in observations:
            if (
                observation.wallet_public_id,
                observation.exchange,
                observation.mode,
            ) != identity:
                raise RuntimeError("active drift episode references a foreign observation")
        detail = observations_by_id[episode.details_source_observation_id]
        if not self._portfolio_reconciliation_episode_observation_is_consistent(
            detail,
            episode,
            episode.latest_full_mismatch_count,
        ):
            raise RuntimeError("active drift episode detail observation is inconsistent")
        trigger = observations_by_id[episode.trigger_observation_id]
        await self._validate_portfolio_reconciliation_episode_trigger(s, episode, trigger)
        last = observations_by_id[episode.last_observation_id]
        if not self._portfolio_reconciliation_episode_observation_is_consistent(
            last,
            episode,
            episode.latest_full_mismatch_count,
        ):
            raise RuntimeError("active drift episode last observation is inconsistent")
        self._validate_portfolio_reconciliation_episode_state_consistency(episode, state)

    async def _lock_active_drift_episode(
        self,
        s: AsyncSession,
        public_id: str | None,
        identity: _PortfolioReconciliationIdentity,
        state: PortfolioReconciliationState,
    ) -> PortfolioDriftEpisode | None:
        """Lock and return the sentinel-active drift episode when identified.

        Args:
            s: Open transaction session.
            public_id: Stable episode identity, or ``None``.
            identity: Expected wallet, venue, and mode identity.
            state: Active reconciliation state naming the episode.

        Returns:
            The locked active episode or ``None``.
        """
        if public_id is None:
            return None
        episode_result = await s.execute(
            select(PortfolioDriftEpisode)
            .where(
                PortfolioDriftEpisode.public_id == public_id,
                PortfolioDriftEpisode.known_to == KNOWN_TO_MAX,
            )
            .with_for_update()
        )
        episode = episode_result.scalars().first()
        if episode is None:
            return None
        if (
            episode.wallet_public_id,
            episode.exchange,
            episode.mode,
        ) != identity:
            raise RuntimeError("active drift episode identity does not match reconciliation state")
        await self._validate_locked_drift_episode(
            s,
            episode,
            state,
            identity,
        )
        return episode

    @staticmethod
    def _portfolio_reconciliation_replay_matches(
        observation: PortfolioReconciliationObservation,
        evaluation: PortfolioReconciliationEvaluationRow,
    ) -> bool:
        """Return whether stored evidence exactly matches a replayed evaluation.

        Args:
            observation: Existing observation with the same evaluation key.
            evaluation: Incoming raw evaluation.

        Returns:
            Whether every caller-supplied evidence field is identical.
        """
        return (
            observation.method == evaluation["method"]
            and observation.evaluation_status == evaluation["evaluation_status"]
            and observation.venue_account_state_public_id
            == evaluation["venue_account_state_public_id"]
            and observation.venue_account_observation_id
            == evaluation["venue_account_observation_id"]
            and observation.account_authoritative_until == evaluation["account_authoritative_until"]
            and observation.source_watermark_kind == evaluation["source_watermark_kind"]
            and observation.source_watermark == evaluation["source_watermark"]
            and observation.anchor_public_id == evaluation["anchor_public_id"]
            and observation.expected_json == evaluation["expected_json"]
            and observation.actual_json == evaluation["actual_json"]
            and observation.difference_json == evaluation["difference_json"]
            and observation.tolerance_json == evaluation["tolerance_json"]
            and observation.error == evaluation["error"]
            and observation.timestamp == evaluation["bus_time"]
        )

    @staticmethod
    def _portfolio_reconciliation_lineage_observation_to_row(
        observation: PortfolioReconciliationObservation,
    ) -> PortfolioReconciliationLineageObservationRow:
        """Project one observation to the pure lineage-validation boundary.

        Args:
            observation: Referenced reconciliation observation.

        Returns:
            The fields required for state-lineage validation.
        """
        return {
            "id": int(observation.id),
            "wallet_public_id": observation.wallet_public_id,
            "exchange": observation.exchange,
            "mode": observation.mode,
            "method": observation.method,
            "evaluation_status": observation.evaluation_status,
            "venue_account_state_public_id": observation.venue_account_state_public_id,
            "venue_account_observation_id": observation.venue_account_observation_id,
            "account_authoritative_until": observation.account_authoritative_until,
            "source_watermark_kind": observation.source_watermark_kind,
            "source_watermark": observation.source_watermark,
            "anchor_public_id": observation.anchor_public_id,
            "expected_json": observation.expected_json,
            "actual_json": observation.actual_json,
            "difference_json": observation.difference_json,
            "tolerance_json": observation.tolerance_json,
            "resulting_full_mismatch_count": observation.resulting_full_mismatch_count,
            "drift_episode_public_id": observation.drift_episode_public_id,
            "error": observation.error,
            "timestamp": observation.timestamp,
            "session_id": observation.session_id,
            "sequence_id": observation.sequence_id,
        }

    async def _validate_portfolio_reconciliation_lineage(
        self,
        s: AsyncSession,
        existing: PortfolioReconciliationState,
    ) -> None:
        """Validate every predecessor observation reference and its identity.

        Args:
            s: Open transaction session.
            existing: Locked sentinel-active reconciliation state.

        Returns:
            None.

        Raises:
            RuntimeError: If any referenced observation is missing, foreign,
                or inconsistent with the predecessor's current metadata.
        """
        observation_ids = {
            observation_id
            for observation_id in (
                existing.current_observation_id,
                existing.last_full_observation_id,
                existing.detail_source_observation_id,
            )
            if observation_id is not None
        }
        observations = (
            (
                await s.execute(
                    select(PortfolioReconciliationObservation).where(
                        PortfolioReconciliationObservation.id.in_(observation_ids)
                    )
                )
            )
            .scalars()
            .all()
        )
        existing_row = self._portfolio_reconciliation_state_to_row(existing)
        observation_rows = [
            self._portfolio_reconciliation_lineage_observation_to_row(observation)
            for observation in observations
        ]
        validate_portfolio_reconciliation_observation_lineage(existing_row, observation_rows)
        latest_ordered_observation_id = await s.scalar(
            select(PortfolioReconciliationObservation.id)
            .where(
                PortfolioReconciliationObservation.wallet_public_id == existing.wallet_public_id,
                PortfolioReconciliationObservation.exchange == existing.exchange,
                PortfolioReconciliationObservation.mode == existing.mode,
            )
            .order_by(
                PortfolioReconciliationObservation.session_id.desc(),
                PortfolioReconciliationObservation.sequence_id.desc(),
                PortfolioReconciliationObservation.id.desc(),
            )
            .limit(1)
        )
        latest_appended_observation_id = await s.scalar(
            select(func.max(PortfolioReconciliationObservation.id)).where(
                PortfolioReconciliationObservation.wallet_public_id == existing.wallet_public_id,
                PortfolioReconciliationObservation.exchange == existing.exchange,
                PortfolioReconciliationObservation.mode == existing.mode,
            )
        )
        validate_portfolio_reconciliation_latest_observation_lineage(
            existing_row,
            latest_ordered_observation_id,
            latest_appended_observation_id,
        )

    async def _find_portfolio_reconciliation_replay(
        self,
        s: AsyncSession,
        evaluation: PortfolioReconciliationEvaluationRow,
    ) -> PortfolioReconciliationObservation | None:
        """Find an observation with the incoming account evaluation key.

        Args:
            s: Open transaction session.
            evaluation: Incoming raw evaluation.

        Returns:
            Existing same-key observation, or ``None``.
        """
        return (
            (
                await s.execute(
                    select(PortfolioReconciliationObservation).where(
                        PortfolioReconciliationObservation.wallet_public_id
                        == evaluation["wallet_public_id"],
                        PortfolioReconciliationObservation.exchange == evaluation["exchange"],
                        PortfolioReconciliationObservation.mode == evaluation["mode"],
                        PortfolioReconciliationObservation.session_id == evaluation["session_id"],
                        PortfolioReconciliationObservation.sequence_id == evaluation["sequence_id"],
                    )
                )
            )
            .scalars()
            .first()
        )

    async def _version_drift_episode(
        self,
        s: AsyncSession,
        existing: PortfolioDriftEpisode,
        state: PortfolioReconciliationState,
        observation_id: int,
        mismatch_count: int,
        effective: datetime,
        evaluation: PortfolioReconciliationEvaluationRow,
        status: str,
    ) -> None:
        """Close and replace one drift-episode lifecycle version.

        Args:
            s: Open transaction session.
            existing: Locked active episode version.
            state: Locked active reconciliation-state predecessor.
            observation_id: Observation advancing or resolving the episode.
            mismatch_count: Latest sustained full-mismatch count.
            effective: Clock-clamped lifecycle effective time.
            evaluation: Raw evaluation carrying temporal provenance.
            status: Successor lifecycle status, ``open`` or ``resolved``.

        Returns:
            None.
        """
        resolved = status == "resolved"
        trigger = (
            (
                await s.execute(
                    select(PortfolioReconciliationObservation).where(
                        PortfolioReconciliationObservation.id == existing.trigger_observation_id
                    )
                )
            )
            .scalars()
            .one()
        )
        await self._validate_portfolio_reconciliation_episode_trigger(s, existing, trigger)
        if resolved:
            detail = (
                (
                    await s.execute(
                        select(PortfolioReconciliationObservation).where(
                            PortfolioReconciliationObservation.id
                            == existing.details_source_observation_id
                        )
                    )
                )
                .scalars()
                .one()
            )
            if not self._portfolio_reconciliation_episode_observation_is_consistent(
                detail, existing, existing.latest_full_mismatch_count
            ):
                raise RuntimeError("active drift episode detail observation is inconsistent")
            self._validate_portfolio_reconciliation_episode_state_consistency(existing, state)
        await s.execute(
            update(PortfolioDriftEpisode)
            .where(PortfolioDriftEpisode.id == existing.id)
            .values(known_to=effective)
        )
        successor = PortfolioDriftEpisode(
            wallet_public_id=existing.wallet_public_id,
            exchange=existing.exchange,
            mode=existing.mode,
            status=status,
            opened_at=existing.opened_at,
            closed_at=effective if resolved else None,
            trigger_observation_id=existing.trigger_observation_id,
            last_observation_id=observation_id,
            details_source_observation_id=(
                existing.details_source_observation_id if resolved else observation_id
            ),
            latest_full_mismatch_count=(
                existing.latest_full_mismatch_count if resolved else mismatch_count
            ),
            resolution_reason="matched" if resolved else None,
            closed_by_user_public_id=None,
            closed_by_operator_public_id=None,
            rebase_anchor_public_id=None,
            public_id=existing.public_id,
            session_id=evaluation["session_id"],
            sequence_id=evaluation["sequence_id"],
            timestamp=effective,
            known_to=KNOWN_TO_MAX,
        )
        s.add(successor)
        await s.flush()

    def _validate_portfolio_reconciliation_evaluation_config(
        self,
        evaluation: PortfolioReconciliationEvaluationRow,
        config: PortfolioReconciliationMethodConfig | None,
    ) -> None:
        """Fail closed on invalid status, config mismatch, or non-full evidence."""
        config_row = (
            None if config is None else self._portfolio_reconciliation_method_config_to_row(config)
        )
        validate_portfolio_reconciliation_evaluation_config(evaluation, config_row)

    def _validate_portfolio_reconciliation_method_transition(
        self,
        existing: PortfolioReconciliationState | None,
        evaluation: PortfolioReconciliationEvaluationRow,
        config: PortfolioReconciliationMethodConfig | None,
    ) -> None:
        """Permit only a safe unclassified-to-first-real-method transition."""
        existing_row = (
            None if existing is None else self._portfolio_reconciliation_state_to_row(existing)
        )
        config_row = (
            None if config is None else self._portfolio_reconciliation_method_config_to_row(config)
        )
        validate_portfolio_reconciliation_method_transition(existing_row, evaluation, config_row)

    async def _load_active_portfolio_reconciliation_state(
        self,
        s: AsyncSession,
        evaluation: PortfolioReconciliationEvaluationRow,
    ) -> PortfolioReconciliationState | None:
        """Lock and validate the active state or require an empty history."""
        state_result = await s.execute(
            select(PortfolioReconciliationState)
            .where(
                PortfolioReconciliationState.known_to == KNOWN_TO_MAX,
                *self._portfolio_reconciliation_identity_filters(
                    evaluation["wallet_public_id"],
                    evaluation["exchange"],
                    evaluation["mode"],
                ),
            )
            .with_for_update()
        )
        existing = state_result.scalars().first()
        if existing is not None:
            await self._validate_portfolio_reconciliation_lineage(s, existing)
            return existing
        prior_observation_id = await s.scalar(
            select(PortfolioReconciliationObservation.id)
            .where(
                PortfolioReconciliationObservation.wallet_public_id
                == evaluation["wallet_public_id"],
                PortfolioReconciliationObservation.exchange == evaluation["exchange"],
                PortfolioReconciliationObservation.mode == evaluation["mode"],
                or_(
                    PortfolioReconciliationObservation.session_id != evaluation["session_id"],
                    PortfolioReconciliationObservation.sequence_id != evaluation["sequence_id"],
                ),
            )
            .limit(1)
        )
        if prior_observation_id is not None:
            raise RuntimeError(
                "active reconciliation state predecessor is missing for prior observation"
            )
        return None

    async def _load_portfolio_reconciliation_write_context(
        self,
        s: AsyncSession,
        evaluation: PortfolioReconciliationEvaluationRow,
    ) -> _PortfolioReconciliationWriteContext:
        """Open, lock, and validate every predecessor needed by one write."""
        await self._begin_portfolio_reconciliation_write(s)
        await self._acquire_wallet_advisory_lock(s, evaluation["wallet_public_id"])
        await self._require_active_portfolio_wallet(s, evaluation["wallet_public_id"])
        config = await self._load_active_portfolio_reconciliation_method_config(
            s,
            evaluation["wallet_public_id"],
            evaluation["exchange"],
            evaluation["mode"],
            lock=True,
        )
        existing = await self._load_active_portfolio_reconciliation_state(s, evaluation)
        active_episode: PortfolioDriftEpisode | None = None
        if existing is not None:
            identity = (
                evaluation["wallet_public_id"],
                evaluation["exchange"],
                evaluation["mode"],
            )
            active_episode = await self._lock_active_drift_episode(
                s,
                existing.open_drift_episode_public_id,
                identity,
                existing,
            )
            if existing.open_drift_episode_public_id is not None and (
                active_episode is None or active_episode.status != "open"
            ):
                raise RuntimeError("active reconciliation state has no open drift episode")
        return _PortfolioReconciliationWriteContext(config, existing, active_episode)

    async def _portfolio_reconciliation_replay_state_id(
        self,
        s: AsyncSession,
        evaluation: PortfolioReconciliationEvaluationRow,
        existing: PortfolioReconciliationState | None,
    ) -> int | None:
        """Return the active state id for an exact replay, or no replay marker."""
        replay = await self._find_portfolio_reconciliation_replay(s, evaluation)
        if replay is None:
            return None
        if not self._portfolio_reconciliation_replay_matches(replay, evaluation):
            raise RuntimeError("conflicting reconciliation evaluation replay")
        if existing is None:
            raise RuntimeError("reconciliation observation has no active state")
        return int(existing.id)

    @staticmethod
    def _portfolio_reconciliation_evaluation_is_stale(
        existing: PortfolioReconciliationState | None,
        evaluation: PortfolioReconciliationEvaluationRow,
    ) -> bool:
        """Return whether an evaluation precedes the active state ordering key."""
        if existing is None:
            return False
        incoming_key = (evaluation["session_id"], evaluation["sequence_id"])
        current_key = (existing.session_id, existing.sequence_id)
        return incoming_key < current_key

    async def _validate_portfolio_reconciliation_spot_lineage(
        self,
        s: AsyncSession,
        evaluation: PortfolioReconciliationEvaluationRow,
    ) -> None:
        """Validate anchor lineage for a full spot execution replay."""
        full_spot_replay = evaluation["method"] == "spot_execution_replay" and evaluation[
            "evaluation_status"
        ] in ("matched", "mismatched")
        if not full_spot_replay:
            return
        anchor_public_id = evaluation["anchor_public_id"]
        source_watermark = evaluation["source_watermark"]
        if anchor_public_id is None or source_watermark is None:
            raise RuntimeError("full spot reconciliation requires anchor lineage")
        if evaluation["source_watermark_kind"] != "scope_sequence":
            raise RuntimeError("full spot reconciliation requires scope-sequence lineage")
        anchor_result = await s.execute(
            select(PortfolioSpotReconciliationAnchor).where(
                PortfolioSpotReconciliationAnchor.known_to == KNOWN_TO_MAX,
                PortfolioSpotReconciliationAnchor.public_id == anchor_public_id,
            )
        )
        anchor = anchor_result.scalars().first()
        validate_portfolio_reconciliation_spot_anchor_lineage(
            evaluation,
            None if anchor is None else self._spot_anchor_to_row(anchor),
        )

    @staticmethod
    def _derive_portfolio_reconciliation_outcome(
        existing: PortfolioReconciliationState | None,
        evaluation: PortfolioReconciliationEvaluationRow,
    ) -> _PortfolioReconciliationOutcome:
        """Derive effective time, mismatch streak, and episode identity."""
        effective = max(
            evaluation["bus_time"],
            existing.timestamp if existing is not None else evaluation["bus_time"],
        )
        status = evaluation["evaluation_status"]
        previous_count = existing.consecutive_full_mismatches if existing is not None else 0
        previous_outcome = existing.last_full_outcome if existing is not None else None
        if status == "matched":
            mismatch_count = 0
            episode_public_id: str | None = None
        elif status == "mismatched":
            mismatch_count = previous_count + 1 if previous_outcome == "mismatched" else 1
            if mismatch_count >= 3:
                episode_public_id = (
                    existing.open_drift_episode_public_id
                    if existing is not None and existing.open_drift_episode_public_id is not None
                    else str(uuid7())
                )
            else:
                episode_public_id = None
        else:
            mismatch_count = previous_count
            episode_public_id = (
                existing.open_drift_episode_public_id if existing is not None else None
            )
        return _PortfolioReconciliationOutcome(
            effective,
            status,
            mismatch_count,
            episode_public_id,
        )

    @staticmethod
    async def _append_portfolio_reconciliation_observation(
        s: AsyncSession,
        evaluation: PortfolioReconciliationEvaluationRow,
        outcome: _PortfolioReconciliationOutcome,
    ) -> int:
        """Append one immutable reconciliation observation."""
        observation = PortfolioReconciliationObservation(
            wallet_public_id=evaluation["wallet_public_id"],
            exchange=evaluation["exchange"],
            mode=evaluation["mode"],
            method=evaluation["method"],
            evaluation_status=outcome.status,
            venue_account_state_public_id=evaluation["venue_account_state_public_id"],
            venue_account_observation_id=evaluation["venue_account_observation_id"],
            account_authoritative_until=evaluation["account_authoritative_until"],
            source_watermark_kind=evaluation["source_watermark_kind"],
            source_watermark=evaluation["source_watermark"],
            source_chain_tip=evaluation.get("source_chain_tip"),
            anchor_public_id=evaluation["anchor_public_id"],
            expected_json=evaluation["expected_json"],
            actual_json=evaluation["actual_json"],
            difference_json=evaluation["difference_json"],
            tolerance_json=evaluation["tolerance_json"],
            resulting_full_mismatch_count=outcome.mismatch_count,
            drift_episode_public_id=outcome.episode_public_id,
            error=evaluation["error"],
            session_id=evaluation["session_id"],
            sequence_id=evaluation["sequence_id"],
            timestamp=evaluation["bus_time"],
            known_to=KNOWN_TO_MAX,
        )
        s.add(observation)
        await s.flush()
        return int(observation.id)

    async def _apply_portfolio_reconciliation_episode_transition(
        self,
        s: AsyncSession,
        evaluation: PortfolioReconciliationEvaluationRow,
        context: _PortfolioReconciliationWriteContext,
        outcome: _PortfolioReconciliationOutcome,
        observation_id: int,
    ) -> None:
        """Create, advance, or resolve the drift episode for one observation."""
        if outcome.status == "mismatched" and outcome.mismatch_count == 3:
            episode = PortfolioDriftEpisode(
                wallet_public_id=evaluation["wallet_public_id"],
                exchange=evaluation["exchange"],
                mode=evaluation["mode"],
                status="open",
                opened_at=outcome.effective,
                closed_at=None,
                trigger_observation_id=observation_id,
                last_observation_id=observation_id,
                details_source_observation_id=observation_id,
                latest_full_mismatch_count=outcome.mismatch_count,
                resolution_reason=None,
                closed_by_user_public_id=None,
                closed_by_operator_public_id=None,
                rebase_anchor_public_id=None,
                public_id=outcome.episode_public_id,
                session_id=evaluation["session_id"],
                sequence_id=evaluation["sequence_id"],
                timestamp=outcome.effective,
                known_to=KNOWN_TO_MAX,
            )
            s.add(episode)
            await s.flush()
        elif outcome.status == "mismatched" and outcome.mismatch_count > 3:
            await self._version_drift_episode(
                s,
                cast(PortfolioDriftEpisode, context.active_episode),
                cast(PortfolioReconciliationState, context.existing),
                observation_id,
                outcome.mismatch_count,
                outcome.effective,
                evaluation,
                "open",
            )
        elif outcome.status == "matched" and context.active_episode is not None:
            await self._version_drift_episode(
                s,
                context.active_episode,
                cast(PortfolioReconciliationState, context.existing),
                observation_id,
                context.active_episode.latest_full_mismatch_count,
                outcome.effective,
                evaluation,
                "resolved",
            )

    @staticmethod
    def _portfolio_reconciliation_state_evidence(
        existing: PortfolioReconciliationState | None,
        evaluation: PortfolioReconciliationEvaluationRow,
        outcome: _PortfolioReconciliationOutcome,
        observation_id: int,
    ) -> dict[str, Any]:
        """Select current or retained full evidence for the successor state."""
        is_full = outcome.status in ("matched", "mismatched")
        if is_full:
            return {
                "last_full_observation_id": observation_id,
                "last_full_outcome": outcome.status,
                "detail_source_observation_id": observation_id,
                "anchor_public_id": evaluation["anchor_public_id"],
                "venue_account_state_public_id": evaluation["venue_account_state_public_id"],
                "venue_account_observation_id": evaluation["venue_account_observation_id"],
                "source_watermark_kind": evaluation["source_watermark_kind"],
                "source_watermark": evaluation["source_watermark"],
                "source_chain_tip": evaluation.get("source_chain_tip"),
                "expected_json": evaluation["expected_json"],
                "actual_json": evaluation["actual_json"],
                "difference_json": evaluation["difference_json"],
                "tolerance_json": evaluation["tolerance_json"],
                "reconciled_at": evaluation["bus_time"],
                "authoritative_until": evaluation["account_authoritative_until"],
            }
        if existing is not None:
            return {
                "last_full_observation_id": existing.last_full_observation_id,
                "last_full_outcome": existing.last_full_outcome,
                "detail_source_observation_id": existing.detail_source_observation_id,
                "anchor_public_id": existing.anchor_public_id,
                "venue_account_state_public_id": existing.venue_account_state_public_id,
                "venue_account_observation_id": existing.venue_account_observation_id,
                "source_watermark_kind": existing.source_watermark_kind,
                "source_watermark": existing.source_watermark,
                "source_chain_tip": existing.source_chain_tip,
                "expected_json": existing.expected_json,
                "actual_json": existing.actual_json,
                "difference_json": existing.difference_json,
                "tolerance_json": existing.tolerance_json,
                "reconciled_at": existing.reconciled_at,
                "authoritative_until": existing.authoritative_until,
            }
        return {
            "last_full_observation_id": None,
            "last_full_outcome": None,
            "detail_source_observation_id": None,
            "anchor_public_id": None,
            "venue_account_state_public_id": None,
            "venue_account_observation_id": None,
            "source_watermark_kind": None,
            "source_watermark": None,
            "source_chain_tip": None,
            "expected_json": None,
            "actual_json": None,
            "difference_json": None,
            "tolerance_json": None,
            "reconciled_at": None,
            "authoritative_until": None,
        }

    async def _append_portfolio_reconciliation_state(
        self,
        s: AsyncSession,
        evaluation: PortfolioReconciliationEvaluationRow,
        context: _PortfolioReconciliationWriteContext,
        outcome: _PortfolioReconciliationOutcome,
        observation_id: int,
    ) -> int:
        """Close the predecessor and append the derived active state."""
        state_values: dict[str, Any] = {
            "wallet_public_id": evaluation["wallet_public_id"],
            "exchange": evaluation["exchange"],
            "mode": evaluation["mode"],
            "method": evaluation["method"],
            "current_evaluation_status": outcome.status,
            "current_observation_id": observation_id,
            "consecutive_full_mismatches": outcome.mismatch_count,
            "open_drift_episode_public_id": outcome.episode_public_id,
            "error": evaluation["error"],
            "session_id": evaluation["session_id"],
            "sequence_id": evaluation["sequence_id"],
            "timestamp": outcome.effective,
            "known_to": KNOWN_TO_MAX,
        }
        state_values.update(
            self._portfolio_reconciliation_state_evidence(
                context.existing,
                evaluation,
                outcome,
                observation_id,
            )
        )
        if context.existing is not None:
            state_values["public_id"] = context.existing.public_id
            await s.execute(
                update(PortfolioReconciliationState)
                .where(PortfolioReconciliationState.id == context.existing.id)
                .values(known_to=outcome.effective)
            )
        state = PortfolioReconciliationState(**state_values)
        s.add(state)
        await s.flush()
        return int(state.id)

    async def _write_portfolio_reconciliation(
        self, s: AsyncSession, evaluation: PortfolioReconciliationEvaluationRow
    ) -> int:
        """Append an evaluation and derive state plus episode lifecycle atomically.

        The active state is locked before evidence is appended. Full matches
        reset the streak and resolve an open episode. Full mismatches advance
        only a prior full-mismatch streak, minting one stable episode identity
        at the third consecutive mismatch and reusing it thereafter. Every
        non-full outcome retains the prior full detail and streak without
        incrementing or resetting either. A strictly older evaluation than the
        active predecessor is a benign out-of-order delivery: it is ignored
        idempotently right after the replay guard, before method or config
        validation, so a stale pre-classification tuple that lost the race to a
        newer real-method evaluation is dropped rather than raising a spurious
        conflict.

        Args:
            s: Open transaction session owned by the caller.
            evaluation: Raw comparison evidence and outcome.

        Returns:
            The new active reconciliation-state row id.

        Raises:
            RuntimeError: If predecessor lineage, episode identity, or replay
                evidence is missing, foreign, or inconsistent.
        """
        context = await self._load_portfolio_reconciliation_write_context(s, evaluation)
        replayed_state_id = await self._portfolio_reconciliation_replay_state_id(
            s,
            evaluation,
            context.existing,
        )
        if replayed_state_id is not None:
            return replayed_state_id
        if self._portfolio_reconciliation_evaluation_is_stale(context.existing, evaluation):
            return int(cast(PortfolioReconciliationState, context.existing).id)
        self._validate_portfolio_reconciliation_evaluation_config(evaluation, context.config)
        self._validate_portfolio_reconciliation_method_transition(
            context.existing,
            evaluation,
            context.config,
        )
        await self._validate_portfolio_reconciliation_spot_lineage(s, evaluation)
        outcome = self._derive_portfolio_reconciliation_outcome(context.existing, evaluation)
        observation_id = await self._append_portfolio_reconciliation_observation(
            s,
            evaluation,
            outcome,
        )
        await self._apply_portfolio_reconciliation_episode_transition(
            s,
            evaluation,
            context,
            outcome,
            observation_id,
        )
        return await self._append_portfolio_reconciliation_state(
            s,
            evaluation,
            context,
            outcome,
            observation_id,
        )

    async def _try_record_portfolio_reconciliation(
        self,
        evaluation: PortfolioReconciliationEvaluationRow,
    ) -> int | IntegrityError | OperationalError:
        """Run one write attempt in an independently owned session.

        Operational failures invalidate their connection inside the owning
        context so its normal exit cannot issue a rollback against that
        connection. Integrity failures retain the ordinary rollback path.
        """
        async with self.session() as s:
            try:
                state_id = await self._write_portfolio_reconciliation(s, evaluation)
                await s.commit()
            except OperationalError as exc:
                await s.invalidate()
                return exc
            except IntegrityError as exc:
                await s.rollback()
                return exc
            return state_id

    async def record_portfolio_reconciliation(
        self, evaluation: PortfolioReconciliationEvaluationRow
    ) -> int:
        """Atomically persist evaluation evidence, state, and drift lifecycle.

        This DAL is the single writer and fails closed by validating cross-row
        consistency between state and observation, episode and observation,
        and state and episode, plus latest-observation currency, ``opened_at``
        temporal integrity, and predecessor existence. Therefore no single
        tampered predecessor/episode/observation row can drive the WRITER into a
        new authoritative reconciled or drift transition. This is a WRITE-PATH
        guarantee only: the scoped reader ``get_portfolio_reconciliation_states``
        returns the raw active rows WITHOUT read-time revalidation, so it is NOT
        the authoritative fail-closed read surface. That surface — read-time
        coherence revalidation of the stored fields against the observation
        lineage, mirroring Phase 3's ``build_portfolio_account_state`` /
        ``_row_is_coherent`` (Phase 3 S1's raw ``get_venue_account_states`` was
        likewise revalidated only by the S3 read surface) — is Phase 4 S4 and
        MUST run before any REST/MCP exposure. Arbitrary direct-database row mutation by an actor with
        write access is outside this validation boundary, including tampering
        with SCD2 envelope metadata such as an active row's ``timestamp``,
        versioning a ``resolved`` episode's terminal and non-authoritative
        history, or corrupting unrelated planes. That boundary is a database-
        access-control concern identical to every other plane, including venue
        truth, positions, and orders.

        A lost concurrent first insert or SQLite stale-read operational race is
        retried once in a fresh session after the failed transaction is rolled
        back or its connection is invalidated. A per-identity process lock
        serializes same-repository writers, including SQLite where ``FOR
        UPDATE`` is ignored; PostgreSQL additionally enforces the row lock
        across repository processes. The evaluation tuple is unique per
        account: exact replays are idempotent, conflicting replays fail closed,
        and tuples older than the active predecessor are ignored.

        Args:
            evaluation: Raw comparison evidence and evaluation outcome.

        Returns:
            The new active reconciliation-state row id.
        """
        canonical_evaluation = evaluation.copy()
        canonical_evaluation["wallet_public_id"] = _canonicalize_reconciliation_wallet_public_id(
            evaluation["wallet_public_id"]
        )
        identity = (
            canonical_evaluation["wallet_public_id"],
            canonical_evaluation["exchange"],
            canonical_evaluation["mode"],
        )
        lock = self._portfolio_reconciliation_locks.setdefault(identity, asyncio.Lock())
        async with lock:
            result = await self._try_record_portfolio_reconciliation(canonical_evaluation)
            if isinstance(result, int):
                return result
            retry_result = await self._try_record_portfolio_reconciliation(canonical_evaluation)
            if isinstance(retry_result, int):
                return retry_result
            raise retry_result

    async def has_portfolio_reconciliation_evaluation(
        self,
        wallet_public_id: str,
        exchange: str,
        mode: str,
        session_id: str,
        sequence_id: int,
    ) -> bool:
        """Check the indexed five-column evaluation idempotency key.

        Alias UUID spellings are canonicalized before filtering; malformed
        wallet identities raise ``ValueError`` like reconciliation writers.
        """
        wallet_public_id = _canonicalize_reconciliation_wallet_public_id(wallet_public_id)
        async with self.session() as s:
            return bool(
                await s.scalar(
                    select(
                        exists().where(
                            PortfolioReconciliationObservation.wallet_public_id == wallet_public_id,
                            PortfolioReconciliationObservation.exchange == exchange,
                            PortfolioReconciliationObservation.mode == mode,
                            PortfolioReconciliationObservation.session_id == session_id,
                            PortfolioReconciliationObservation.sequence_id == sequence_id,
                        )
                    )
                )
            )

    async def get_portfolio_drift_episode_transition(
        self,
        wallet_public_id: str,
        exchange: str,
        mode: str,
        session_id: str,
        sequence_id: int,
    ) -> PortfolioDriftEpisodeTransitionRow | None:
        """Return the exact committed drift lifecycle version from one evaluation.

        Alias UUID spellings are canonicalized before filtering; malformed
        wallet identities raise ``ValueError`` like reconciliation writers.
        """
        wallet_public_id = _canonicalize_reconciliation_wallet_public_id(wallet_public_id)
        async with self.session() as s:
            episode = (
                (
                    await s.execute(
                        select(PortfolioDriftEpisode).where(
                            PortfolioDriftEpisode.wallet_public_id == wallet_public_id,
                            PortfolioDriftEpisode.exchange == exchange,
                            PortfolioDriftEpisode.mode == mode,
                            PortfolioDriftEpisode.session_id == session_id,
                            PortfolioDriftEpisode.sequence_id == sequence_id,
                        )
                    )
                )
                .scalars()
                .one_or_none()
            )
            if episode is None:
                return None
            return {
                "wallet_public_id": episode.wallet_public_id,
                "exchange": episode.exchange,
                "mode": episode.mode,
                "status": episode.status,
                "opened_at": episode.opened_at,
                "closed_at": episode.closed_at,
                "trigger_observation_id": episode.trigger_observation_id,
                "last_observation_id": episode.last_observation_id,
                "latest_full_mismatch_count": episode.latest_full_mismatch_count,
                "resolution_reason": episode.resolution_reason,
                "public_id": episode.public_id,
                "session_id": episode.session_id,
                "sequence_id": episode.sequence_id,
            }

    async def list_open_portfolio_drift_episodes(self) -> list[PortfolioDriftEpisodeRow]:
        """Return current open drift episodes in deterministic scan order."""
        async with self.session() as s:
            episodes = (
                (
                    await s.execute(
                        select(PortfolioDriftEpisode)
                        .where(
                            PortfolioDriftEpisode.status == "open",
                            PortfolioDriftEpisode.known_to == KNOWN_TO_MAX,
                        )
                        .order_by(
                            PortfolioDriftEpisode.opened_at,
                            PortfolioDriftEpisode.public_id,
                        )
                    )
                )
                .scalars()
                .all()
            )
            return [self._portfolio_drift_episode_to_row(episode) for episode in episodes]

    @staticmethod
    def _portfolio_reconciliation_state_to_row(
        state: PortfolioReconciliationState,
    ) -> PortfolioReconciliationStateRow:
        """Project a reconciliation state ORM row to its read TypedDict.

        Args:
            state: Sentinel-active ORM state.

        Returns:
            The read row dict.
        """
        return {
            "wallet_public_id": state.wallet_public_id,
            "exchange": state.exchange,
            "mode": state.mode,
            "method": state.method,
            "current_evaluation_status": state.current_evaluation_status,
            "current_observation_id": state.current_observation_id,
            "last_full_observation_id": state.last_full_observation_id,
            "last_full_outcome": state.last_full_outcome,
            "detail_source_observation_id": state.detail_source_observation_id,
            "consecutive_full_mismatches": state.consecutive_full_mismatches,
            "open_drift_episode_public_id": state.open_drift_episode_public_id,
            "anchor_public_id": state.anchor_public_id,
            "venue_account_state_public_id": state.venue_account_state_public_id,
            "venue_account_observation_id": state.venue_account_observation_id,
            "source_watermark_kind": state.source_watermark_kind,
            "source_watermark": state.source_watermark,
            "expected_json": state.expected_json,
            "actual_json": state.actual_json,
            "difference_json": state.difference_json,
            "tolerance_json": state.tolerance_json,
            "reconciled_at": state.reconciled_at,
            "authoritative_until": state.authoritative_until,
            "error": state.error,
            "public_id": state.public_id,
            "timestamp": state.timestamp,
            "session_id": state.session_id,
            "sequence_id": state.sequence_id,
        }

    @staticmethod
    def _portfolio_drift_episode_to_row(
        episode: PortfolioDriftEpisode,
    ) -> PortfolioDriftEpisodeRow:
        """Project one active open drift episode to its typed boundary."""
        return {
            "wallet_public_id": episode.wallet_public_id,
            "exchange": episode.exchange,
            "mode": episode.mode,
            "status": episode.status,
            "opened_at": episode.opened_at,
            "trigger_observation_id": episode.trigger_observation_id,
            "last_observation_id": episode.last_observation_id,
            "details_source_observation_id": episode.details_source_observation_id,
            "latest_full_mismatch_count": episode.latest_full_mismatch_count,
            "public_id": episode.public_id,
        }

    async def get_portfolio_reconciliation_states(
        self, wallet_public_ids: list[str] | None = None
    ) -> list[PortfolioReconciliationStateRow]:
        """Return sentinel-active reconciliation states by optional wallet scope.

        RAW rows for DAL/orchestration use only — NOT the authoritative
        fail-closed read surface. The stored fields are projected verbatim
        without read-time coherence revalidation against the observation
        lineage, so a CHECK-valid tampered active row would read as-is. The
        authoritative surface (read-time revalidation mirroring Phase 3's
        ``build_portfolio_account_state``) is Phase 4 S4 and MUST run before any
        REST/MCP exposure. See ``record_portfolio_reconciliation`` for the
        write-path fail-closed boundary.

        Args:
            wallet_public_ids: Full wallet identities to include, or ``None``
                for no wallet filter. An empty list yields no rows.

        Returns:
            Active states ordered by exchange then mode.

        Raises:
            ValueError: If a supplied wallet identity is malformed. Alias UUID
                spellings are canonicalized before filtering.
        """
        canonical_wallet_public_ids = (
            None
            if wallet_public_ids is None
            else [
                _canonicalize_reconciliation_wallet_public_id(wallet_public_id)
                for wallet_public_id in wallet_public_ids
            ]
        )
        async with self.session() as s:
            query = select(PortfolioReconciliationState).where(
                PortfolioReconciliationState.known_to == KNOWN_TO_MAX
            )
            if canonical_wallet_public_ids is not None:
                query = query.where(
                    PortfolioReconciliationState.wallet_public_id.in_(canonical_wallet_public_ids)
                )
            query = query.order_by(
                PortfolioReconciliationState.exchange,
                PortfolioReconciliationState.mode,
            )
            rows = (await s.execute(query)).scalars().all()
            return [self._portfolio_reconciliation_state_to_row(row) for row in rows]

    def _portfolio_reconciliation_read_observations(
        self,
        observations: tuple[
            PortfolioReconciliationObservation | None,
            PortfolioReconciliationObservation | None,
            PortfolioReconciliationObservation | None,
        ],
    ) -> list[PortfolioReconciliationLineageObservationRow]:
        """Project the unique observations referenced by one read-context row."""
        rows: list[PortfolioReconciliationLineageObservationRow] = []
        seen_observation_ids: set[int] = set()
        for observation in observations:
            if observation is None or observation.id in seen_observation_ids:
                continue
            seen_observation_ids.add(observation.id)
            rows.append(self._portfolio_reconciliation_lineage_observation_to_row(observation))
        return rows

    def _portfolio_reconciliation_read_context_from_row(
        self,
        row: _PortfolioReconciliationReadResultRow,
    ) -> tuple[
        _PortfolioReconciliationIdentity,
        PortfolioReconciliationReadContextRow,
        _PortfolioReconciliationActiveRowIds,
    ]:
        """Project one joined row and its active-version identity sets."""
        (
            account_state,
            state,
            current,
            last_full,
            detail_source,
            config,
            episode,
            spot_anchor,
            latest_ordered_id,
            latest_appended_id,
        ) = row
        identity = (
            account_state.wallet_public_id,
            account_state.exchange,
            account_state.mode,
        )
        context: PortfolioReconciliationReadContextRow = {
            "account_state": self._venue_account_state_to_row(account_state),
            "state": None if state is None else self._portfolio_reconciliation_state_to_row(state),
            "observations": self._portfolio_reconciliation_read_observations(
                (current, last_full, detail_source)
            ),
            "config": (
                None
                if config is None
                else self._portfolio_reconciliation_method_config_to_row(config)
            ),
            "latest_ordered_observation_id": latest_ordered_id,
            "latest_appended_observation_id": latest_appended_id,
            "open_drift_episode": (
                None if episode is None else self._portfolio_drift_episode_to_row(episode)
            ),
            "spot_anchor": None if spot_anchor is None else self._spot_anchor_to_row(spot_anchor),
            "duplicate_active_rows": False,
        }
        active_row_ids: _PortfolioReconciliationActiveRowIds = (
            {account_state.id},
            set() if state is None else {state.id},
            set() if config is None else {config.id},
            set() if episode is None else {episode.id},
            set() if spot_anchor is None else {spot_anchor.id},
        )
        return identity, context, active_row_ids

    @staticmethod
    def _merge_portfolio_reconciliation_active_row_ids(
        existing: _PortfolioReconciliationActiveRowIds,
        incoming: _PortfolioReconciliationActiveRowIds,
    ) -> None:
        """Merge active-version identity sets from a multiplicative join row."""
        for existing_ids, incoming_ids in zip(existing, incoming, strict=True):
            existing_ids.update(incoming_ids)

    async def get_portfolio_reconciliation_read_contexts(
        self, wallet_public_ids: list[str] | None = None
    ) -> list[PortfolioReconciliationReadContextRow]:
        """Load complete account reconciliation contexts in one set query.

        The account-state table anchors the result so every rendered account
        receives exactly one context, including accounts without reconciliation
        history. Multiplicative joins from duplicate active account anchors,
        reconciliation states, method configs, referenced open drift episodes,
        or referenced spot anchors collapse to one context carrying an explicit
        corruption marker. That marker invalidates the whole account
        presentation and its nested reconciliation view. Observation references
        join by internal id without an identity predicate so forged cross-account
        lineage remains visible to the shared validators and fails closed instead
        of appearing merely absent.

        Args:
            wallet_public_ids: Full wallet identities to include, or ``None``
                for no wallet filter. An empty list yields no rows.

        Returns:
            Complete read-validation contexts ordered by account identity.

        Raises:
            ValueError: If a supplied wallet identity is malformed. Alias UUID
                spellings are canonicalized before filtering.
        """
        canonical_wallet_public_ids = (
            None
            if wallet_public_ids is None
            else [
                _canonicalize_reconciliation_wallet_public_id(wallet_public_id)
                for wallet_public_id in wallet_public_ids
            ]
        )
        if canonical_wallet_public_ids == []:
            return []
        current_observation = aliased(PortfolioReconciliationObservation)
        last_full_observation = aliased(PortfolioReconciliationObservation)
        detail_source_observation = aliased(PortfolioReconciliationObservation)
        latest_ordered_observation_id = (
            select(PortfolioReconciliationObservation.id)
            .where(
                PortfolioReconciliationObservation.wallet_public_id
                == VenueAccountState.wallet_public_id,
                PortfolioReconciliationObservation.exchange == VenueAccountState.exchange,
                PortfolioReconciliationObservation.mode == VenueAccountState.mode,
            )
            .order_by(
                PortfolioReconciliationObservation.session_id.desc(),
                PortfolioReconciliationObservation.sequence_id.desc(),
                PortfolioReconciliationObservation.id.desc(),
            )
            .limit(1)
            .correlate(VenueAccountState)
            .scalar_subquery()
        )
        latest_appended_observation_id = (
            select(func.max(PortfolioReconciliationObservation.id))
            .where(
                PortfolioReconciliationObservation.wallet_public_id
                == VenueAccountState.wallet_public_id,
                PortfolioReconciliationObservation.exchange == VenueAccountState.exchange,
                PortfolioReconciliationObservation.mode == VenueAccountState.mode,
            )
            .correlate(VenueAccountState)
            .scalar_subquery()
        )
        async with self.session() as s:
            query = (
                select(
                    VenueAccountState,
                    PortfolioReconciliationState,
                    current_observation,
                    last_full_observation,
                    detail_source_observation,
                    PortfolioReconciliationMethodConfig,
                    PortfolioDriftEpisode,
                    PortfolioSpotReconciliationAnchor,
                    latest_ordered_observation_id,
                    latest_appended_observation_id,
                )
                .select_from(VenueAccountState)
                .outerjoin(
                    PortfolioReconciliationState,
                    and_(
                        PortfolioReconciliationState.wallet_public_id
                        == VenueAccountState.wallet_public_id,
                        PortfolioReconciliationState.exchange == VenueAccountState.exchange,
                        PortfolioReconciliationState.mode == VenueAccountState.mode,
                        PortfolioReconciliationState.known_to == KNOWN_TO_MAX,
                    ),
                )
                .outerjoin(
                    current_observation,
                    current_observation.id == PortfolioReconciliationState.current_observation_id,
                )
                .outerjoin(
                    last_full_observation,
                    last_full_observation.id
                    == PortfolioReconciliationState.last_full_observation_id,
                )
                .outerjoin(
                    detail_source_observation,
                    detail_source_observation.id
                    == PortfolioReconciliationState.detail_source_observation_id,
                )
                .outerjoin(
                    PortfolioReconciliationMethodConfig,
                    and_(
                        PortfolioReconciliationMethodConfig.wallet_public_id
                        == VenueAccountState.wallet_public_id,
                        PortfolioReconciliationMethodConfig.exchange == VenueAccountState.exchange,
                        PortfolioReconciliationMethodConfig.mode == VenueAccountState.mode,
                        PortfolioReconciliationMethodConfig.known_to == KNOWN_TO_MAX,
                    ),
                )
                .outerjoin(
                    PortfolioDriftEpisode,
                    and_(
                        PortfolioDriftEpisode.public_id
                        == PortfolioReconciliationState.open_drift_episode_public_id,
                        PortfolioDriftEpisode.known_to == KNOWN_TO_MAX,
                    ),
                )
                .outerjoin(
                    PortfolioSpotReconciliationAnchor,
                    and_(
                        PortfolioSpotReconciliationAnchor.public_id
                        == PortfolioReconciliationState.anchor_public_id,
                        PortfolioSpotReconciliationAnchor.known_to == KNOWN_TO_MAX,
                    ),
                )
                .where(VenueAccountState.known_to == KNOWN_TO_MAX)
                .order_by(
                    VenueAccountState.exchange,
                    VenueAccountState.mode,
                    VenueAccountState.wallet_public_id,
                )
            )
            if canonical_wallet_public_ids is not None:
                query = query.where(
                    VenueAccountState.wallet_public_id.in_(canonical_wallet_public_ids)
                )
            result = await s.execute(query)
            contexts: list[PortfolioReconciliationReadContextRow] = []
            contexts_by_identity: dict[
                _PortfolioReconciliationIdentity,
                PortfolioReconciliationReadContextRow,
            ] = {}
            active_row_ids: dict[
                _PortfolioReconciliationIdentity,
                _PortfolioReconciliationActiveRowIds,
            ] = {}
            for result_row in result.tuples().all():
                identity, context, row_ids = self._portfolio_reconciliation_read_context_from_row(
                    result_row
                )
                existing_ids = active_row_ids.get(identity)
                if existing_ids is not None:
                    self._merge_portfolio_reconciliation_active_row_ids(existing_ids, row_ids)
                    continue
                active_row_ids[identity] = row_ids
                contexts_by_identity[identity] = context
                contexts.append(context)
            for identity, context in contexts_by_identity.items():
                context["duplicate_active_rows"] = any(
                    len(ids) > 1 for ids in active_row_ids[identity]
                )
            return contexts

    async def get_fill_shard_keys_by_client_order_ids(
        self, client_order_ids: list[str]
    ) -> tuple[dict[str, tuple[str, str]], set[str]]:
        """Durable fill lineage: client order id -> venue-event shard key.

        Execution rows carry no shard key, so execution-replay recovery
        historically RECONSTRUCTED one (untagged, live) — minting a
        phantom sibling for tagged paper shards that fails the
        projection certification. The executor writes ``fill_observed``
        venue events fail-closed with the EXACT shard key (mode and
        strategy tag included) before publishing, so this map is the
        durable lineage. Clock-free sentinel-less scan (venue events
        are append-only); a client order id whose fill events disagree
        on the shard key is DROPPED as ambiguous — the caller falls
        back to reconstruction and the shard stays uncertified.

        Args:
            client_order_ids: Client order ids of the executions being
                replayed.

        Returns:
            Tuple of (mapping of client_order_id to its single durable
            (shard key, FULL wallet public id) pair, set of AMBIGUOUS
            client order ids whose fill events disagree on the shard or
            wallet, or carry an empty shard) — the caller must treat
            ambiguity as a certification failure, never as absence of
            evidence. The full wallet id rides along because shard keys
            carry only a 48-bit wallet suffix and suffix collisions
            must not certify fills under the wrong wallet.
        """
        if not client_order_ids:
            return {}, set()
        pairs: set[tuple[str, str, str]] = set()
        async with self.session() as s:
            for start in range(0, len(client_order_ids), _ORDER_LIFECYCLE_LOOKUP_CHUNK_SIZE):
                chunk = client_order_ids[start : start + _ORDER_LIFECYCLE_LOOKUP_CHUNK_SIZE]
                result = await s.execute(
                    select(
                        VenueEvent.client_order_id,
                        VenueEvent.shard_key,
                        VenueEvent.wallet_public_id,
                    )
                    .where(
                        VenueEvent.event_type == "fill_observed",
                        VenueEvent.client_order_id.in_(chunk),
                    )
                    .distinct()
                )
                for cid, shard_key, wallet_public_id in result.all():
                    pairs.add((str(cid), str(shard_key or ""), str(wallet_public_id or "")))
        by_cid: dict[str, set[tuple[str, str]]] = {}
        for cid, shard_key, wallet_public_id in pairs:
            by_cid.setdefault(cid, set()).add((shard_key, wallet_public_id))
        resolved: dict[str, tuple[str, str]] = {}
        ambiguous: set[str] = set()
        for cid, lineages in by_cid.items():
            only = next(iter(lineages)) if len(lineages) == 1 else None
            if only is not None and only[0]:
                resolved[cid] = only
            else:
                ambiguous.add(cid)
        return resolved, ambiguous

    async def get_command_shard_keys_by_client_order_ids(
        self, client_order_ids: list[str]
    ) -> tuple[dict[str, tuple[str, str]], set[str]]:
        """Durable command lineage: client order id -> trade-command shard key.

        Active-order recovery historically RECONSTRUCTED an untagged,
        live-mode shard key from the order row — minting a phantom
        sibling engine (and a phantom pending-CID route) for tagged
        paper shards. Order dispatch persists the ``trade_commands``
        row fail-closed with the EXACT shard key (mode and strategy tag
        included) BEFORE publishing, so this map is the durable lineage
        for orders that have no fills yet. Clock-free scan across all
        SCD2 versions (a command's shard key and wallet never legally
        change across versions); a client order id whose command rows
        disagree on the shard key or wallet is returned as ambiguous —
        the caller must treat ambiguity as a certification failure,
        never as absence of evidence.

        Args:
            client_order_ids: Client order ids of the active orders
                being recovered.

        Returns:
            Tuple of (mapping of client_order_id to its single durable
            (shard key, FULL wallet public id) pair, set of AMBIGUOUS
            client order ids whose command rows disagree on the shard
            or wallet, or carry an empty shard). The full wallet id
            rides along because shard keys carry only a 48-bit wallet
            suffix and suffix collisions must not install a pending
            route under the wrong wallet.
        """
        if not client_order_ids:
            return {}, set()
        pairs: set[tuple[str, str, str]] = set()
        async with self.session() as s:
            for start in range(0, len(client_order_ids), _ORDER_LIFECYCLE_LOOKUP_CHUNK_SIZE):
                chunk = client_order_ids[start : start + _ORDER_LIFECYCLE_LOOKUP_CHUNK_SIZE]
                result = await s.execute(
                    select(
                        TradeCommand.client_order_id,
                        TradeCommand.shard_key,
                        TradeCommand.wallet_public_id,
                    )
                    .where(TradeCommand.client_order_id.in_(chunk))
                    .distinct()
                )
                for cid, shard_key, wallet_public_id in result.all():
                    pairs.add((str(cid), str(shard_key or ""), str(wallet_public_id or "")))
        by_cid: dict[str, set[tuple[str, str]]] = {}
        for cid, shard_key, wallet_public_id in pairs:
            by_cid.setdefault(cid, set()).add((shard_key, wallet_public_id))
        resolved: dict[str, tuple[str, str]] = {}
        ambiguous: set[str] = set()
        for cid, lineages in by_cid.items():
            only = next(iter(lineages)) if len(lineages) == 1 else None
            if only is not None and only[0]:
                resolved[cid] = only
            else:
                ambiguous.add(cid)
        return resolved, ambiguous

    async def get_active_position_identities(self) -> list[tuple[str, str, str, str]]:
        """Clock-free scan of active position rows for recovery diagnostics.

        Reads by the current-version sentinel filter with NO temporal
        joins, so a row whose clamped timestamp sits ahead of the
        recovery clock — or one a temporal Instrument/Symbol join would
        hide — is still visible to the stale-row warning after the
        projection rebuild.

        Returns:
            Tuples of (public_id, instrument_public_id, mode,
            wallet_public_id) for every active row.
        """
        async with self.session() as s:
            result = await s.execute(
                select(
                    Position.public_id,
                    Position.instrument_public_id,
                    Position.mode,
                    Position.wallet_public_id,
                ).where(Position.known_to == KNOWN_TO_MAX)
            )
            return [(str(r[0]), str(r[1]), str(r[2]), str(r[3])) for r in result.all()]

    async def get_checkpoint(
        self, shard_key: str, as_of: datetime
    ) -> TradeProjectionCheckpointRow | None:
        """Return the active checkpoint for a shard, or None."""
        async with self.session() as s:
            result = await s.execute(
                select(TradeProjectionCheckpoint).where(
                    TradeProjectionCheckpoint.shard_key == shard_key,
                    *where_active(TradeProjectionCheckpoint, as_of),
                )
            )
            cp = result.scalars().first()
            if cp is None:
                return None
            row: TradeProjectionCheckpointRow = {
                "public_id": cp.public_id,
                "shard_key": cp.shard_key,
                "projection_calc_version": cp.projection_calc_version,
                "position_qty": cp.position_qty,
                "entry_price": cp.entry_price,
                "position_opened_at": cp.position_opened_at,
                "cash": cp.cash,
                "peak_equity": cp.peak_equity,
                "realized_pnl": cp.realized_pnl,
                "turnover": cp.turnover,
                "last_venue_event_id": cp.last_venue_event_id,
                "last_venue_event_at": cp.last_venue_event_at,
                "open_command_ids": cp.open_command_ids,
                "seen_exec_ids": cp.seen_exec_ids,
                "checkpoint_at": cp.checkpoint_at,
                "session_id": cp.session_id,
                "operator_public_id": cp.operator_public_id,
            }
            return row

    async def get_all_checkpoints(self, as_of: datetime) -> list[TradeProjectionCheckpointRow]:
        """Return all CURRENT checkpoints for recovery.

        Clock-free: reads by the current-version sentinel filter, not a
        caller-clock temporal window — a checkpoint whose clamped
        timestamp sits ahead of a lagging recovery clock must still be
        recovered (the Phase-0 clock-skew class). ``as_of`` is retained
        for signature stability but no longer scopes the read.
        """
        del as_of
        async with self.session() as s:
            result = await s.execute(
                select(TradeProjectionCheckpoint)
                .where(TradeProjectionCheckpoint.known_to == KNOWN_TO_MAX)
                .order_by(TradeProjectionCheckpoint.shard_key)
            )
            rows: list[TradeProjectionCheckpointRow] = []
            for cp in result.scalars().all():
                rows.append(
                    {
                        "public_id": cp.public_id,
                        "shard_key": cp.shard_key,
                        "projection_calc_version": cp.projection_calc_version,
                        "position_qty": cp.position_qty,
                        "entry_price": cp.entry_price,
                        "position_opened_at": cp.position_opened_at,
                        "cash": cp.cash,
                        "peak_equity": cp.peak_equity,
                        "realized_pnl": cp.realized_pnl,
                        "turnover": cp.turnover,
                        "last_venue_event_id": cp.last_venue_event_id,
                        "last_venue_event_at": cp.last_venue_event_at,
                        "open_command_ids": cp.open_command_ids,
                        "seen_exec_ids": cp.seen_exec_ids,
                        "checkpoint_at": cp.checkpoint_at,
                        "session_id": cp.session_id,
                        "wallet_public_id": cp.wallet_public_id,
                        "operator_public_id": cp.operator_public_id,
                    }
                )
            return rows

    async def retire_trade_projection_checkpoints(
        self,
        shard_key: str | None,
        expected_public_ids: list[str],
        retired_at: datetime,
    ) -> int:
        """SCD2-close exactly the active checkpoints the operator previewed.

        The writer reselects current rows under lock and refuses when their
        public ids differ from the preview assertion. It only changes
        ``known_to`` and verifies the database-reported affected-row count
        before committing.

        Args:
            shard_key: One exact shard key, or None for every active checkpoint.
            expected_public_ids: Exact public ids shown by the CLI preview.
            retired_at: Knowledge time stamped onto ``known_to``.

        Returns:
            Number of checkpoint versions closed.

        Raises:
            ValueError: If current rows differ from the preview or the affected
                row count differs from the asserted count.
        """
        async with self.session() as s:
            filters: list[ColumnElement[bool]] = [TradeProjectionCheckpoint.known_to > retired_at]
            if shard_key is not None:
                filters.append(TradeProjectionCheckpoint.shard_key == shard_key)
            result = await s.execute(
                select(TradeProjectionCheckpoint.id, TradeProjectionCheckpoint.public_id)
                .where(*filters)
                .order_by(TradeProjectionCheckpoint.shard_key)
                .with_for_update()
            )
            rows = result.all()
            actual_public_ids = [str(row.public_id) for row in rows]
            if actual_public_ids != expected_public_ids:
                raise ValueError(
                    "checkpoint set changed after preview; nothing was written: "
                    f"expected={expected_public_ids!r} actual={actual_public_ids!r}"
                )
            if not rows:
                return 0
            row_ids = [int(row.id) for row in rows]
            update_result = await s.execute(
                update(TradeProjectionCheckpoint)
                .where(
                    TradeProjectionCheckpoint.id.in_(row_ids),
                    TradeProjectionCheckpoint.known_to > retired_at,
                )
                .values(known_to=retired_at)
            )
            closed = cast(CursorResult[Any], update_result).rowcount
            if closed != len(rows):
                raise ValueError(
                    "checkpoint close count mismatch; transaction rolled back: "
                    f"previewed={len(rows)} closed={closed}"
                )
            await s.commit()
            return closed

    async def get_trade_projection_checkpoint_retirement_candidates(
        self, shard_key: str | None, as_of: datetime
    ) -> list[TradeProjectionCheckpointRow]:
        """Return checkpoint versions still known at the preview instant.

        Args:
            shard_key: One exact shard key, or None for every checkpoint.
            as_of: Knowledge instant used by the ``known_to > as_of`` predicate.

        Returns:
            Candidate checkpoints ordered by shard key.
        """
        filters: list[ColumnElement[bool]] = [TradeProjectionCheckpoint.known_to > as_of]
        if shard_key is not None:
            filters.append(TradeProjectionCheckpoint.shard_key == shard_key)
        async with self.session() as s:
            result = await s.execute(
                select(TradeProjectionCheckpoint)
                .where(*filters)
                .order_by(TradeProjectionCheckpoint.shard_key)
            )
            return [
                {
                    "public_id": cp.public_id,
                    "shard_key": cp.shard_key,
                    "projection_calc_version": cp.projection_calc_version,
                    "position_qty": cp.position_qty,
                    "entry_price": cp.entry_price,
                    "position_opened_at": cp.position_opened_at,
                    "cash": cp.cash,
                    "peak_equity": cp.peak_equity,
                    "realized_pnl": cp.realized_pnl,
                    "turnover": cp.turnover,
                    "last_venue_event_id": cp.last_venue_event_id,
                    "last_venue_event_at": cp.last_venue_event_at,
                    "open_command_ids": cp.open_command_ids,
                    "seen_exec_ids": cp.seen_exec_ids,
                    "checkpoint_at": cp.checkpoint_at,
                    "session_id": cp.session_id,
                    "wallet_public_id": cp.wallet_public_id,
                    "operator_public_id": cp.operator_public_id,
                }
                for cp in result.scalars().all()
            ]

    async def insert_funding_rate(
        self,
        row: FundingRateInsertRow,
        session: AsyncSession | None = None,
    ) -> int:
        """Insert a funding rate row, optionally on a caller-managed session.

        See ``Repository.insert_funding_rate`` for the contract. When
        the caller passes its own ``session``, the insert is wrapped in
        a ``begin_nested()`` SAVEPOINT so a duplicate ``IntegrityError``
        from the partial unique index only rolls back the savepoint —
        the outer transaction stays usable and the caller can swallow
        the duplicate as a "boundary already applied" no-op.
        """
        if session is None:
            async with self.session() as s:
                obj = FundingRate(**row)
                s.add(obj)
                await s.commit()
                await s.refresh(obj)
                return int(obj.id)
        obj = FundingRate(**row)
        async with session.begin_nested():
            session.add(obj)
            await session.flush()
        return int(obj.id)

    async def get_funding_rates(
        self,
        instrument_public_id: str,
        exchange: str,
        rate_type: str,
        direction: str,
        as_of: datetime,
        range_start: datetime | None = None,
        range_end: datetime | None = None,
    ) -> list[FundingRateRow]:
        """Bitemporal lookup of funding rates with explicit time window."""
        async with self.session() as s:
            stmt = (
                select(FundingRate)
                .where(
                    FundingRate.instrument_public_id == instrument_public_id,
                    FundingRate.exchange == exchange,
                    FundingRate.rate_type == rate_type,
                    FundingRate.direction == direction,
                    *where_active(FundingRate, as_of),
                )
                .order_by(FundingRate.effective_from)
            )
            if range_start is not None:
                stmt = stmt.where(FundingRate.effective_from >= range_start)
            if range_end is not None:
                stmt = stmt.where(FundingRate.effective_from <= range_end)
            result = await s.execute(stmt)
            return [
                FundingRateRow(
                    public_id=fr.public_id,
                    instrument_public_id=fr.instrument_public_id,
                    exchange=fr.exchange,
                    rate_type=fr.rate_type,
                    direction=fr.direction,
                    rate=fr.rate,
                    notional_asset=fr.notional_asset,
                    effective_from=fr.effective_from,
                    source=fr.source,
                    timestamp=fr.timestamp,
                    session_id=fr.session_id,
                    sequence_id=fr.sequence_id,
                )
                for fr in result.scalars().all()
            ]

    async def insert_accrual(
        self,
        row: AccrualLedgerInsertRow,
        session: AsyncSession | None = None,
    ) -> int:
        """Insert an accrual ledger row, optionally on a caller-managed session.

        See ``Repository.insert_accrual`` for the contract. When the
        caller passes its own ``session``, the insert is wrapped in a
        ``begin_nested()`` SAVEPOINT so a duplicate ``IntegrityError``
        from the partial unique index only rolls back the savepoint —
        the outer transaction stays usable and the caller can swallow
        the duplicate as a "boundary already applied" no-op without
        losing earlier writes from the same outer transaction.
        """
        row_with_defaults: dict[str, Any] = {"wallet_public_id": "", **row}
        if session is None:
            async with self.session() as s:
                obj = AccrualLedger(**row_with_defaults)
                s.add(obj)
                await s.commit()
                await s.refresh(obj)
                return int(obj.id)
        obj = AccrualLedger(**row_with_defaults)
        async with session.begin_nested():
            session.add(obj)
            await session.flush()
        return int(obj.id)

    async def get_accruals(
        self,
        instrument_public_id: str,
        mode: str,
        range_start: datetime,
        range_end: datetime,
        wallet_public_id: str = "",
    ) -> list[AccrualLedgerRow]:
        """Replay-window query keyed on insertion timestamp, not accrued_at."""
        async with self.session() as s:
            now = datetime.now(UTC)
            filters = [
                AccrualLedger.instrument_public_id == instrument_public_id,
                AccrualLedger.mode == mode,
                AccrualLedger.timestamp > range_start,
                AccrualLedger.timestamp <= range_end,
                *where_active(AccrualLedger, now),
            ]
            if wallet_public_id:
                filters.append(AccrualLedger.wallet_public_id == wallet_public_id)
            stmt = select(AccrualLedger).where(*filters).order_by(AccrualLedger.accrued_at)
            result = await s.execute(stmt)
            return [self._accrual_row_to_dict(al) for al in result.scalars().all()]

    async def get_last_accrual(
        self,
        instrument_public_id: str,
        mode: str,
        accrual_type: str,
        wallet_public_id: str = "",
    ) -> AccrualLedgerRow | None:
        """Return the most recent accrual for catch-up boundary computation."""
        async with self.session() as s:
            now = datetime.now(UTC)
            filters = [
                AccrualLedger.instrument_public_id == instrument_public_id,
                AccrualLedger.mode == mode,
                AccrualLedger.accrual_type == accrual_type,
                *where_active(AccrualLedger, now),
            ]
            if wallet_public_id:
                filters.append(AccrualLedger.wallet_public_id == wallet_public_id)
            stmt = (
                select(AccrualLedger)
                .where(*filters)
                .order_by(AccrualLedger.accrued_at.desc())
                .limit(1)
            )
            result = await s.execute(stmt)
            row = result.scalars().first()
            if row is None:
                return None
            return self._accrual_row_to_dict(row)

    @staticmethod
    def _accrual_row_to_dict(al: AccrualLedger) -> AccrualLedgerRow:
        """Project an AccrualLedger ORM row into the TypedDict shape."""
        return AccrualLedgerRow(
            public_id=al.public_id,
            instrument_public_id=al.instrument_public_id,
            mode=al.mode,
            accrual_type=al.accrual_type,
            accrued_at=al.accrued_at,
            amount=al.amount,
            amount_asset=al.amount_asset,
            rate=al.rate,
            notional=al.notional,
            position_quantity_at_accrual=al.position_quantity_at_accrual,
            exchange=al.exchange,
            timestamp=al.timestamp,
            session_id=al.session_id,
            sequence_id=al.sequence_id,
        )

    async def get_fill_exec_ids_for_shard(self, shard_key: str) -> set[str]:
        """Return all exec_id and trade_id values from fill events for a shard.

        Used to rebuild the fill dedup set during recovery. Queries all
        VenueEvent rows with event_type='fill_observed' for the shard.

        Args:
            shard_key: Shard to query.

        Returns:
            Set of exec_id and trade_id strings (non-null values only).
        """
        async with self.session() as s:
            result = await s.execute(
                select(VenueEvent.exec_id, VenueEvent.trade_id).where(
                    VenueEvent.shard_key == shard_key,
                    VenueEvent.event_type == "fill_observed",
                )
            )
            ids: set[str] = set()
            for row in result.all():
                if row[0]:
                    ids.add(row[0])
                if row[1]:
                    ids.add(row[1])
            return ids

    async def get_underlying_assets(
        self,
        as_of: datetime,
    ) -> list[UnderlyingAssetRow]:
        """All active underlying assets at as_of with instrument counts."""
        async with self.session() as s:
            mapping_count = (
                select(
                    InstrumentUnderlyingMapping.underlying_public_id,
                    func.count().label("cnt"),
                )
                .join(
                    Instrument,
                    and_(
                        Instrument.public_id == InstrumentUnderlyingMapping.instrument_public_id,
                        *where_active(Instrument, as_of),
                    ),
                )
                .join(
                    Symbol,
                    and_(
                        Symbol.public_id == Instrument.symbol_public_id,
                        *where_active(Symbol, as_of),
                    ),
                )
                .where(*where_active(InstrumentUnderlyingMapping, as_of))
                .group_by(InstrumentUnderlyingMapping.underlying_public_id)
                .subquery()
            )
            stmt = (
                select(
                    UnderlyingAsset.public_id,
                    UnderlyingAsset.ticker,
                    UnderlyingAsset.name,
                    UnderlyingAsset.asset_class,
                    UnderlyingAsset.sector,
                    UnderlyingAsset.description,
                    UnderlyingAsset.timestamp,
                    UnderlyingAsset.session_id,
                    UnderlyingAsset.sequence_id,
                    func.coalesce(mapping_count.c.cnt, 0).label("instrument_count"),
                )
                .outerjoin(
                    mapping_count,
                    mapping_count.c.underlying_public_id == UnderlyingAsset.public_id,
                )
                .where(*where_active(UnderlyingAsset, as_of))
                .order_by(UnderlyingAsset.ticker)
            )
            result = await s.execute(stmt)
            return [
                UnderlyingAssetRow(
                    public_id=r.public_id,
                    ticker=r.ticker,
                    name=r.name,
                    asset_class=r.asset_class,
                    sector=r.sector,
                    description=r.description,
                    timestamp=r.timestamp,
                    session_id=r.session_id,
                    sequence_id=r.sequence_id,
                    instrument_count=r.instrument_count,
                )
                for r in result.all()
            ]

    async def get_underlying_by_ticker(
        self,
        ticker: str,
        as_of: datetime,
    ) -> UnderlyingAssetRow | None:
        """Lookup underlying by ticker."""
        async with self.session() as s:
            count_sq = (
                select(func.count())
                .select_from(InstrumentUnderlyingMapping)
                .join(
                    Instrument,
                    and_(
                        Instrument.public_id == InstrumentUnderlyingMapping.instrument_public_id,
                        *where_active(Instrument, as_of),
                    ),
                )
                .join(
                    Symbol,
                    and_(
                        Symbol.public_id == Instrument.symbol_public_id,
                        *where_active(Symbol, as_of),
                    ),
                )
                .where(
                    InstrumentUnderlyingMapping.underlying_public_id == UnderlyingAsset.public_id,
                    *where_active(InstrumentUnderlyingMapping, as_of),
                )
                .correlate(UnderlyingAsset)
                .scalar_subquery()
                .label("instrument_count")
            )
            result = await s.execute(
                select(
                    UnderlyingAsset.public_id,
                    UnderlyingAsset.ticker,
                    UnderlyingAsset.name,
                    UnderlyingAsset.asset_class,
                    UnderlyingAsset.sector,
                    UnderlyingAsset.description,
                    UnderlyingAsset.timestamp,
                    UnderlyingAsset.session_id,
                    UnderlyingAsset.sequence_id,
                    count_sq,
                ).where(
                    UnderlyingAsset.ticker == ticker,
                    *where_active(UnderlyingAsset, as_of),
                )
            )
            r = result.first()
            if r is None:
                return None
            return UnderlyingAssetRow(
                public_id=r.public_id,
                ticker=r.ticker,
                name=r.name,
                asset_class=r.asset_class,
                sector=r.sector,
                description=r.description,
                timestamp=r.timestamp,
                session_id=r.session_id,
                sequence_id=r.sequence_id,
                instrument_count=r.instrument_count,
            )

    async def get_instruments_by_underlying(
        self,
        underlying_public_id: str,
        as_of: datetime,
        relationship_types: list[str] | None = None,
    ) -> list[InstrumentUnderlyingRow]:
        """Instruments mapped to an underlying asset."""
        async with self.session() as s:
            stmt = (
                select(
                    InstrumentUnderlyingMapping.public_id,
                    InstrumentUnderlyingMapping.instrument_public_id,
                    InstrumentUnderlyingMapping.underlying_public_id,
                    InstrumentUnderlyingMapping.relationship_type,
                    InstrumentUnderlyingMapping.contract_family,
                    Symbol.native_symbol.label("native_symbol"),
                    Instrument.exchange,
                    Symbol.asset_type,
                    InstrumentUnderlyingMapping.timestamp,
                    InstrumentUnderlyingMapping.session_id,
                    InstrumentUnderlyingMapping.sequence_id,
                )
                .join(
                    Instrument,
                    and_(
                        Instrument.public_id == InstrumentUnderlyingMapping.instrument_public_id,
                        *where_active(Instrument, as_of),
                    ),
                )
                .join(
                    Symbol,
                    and_(
                        Symbol.public_id == Instrument.symbol_public_id,
                        *where_active(Symbol, as_of),
                    ),
                )
                .where(
                    InstrumentUnderlyingMapping.underlying_public_id == underlying_public_id,
                    *where_active(InstrumentUnderlyingMapping, as_of),
                )
                .order_by(Instrument.exchange, Symbol.native_symbol)
            )
            if relationship_types:
                stmt = stmt.where(
                    InstrumentUnderlyingMapping.relationship_type.in_(relationship_types)
                )
            result = await s.execute(stmt)
            return [
                InstrumentUnderlyingRow(
                    public_id=r.public_id,
                    instrument_public_id=r.instrument_public_id,
                    underlying_public_id=r.underlying_public_id,
                    relationship_type=r.relationship_type,
                    contract_family=r.contract_family,
                    native_symbol=r.native_symbol,
                    exchange=r.exchange,
                    asset_type=r.asset_type,
                    timestamp=r.timestamp,
                    session_id=r.session_id,
                    sequence_id=r.sequence_id,
                )
                for r in result.all()
            ]

    async def get_underlying_for_instrument(
        self,
        instrument_public_id: str,
        as_of: datetime,
    ) -> UnderlyingAssetRow | None:
        """Reverse lookup: which underlying does this instrument belong to?"""
        async with self.session() as s:
            result = await s.execute(
                select(
                    UnderlyingAsset.public_id,
                    UnderlyingAsset.ticker,
                    UnderlyingAsset.name,
                    UnderlyingAsset.asset_class,
                    UnderlyingAsset.sector,
                    UnderlyingAsset.description,
                    UnderlyingAsset.timestamp,
                    UnderlyingAsset.session_id,
                    UnderlyingAsset.sequence_id,
                )
                .join(
                    InstrumentUnderlyingMapping,
                    and_(
                        InstrumentUnderlyingMapping.underlying_public_id
                        == UnderlyingAsset.public_id,
                        *where_active(InstrumentUnderlyingMapping, as_of),
                    ),
                )
                .where(
                    InstrumentUnderlyingMapping.instrument_public_id == instrument_public_id,
                    *where_active(UnderlyingAsset, as_of),
                )
            )
            r = result.first()
            if r is None:
                return None
            return UnderlyingAssetRow(
                public_id=r.public_id,
                ticker=r.ticker,
                name=r.name,
                asset_class=r.asset_class,
                sector=r.sector,
                description=r.description,
                timestamp=r.timestamp,
                session_id=r.session_id,
                sequence_id=r.sequence_id,
                instrument_count=0,
            )

    async def get_related_instruments_for_symbol(
        self,
        exchange: str,
        native_symbol: str,
        as_of: datetime,
    ) -> tuple[UnderlyingAssetRow | None, list[InstrumentRelatedRow]]:
        """Resolve the underlying + every sibling instrument for a UI-selected symbol.

        Returns a ``(underlying, related_rows)`` tuple powering the
        ``GET /api/instruments/{exchange}/{native_symbol}/related``
        endpoint and the MarketData "related instruments" UI row.

        Resolution steps (all SCD2-active at ``as_of``):

        1. ``Symbol`` lookup by ``(native_symbol, exchange)``.
        2. ``Instrument`` lookup by ``Symbol.public_id``.
        3. ``InstrumentUnderlyingMapping`` for the resolved instrument
           returns the parent underlying.
        4. ``get_instruments_by_underlying`` returns every sibling
           (including the input row itself, with ``is_selected=True``).

        Returns ``(None, [])`` when any step misses — symbol unknown,
        instrument not provisioned, or no underlying mapping (orphan).
        The route handler distinguishes "unknown symbol" (404) from
        "orphan" (200 + empty groups) using a second lookup.
        """
        async with self.session() as s:
            symbol_row = (
                (
                    await s.execute(
                        select(Symbol.public_id)
                        .join(
                            SymbolAlias,
                            and_(
                                SymbolAlias.symbol_public_id == Symbol.public_id,
                                SymbolAlias.exchange == exchange,
                                *where_active(SymbolAlias, as_of),
                            ),
                        )
                        .where(
                            Symbol.native_symbol == native_symbol,
                            *where_active(Symbol, as_of),
                        )
                        .limit(1)
                    )
                )
                .scalars()
                .first()
            )
            if symbol_row is None:
                return None, []
            inst_row = (
                (
                    await s.execute(
                        select(Instrument.public_id)
                        .where(
                            Instrument.symbol_public_id == symbol_row,
                            Instrument.exchange == exchange,
                            *where_active(Instrument, as_of),
                        )
                        .limit(1)
                    )
                )
                .scalars()
                .first()
            )
            if inst_row is None:
                return None, []
        underlying = await self.get_underlying_for_instrument(inst_row, as_of)
        if underlying is None:
            return None, []
        siblings = await self.get_instruments_by_underlying(underlying["public_id"], as_of)
        related: list[InstrumentRelatedRow] = []
        for sib in siblings:
            related.append(
                InstrumentRelatedRow(
                    instrument_public_id=sib["instrument_public_id"],
                    native_symbol=sib["native_symbol"],
                    exchange=sib["exchange"],
                    relationship_type=sib["relationship_type"],
                    contract_family=sib["contract_family"],
                    asset_type=sib["asset_type"],
                    is_selected=(
                        sib["instrument_public_id"] == inst_row and sib["exchange"] == exchange
                    ),
                )
            )
        return underlying, related

    async def upsert_underlying_asset(
        self,
        ticker: str,
        name: dict[str, str] | str,
        asset_class: str,
        session_id: str,
        sequence_id: int,
        timestamp: datetime,
        sector: str | None = None,
        description: dict[str, str] | None = None,
    ) -> tuple[str, str]:
        """SCD2 upsert for an underlying asset."""
        description_json = cast(dict[str, JsonValue] | None, description)
        name_dict: dict[str, str] = {"en": name} if isinstance(name, str) else name
        name_json = cast(dict[str, JsonValue], name_dict)
        async with self.session() as s:
            existing = (
                (
                    await s.execute(
                        select(UnderlyingAsset)
                        .where(
                            UnderlyingAsset.ticker == ticker,
                            *where_active(UnderlyingAsset, timestamp),
                        )
                        .with_for_update()
                    )
                )
                .scalars()
                .first()
            )

            if existing is not None:
                changed = (
                    existing.name != name_json
                    or existing.asset_class != asset_class
                    or existing.sector != sector
                    or existing.description != description_json
                )
                if not changed:
                    return existing.public_id, "unchanged"

                await s.execute(
                    update(UnderlyingAsset)
                    .where(UnderlyingAsset.id == existing.id)
                    .values(known_to=timestamp)
                )
                new_row = UnderlyingAsset(
                    public_id=existing.public_id,
                    ticker=ticker,
                    name=name_json,
                    asset_class=asset_class,
                    sector=sector,
                    description=description_json,
                    session_id=session_id,
                    sequence_id=sequence_id,
                    timestamp=timestamp,
                    known_to=KNOWN_TO_MAX,
                )
                s.add(new_row)
                await s.commit()
                return existing.public_id, "updated"

            new_row = UnderlyingAsset(
                ticker=ticker,
                name=name_json,
                asset_class=asset_class,
                sector=sector,
                description=description_json,
                session_id=session_id,
                sequence_id=sequence_id,
                timestamp=timestamp,
                known_to=KNOWN_TO_MAX,
            )
            s.add(new_row)
            await s.commit()
            return new_row.public_id, "created"

    async def upsert_instrument_underlying_mapping(
        self,
        instrument_public_id: str,
        underlying_public_id: str,
        relationship_type: str,
        session_id: str,
        sequence_id: int,
        timestamp: datetime,
        contract_family: str | None = None,
    ) -> str:
        """SCD2 upsert for an instrument-underlying mapping."""
        async with self.session() as s:
            existing = (
                (
                    await s.execute(
                        select(InstrumentUnderlyingMapping)
                        .where(
                            InstrumentUnderlyingMapping.instrument_public_id
                            == instrument_public_id,
                            *where_active(InstrumentUnderlyingMapping, timestamp),
                        )
                        .with_for_update()
                    )
                )
                .scalars()
                .first()
            )

            if existing is not None:
                changed = (
                    existing.underlying_public_id != underlying_public_id
                    or existing.relationship_type != relationship_type
                    or existing.contract_family != contract_family
                )
                if not changed:
                    return "unchanged"

                await s.execute(
                    update(InstrumentUnderlyingMapping)
                    .where(InstrumentUnderlyingMapping.id == existing.id)
                    .values(known_to=timestamp)
                )
                new_row = InstrumentUnderlyingMapping(
                    public_id=existing.public_id,
                    instrument_public_id=instrument_public_id,
                    underlying_public_id=underlying_public_id,
                    relationship_type=relationship_type,
                    contract_family=contract_family,
                    session_id=session_id,
                    sequence_id=sequence_id,
                    timestamp=timestamp,
                    known_to=KNOWN_TO_MAX,
                )
                s.add(new_row)
                await s.commit()
                return "updated"

            new_row = InstrumentUnderlyingMapping(
                instrument_public_id=instrument_public_id,
                underlying_public_id=underlying_public_id,
                relationship_type=relationship_type,
                contract_family=contract_family,
                session_id=session_id,
                sequence_id=sequence_id,
                timestamp=timestamp,
                known_to=KNOWN_TO_MAX,
            )
            s.add(new_row)
            await s.commit()
            return "created"

    async def close_instrument_underlying_mapping(
        self,
        instrument_public_id: str,
        session_id: str,
        sequence_id: int,
        timestamp: datetime,
    ) -> bool:
        """Close active mapping for instrument."""
        async with self.session() as s:
            existing = (
                (
                    await s.execute(
                        select(InstrumentUnderlyingMapping)
                        .where(
                            InstrumentUnderlyingMapping.instrument_public_id
                            == instrument_public_id,
                            *where_active(InstrumentUnderlyingMapping, timestamp),
                        )
                        .with_for_update()
                    )
                )
                .scalars()
                .first()
            )
            if existing is None:
                return False
            await s.execute(
                update(InstrumentUnderlyingMapping)
                .where(InstrumentUnderlyingMapping.id == existing.id)
                .values(known_to=timestamp)
            )
            await s.commit()
            return True

