    async def close_position_cycle(
        self,
        cycle_public_id: str,
        closed_at: datetime,
        closing_command_public_id: str | None,
        bus_time: datetime,
        session_id: str,
        sequence_id: int,
    ) -> int | None:
        """SCD2 close-and-insert transitioning an open cycle to closed."""
        async with self.session() as s:
            existing = (
                (
                    await s.execute(
                        select(PositionCycle)
                        .where(
                            PositionCycle.public_id == cycle_public_id,
                            PositionCycle.status == "open",
                            *where_active(PositionCycle, bus_time),
                        )
                        .with_for_update()
                    )
                )
                .scalars()
                .first()
            )
            if existing is None:
                return None
            await s.execute(
                update(PositionCycle)
                .where(PositionCycle.id == existing.id)
                .values(known_to=bus_time)
            )
            new_row = PositionCycle(
                public_id=existing.public_id,
                instrument_public_id=existing.instrument_public_id,
                exchange=existing.exchange,
                mode=existing.mode,
                shard_key=existing.shard_key,
                wallet_public_id=existing.wallet_public_id,
                operator_public_id=existing.operator_public_id,
                direction=existing.direction,
                max_qty=existing.max_qty,
                status="closed",
                opened_at=existing.opened_at,
                closed_at=closed_at,
                opening_command_public_id=existing.opening_command_public_id,
                closing_command_public_id=closing_command_public_id,
                session_id=session_id,
                sequence_id=sequence_id,
                timestamp=bus_time,
            )
            s.add(new_row)
            await s.commit()
            await s.refresh(new_row)
            return new_row.id

    async def get_open_position_cycle(
        self,
        shard_key: str,
        as_of: datetime,
    ) -> PositionCycleRow | None:
        """Return the active open cycle for a shard at a point in time."""
        async with self.session() as s:
            stmt = select(PositionCycle).where(
                PositionCycle.shard_key == shard_key,
                PositionCycle.status == "open",
                *where_active(PositionCycle, as_of),
            )
            result = await s.execute(stmt)
            row = result.scalars().first()
            if row is None:
                return None
            return self._position_cycle_row_to_dict(row)

    async def get_open_position_cycles_for_shards(
        self,
        shard_keys: list[str],
        as_of: datetime,
    ) -> dict[str, PositionCycleRow]:
        """Batch-fetch open position cycles for many shards."""
        if not shard_keys:
            return {}
        async with self.session() as s:
            stmt = select(PositionCycle).where(
                PositionCycle.shard_key.in_(shard_keys),
                PositionCycle.status == "open",
                *where_active(PositionCycle, as_of),
            )
            result = await s.execute(stmt)
            return {
                row.shard_key: self._position_cycle_row_to_dict(row) for row in result.scalars()
            }

    async def get_position_cycle_by_public_id(
        self,
        cycle_public_id: str,
        as_of: datetime,
    ) -> PositionCycleRow | None:
        """Retrieve a position cycle by its public_id."""
        async with self.session() as s:
            stmt = select(PositionCycle).where(
                PositionCycle.public_id == cycle_public_id,
                *where_active(PositionCycle, as_of),
            )
            result = await s.execute(stmt)
            row = result.scalars().first()
            if row is None:
                return None
            return self._position_cycle_row_to_dict(row)

    async def get_position_cycle_statuses_by_public_ids(
        self,
        cycle_public_ids: list[str],
        as_of: datetime,
    ) -> dict[str, str]:
        """Return the active status of each given cycle public_id, chunked by IN-list."""
        if not cycle_public_ids:
            return {}
        result: dict[str, str] = {}
        async with self.session() as s:
            for offset in range(0, len(cycle_public_ids), _POSITION_CYCLE_LOOKUP_CHUNK_SIZE):
                chunk = cycle_public_ids[offset : offset + _POSITION_CYCLE_LOOKUP_CHUNK_SIZE]
                rows = (
                    (
                        await s.execute(
                            select(PositionCycle.public_id, PositionCycle.status).where(
                                PositionCycle.public_id.in_(chunk),
                                *where_active(PositionCycle, as_of),
                            )
                        )
                    )
                    .tuples()
                    .all()
                )
                result.update(rows)
        return result

    async def flip_position_cycle(
        self,
        close_cycle_public_id: str,
        new_open_row: PositionCycleInsertRow,
        bus_time: datetime,
        session_id: str,
        sequence_id: int,
    ) -> tuple[int, str]:
        """Atomically close one cycle and open another in a single transaction."""
        async with self.session() as s:
            existing = (
                (
                    await s.execute(
                        select(PositionCycle)
                        .where(
                            PositionCycle.public_id == close_cycle_public_id,
                            PositionCycle.status == "open",
                            *where_active(PositionCycle, bus_time),
                        )
                        .with_for_update()
                    )
                )
                .scalars()
                .first()
            )
            if existing is None:
                raise ValueError(
                    f"flip_position_cycle: no active open cycle found for "
                    f"public_id={close_cycle_public_id!r}"
                )
            new_shard_key = new_open_row["shard_key"]
            if existing.shard_key != new_shard_key:
                raise ValueError(
                    f"flip_position_cycle: shard_key mismatch "
                    f"existing={existing.shard_key!r} new={new_shard_key!r}"
                )
            await s.execute(
                update(PositionCycle)
                .where(PositionCycle.id == existing.id)
                .values(known_to=bus_time)
            )
            closed_row = PositionCycle(
                public_id=existing.public_id,
                instrument_public_id=existing.instrument_public_id,
                exchange=existing.exchange,
                mode=existing.mode,
                shard_key=existing.shard_key,
                wallet_public_id=existing.wallet_public_id,
                operator_public_id=existing.operator_public_id,
                direction=existing.direction,
                max_qty=existing.max_qty,
                status="closed",
                opened_at=existing.opened_at,
                closed_at=bus_time,
                opening_command_public_id=existing.opening_command_public_id,
                closing_command_public_id=new_open_row.get("opening_command_public_id"),
                session_id=session_id,
                sequence_id=sequence_id,
                timestamp=bus_time,
            )
            s.add(closed_row)
            opened_row = PositionCycle(
                instrument_public_id=new_open_row["instrument_public_id"],
                exchange=new_open_row["exchange"],
                mode=new_open_row["mode"],
                shard_key=new_shard_key,
                wallet_public_id=new_open_row["wallet_public_id"],
                operator_public_id=new_open_row.get("operator_public_id"),
                direction=new_open_row["direction"],
                max_qty=new_open_row["max_qty"],
                status="open",
                opened_at=new_open_row["opened_at"],
                closed_at=None,
                opening_command_public_id=new_open_row.get("opening_command_public_id"),
                closing_command_public_id=None,
                session_id=session_id,
                sequence_id=sequence_id,
                timestamp=bus_time,
            )
            s.add(opened_row)
            await s.commit()
            await s.refresh(opened_row)
            return opened_row.id, opened_row.public_id

    async def update_position_cycle_max_qty(
        self,
        cycle_public_id: str,
        new_max_qty: float,
        bus_time: datetime,
        session_id: str,
        sequence_id: int,
    ) -> int | None:
        """Monotonic SCD2 revision of a cycle's max_qty peak."""
        async with self.session() as s:
            existing = (
                (
                    await s.execute(
                        select(PositionCycle)
                        .where(
                            PositionCycle.public_id == cycle_public_id,
                            PositionCycle.status == "open",
                            *where_active(PositionCycle, bus_time),
                        )
                        .with_for_update()
                    )
                )
                .scalars()
                .first()
            )
            if existing is None:
                raise ValueError(
                    f"update_position_cycle_max_qty: no active open cycle found "
                    f"for public_id={cycle_public_id!r}"
                )
            if new_max_qty <= existing.max_qty:
                return None
            await s.execute(
                update(PositionCycle)
                .where(PositionCycle.id == existing.id)
                .values(known_to=bus_time)
            )
            new_row = PositionCycle(
                public_id=existing.public_id,
                instrument_public_id=existing.instrument_public_id,
                exchange=existing.exchange,
                mode=existing.mode,
                shard_key=existing.shard_key,
                wallet_public_id=existing.wallet_public_id,
                operator_public_id=existing.operator_public_id,
                direction=existing.direction,
                max_qty=new_max_qty,
                status=existing.status,
                opened_at=existing.opened_at,
                closed_at=existing.closed_at,
                opening_command_public_id=existing.opening_command_public_id,
                closing_command_public_id=existing.closing_command_public_id,
                session_id=session_id,
                sequence_id=sequence_id,
                timestamp=bus_time,
            )
            s.add(new_row)
            await s.commit()
            await s.refresh(new_row)
            return new_row.id

    async def get_all_open_position_cycles(
        self,
        as_of: datetime,
        opened_before: datetime | None = None,
    ) -> list[PositionCycleRow]:
        """Return all open position cycles, optionally filtered by age."""
        async with self.session() as s:
            conditions = [
                PositionCycle.status == "open",
                *where_active(PositionCycle, as_of),
            ]
            if opened_before is not None:
                conditions.append(PositionCycle.opened_at < opened_before)
            rows = (await s.execute(select(PositionCycle).where(*conditions))).scalars().all()
            return [self._position_cycle_row_to_dict(r) for r in rows]

    async def create_scope_grant(self, request: CreateScopeGrantRequest) -> ScopeGrantRow:
        """Create a new scope grant with advisory-locked overlap detection."""
        self._validate_scope_xor(request)
        timestamp = request["timestamp"]
        async with self.session() as s:
            await self._acquire_wallet_advisory_lock(s, request["wallet_public_id"])
            existing = await self._load_active_grants_for_wallet(
                s, request["wallet_public_id"], timestamp
            )
            conflict = await self._find_overlap(s, existing, request, timestamp)
            if conflict is not None:
                raise ScopeGrantConflictError(
                    wallet_public_id=request["wallet_public_id"],
                    conflicting_grant_public_id=conflict.public_id,
                    conflicting_operator_public_id=conflict.operator_public_id,
                    reason=(
                        f"existing {conflict.scope_kind}-scoped grant overlaps the "
                        f"requested {request['scope_kind']} scope"
                    ),
                )
            new_grant = WalletOperatorScopeGrant(
                operator_public_id=request["operator_public_id"],
                wallet_public_id=request["wallet_public_id"],
                granted_by_user_public_id=request["granted_by_user_public_id"],
                scope_kind=request["scope_kind"],
                underlying_public_id=request.get("underlying_public_id"),
                instrument_public_id=request.get("instrument_public_id"),
                note=request.get("note"),
                session_id=request["session_id"],
                sequence_id=request["sequence_id"],
                timestamp=timestamp,
                known_to=KNOWN_TO_MAX,
            )
            s.add(new_grant)
            try:
                await s.commit()
            except IntegrityError as exc:
                err_msg = str(exc.orig).lower() if exc.orig else ""
                if "unique" not in err_msg and "duplicate" not in err_msg:
                    raise
                raise ScopeGrantConflictError(
                    wallet_public_id=request["wallet_public_id"],
                    conflicting_grant_public_id="",
                    conflicting_operator_public_id=request["operator_public_id"],
                    reason="partial unique index fired during insert — a concurrent grant creation on the same scope already succeeded",
                ) from exc
            await s.refresh(new_grant)
            return self._row_from_grant(new_grant)

    async def list_active_scope_grants_for_wallet(
        self,
        wallet_public_id: str,
        as_of: datetime,
    ) -> list[ScopeGrantRow]:
        """Return all currently active scope grants on the wallet."""
        async with self.session() as s:
            grants = await self._load_active_grants_for_wallet(s, wallet_public_id, as_of)
            return [self._row_from_grant(g) for g in grants]

    async def list_grant_covered_instrument_public_ids(
        self,
        operator_public_id: str,
        wallet_public_id: str,
        as_of: datetime,
    ) -> set[str]:
        """Return covered instrument set for an operator on a wallet.

        Expands underlying-scoped grants to their current instrument set
        per the dynamic-scope rule.

        Returns an empty set when the operator has no active grants on the
        wallet OR when the operator has only underlying-scoped grants whose
        underlyings currently have zero active instrument mappings.
        """
        async with self.session() as s:
            result = await s.execute(
                select(
                    WalletOperatorScopeGrant.scope_kind,
                    WalletOperatorScopeGrant.underlying_public_id,
                    WalletOperatorScopeGrant.instrument_public_id,
                )
                .where(
                    WalletOperatorScopeGrant.wallet_public_id == wallet_public_id,
                    WalletOperatorScopeGrant.operator_public_id == operator_public_id,
                    *where_active(WalletOperatorScopeGrant, as_of),
                )
                .order_by(WalletOperatorScopeGrant.timestamp.asc())
            )
            refs = {
                self._scope_expansion_key(scope_kind, underlying_public_id, instrument_public_id)
                for scope_kind, underlying_public_id, instrument_public_id in result.all()
            }
            if not refs:
                return set()
            expanded = await self._expand_scope_refs_to_instruments(s, refs, as_of)
            covered: set[str] = set()
            for instrument_ids in expanded.values():
                covered.update(instrument_ids)
            return covered

    async def get_instrument_public_id_by_symbol(
        self,
        native_symbol: str,
        exchange: str,
        as_of: datetime,
    ) -> str | None:
        """Resolve a native symbol on a given exchange to its instrument public_id.

        Returns None when no active Instrument row exists for the
        ``(native_symbol, exchange)`` pair at ``as_of``. Used by the
        strategy permission check to map strategy ``outputs``
        (symbols) to the instrument set covered by an operator's grants.
        """
        async with self.session() as s:
            instrument = await self._resolve_active_instrument(
                s, native_symbol=native_symbol, exchange=exchange, as_of=as_of
            )
            return instrument.public_id if instrument is not None else None

    async def get_instrument_public_ids_by_symbols(
        self,
        native_symbols: set[str],
        exchange: str,
        as_of: datetime,
    ) -> dict[str, str]:
        """Resolve native symbols on an exchange to instrument public IDs.

        Args:
            native_symbols: Native symbol strings to resolve.
            exchange: Exchange name.
            as_of: Point-in-time for temporal query.

        Returns:
            Mapping from native symbol to active instrument public ID.
            Missing symbols and symbols without an active exchange
            instrument are omitted.
        """
        async with self.session() as s:
            s_ts, s_kt = where_active(Symbol, as_of)
            i_ts, i_kt = where_active(Instrument, as_of)
            result = await s.execute(
                select(Symbol.native_symbol, Instrument.public_id)
                .join(Instrument, Instrument.symbol_public_id == Symbol.public_id)
                .where(
                    Symbol.native_symbol.in_(tuple(native_symbols)),
                    Instrument.exchange == exchange,
                    s_ts,
                    s_kt,
                    i_ts,
                    i_kt,
                )
            )
            return dict(result.tuples().all())

    async def get_symbol_for_instrument(
        self,
        instrument_public_id: str,
        as_of: datetime,
    ) -> str | None:
        """Resolve an instrument public_id back to its native symbol.

        Single joined query over active ``Instrument`` + active ``Symbol``
        at ``as_of`` — both ``where_active`` predicates are combined into
        one SQL statement so the two rows are guaranteed to be from the
        same temporal snapshot (avoids the subtle read-skew that two
        sequential queries would expose under concurrent SCD2 writers).
        """
        async with self.session() as s:
            i_ts, i_kt = where_active(Instrument, as_of)
            s_ts, s_kt = where_active(Symbol, as_of)
            native = (
                await s.execute(
                    select(Symbol.native_symbol)
                    .join(Instrument, Instrument.symbol_public_id == Symbol.public_id)
                    .where(
                        Instrument.public_id == instrument_public_id,
                        i_ts,
                        i_kt,
                        s_ts,
                        s_kt,
                    )
                )
            ).scalar_one_or_none()
            return native

    async def handover_grant(
        self,
        from_grant_public_id: str,
        to_operator_public_id: str,
        granted_by_user_public_id: str,
        reason: str | None,
        session_id: str,
        sequence_id: int,
        timestamp: datetime,
    ) -> tuple[ScopeGrantRow, ScopeGrantRow]:
        """Atomic SCD2 close + insert handover."""
        async with self.session() as s:
            from_grant = (
                (
                    await s.execute(
                        select(WalletOperatorScopeGrant).where(
                            WalletOperatorScopeGrant.public_id == from_grant_public_id,
                            *where_active(WalletOperatorScopeGrant, timestamp),
                        )
                    )
                )
                .scalars()
                .first()
            )
            if from_grant is None:
                raise ScopeGrantNotFoundError(
                    f"active scope grant {from_grant_public_id} not found at {timestamp.isoformat()}"
                )
            if from_grant.operator_public_id == to_operator_public_id:
                raise ScopeGrantValidationError(
                    f"handover target operator {to_operator_public_id} is already the holder"
                )

            await self._acquire_wallet_advisory_lock(s, from_grant.wallet_public_id)

            destination = (
                (
                    await s.execute(
                        select(Operator).where(
                            Operator.public_id == to_operator_public_id,
                            *where_active(Operator, timestamp),
                        )
                    )
                )
                .scalars()
                .first()
            )
            if destination is None:
                raise ScopeGrantNotFoundError(
                    f"destination operator {to_operator_public_id} not found at {timestamp.isoformat()}"
                )

            await s.execute(
                update(WalletOperatorScopeGrant)
                .where(WalletOperatorScopeGrant.id == from_grant.id)
                .values(known_to=timestamp)
            )
            new_grant = WalletOperatorScopeGrant(
                operator_public_id=to_operator_public_id,
                wallet_public_id=from_grant.wallet_public_id,
                granted_by_user_public_id=granted_by_user_public_id,
                scope_kind=from_grant.scope_kind,
                underlying_public_id=from_grant.underlying_public_id,
                instrument_public_id=from_grant.instrument_public_id,
                note=reason,
                session_id=session_id,
                sequence_id=sequence_id,
                timestamp=timestamp,
                known_to=KNOWN_TO_MAX,
            )
            s.add(new_grant)
            try:
                await s.commit()
            except IntegrityError as exc:
                err_msg = str(exc.orig).lower() if exc.orig else ""
                if "unique" not in err_msg and "duplicate" not in err_msg:
                    raise
                raise ScopeGrantConflictError(
                    wallet_public_id=from_grant.wallet_public_id,
                    conflicting_grant_public_id=from_grant.public_id,
                    conflicting_operator_public_id=to_operator_public_id,
                    reason="concurrent handover detected by partial unique index",
                ) from exc
            await s.refresh(new_grant)

            closed_row = ScopeGrantRow(
                public_id=from_grant.public_id,
                operator_public_id=from_grant.operator_public_id,
                wallet_public_id=from_grant.wallet_public_id,
                granted_by_user_public_id=from_grant.granted_by_user_public_id,
                scope_kind=from_grant.scope_kind,
                underlying_public_id=from_grant.underlying_public_id,
                instrument_public_id=from_grant.instrument_public_id,
                note=from_grant.note,
                timestamp=from_grant.timestamp,
                known_to=timestamp,
                session_id=from_grant.session_id,
                sequence_id=from_grant.sequence_id,
            )
            return closed_row, self._row_from_grant(new_grant)

    async def list_scope_grant_instrument_pairs(
        self,
        operator_public_ids: list[str],
        as_of: datetime,
    ) -> set[tuple[str, str]]:
        """Project active grants held by operators to (exchange, native_symbol) pairs."""
        if not operator_public_ids:
            return set()
        async with self.session() as s:
            grants_result = await s.execute(
                select(WalletOperatorScopeGrant).where(
                    WalletOperatorScopeGrant.operator_public_id.in_(operator_public_ids),
                    *where_active(WalletOperatorScopeGrant, as_of),
                )
            )
            grants = grants_result.scalars().all()
            if not grants:
                return set()

            direct_instrument_ids: set[str] = set()
            underlying_ids: set[str] = set()
            for grant in grants:
                if grant.scope_kind == "instrument":
                    direct_instrument_ids.add(cast(str, grant.instrument_public_id))
                else:
                    underlying_ids.add(cast(str, grant.underlying_public_id))

            expanded_instrument_ids: set[str] = set(direct_instrument_ids)
            if underlying_ids:
                mapping_result = await s.execute(
                    select(InstrumentUnderlyingMapping.instrument_public_id).where(
                        InstrumentUnderlyingMapping.underlying_public_id.in_(underlying_ids),
                        *where_active(InstrumentUnderlyingMapping, as_of),
                    )
                )
                expanded_instrument_ids.update(row[0] for row in mapping_result.all())

            if not expanded_instrument_ids:
                return set()

            pairs_result = await s.execute(
                select(Instrument.exchange, Symbol.native_symbol)
                .select_from(Instrument)
                .join(Symbol, Instrument.symbol_public_id == Symbol.public_id)
                .where(
                    Instrument.public_id.in_(expanded_instrument_ids),
                    *where_active(Instrument, as_of),
                    *where_active(Symbol, as_of),
                )
            )
            return {(exchange, native_symbol) for exchange, native_symbol in pairs_result.all()}

    async def revoke_scope_grant(
        self,
        grant_public_id: str,
        revoked_by_user_public_id: str,
        revoked_at: datetime,
        reason: str | None,
    ) -> ScopeGrantRow:
        """Atomic SCD2 close (no replacement row) under per-wallet advisory lock."""
        del revoked_by_user_public_id, reason
        async with self.session() as s:
            grant = (
                (
                    await s.execute(
                        select(WalletOperatorScopeGrant).where(
                            WalletOperatorScopeGrant.public_id == grant_public_id,
                            *where_active(WalletOperatorScopeGrant, revoked_at),
                        )
                    )
                )
                .scalars()
                .first()
            )
            if grant is None:
                raise ScopeGrantNotFoundError(
                    f"active scope grant {grant_public_id} not found at {revoked_at.isoformat()}"
                )

            await self._acquire_wallet_advisory_lock(s, grant.wallet_public_id)

            result = await s.execute(
                update(WalletOperatorScopeGrant)
                .where(
                    WalletOperatorScopeGrant.id == grant.id,
                    *where_active(WalletOperatorScopeGrant, revoked_at),
                )
                .values(known_to=revoked_at)
            )
            if int(cast(Any, result).rowcount or 0) == 0:
                raise ScopeGrantNotFoundError(
                    f"active scope grant {grant_public_id} "
                    f"no longer active at {revoked_at.isoformat()} (concurrent mutation)"
                )
            await s.commit()

            return ScopeGrantRow(
                public_id=grant.public_id,
                operator_public_id=grant.operator_public_id,
                wallet_public_id=grant.wallet_public_id,
                granted_by_user_public_id=grant.granted_by_user_public_id,
                scope_kind=grant.scope_kind,
                underlying_public_id=grant.underlying_public_id,
                instrument_public_id=grant.instrument_public_id,
                note=grant.note,
                timestamp=grant.timestamp,
                known_to=revoked_at,
                session_id=grant.session_id,
                sequence_id=grant.sequence_id,
            )

    async def list_active_operators(self, as_of: datetime) -> list[OperatorRow]:
        """Return every active operator at the given bus time."""
        async with self.session() as s:
            result = await s.execute(
                select(Operator)
                .where(*where_active(Operator, as_of))
                .order_by(Operator.label.asc())
            )
            return [
                OperatorRow(
                    public_id=row.public_id,
                    label=row.label,
                    description=row.description,
                    timestamp=row.timestamp,
                    session_id=row.session_id,
                    sequence_id=row.sequence_id,
                )
                for row in result.scalars().all()
            ]

    async def get_active_user_public_id_by_username(
        self, username: str, as_of: datetime
    ) -> str | None:
        """Return the active user's public id for a username, or None.

        Excludes soft-deactivated users (``is_active`` False on an
        otherwise-active SCD2 row) so a deactivated account can never
        resolve a live scope reference.
        """
        async with self.session() as s:
            result = await s.execute(
                select(User.public_id).where(
                    User.username == username,
                    User.is_active.is_(True),
                    *where_active(User, as_of),
                )
            )
            return result.scalars().first()

    async def create_operator(
        self,
        label: str,
        description: str | None,
        session_id: str,
        sequence_id: int,
        timestamp: datetime,
    ) -> OperatorRow:
        """Insert a new active operator row."""
        async with self.session() as s:
            operator = Operator(
                label=label,
                description=description,
                session_id=session_id,
                sequence_id=sequence_id,
                timestamp=timestamp,
                known_to=KNOWN_TO_MAX,
            )
            s.add(operator)
            try:
                await s.commit()
            except IntegrityError as exc:
                err_msg = str(exc.orig).lower() if exc.orig else ""
                if "unique" not in err_msg and "duplicate" not in err_msg:
                    raise
                raise OperatorConflictError(
                    label=label,
                    reason="active operator with the same label already exists",
                ) from exc
            await s.refresh(operator)
            return OperatorRow(
                public_id=operator.public_id,
                label=operator.label,
                description=operator.description,
                timestamp=operator.timestamp,
                session_id=operator.session_id,
                sequence_id=operator.sequence_id,
            )

    @staticmethod
    def _wallet_row_from(wallet: Wallet) -> WalletRow:
        """Project a ``Wallet`` ORM instance to its ``WalletRow`` TypedDict."""
        return WalletRow(
            public_id=wallet.public_id,
            label=wallet.label,
            description=wallet.description,
            is_paper=bool(wallet.is_paper),
            timestamp=wallet.timestamp,
            session_id=wallet.session_id,
            sequence_id=wallet.sequence_id,
        )

    async def create_wallet(
        self,
        label: str,
        description: str | None,
        is_paper: bool,
        session_id: str,
        sequence_id: int,
        timestamp: datetime,
    ) -> WalletRow:
        """Insert a new active wallet row."""
        async with self.session() as s:
            wallet = Wallet(
                label=label,
                description=description,
                is_paper=is_paper,
                session_id=session_id,
                sequence_id=sequence_id,
                timestamp=timestamp,
                known_to=KNOWN_TO_MAX,
            )
            s.add(wallet)
            try:
                await s.commit()
            except IntegrityError as exc:
                err_msg = str(exc.orig).lower() if exc.orig else ""
                if "unique" not in err_msg and "duplicate" not in err_msg:
                    raise
                raise WalletConflictError(
                    label=label,
                    is_paper=is_paper,
                    reason="active wallet with the same (label, is_paper) already exists",
                ) from exc
            await s.refresh(wallet)
            return self._wallet_row_from(wallet)

    async def list_active_wallets(self, as_of: datetime) -> list[WalletRow]:
        """Return every active wallet at the given bus time."""
        async with self.session() as s:
            result = await s.execute(
                select(Wallet)
                .where(*where_active(Wallet, as_of))
                .order_by(Wallet.is_paper.asc(), Wallet.label.asc())
            )
            return [self._wallet_row_from(row) for row in result.scalars().all()]

    @staticmethod
    def _operator_scope_grant_wallet_predicate(
        operator_public_ids: list[str],
        as_of: datetime,
    ) -> ColumnElement[bool]:
        """Predicate matching wallets covered by an active operator scope grant.

        Sole definition of the trade-plane accessibility rule. Both
        ``list_accessible_wallets_for_operators`` and the read-plane union in
        ``list_readable_wallets_for_user`` compose this, so the two can never
        drift into disagreeing about what an operator grant makes visible.
        """
        return Wallet.public_id.in_(
            select(WalletOperatorScopeGrant.wallet_public_id)
            .where(
                WalletOperatorScopeGrant.operator_public_id.in_(operator_public_ids),
                *where_active(WalletOperatorScopeGrant, as_of),
            )
            .distinct()
        )

    @staticmethod
    def _user_read_grant_wallet_predicate(
        user_public_id: str,
        as_of: datetime,
    ) -> ColumnElement[bool]:
        """Predicate matching wallets the user holds an active read grant on."""
        return Wallet.public_id.in_(
            select(WalletUserReadGrant.wallet_public_id)
            .where(
                WalletUserReadGrant.user_public_id == user_public_id,
                *where_active(WalletUserReadGrant, as_of),
            )
            .distinct()
        )

    async def _list_wallets_matching(
        self,
        wallet_predicate: ColumnElement[bool],
        as_of: datetime,
    ) -> list[WalletRow]:
        """Return active wallets matching a predicate in the picker's order.

        Selecting FROM ``wallets`` with an ``IN`` predicate (rather than
        joining the grant tables) is what makes the result inherently
        de-duplicated: the active-unique ``ix_wallets_public_id`` admits one
        active row per logical wallet, so a wallet reachable through several
        grants — or through both visibility planes at once — is still one row.
        """
        async with self.session() as s:
            result = await s.execute(
                select(Wallet)
                .where(wallet_predicate, *where_active(Wallet, as_of))
                .order_by(Wallet.is_paper.asc(), Wallet.label.asc())
            )
            return [self._wallet_row_from(row) for row in result.scalars().all()]

    async def list_accessible_wallets_for_operators(
        self,
        operator_public_ids: list[str],
        as_of: datetime,
    ) -> list[WalletRow]:
        """Wallets covered by at least one active grant from the given operators."""
        if not operator_public_ids:
            return []
        return await self._list_wallets_matching(
            self._operator_scope_grant_wallet_predicate(operator_public_ids, as_of), as_of
        )

    async def list_readable_wallets_for_user(
        self,
        user_public_id: str,
        operator_public_ids: list[str],
        as_of: datetime,
    ) -> list[WalletRow]:
        """Union of the user's operator-scoped wallets and their read grants.

        Deliberately does NOT short-circuit on an empty operator list: the
        read-grant disjunct always participates, so a user with zero
        memberships still sees every wallet they were granted read access to.
        """
        predicates = [self._user_read_grant_wallet_predicate(user_public_id, as_of)]
        if operator_public_ids:
            predicates.append(
                self._operator_scope_grant_wallet_predicate(operator_public_ids, as_of)
            )
        return await self._list_wallets_matching(or_(*predicates), as_of)

    @staticmethod
    def _wallet_user_read_grant_row_from(
        grant: WalletUserReadGrant,
        known_to: datetime,
    ) -> WalletUserReadGrantRow:
        """Project a ``WalletUserReadGrant`` ORM row to its TypedDict.

        ``known_to`` is passed in rather than read off the instance so a
        just-closed row can be reported with the close time the UPDATE wrote,
        without re-reading the row or mutating the ORM object.
        """
        return WalletUserReadGrantRow(
            public_id=grant.public_id,
            user_public_id=grant.user_public_id,
            wallet_public_id=grant.wallet_public_id,
            granted_by_user_public_id=grant.granted_by_user_public_id,
            note=grant.note,
            timestamp=grant.timestamp,
            known_to=known_to,
            session_id=grant.session_id,
            sequence_id=grant.sequence_id,
        )

    async def grant_wallet_user_read_access(
        self,
        request: CreateWalletUserReadGrantRequest,
    ) -> WalletUserReadGrantRow:
        """Insert one active read grant, rejecting a duplicate active pair."""
        user_public_id = request["user_public_id"]
        wallet_public_id = request["wallet_public_id"]
        async with self.session() as s:
            existing = (
                (
                    await s.execute(
                        select(WalletUserReadGrant.public_id).where(
                            WalletUserReadGrant.user_public_id == user_public_id,
                            WalletUserReadGrant.wallet_public_id == wallet_public_id,
                            *where_active(WalletUserReadGrant, request["timestamp"]),
                        )
                    )
                )
                .scalars()
                .first()
            )
            if existing is not None:
                raise WalletUserReadGrantConflictError(
                    user_public_id=user_public_id,
                    wallet_public_id=wallet_public_id,
                    reason=f"active read grant {existing} already covers this pair",
                )
            grant = WalletUserReadGrant(
                user_public_id=user_public_id,
                wallet_public_id=wallet_public_id,
                granted_by_user_public_id=request["granted_by_user_public_id"],
                note=request["note"],
                session_id=request["session_id"],
                sequence_id=request["sequence_id"],
                timestamp=request["timestamp"],
                known_to=KNOWN_TO_MAX,
            )
            s.add(grant)
            try:
                await s.commit()
            except IntegrityError as exc:
                err_msg = str(exc.orig).lower() if exc.orig else ""
                if "unique" not in err_msg and "duplicate" not in err_msg:
                    raise
                raise WalletUserReadGrantConflictError(
                    user_public_id=user_public_id,
                    wallet_public_id=wallet_public_id,
                    reason="a concurrent writer holds an active read grant for this pair",
                ) from exc
            await s.refresh(grant)
            return self._wallet_user_read_grant_row_from(grant, grant.known_to)

    async def revoke_wallet_user_read_grant(
        self,
        user_public_id: str,
        wallet_public_id: str,
        revoked_at: datetime,
    ) -> WalletUserReadGrantRow:
        """SCD2-close the active read grant for one (user, wallet) pair."""
        async with self.session() as s:
            grant = (
                (
                    await s.execute(
                        select(WalletUserReadGrant).where(
                            WalletUserReadGrant.user_public_id == user_public_id,
                            WalletUserReadGrant.wallet_public_id == wallet_public_id,
                            *where_active(WalletUserReadGrant, revoked_at),
                        )
                    )
                )
                .scalars()
                .first()
            )
            if grant is None:
                raise WalletUserReadGrantNotFoundError(
                    f"no active wallet read grant for user={user_public_id} "
                    f"wallet={wallet_public_id} at {revoked_at.isoformat()}"
                )
            result = await s.execute(
                update(WalletUserReadGrant)
                .where(
                    WalletUserReadGrant.id == grant.id,
                    *where_active(WalletUserReadGrant, revoked_at),
                )
                .values(known_to=revoked_at)
            )
            if int(cast(Any, result).rowcount or 0) == 0:
                raise WalletUserReadGrantNotFoundError(
                    f"wallet read grant {grant.public_id} no longer active at "
                    f"{revoked_at.isoformat()} (concurrent mutation)"
                )
            await s.commit()
            return self._wallet_user_read_grant_row_from(grant, revoked_at)

    async def get_user_operator_memberships(
        self,
        user_public_id: str,
        as_of: datetime,
    ) -> list[UserOperatorMembershipRow]:
        """Return active operator memberships for a user."""
        async with self.session() as s:
            result = await s.execute(
                select(UserOperatorMembership)
                .where(
                    UserOperatorMembership.user_public_id == user_public_id,
                    *where_active(UserOperatorMembership, as_of),
                )
                .order_by(UserOperatorMembership.timestamp.asc())
            )
            return [
                UserOperatorMembershipRow(
                    public_id=row.public_id,
                    user_public_id=row.user_public_id,
                    operator_public_id=row.operator_public_id,
                    is_primary=bool(row.is_primary),
                    timestamp=row.timestamp,
                    session_id=row.session_id,
                    sequence_id=row.sequence_id,
                )
                for row in result.scalars().all()
            ]

    async def attach_viewer_to_desk(
        self, request: DeskMembershipAttach
    ) -> UserOperatorMembershipRow:
        """Attach an active human VIEWER to an active desk atomically."""
        async with self.session() as s:
            await self._begin_desk_membership_write(s)
            user = await self._load_desk_target_user(s, request, lock=True)
            decision_at = max(request.timestamp, datetime.now(UTC))
            await self._require_active_desk(s, request.operator_public_id, decision_at)
            memberships = await self._load_desk_memberships(
                s,
                user.public_id,
                decision_at,
                lock=True,
            )
            existing = next(
                (
                    row
                    for row in memberships
                    if row.operator_public_id == request.operator_public_id
                ),
                None,
            )
            if existing is not None:
                return self._user_operator_membership_row(existing)
            membership = UserOperatorMembership(
                user_public_id=user.public_id,
                operator_public_id=request.operator_public_id,
                is_primary=not memberships,
                timestamp=decision_at,
                session_id=request.session_id,
                sequence_id=request.sequence_id,
            )
            s.add(membership)
            await s.commit()
            await s.refresh(membership)
            return self._user_operator_membership_row(membership)

    async def list_human_desk_members(
        self,
        operator_public_id: str,
        as_of: datetime,
    ) -> list[DeskMemberRow]:
        """Return active human members of one active desk."""
        async with self.session() as s:
            desk_exists = (
                await s.execute(
                    select(Operator.id)
                    .where(
                        Operator.public_id == operator_public_id,
                        *where_active(Operator, as_of),
                    )
                    .limit(1)
                )
            ).scalar_one_or_none()
            if desk_exists is None:
                raise DeskMembershipNotFoundError("Active target desk not found")
            rows = (
                await s.execute(
                    select(User, UserOperatorMembership)
                    .join(
                        UserOperatorMembership,
                        UserOperatorMembership.user_public_id == User.public_id,
                    )
                    .where(
                        UserOperatorMembership.operator_public_id == operator_public_id,
                        User.role.in_(_HUMAN_DESK_MEMBER_ROLE_VALUES),
                        User.is_active.is_(True),
                        *where_active(User, as_of),
                        *where_active(UserOperatorMembership, as_of),
                    )
                    .order_by(User.username.asc(), User.public_id.asc())
                )
            ).all()
            return [self._desk_member_row(user, membership) for user, membership in rows]

    async def detach_viewer_from_desk(
        self,
        request: DeskMembershipDetach,
        revoke_authority: Callable[[str], Awaitable[None]],
    ) -> DeskMembershipDetachResult | None:
        """Detach a VIEWER without deadlocking SQLite credential revocation.

        PostgreSQL keeps its user and membership row locks while the external
        credential barrier runs. SQLite cannot do that because the callback
        writes through separate sessions: retaining either a read transaction
        or ``BEGIN IMMEDIATE`` across the callback would create a lock-upgrade
        failure or a writer deadlock. SQLite therefore validates first, closes
        that read transaction, runs the barrier, and then performs the complete
        membership decision under a fresh ``BEGIN IMMEDIATE`` transaction.

        Credential revocation is intentionally one-way. If the membership
        commit fails, SQLAlchemy rolls back every membership write while the
        already-revoked credentials stay revoked; the user can authenticate
        again and the caller can safely retry the idempotent detachment.
        """
        if self.dialect_name == "sqlite":
            return await self._detach_viewer_from_desk_sqlite(request, revoke_authority)
        async with self.session() as s:
            user = await self._load_desk_target_user(s, request, lock=True)
            decision_at = max(request.timestamp, datetime.now(UTC))
            await self._require_active_desk(s, request.operator_public_id, decision_at)
            memberships = await self._load_desk_memberships(
                s,
                user.public_id,
                decision_at,
                lock=True,
            )
            target = self._find_desk_membership(memberships, request.operator_public_id)
            if target is None:
                return None
            await revoke_authority(user.public_id)
            return await self._commit_desk_detach(
                s,
                request,
                _DeskDetachDecision(user, memberships, target, decision_at),
            )

    async def _detach_viewer_from_desk_sqlite(
        self,
        request: DeskMembershipDetach,
        revoke_authority: Callable[[str], Awaitable[None]],
    ) -> DeskMembershipDetachResult | None:
        """Run SQLite revocation between a closed preflight and serialized write."""
        async with self.session() as preflight_session:
            user = await self._load_desk_target_user(
                preflight_session,
                request,
                lock=False,
            )
            preflight_at = max(request.timestamp, datetime.now(UTC))
            await self._require_active_desk(
                preflight_session,
                request.operator_public_id,
                preflight_at,
            )
            memberships = await self._load_desk_memberships(
                preflight_session,
                user.public_id,
                preflight_at,
                lock=False,
            )
            target = self._find_desk_membership(
                memberships,
                request.operator_public_id,
            )
            if target is None:
                return None
            user_public_id = user.public_id
        await revoke_authority(user_public_id)
        async with self.session() as s:
            await self._begin_desk_membership_write(s)
            user = await self._load_desk_target_user(s, request, lock=True)
            decision_at = max(request.timestamp, datetime.now(UTC))
            await self._require_active_desk(s, request.operator_public_id, decision_at)
            memberships = await self._load_desk_memberships(
                s,
                user.public_id,
                decision_at,
                lock=True,
            )
            target = self._find_desk_membership(memberships, request.operator_public_id)
            if target is None:
                return None
            return await self._commit_desk_detach(
                s,
                request,
                _DeskDetachDecision(user, memberships, target, decision_at),
            )

    async def _commit_desk_detach(
        self,
        s: AsyncSession,
        request: DeskMembershipDetach,
        decision: _DeskDetachDecision,
    ) -> DeskMembershipDetachResult | None:
        """Close one locked membership, promote deterministically, and commit."""
        await s.execute(
            update(UserOperatorMembership)
            .where(
                UserOperatorMembership.id == decision.target.id,
                *where_active(UserOperatorMembership, decision.decision_at),
            )
            .values(known_to=decision.decision_at)
            .execution_options(synchronize_session=False)
        )
        promoted_operator_public_id: str | None = None
        if decision.target.is_primary:
            promotion = next(
                (
                    membership
                    for membership in decision.memberships
                    if membership.id != decision.target.id
                ),
                None,
            )
            if promotion is not None:
                await close_and_insert(
                    session=s,
                    model=UserOperatorMembership,
                    match_filters=[UserOperatorMembership.id == promotion.id],
                    new_values={
                        "user_public_id": promotion.user_public_id,
                        "operator_public_id": promotion.operator_public_id,
                        "is_primary": True,
                        "session_id": request.session_id,
                        "sequence_id": request.sequence_id,
                    },
                    bus_time=decision.decision_at,
                )
                promoted_operator_public_id = promotion.operator_public_id
        await s.commit()
        return DeskMembershipDetachResult(
            membership_public_id=decision.target.public_id,
            user_public_id=decision.user.public_id,
            username=decision.user.username,
            operator_public_id=request.operator_public_id,
            detached_at=decision.decision_at,
            promoted_operator_public_id=promoted_operator_public_id,
        )

    async def _begin_desk_membership_write(self, s: AsyncSession) -> None:
        """Reserve SQLite's writer slot before any membership decision read."""
        if self.dialect_name == "sqlite":
            await s.execute(text("BEGIN IMMEDIATE"))

    async def _load_desk_target_user(
        self,
        s: AsyncSession,
        request: DeskMembershipAttach | DeskMembershipDetach,
        *,
        lock: bool,
    ) -> User:
        """Load and validate the live human VIEWER targeted by one mutation."""
        as_of = max(request.timestamp, datetime.now(UTC))
        statement = select(User).where(
            User.username == request.username,
            User.is_active.is_(True),
            *where_active(User, as_of),
        )
        if lock:
            statement = statement.with_for_update()
        user = (await s.execute(statement)).scalars().first()
        if user is None:
            raise DeskMembershipNotFoundError("Active target user not found")
        if not _is_human_viewer_role(user.role):
            raise DeskMembershipTargetError(
                "Desk membership supports human VIEWER users only; "
                "AI delegate membership is managed by delegate lifecycle"
            )
        return user

    @staticmethod
    async def _require_active_desk(
        s: AsyncSession,
        operator_public_id: str,
        as_of: datetime,
    ) -> None:
        """Reject a mutation whose target desk is not active."""
        desk_exists = (
            await s.execute(
                select(Operator.id)
                .where(
                    Operator.public_id == operator_public_id,
                    *where_active(Operator, as_of),
                )
                .limit(1)
            )
        ).scalar_one_or_none()
        if desk_exists is None:
            raise DeskMembershipNotFoundError("Active target desk not found")

    @staticmethod
    async def _load_desk_memberships(
        s: AsyncSession,
        user_public_id: str,
        as_of: datetime,
        *,
        lock: bool,
    ) -> list[UserOperatorMembership]:
        """Load one user's active memberships in deterministic promotion order."""
        statement = (
            select(UserOperatorMembership)
            .where(
                UserOperatorMembership.user_public_id == user_public_id,
                *where_active(UserOperatorMembership, as_of),
            )
            .order_by(
                UserOperatorMembership.timestamp.asc(),
                UserOperatorMembership.public_id.asc(),
            )
        )
        if lock:
            statement = statement.with_for_update()
        return list((await s.execute(statement)).scalars().all())

    @staticmethod
    def _find_desk_membership(
        memberships: Sequence[UserOperatorMembership],
        operator_public_id: str,
    ) -> UserOperatorMembership | None:
        """Return one active membership for a desk, if present."""
        return next(
            (
                membership
                for membership in memberships
                if membership.operator_public_id == operator_public_id
            ),
            None,
        )

    @staticmethod
    def _user_operator_membership_row(
        membership: UserOperatorMembership,
    ) -> UserOperatorMembershipRow:
        """Project one membership model into the repository row contract."""
        return UserOperatorMembershipRow(
            public_id=membership.public_id,
            user_public_id=membership.user_public_id,
            operator_public_id=membership.operator_public_id,
            is_primary=bool(membership.is_primary),
            timestamp=membership.timestamp,
            session_id=membership.session_id,
            sequence_id=membership.sequence_id,
        )

    @staticmethod
    def _desk_member_row(
        user: User,
        membership: UserOperatorMembership,
    ) -> DeskMemberRow:
        """Project one active human membership into the directory contract."""
        return DeskMemberRow(
            membership_public_id=membership.public_id,
            user_public_id=user.public_id,
            operator_public_id=membership.operator_public_id,
            username=user.username,
            email=user.email,
            role=user.role,
            is_active=bool(user.is_active),
            created_at=user.created_at,
            default_language=user.default_language,
            user_timestamp=user.timestamp,
            user_session_id=user.session_id,
            user_sequence_id=user.sequence_id,
            is_primary=bool(membership.is_primary),
            attached_at=membership.timestamp,
        )

    async def get_active_credential(
        self,
        exchange: str,
        wallet_public_id: str,
        as_of: datetime,
    ) -> WalletCredentialRow | None:
        """Return the active wallet credential row or None.

        Alias UUID spellings are canonicalized before filtering; malformed
        wallet identities raise ``ValueError`` like credential writers.
        """
        wallet_public_id = _canonicalize_reconciliation_wallet_public_id(wallet_public_id)
        async with self.session() as s:
            result = await s.execute(
                select(WalletCredential).where(
                    WalletCredential.exchange == exchange.lower(),
                    WalletCredential.wallet_public_id == wallet_public_id,
                    *where_active(WalletCredential, as_of),
                )
            )
            row = result.scalars().first()
            if row is None:
                return None
            return self._credential_row_from(row)

    async def list_active_wallet_credentials(
        self,
        as_of: datetime,
    ) -> list[WalletCredentialRow]:
        """Return all active wallet credentials at ``as_of``.

        Ordered by ``(exchange, wallet_public_id)`` for deterministic
        spawner behaviour across boots.
        """
        async with self.session() as s:
            result = await s.execute(
                select(WalletCredential)
                .where(*where_active(WalletCredential, as_of))
                .order_by(WalletCredential.exchange, WalletCredential.wallet_public_id)
            )
            return [self._credential_row_from(row) for row in result.scalars().all()]

    async def resolve_wallet_public_id_by_short(
        self,
        wallet_short: str,
        as_of: datetime,
    ) -> str | None:
        """Resolve canonical or legacy wallet-short aliases at ``as_of``.

        Args:
            wallet_short: Twelve lowercase hex characters parsed from a
                persisted shard key's ``w{wallet_short}`` segment.
            as_of: Temporal read anchor for ``wallet_credentials``.

        Returns:
            Matching wallet public ID, or ``None`` when no active
            credential owns the short at ``as_of``.
        """
        async with self.session() as s:
            result = await s.execute(
                select(distinct(WalletCredential.wallet_public_id))
                .where(*where_active(WalletCredential, as_of))
                .order_by(WalletCredential.wallet_public_id)
            )
            wallet_public_ids = [row[0] for row in result.all()]
        return self._wallet_public_id_from_short(wallet_short, wallet_public_ids)

    @staticmethod
    def _wallet_public_id_from_short(
        wallet_short: str,
        wallet_public_ids: Sequence[str],
    ) -> str | None:
        """Resolve a short wallet alias from ordered wallet public IDs."""
        legacy_match: str | None = None
        for wallet_public_id in wallet_public_ids:
            if compute_wallet_short(wallet_public_id) == wallet_short:
                return wallet_public_id
            if (
                legacy_match is None
                and compute_legacy_wallet_short(wallet_public_id) == wallet_short
            ):
                legacy_match = wallet_public_id
        return legacy_match

    @staticmethod
    def _credential_row_from(cred: WalletCredential) -> WalletCredentialRow:
        """Project a ``WalletCredential`` ORM instance to its ``WalletCredentialRow``."""
        return WalletCredentialRow(
            public_id=cred.public_id,
            wallet_public_id=cred.wallet_public_id,
            exchange=cred.exchange,
            credential_type=cred.credential_type,
            encrypted_payload=cred.encrypted_payload,
            label=cred.label,
            timestamp=cred.timestamp,
            session_id=cred.session_id,
            sequence_id=cred.sequence_id,
        )

    @staticmethod
    def _validate_wallet_credential_reconciliation_method(
        normalized_exchange: str,
        credential_type: str,
        reconciliation_method: str,
    ) -> bool:
        """Validate classification and return whether the credential is paper."""
        paper_credential = (
            normalized_exchange == ExchangeEnum.PAPER.value or credential_type == "paper"
        )
        if paper_credential and reconciliation_method != "unclassified":
            raise ValueError("paper credentials cannot have a reconciliation method config")
        if (
            not paper_credential
            and reconciliation_method
            not in _PORTFOLIO_REAL_RECONCILIATION_METHODS | {"unclassified"}
        ):
            raise ValueError("credential reconciliation method is invalid")
        return paper_credential

    async def _require_no_active_credential_method_config(
        self,
        s: AsyncSession,
        wallet_public_id: str,
        normalized_exchange: str,
    ) -> None:
        """Reject an unclassified credential when a real method is active."""
        existing_config = await self._load_active_portfolio_reconciliation_method_config(
            s,
            wallet_public_id,
            normalized_exchange,
            "live",
            lock=True,
        )
        if existing_config is not None:
            raise ReconciliationMethodImmutableError(
                "unclassified credential conflicts with active method config"
            )

    async def get_active_credential_by_id(
        self,
        credential_public_id: str,
        as_of: datetime,
    ) -> WalletCredentialRow | None:
        """Return the active credential row by its ``public_id``."""
        async with self.session() as s:
            result = await s.execute(
                select(WalletCredential).where(
                    WalletCredential.public_id == credential_public_id,
                    *where_active(WalletCredential, as_of),
                )
            )
            row = result.scalars().first()
            if row is None:
                return None
            return self._credential_row_from(row)

    async def create_wallet_credential(
        self,
        wallet_public_id: str,
        exchange: str,
        credential_type: str,
        encrypted_payload: str,
        label: str | None,
        session_id: str,
        sequence_id: int,
        timestamp: datetime,
        reconciliation_method: str,
    ) -> WalletCredentialRow:
        """Atomically insert a credential and its operator classification."""
        wallet_public_id = _canonicalize_reconciliation_wallet_public_id(wallet_public_id)
        normalized_exchange = exchange.lower()
        paper_credential = self._validate_wallet_credential_reconciliation_method(
            normalized_exchange,
            credential_type,
            reconciliation_method,
        )
        identity = (wallet_public_id, normalized_exchange, "live")
        process_lock = self._portfolio_reconciliation_locks.setdefault(identity, asyncio.Lock())
        async with process_lock, self.session() as s:
            await self._begin_portfolio_reconciliation_write(s)
            await self._acquire_wallet_advisory_lock(s, wallet_public_id)
            await self._require_active_portfolio_wallet(s, wallet_public_id)
            if not paper_credential and reconciliation_method == "unclassified":
                await self._require_no_active_credential_method_config(
                    s,
                    wallet_public_id,
                    normalized_exchange,
                )
            cred = WalletCredential(
                wallet_public_id=wallet_public_id,
                exchange=normalized_exchange,
                credential_type=credential_type,
                encrypted_payload=encrypted_payload,
                label=label,
                session_id=session_id,
                sequence_id=sequence_id,
                timestamp=timestamp,
                known_to=KNOWN_TO_MAX,
            )
            s.add(cred)
            if reconciliation_method in _PORTFOLIO_REAL_RECONCILIATION_METHODS:
                await self._set_portfolio_reconciliation_method_config_locked(
                    s,
                    wallet_public_id,
                    normalized_exchange,
                    "live",
                    reconciliation_method,
                    session_id,
                    sequence_id,
                    timestamp,
                )
            try:
                await s.commit()
            except IntegrityError as exc:
                err_msg = str(exc.orig).lower() if exc.orig else ""
                if "unique" not in err_msg and "duplicate" not in err_msg:
                    raise
                raise CredentialConflictError(
                    wallet_public_id=wallet_public_id,
                    exchange=exchange,
                    reason="active credential for (wallet, exchange) already exists",
                ) from exc
            await s.refresh(cred)
            return self._credential_row_from(cred)

    async def rotate_wallet_credential(
        self,
        credential_public_id: str,
        encrypted_payload: str,
        label: str | None,
        session_id: str,
        sequence_id: int,
        timestamp: datetime,
    ) -> WalletCredentialRow:
        """SCD2 close + insert rotation of a wallet credential."""
        async with self.session() as s:
            existing = (
                (
                    await s.execute(
                        select(WalletCredential).where(
                            WalletCredential.public_id == credential_public_id,
                            *where_active(WalletCredential, timestamp),
                        )
                    )
                )
                .scalars()
                .first()
            )
            if existing is None:
                raise CredentialNotFoundError(
                    f"active credential {credential_public_id} not found at {timestamp.isoformat()}"
                )
            await s.execute(
                update(WalletCredential)
                .where(WalletCredential.id == existing.id)
                .values(known_to=timestamp)
            )
            new_cred = WalletCredential(
                wallet_public_id=existing.wallet_public_id,
                exchange=existing.exchange,
                credential_type=existing.credential_type,
                encrypted_payload=encrypted_payload,
                label=label if label is not None else existing.label,
                session_id=session_id,
                sequence_id=sequence_id,
                timestamp=timestamp,
                known_to=KNOWN_TO_MAX,
            )
            s.add(new_cred)
            await s.commit()
            await s.refresh(new_cred)
            return self._credential_row_from(new_cred)

    async def list_wallet_credentials_for_wallet(
        self,
        wallet_public_id: str,
        as_of: datetime,
    ) -> list[WalletCredentialRow]:
        """Return active credentials on one canonicalized wallet at ``as_of``.

        Alias UUID spellings are canonicalized before filtering; malformed
        wallet identities raise ``ValueError`` like credential writers.
        """
        wallet_public_id = _canonicalize_reconciliation_wallet_public_id(wallet_public_id)
        async with self.session() as s:
            result = await s.execute(
                select(WalletCredential)
                .where(
                    WalletCredential.wallet_public_id == wallet_public_id,
                    *where_active(WalletCredential, as_of),
                )
                .order_by(WalletCredential.exchange)
            )
            return [self._credential_row_from(row) for row in result.scalars().all()]

