    @staticmethod
    async def _close_active_user_alert_default(
        s: AsyncSession,
        existing: UserAlertDefault | None,
        timestamp: datetime,
    ) -> Exception | None:
        """Close the existing active default row when one was found."""
        if existing is None:
            return None
        close_result = await s.execute(
            update(UserAlertDefault)
            .where(
                UserAlertDefault.id == existing.id,
                UserAlertDefault.known_to == KNOWN_TO_MAX,
            )
            .values(known_to=timestamp)
            .execution_options(synchronize_session=False)
        )
        if SQLAlchemyRepository._affected_rows(close_result) > 0:
            return None
        await s.rollback()
        return RuntimeError(
            "upsert_user_alert_default close-race: active row"
            " closed by competitor between SELECT and UPDATE."
        )

    async def _try_upsert_user_alert_default(
        self,
        row: UserAlertDefaultUpsertRow,
    ) -> _UserAlertDefaultAttemptResult:
        """Run one retryable user default upsert attempt."""
        async with self.session() as s:
            existing = (
                await s.execute(self._active_user_alert_default_query(row))
            ).scalar_one_or_none()
            values = self._user_alert_default_values(row, existing)
            close_error = await self._close_active_user_alert_default(
                s,
                existing,
                row["timestamp"],
            )
            if close_error is not None:
                return _UserAlertDefaultAttemptResult(public_id=values.public_id, error=close_error)
            s.add(self._build_user_alert_default(row, values))
            return _UserAlertDefaultAttemptResult(
                public_id=values.public_id,
                error=await self._commit_write_attempt(s),
            )

    async def upsert_user_alert_default(self, row: UserAlertDefaultUpsertRow) -> str:
        """Atomic SCD2 close + insert on (user, alert_type) default.

        Concurrent same-key upserts converge idempotently via the same
        atomic-close + IntegrityError-retry pattern as
        ``upsert_notification_device``.

        Returns:
            The stable ``public_id`` of the now-active row. Reused
            across SCD2 versions when an active row already existed
            for this ``(user, alert_type)`` tuple; freshly minted on
            the first write.
        """
        max_attempts = 20
        last_error: Exception = RuntimeError("upsert_user_alert_default: retry budget exhausted.")
        for _attempt in range(max_attempts):
            result = await self._try_upsert_user_alert_default(row)
            if result.error is None:
                return result.public_id
            last_error = result.error
        logger.warning(
            "upsert_user_alert_default: sustained contention exhausted"
            " {max_attempts}-attempt retry budget on"
            " (user={u}, alert_type={at}); raising last_error={err}",
            max_attempts=max_attempts,
            u=row["user_public_id"],
            at=row["alert_type"],
            err=type(last_error).__name__,
        )
        raise last_error

    @staticmethod
    def _build_alert_event(row: AlertEventInsertRow, public_id: str) -> AlertEvent:
        """Build one ORM alert-event row from the typed insert boundary."""
        return AlertEvent(
            public_id=public_id,
            session_id=row["session_id"],
            sequence_id=row["sequence_id"],
            timestamp=row["timestamp"],
            known_to=row.get("known_to", KNOWN_TO_MAX),
            user_public_id=row["user_public_id"],
            operator_public_id=row.get("operator_public_id"),
            wallet_public_id=row.get("wallet_public_id"),
            alert_type=row["alert_type"],
            priority=row["priority"],
            is_safety_critical=row.get("is_safety_critical", False),
            title=row["title"],
            body=row["body"],
            payload=row.get("payload"),
            dedup_key=row.get("dedup_key"),
            thread_key=row.get("thread_key"),
            source_topic=row.get("source_topic"),
        )

    async def _acquire_alert_event_dedup_lock(
        self,
        s: AsyncSession,
        user_public_id: str,
        dedup_key: str,
    ) -> None:
        """Serialize one alert dedup identity for the current transaction.

        PostgreSQL uses a transaction-scoped advisory lock shared by every
        sidecar process. SQLite obtains its database writer lock before the
        existence read so separate repository instances cannot both observe a
        miss.

        Args:
            s: Open transaction session.
            user_public_id: Alert recipient identity.
            dedup_key: Logical event identity minted by the rule.

        Raises:
            NotImplementedError: If the repository dialect is unsupported.
        """
        identity = f"{user_public_id}\x1f{dedup_key}"
        if self.dialect_name == "postgresql":
            await s.execute(
                text("SELECT pg_advisory_xact_lock(hashtext(:identity))"),
                {"identity": identity},
            )
            return
        if self.dialect_name == "sqlite":
            await s.execute(text("BEGIN IMMEDIATE"))
            return
        raise NotImplementedError(
            f"alert-event dedup lock not implemented for dialect={self.dialect_name}"
        )

    async def insert_alert_event(self, row: AlertEventInsertRow) -> str:
        """Insert a temporal (SCD2) alert_events row."""
        public_id = row.get("public_id") or str(uuid7())
        async with self.session() as s:
            s.add(self._build_alert_event(row, public_id))
            await s.commit()
            return public_id

    async def insert_alert_event_if_dedup_absent(
        self,
        row: AlertEventInsertRow,
    ) -> str | None:
        """Atomically insert an alert when its active dedup identity is absent."""
        dedup_key = row.get("dedup_key")
        if not dedup_key:
            raise ValueError("atomic alert-event insert requires dedup_key")
        user_public_id = row["user_public_id"]
        public_id = row.get("public_id") or str(uuid7())
        async with self.session() as s:
            await self._acquire_alert_event_dedup_lock(
                s,
                user_public_id,
                dedup_key,
            )
            already_exists = await s.scalar(
                select(
                    exists().where(
                        AlertEvent.user_public_id == user_public_id,
                        AlertEvent.dedup_key == dedup_key,
                        AlertEvent.known_to == KNOWN_TO_MAX,
                    )
                )
            )
            if already_exists:
                await s.rollback()
                return None
            s.add(self._build_alert_event(row, public_id))
            await s.commit()
            return public_id

    async def list_recent_alerts_for_user(
        self,
        user_public_id: str,
        limit: int,
        before: AlertListCursor | None,
    ) -> list[AlertEventRow]:
        """Active alert_events rows, newest-first, composite keyset paginated.

        When ``before`` is provided, applies the keyset predicate
        directly from the cursor's ``(timestamp, public_id)`` — no
        re-derivation from the current active row, so paging stays
        stable even if the anchor alert_event is later SCD2-revised.
        Order: ``(timestamp DESC, public_id DESC)``.
        """
        async with self.session() as s:
            stmt = select(AlertEvent).where(
                AlertEvent.user_public_id == user_public_id,
                AlertEvent.known_to == KNOWN_TO_MAX,
            )
            if before is not None:
                cursor_ts = before["timestamp"]
                cursor_pid = before["public_id"]
                stmt = stmt.where(
                    or_(
                        AlertEvent.timestamp < cursor_ts,
                        and_(
                            AlertEvent.timestamp == cursor_ts,
                            AlertEvent.public_id < cursor_pid,
                        ),
                    )
                )
            stmt = stmt.order_by(AlertEvent.timestamp.desc(), AlertEvent.public_id.desc()).limit(
                limit
            )
            result = await s.execute(stmt)
            return [self._alert_event_row_from(row) for row in result.scalars().all()]

    async def get_alert_event_by_public_id(self, public_id: str) -> AlertEventRow | None:
        """Active alert_event by public_id, None if missing or SCD2-closed."""
        async with self.session() as s:
            result = await s.execute(
                select(AlertEvent).where(
                    AlertEvent.public_id == public_id,
                    AlertEvent.known_to == KNOWN_TO_MAX,
                )
            )
            event_row = result.scalar_one_or_none()
            if event_row is None:
                return None
            return self._alert_event_row_from(event_row)

    async def get_alert_events_by_public_ids(
        self, public_ids: list[str]
    ) -> dict[str, AlertEventRow]:
        """Bulk active-alert-event lookup keyed by public_id.

        Replaces the per-row :meth:`get_alert_event_by_public_id`
        round-trip on the notify sidecar drain/retry hot path. One
        ``WHERE public_id IN (...)`` SELECT returns every active event
        for the batch; missing public_ids are absent from the returned
        dict (not mapped to None).
        """
        if not public_ids:
            return {}
        unique_ids = list(dict.fromkeys(public_ids))
        async with self.session() as s:
            result = await s.execute(
                select(AlertEvent).where(
                    AlertEvent.public_id.in_(unique_ids),
                    AlertEvent.known_to == KNOWN_TO_MAX,
                )
            )
            return {
                row.public_id: self._alert_event_row_from(row) for row in result.scalars().all()
            }

    async def list_alert_events_with_dedup_key(
        self,
        user_public_id: str,
        dedup_key: str,
        since: datetime,
    ) -> list[AlertEventRow]:
        """Dedup-window read: active AlertEvents for (user, dedup_key, >= since)."""
        async with self.session() as s:
            result = await s.execute(
                select(AlertEvent).where(
                    AlertEvent.user_public_id == user_public_id,
                    AlertEvent.dedup_key == dedup_key,
                    AlertEvent.timestamp >= since,
                    AlertEvent.known_to == KNOWN_TO_MAX,
                )
            )
            return [self._alert_event_row_from(row) for row in result.scalars().all()]

    async def get_default_languages_for_users(
        self, user_public_ids: list[str]
    ) -> dict[str, str | None]:
        """Bulk ``default_language`` lookup keyed by ``user_public_id``.

        One ``WHERE public_id IN (...)`` SELECT against the active
        ``users`` rows. Missing ``user_public_id``s map to ``None`` so
        the sidecar treats unknown users + users-with-no-preference
        identically (both fall back to English emission).
        """
        if not user_public_ids:
            return {}
        unique_ids = list(dict.fromkeys(user_public_ids))
        result: dict[str, str | None] = dict.fromkeys(unique_ids)
        async with self.session() as s:
            rows = await s.execute(
                select(User.public_id, User.default_language).where(
                    User.public_id.in_(unique_ids),
                    User.known_to == KNOWN_TO_MAX,
                )
            )
            result.update(dict(rows.tuples().all()))
        return result

    async def list_users_with_permission(self, permission: str) -> list[str]:
        """Active user public_ids whose role grants ``permission``.

        Role → permissions mapping is read from
        ``snapper.auth.domain.permissions.ROLE_PERMISSIONS``; the
        matched role names are then used to filter the ``users`` SCD2
        table on its ``role`` column. This is intentionally different
        from request authorization: token scope limits actions attempted
        through one credential, while notification fan-out applies to the
        principal across every concurrently held credential. A downscoped
        token therefore cannot suppress notifications, and this lookup
        never consults token claims. "Active" means BOTH the current
        SCD2 row (``known_to`` sentinel) AND ``is_active`` TRUE — a
        deactivated user keeps a current row but must not receive
        alert fan-out (they can no longer log in to act on it, and
        their devices should not be paged).
        """
        matching_roles: list[str] = [
            role.value
            for role, perms in ROLE_PERMISSIONS.items()
            if permission in {p.value for p in perms}
        ]
        if not matching_roles:
            return []
        async with self.session() as s:
            result = await s.execute(
                select(User.public_id)
                .where(
                    User.role.in_(matching_roles),
                    User.known_to == KNOWN_TO_MAX,
                    User.is_active.is_(True),
                )
                .order_by(User.timestamp.desc())
            )
            return list(result.scalars().all())

    async def insert_alert_delivery(self, row: AlertDeliveryInsertRow) -> str:
        """Insert a new SCD2 active version of an alert_delivery row.

        Scope columns (user/operator/wallet) MUST be set by the caller
        (denormalised from the source alert_event at queue time) — the
        repo does NOT rehydrate them from ``alert_events`` to avoid
        depending on the current SCD2 state of that table.
        """
        public_id = row.get("public_id") or str(uuid7())
        async with self.session() as s:
            delivery = AlertDelivery(
                public_id=public_id,
                session_id=row["session_id"],
                sequence_id=row["sequence_id"],
                timestamp=row["timestamp"],
                known_to=row.get("known_to", KNOWN_TO_MAX),
                alert_event_public_id=row["alert_event_public_id"],
                device_public_id=row["device_public_id"],
                user_public_id=row["user_public_id"],
                operator_public_id=row.get("operator_public_id"),
                wallet_public_id=row.get("wallet_public_id"),
                status=row["status"],
                attempt_count=row.get("attempt_count", 0),
                last_attempt_at=row.get("last_attempt_at"),
                next_attempt_at=row.get("next_attempt_at"),
                apns_id=row.get("apns_id"),
                error_reason=row.get("error_reason"),
                created_at=row["created_at"],
            )
            s.add(delivery)
            await s.commit()
            return public_id

    async def list_queued_deliveries_all(self) -> list[AlertDeliveryRow]:
        """Every active row with ``status='queued'`` (no time filter)."""
        async with self.session() as s:
            result = await s.execute(
                select(AlertDelivery)
                .where(
                    AlertDelivery.status == "queued",
                    AlertDelivery.known_to == KNOWN_TO_MAX,
                )
                .order_by(AlertDelivery.created_at.asc())
            )
            return [self._alert_delivery_row_from(r) for r in result.scalars().all()]

    async def get_delivery_by_public_id(self, public_id: str) -> AlertDeliveryRow | None:
        """Return the active SCD2 version of one delivery by public_id, or None.

        Indexed lookup replacing the per-row linear scan over
        :meth:`list_queued_deliveries_all` that the notify sidecar used
        on its hot retry path. Only the active SCD2 version is
        returned (``known_to == KNOWN_TO_MAX``).
        """
        async with self.session() as s:
            result = await s.execute(
                select(AlertDelivery).where(
                    AlertDelivery.public_id == public_id,
                    AlertDelivery.known_to == KNOWN_TO_MAX,
                )
            )
            row = result.scalar_one_or_none()
            if row is None:
                return None
            return self._alert_delivery_row_from(row)

    async def list_deliveries_ready_for_retry(self, now: datetime) -> list[AlertDeliveryRow]:
        """Active queued rows with ``next_attempt_at`` NULL or <= ``now``."""
        async with self.session() as s:
            result = await s.execute(
                select(AlertDelivery)
                .where(
                    AlertDelivery.status == "queued",
                    AlertDelivery.known_to == KNOWN_TO_MAX,
                    or_(
                        AlertDelivery.next_attempt_at.is_(None),
                        AlertDelivery.next_attempt_at <= now,
                    ),
                )
                .order_by(AlertDelivery.next_attempt_at.asc().nullsfirst())
            )
            return [self._alert_delivery_row_from(r) for r in result.scalars().all()]

    async def _scd2_transition_delivery(
        self,
        public_id: str,
        new_status: str,
        *,
        transition_at: datetime,
        session_id: str,
        sequence_id: int,
        apns_id: str | None = None,
        error_reason: str | None = None,
        attempt_count_override: int | None = None,
        next_attempt_at_override: datetime | None = None,
        last_attempt_at_override: datetime | None = None,
    ) -> bool:
        """Close the active ``alert_deliveries`` row and insert a new version.

        Only the ``queued`` active row may transition — every caller
        wants this guard (``mark_delivery_*``, ``cancel_*``,
        ``update_delivery_retry_schedule``), so the predicate is
        enforced unconditionally. Returns True when a transition
        happened, False when either:
          - no active row exists for ``public_id``;
          - the active row is no longer ``status='queued'`` (e.g. a
            previous ``mark_delivery_sent`` already ran — sequential
            idempotency);
          - another worker raced us to close this exact active row
            (conditional UPDATE rowcount==0 — concurrent idempotency).

        The close step is an atomic ``UPDATE ... WHERE id=:id AND
        known_to=MAX AND status='queued'`` — two concurrent workers
        both observing the queued row both attempt the UPDATE, but
        only one matches the post-lock predicate. The loser returns
        False without inserting a successor row, so the active-
        ``public_id`` partial unique index is never stressed.
        """
        async with self.session() as s:
            existing = (
                await s.execute(
                    select(AlertDelivery).where(
                        AlertDelivery.public_id == public_id,
                        AlertDelivery.known_to == KNOWN_TO_MAX,
                    )
                )
            ).scalar_one_or_none()
            if existing is None:
                return False
            if existing.status != "queued":
                return False
            close_result = await s.execute(
                update(AlertDelivery)
                .where(
                    AlertDelivery.id == existing.id,
                    AlertDelivery.known_to == KNOWN_TO_MAX,
                    AlertDelivery.status == "queued",
                )
                .values(known_to=transition_at)
                .execution_options(synchronize_session=False)
            )
            if int(cast(Any, close_result).rowcount or 0) == 0:
                await s.rollback()
                return False
            new_version = AlertDelivery(
                public_id=public_id,
                session_id=session_id,
                sequence_id=sequence_id,
                timestamp=transition_at,
                known_to=KNOWN_TO_MAX,
                alert_event_public_id=existing.alert_event_public_id,
                device_public_id=existing.device_public_id,
                user_public_id=existing.user_public_id,
                operator_public_id=existing.operator_public_id,
                wallet_public_id=existing.wallet_public_id,
                status=new_status,
                attempt_count=(
                    attempt_count_override
                    if attempt_count_override is not None
                    else existing.attempt_count
                ),
                last_attempt_at=(
                    last_attempt_at_override
                    if last_attempt_at_override is not None
                    else transition_at
                ),
                next_attempt_at=next_attempt_at_override,
                apns_id=apns_id if apns_id is not None else existing.apns_id,
                error_reason=error_reason if error_reason is not None else existing.error_reason,
                created_at=existing.created_at,
            )
            s.add(new_version)
            await s.commit()
            return True

    async def mark_delivery_sent(
        self,
        public_id: str,
        apns_id: str,
        *,
        transition_at: datetime,
        session_id: str,
        sequence_id: int,
    ) -> None:
        """SCD2 transition queued -> sent (optimistic guard on queued)."""
        await self._scd2_transition_delivery(
            public_id,
            "sent",
            transition_at=transition_at,
            session_id=session_id,
            sequence_id=sequence_id,
            apns_id=apns_id,
        )

    async def mark_delivery_failed(
        self,
        public_id: str,
        error_reason: str,
        *,
        transition_at: datetime,
        session_id: str,
        sequence_id: int,
    ) -> None:
        """SCD2 transition queued -> failed (terminal, give-up)."""
        await self._scd2_transition_delivery(
            public_id,
            "failed",
            transition_at=transition_at,
            session_id=session_id,
            sequence_id=sequence_id,
            error_reason=error_reason,
        )

    async def mark_delivery_unregistered(
        self,
        public_id: str,
        *,
        transition_at: datetime,
        session_id: str,
        sequence_id: int,
    ) -> None:
        """SCD2 transition queued -> unregistered (APNs 410)."""
        await self._scd2_transition_delivery(
            public_id,
            "unregistered",
            transition_at=transition_at,
            session_id=session_id,
            sequence_id=sequence_id,
        )

    async def mark_delivery_cancelled(
        self,
        public_id: str,
        reason: str,
        *,
        transition_at: datetime,
        session_id: str,
        sequence_id: int,
    ) -> None:
        """SCD2 transition queued -> cancelled_scope."""
        await self._scd2_transition_delivery(
            public_id,
            "cancelled_scope",
            transition_at=transition_at,
            session_id=session_id,
            sequence_id=sequence_id,
            error_reason=reason,
        )

    async def update_delivery_retry_schedule(
        self,
        public_id: str,
        attempt_count: int,
        next_attempt_at: datetime | None,
        error_reason: str | None,
        *,
        transition_at: datetime,
        session_id: str,
        sequence_id: int,
    ) -> bool:
        """Bump attempt_count + reschedule next retry via SCD2 close+insert.

        Called BEFORE the APNs HTTP call (crash-safety). Status
        stays ``queued`` across versions.

        Returns:
            True when the active queued row was transitioned; False
            when the row is no longer queued (e.g. cancelled mid-send
            by an admin.scope_revoked handler racing the retry loop —
            race guard). Callers use the False branch to
            short-circuit the APNs send.
        """
        return await self._scd2_transition_delivery(
            public_id,
            "queued",
            transition_at=transition_at,
            session_id=session_id,
            sequence_id=sequence_id,
            error_reason=error_reason,
            attempt_count_override=attempt_count,
            next_attempt_at_override=next_attempt_at,
        )

    async def list_users_with_operator_membership(
        self, operator_public_id: str, as_of: datetime
    ) -> list[str]:
        """User public_ids with an active membership in ``operator_public_id``."""
        async with self.session() as s:
            result = await s.execute(
                select(UserOperatorMembership.user_public_id)
                .where(
                    UserOperatorMembership.operator_public_id == operator_public_id,
                    *where_active(UserOperatorMembership, as_of),
                )
                .distinct()
            )
            return list(result.scalars().all())

    async def is_scope_grant_active(
        self,
        user_public_id: str,
        operator_public_id: str,
        wallet_public_id: str,
        as_of: datetime,
    ) -> bool:
        """True iff the (user, operator, wallet) scope is active at ``as_of``."""
        async with self.session() as s:
            grant_exists = (
                await s.execute(
                    select(WalletOperatorScopeGrant.id)
                    .where(
                        WalletOperatorScopeGrant.operator_public_id == operator_public_id,
                        WalletOperatorScopeGrant.wallet_public_id == wallet_public_id,
                        *where_active(WalletOperatorScopeGrant, as_of),
                    )
                    .limit(1)
                )
            ).scalar_one_or_none()
            if grant_exists is None:
                return False
            membership_exists = (
                await s.execute(
                    select(UserOperatorMembership.id)
                    .where(
                        UserOperatorMembership.user_public_id == user_public_id,
                        UserOperatorMembership.operator_public_id == operator_public_id,
                        *where_active(UserOperatorMembership, as_of),
                    )
                    .limit(1)
                )
            ).scalar_one_or_none()
            return membership_exists is not None

    async def is_operator_membership_active(
        self,
        user_public_id: str,
        operator_public_id: str,
        as_of: datetime,
    ) -> bool:
        """Return whether one user-to-desk membership is active at ``as_of``."""
        async with self.session() as s:
            membership_id = (
                await s.execute(
                    select(UserOperatorMembership.id)
                    .where(
                        UserOperatorMembership.user_public_id == user_public_id,
                        UserOperatorMembership.operator_public_id == operator_public_id,
                        *where_active(UserOperatorMembership, as_of),
                    )
                    .limit(1)
                )
            ).scalar_one_or_none()
            return membership_id is not None

    async def has_grant_for_delegate(
        self,
        *,
        delegate_public_id: str,
        wallet_public_id: str,
        instrument_public_id: str,
        as_of: datetime,
    ) -> bool:
        """AI delegate scope check with underlying expansion.

        Resolves ``ai_delegates.public_id -> users.public_id``,
        joins on ``UserOperatorMembership`` for operator memberships,
        then checks ``WalletOperatorScopeGrant`` for matching
        ``scope_kind='instrument'`` (direct match) OR
        ``scope_kind='underlying'`` expanded via
        ``InstrumentUnderlyingMapping``.
        """
        async with self.session() as s:
            delegate_user_id = (
                await s.execute(
                    select(AiDelegate.user_public_id).where(
                        AiDelegate.public_id == delegate_public_id
                    )
                )
            ).scalar_one_or_none()
            if delegate_user_id is None:
                return False

            operator_ids = (
                (
                    await s.execute(
                        select(UserOperatorMembership.operator_public_id).where(
                            UserOperatorMembership.user_public_id == delegate_user_id,
                            *where_active(UserOperatorMembership, as_of),
                        )
                    )
                )
                .scalars()
                .all()
            )
            if not operator_ids:
                return False

            direct_grant = (
                await s.execute(
                    select(WalletOperatorScopeGrant.id)
                    .where(
                        WalletOperatorScopeGrant.operator_public_id.in_(operator_ids),
                        WalletOperatorScopeGrant.wallet_public_id == wallet_public_id,
                        WalletOperatorScopeGrant.scope_kind == "instrument",
                        WalletOperatorScopeGrant.instrument_public_id == instrument_public_id,
                        *where_active(WalletOperatorScopeGrant, as_of),
                    )
                    .limit(1)
                )
            ).scalar_one_or_none()
            if direct_grant is not None:
                return True

            underlying_grant = (
                await s.execute(
                    select(WalletOperatorScopeGrant.id)
                    .join(
                        InstrumentUnderlyingMapping,
                        InstrumentUnderlyingMapping.underlying_public_id
                        == WalletOperatorScopeGrant.underlying_public_id,
                    )
                    .where(
                        WalletOperatorScopeGrant.operator_public_id.in_(operator_ids),
                        WalletOperatorScopeGrant.wallet_public_id == wallet_public_id,
                        WalletOperatorScopeGrant.scope_kind == "underlying",
                        InstrumentUnderlyingMapping.instrument_public_id == instrument_public_id,
                        *where_active(WalletOperatorScopeGrant, as_of),
                        *where_active(InstrumentUnderlyingMapping, as_of),
                    )
                    .limit(1)
                )
            ).scalar_one_or_none()
            return underlying_grant is not None

    async def cancel_pending_deliveries_for_scope(
        self,
        user_public_id: str,
        operator_public_id: str,
        wallet_public_id: str,
        *,
        transition_at: datetime,
        session_id: str,
        sequence_id: int,
    ) -> int:
        """Bulk-cancel queued deliveries by scope columns on the delivery row.

        Filters on the denormalised scope columns on ``alert_deliveries``
        itself — does NOT join ``alert_events`` — so SCD2 corrections
        on the source event cannot cause misses. Each matching active
        row is SCD2-closed and a new version with
        ``status='cancelled_scope'`` is inserted via the per-row atomic
        close+insert helper so a concurrent retry-loop transition on
        the same row is a race the caller can win / lose safely.
        """
        async with self.session() as s:
            rows = await self._select_queued_deliveries_by_scope(
                s,
                user_public_id=user_public_id,
                operator_public_id=operator_public_id,
                wallet_public_id=wallet_public_id,
            )
            transitioned = 0
            for existing in rows:
                if await self._atomic_transition_queued_delivery(
                    s,
                    existing=existing,
                    new_status="cancelled_scope",
                    error_reason="scope_revoked",
                    transition_at=transition_at,
                    session_id=session_id,
                    sequence_id=sequence_id,
                ):
                    transitioned += 1
            await s.commit()
            return transitioned

    async def cancel_pending_deliveries_for_user(
        self,
        user_public_id: str,
        *,
        transition_at: datetime,
        session_id: str,
        sequence_id: int,
        error_reason: str = "user_deactivated",
    ) -> int:
        """Bulk-cancel every queued delivery for one user (admin kill-switch).

        Same per-row atomic close+insert pattern as
        ``cancel_pending_deliveries_for_scope`` — a concurrent retry
        loop transition on the same row is safely skipped when our
        close UPDATE affects zero rows (the competitor already closed
        it). Without this guard, inserting a ``cancelled_scope``
        successor for a row the competitor just transitioned to
        ``sent`` / ``failed`` would collide on the partial unique
        index ``(public_id, known_to=KNOWN_TO_MAX)`` and raise
        ``IntegrityError`` out of the admin-topic dispatcher — which
        in turn would kill the sidecar's receive loop.
        """
        async with self.session() as s:
            rows = await self._select_queued_deliveries_by_user(s, user_public_id)
            transitioned = 0
            for existing in rows:
                if await self._atomic_transition_queued_delivery(
                    s,
                    existing=existing,
                    new_status="cancelled_scope",
                    error_reason=error_reason,
                    transition_at=transition_at,
                    session_id=session_id,
                    sequence_id=sequence_id,
                ):
                    transitioned += 1
            await s.commit()
            return transitioned

    async def cancel_pending_deliveries_for_membership(
        self,
        membership: tuple[str, str],
        *,
        detached_at: datetime,
        transition_at: datetime,
        session_id: str,
        sequence_id: int,
    ) -> int:
        """Cancel queued membership deliveries created no later than detachment."""
        user_public_id, operator_public_id = membership
        async with self.session() as s:
            rows = await self._select_queued_deliveries_by_membership(
                s,
                user_public_id=user_public_id,
                operator_public_id=operator_public_id,
                detached_at=detached_at,
            )
            transitioned = 0
            for existing in rows:
                if await self._atomic_transition_queued_delivery(
                    s,
                    existing=existing,
                    new_status="cancelled_scope",
                    error_reason="desk_membership_revoked",
                    transition_at=transition_at,
                    session_id=session_id,
                    sequence_id=sequence_id,
                ):
                    transitioned += 1
            await s.commit()
            return transitioned

    @staticmethod
    async def _select_queued_deliveries_by_scope(
        s: AsyncSession,
        *,
        user_public_id: str,
        operator_public_id: str,
        wallet_public_id: str,
    ) -> list[AlertDelivery]:
        """Snapshot active queued deliveries matching the scope triple."""
        result = await s.execute(
            select(AlertDelivery).where(
                AlertDelivery.status == "queued",
                AlertDelivery.known_to == KNOWN_TO_MAX,
                AlertDelivery.user_public_id == user_public_id,
                AlertDelivery.operator_public_id == operator_public_id,
                AlertDelivery.wallet_public_id == wallet_public_id,
            )
        )
        return list(result.scalars().all())

    @staticmethod
    async def _select_queued_deliveries_by_user(
        s: AsyncSession, user_public_id: str
    ) -> list[AlertDelivery]:
        """Snapshot active queued deliveries for the whole user."""
        result = await s.execute(
            select(AlertDelivery).where(
                AlertDelivery.status == "queued",
                AlertDelivery.known_to == KNOWN_TO_MAX,
                AlertDelivery.user_public_id == user_public_id,
            )
        )
        return list(result.scalars().all())

    @staticmethod
    async def _select_queued_deliveries_by_membership(
        s: AsyncSession,
        *,
        user_public_id: str,
        operator_public_id: str,
        detached_at: datetime,
    ) -> list[AlertDelivery]:
        """Snapshot membership deliveries queued through the detach boundary."""
        result = await s.execute(
            select(AlertDelivery).where(
                AlertDelivery.status == "queued",
                AlertDelivery.known_to == KNOWN_TO_MAX,
                AlertDelivery.user_public_id == user_public_id,
                AlertDelivery.operator_public_id == operator_public_id,
                AlertDelivery.created_at <= detached_at,
            )
        )
        return list(result.scalars().all())

    @staticmethod
    async def _atomic_transition_queued_delivery(
        s: AsyncSession,
        *,
        existing: AlertDelivery,
        new_status: str,
        error_reason: str,
        transition_at: datetime,
        session_id: str,
        sequence_id: int,
    ) -> bool:
        """Atomically close one queued delivery + insert its terminal successor.

        The close is a guarded UPDATE on ``(id, known_to=KNOWN_TO_MAX,
        status='queued')`` — ``rowcount == 0`` means a competing
        transition (retry-loop or parallel admin handler) closed the
        row first, so we skip the successor insert and return False
        without contending for the partial-unique
        ``(public_id, known_to=KNOWN_TO_MAX)`` index.
        """
        close_result = await s.execute(
            update(AlertDelivery)
            .where(
                AlertDelivery.id == existing.id,
                AlertDelivery.known_to == KNOWN_TO_MAX,
                AlertDelivery.status == "queued",
            )
            .values(known_to=transition_at)
            .execution_options(synchronize_session=False)
        )
        if int(cast(Any, close_result).rowcount or 0) == 0:
            return False
        successor = AlertDelivery(
            public_id=existing.public_id,
            session_id=session_id,
            sequence_id=sequence_id,
            timestamp=transition_at,
            known_to=KNOWN_TO_MAX,
            alert_event_public_id=existing.alert_event_public_id,
            device_public_id=existing.device_public_id,
            user_public_id=existing.user_public_id,
            operator_public_id=existing.operator_public_id,
            wallet_public_id=existing.wallet_public_id,
            status=new_status,
            attempt_count=existing.attempt_count,
            last_attempt_at=existing.last_attempt_at,
            next_attempt_at=None,
            apns_id=existing.apns_id,
            error_reason=error_reason,
            created_at=existing.created_at,
        )
        s.add(successor)
        return True

    async def count_deliveries_by_status(self) -> dict[str, int]:
        """Aggregate counts of active ``alert_deliveries`` rows per ``status``."""
        async with self.session() as s:
            result = await s.execute(
                select(AlertDelivery.status, func.count())
                .where(AlertDelivery.known_to == KNOWN_TO_MAX)
                .group_by(AlertDelivery.status)
            )
            return {status: int(count) for status, count in result.all()}

    @staticmethod
    def _ai_review_row_from_orm(row: AiReview) -> AiReviewRow:
        """Project an :class:`AiReview` ORM row into an :class:`AiReviewRow`."""
        return cast(
            AiReviewRow,
            {
                "public_id": row.public_id,
                "session_id": row.session_id,
                "sequence_id": row.sequence_id,
                "user_public_id": row.user_public_id,
                "operator_public_id": row.operator_public_id,
                "wallet_public_id": row.wallet_public_id,
                "instrument_public_id": row.instrument_public_id,
                "strategy_public_id": row.strategy_public_id,
                "selected_delegate_public_id": row.selected_delegate_public_id,
                "responding_delegate_public_id": row.responding_delegate_public_id,
                "resolution_mode": row.resolution_mode,
                "status": row.status,
                "signal_envelope": row.signal_envelope,
                "signal_snapshot_hash": row.signal_snapshot_hash,
                "instrument_metadata": row.instrument_metadata,
                "deadline": row.deadline,
                "fanout_after": row.fanout_after,
                "decision": row.decision,
                "rationale": row.rationale,
                "dispatch_version": row.dispatch_version,
                "counter_decremented_at": row.counter_decremented_at,
                "created_at": row.created_at,
                "updated_at": row.updated_at,
                "resolved_at": row.resolved_at,
            },
        )

    @staticmethod
    def _ai_review_cycle_transition_from_orm(
        cycle: PositionCycle,
        *,
        transition: str,
        occurred_at: datetime,
    ) -> AiReviewPositionCycleTransitionRow:
        """Project one lifecycle timestamp from an active position cycle.

        Args:
            cycle: Cycle version active at the aftermath temporal anchor.
            transition: Lifecycle transition name exposed by the projection.
            occurred_at: Retained cycle-open or cycle-close timestamp.

        Returns:
            Typed transition row with the cycle's active-as-of state.
        """
        return {
            "cycle_public_id": cycle.public_id,
            "transition": transition,
            "occurred_at": occurred_at,
            "instrument_public_id": cycle.instrument_public_id,
            "exchange": cycle.exchange,
            "mode": cycle.mode,
            "shard_key": cycle.shard_key,
            "wallet_public_id": cycle.wallet_public_id,
            "operator_public_id": cycle.operator_public_id,
            "direction": cycle.direction,
            "max_qty": cycle.max_qty,
            "status_at_as_of": cycle.status,
            "opening_command_public_id": cycle.opening_command_public_id,
            "closing_command_public_id": cycle.closing_command_public_id,
        }

    async def get_ai_review(self, review_public_id: str) -> AiReviewRow | None:
        """Fetch :class:`AiReview` row by public_id."""
        async with self.session() as s:
            row = (
                await s.execute(select(AiReview).where(AiReview.public_id == review_public_id))
            ).scalar_one_or_none()
            if row is None:
                return None
            return self._ai_review_row_from_orm(row)

    async def get_ai_review_aftermath(
        self,
        review_public_id: str,
        as_of: datetime,
    ) -> AiReviewAftermathRow | None:
        """Project exact-scope activity from review creation through ``as_of``.

        Orders, executions, cycles, instruments, symbols, and positions use
        the established temporal-active predicate at the same anchor. An
        execution's sentinel-current parent order supplies only immutable
        wallet and instrument lineage, while a separate active-as-of order
        supplies its optional display identifiers. Cycle lifecycle events are
        derived from the active-as-of row's retained ``opened_at`` and
        ``closed_at`` values so max-quantity revisions are not misreported as
        state transitions.

        Args:
            review_public_id: Review whose wallet and instrument key the read.
            as_of: Inclusive window end and temporal version anchor.

        Returns:
            A complete aftermath projection, or ``None`` when the review does
            not exist.
        """
        async with self.session() as s:
            review_orm = (
                await s.execute(select(AiReview).where(AiReview.public_id == review_public_id))
            ).scalar_one_or_none()
            if review_orm is None:
                return None
            review = self._ai_review_row_from_orm(review_orm)
            window_started_at = review["created_at"]
            wallet_public_id = review["wallet_public_id"]
            instrument_public_id = review["instrument_public_id"]

            order_query = (
                select(Order, Instrument, Symbol)
                .join(
                    Instrument,
                    and_(
                        Order.instrument_public_id == Instrument.public_id,
                        *where_active(Instrument, as_of),
                    ),
                )
                .join(
                    Symbol,
                    and_(
                        Instrument.symbol_public_id == Symbol.public_id,
                        *where_active(Symbol, as_of),
                    ),
                )
                .where(
                    Order.wallet_public_id == wallet_public_id,
                    Order.instrument_public_id == instrument_public_id,
                    Order.created_at >= window_started_at,
                    Order.created_at <= as_of,
                    *where_active(Order, as_of),
                )
                .order_by(Order.created_at.asc(), Order.public_id.asc())
            )
            order_rows = (await s.execute(order_query)).all()
            orders: list[OrderRow] = [
                {
                    "public_id": order.public_id,
                    "timestamp": order.timestamp,
                    "session_id": order.session_id,
                    "sequence_id": order.sequence_id,
                    "instrument": symbol.native_symbol,
                    "exchange": instrument.exchange,
                    "mode": order.mode,
                    "client_order_id": order.client_order_id or "",
                    "exchange_order_id": order.exchange_order_id,
                    "created_at": order.created_at,
                    "updated_at": order.updated_at,
                    "side": order.side,
                    "order_type": order.order_type,
                    "price": order.price,
                    "size": order.size,
                    "filled_size": order.filled_size,
                    "average_price": order.average_price,
                    "status": order.status,
                    "time_in_force": order.time_in_force,
                    "error": order.error,
                    "leverage": order.leverage,
                    "reduce_only": order.reduce_only,
                    "wallet_public_id": order.wallet_public_id,
                    "operator_public_id": order.operator_public_id,
                    "plan_public_id": order.plan_public_id,
                }
                for order, instrument, symbol in order_rows
            ]

            visible_order = aliased(Order)
            execution_query = (
                select(
                    Execution,
                    Order.instrument_public_id,
                    visible_order.client_order_id,
                    visible_order.exchange_order_id,
                    Symbol.native_symbol,
                )
                .join(
                    Order,
                    and_(
                        Execution.order_public_id == Order.public_id,
                        Order.known_to == KNOWN_TO_MAX,
                        Order.wallet_public_id == wallet_public_id,
                        Order.instrument_public_id == instrument_public_id,
                    ),
                )
                .outerjoin(
                    visible_order,
                    and_(
                        Execution.order_public_id == visible_order.public_id,
                        *where_active(visible_order, as_of),
                    ),
                )
                .outerjoin(
                    Instrument,
                    and_(
                        Order.instrument_public_id == Instrument.public_id,
                        *where_active(Instrument, as_of),
                    ),
                )
                .outerjoin(
                    Symbol,
                    and_(
                        Instrument.symbol_public_id == Symbol.public_id,
                        *where_active(Symbol, as_of),
                    ),
                )
                .where(
                    Execution.wallet_public_id == wallet_public_id,
                    Execution.timestamp >= window_started_at,
                    Execution.timestamp <= as_of,
                    *where_active(Execution, as_of),
                )
                .order_by(
                    Execution.timestamp.asc(),
                    Execution.exchange.asc(),
                    Execution.scope_sequence.asc(),
                    Execution.public_id.asc(),
                )
            )
            execution_rows = (await s.execute(execution_query)).all()
            executions: list[AiReviewAftermathExecutionRow] = [
                {
                    "public_id": execution.public_id,
                    "timestamp": execution.timestamp,
                    "session_id": execution.session_id,
                    "sequence_id": execution.sequence_id,
                    "trade_id": execution.trade_id,
                    "exec_id": execution.exec_id,
                    "order_public_id": execution.order_public_id,
                    "instrument_public_id": execution_instrument_public_id,
                    "exchange_order_id": exchange_order_id,
                    "client_order_id": client_order_id,
                    "instrument": native_symbol or execution_instrument_public_id,
                    "exchange": execution.exchange,
                    "mode": execution.mode,
                    "scope_sequence": execution.scope_sequence,
                    "side": execution.side,
                    "size": execution.size,
                    "price": execution.price,
                    "fee": execution.fee,
                    "fee_asset": execution.fee_asset,
                    "status": execution.status,
                    "executed_at": execution.executed_at or execution.timestamp,
                    "wallet_public_id": execution.wallet_public_id,
                    "operator_public_id": execution.operator_public_id,
                    "liquidity_role": execution.liquidity_role,
                    "price_decimal": execution.price_decimal,
                    "size_decimal": execution.size_decimal,
                    "fee_decimal": execution.fee_decimal,
                    "counter_amount_decimal": execution.counter_amount_decimal,
                    "numeric_provenance": execution.numeric_provenance,
                }
                for (
                    execution,
                    execution_instrument_public_id,
                    client_order_id,
                    exchange_order_id,
                    native_symbol,
                ) in execution_rows
            ]

            cycle_query = (
                select(PositionCycle)
                .where(
                    PositionCycle.wallet_public_id == wallet_public_id,
                    PositionCycle.instrument_public_id == instrument_public_id,
                    *where_active(PositionCycle, as_of),
                    or_(
                        and_(
                            PositionCycle.opened_at >= window_started_at,
                            PositionCycle.opened_at <= as_of,
                        ),
                        and_(
                            PositionCycle.closed_at.is_not(None),
                            PositionCycle.closed_at >= window_started_at,
                            PositionCycle.closed_at <= as_of,
                        ),
                    ),
                )
                .order_by(PositionCycle.opened_at.asc(), PositionCycle.public_id.asc())
            )
            cycle_rows = (await s.execute(cycle_query)).scalars().all()
            transitions: list[AiReviewPositionCycleTransitionRow] = []
            for cycle in cycle_rows:
                if window_started_at <= cycle.opened_at <= as_of:
                    transitions.append(
                        self._ai_review_cycle_transition_from_orm(
                            cycle,
                            transition="opened",
                            occurred_at=cycle.opened_at,
                        )
                    )
                if cycle.closed_at is not None and window_started_at <= cycle.closed_at <= as_of:
                    transition = "liquidated" if cycle.status == "liquidated" else "closed"
                    transitions.append(
                        self._ai_review_cycle_transition_from_orm(
                            cycle,
                            transition=transition,
                            occurred_at=cycle.closed_at,
                        )
                    )
            transition_order = {"closed": 0, "liquidated": 0, "opened": 1}
            transitions.sort(
                key=lambda transition: (
                    transition["occurred_at"],
                    transition_order[transition["transition"]],
                    transition["cycle_public_id"],
                )
            )

            other_cycle = aliased(PositionCycle)
            open_cycle_unambiguous = (
                select(
                    PositionCycle.instrument_public_id.label("instrument_public_id"),
                    PositionCycle.exchange.label("exchange"),
                    PositionCycle.mode.label("mode"),
                    PositionCycle.wallet_public_id.label("wallet_public_id"),
                    PositionCycle.public_id.label("position_cycle_public_id"),
                )
                .where(
                    PositionCycle.wallet_public_id == wallet_public_id,
                    PositionCycle.instrument_public_id == instrument_public_id,
                    PositionCycle.status == "open",
                    *where_active(PositionCycle, as_of),
                    ~(
                        select(1)
                        .select_from(other_cycle)
                        .where(
                            other_cycle.status == "open",
                            *where_active(other_cycle, as_of),
                            other_cycle.instrument_public_id == PositionCycle.instrument_public_id,
                            other_cycle.exchange == PositionCycle.exchange,
                            other_cycle.mode == PositionCycle.mode,
                            other_cycle.wallet_public_id == PositionCycle.wallet_public_id,
                            other_cycle.id != PositionCycle.id,
                        )
                        .exists()
                    ),
                )
                .subquery()
            )
            position_query = (
                select(
                    Position,
                    Instrument,
                    Symbol,
                    open_cycle_unambiguous.c.position_cycle_public_id,
                )
                .join(
                    Instrument,
                    and_(
                        Position.instrument_public_id == Instrument.public_id,
                        *where_active(Instrument, as_of),
                    ),
                )
                .join(
                    Symbol,
                    and_(
                        Instrument.symbol_public_id == Symbol.public_id,
                        *where_active(Symbol, as_of),
                    ),
                )
                .outerjoin(
                    open_cycle_unambiguous,
                    and_(
                        open_cycle_unambiguous.c.instrument_public_id == Instrument.public_id,
                        open_cycle_unambiguous.c.exchange == Instrument.exchange,
                        open_cycle_unambiguous.c.mode == Position.mode,
                        open_cycle_unambiguous.c.wallet_public_id == Position.wallet_public_id,
                    ),
                )
                .where(
                    Position.wallet_public_id == wallet_public_id,
                    Position.instrument_public_id == instrument_public_id,
                    *where_active(Position, as_of),
                )
                .order_by(Position.mode.asc(), Position.public_id.asc())
            )
            position_rows = (await s.execute(position_query)).all()
            current_positions: list[PositionRow] = [
                {
                    "public_id": position.public_id,
                    "timestamp": position.timestamp,
                    "session_id": position.session_id,
                    "sequence_id": position.sequence_id,
                    "instrument": symbol.native_symbol,
                    "instrument_public_id": instrument.public_id,
                    "exchange": instrument.exchange,
                    "mode": position.mode,
                    "quantity": position.quantity,
                    "average_price": position.average_price,
                    "unrealized_pnl": position.unrealized_pnl,
                    "realized_pnl": position.realized_pnl,
                    "mark_price": position.mark_price,
                    "marked_at": position.marked_at,
                    "source_venue_event_id": position.source_venue_event_id,
                    "position_cycle_public_id": cycle_public_id,
                    "wallet_public_id": position.wallet_public_id,
                }
                for position, instrument, symbol, cycle_public_id in position_rows
            ]
            return {
                "review": review,
                "window_started_at": window_started_at,
                "as_of": as_of,
                "orders": orders,
                "executions": executions,
                "position_cycle_transitions": transitions,
                "current_positions": current_positions,
            }

    async def list_ai_reviews(
        self,
        *,
        limit: int,
        status: str | None = None,
        wallet_public_id: str | None = None,
        strategy_public_id: str | None = None,
        operator_public_ids: list[str] | None = None,
    ) -> list[AiReviewRow]:
        """List :class:`AiReview` rows newest-first for operator audit.

        NOT delegate-keyed and includes terminal decided rows, so an
        operator/admin can see what the AI decided. Optional exact-match
        filters narrow by ``status`` / ``wallet_public_id`` /
        ``strategy_public_id``. ``operator_public_ids`` (when provided)
        restricts the snapshot to those operators' reviews — the route
        passes a non-admin caller's memberships so an operator cannot
        read another book's reviews; an empty list matches nothing.
        """
        async with self.session() as s:
            query = select(AiReview)
            if status is not None:
                query = query.where(AiReview.status == status)
            if wallet_public_id is not None:
                query = query.where(AiReview.wallet_public_id == wallet_public_id)
            if strategy_public_id is not None:
                query = query.where(AiReview.strategy_public_id == strategy_public_id)
            if operator_public_ids is not None:
                query = query.where(AiReview.operator_public_id.in_(operator_public_ids))
            query = query.order_by(AiReview.created_at.desc()).limit(limit)
            rows = (await s.execute(query)).scalars().all()
            return [self._ai_review_row_from_orm(row) for row in rows]

    async def insert_ai_review(self, row: AiReviewInsertRow) -> str:
        """INSERT new :class:`AiReview` row; returns ``public_id``."""
        async with self.session() as s:
            review = AiReview(**row)
            s.add(review)
            await s.commit()
            return review.public_id

    @staticmethod
    def _ai_research_round_row_from_orm(row: AiResearchRound) -> AiResearchRoundRow:
        """Project an AI-research round ORM row into its typed contract."""
        return {
            "public_id": row.public_id,
            "trigger": row.trigger,
            "status": row.status,
            "created_at": row.created_at,
            "updated_at": row.updated_at,
            "resolved_at": row.resolved_at,
        }

    @staticmethod
    def _market_view_source_row_from_orm(row: MarketViewSource) -> MarketViewSourceRow:
        """Project a source ORM row into its externally citable contract."""
        return {
            "public_id": row.public_id,
            "market_view_public_id": row.market_view_public_id,
            "ordinal": row.ordinal,
            "url": row.url,
            "title": row.title,
            "retrieved_at": row.retrieved_at,
        }

    @staticmethod
    def _market_view_next_events_from_orm(
        events: list[JsonObject],
    ) -> list[MarketViewNextEventRow]:
        """Decode JSON-safe event timestamps into typed datetimes."""
        return [
            {
                "when_utc": datetime.fromisoformat(cast(str, event["when_utc"])),
                "name": cast(str, event["name"]),
                "severity": cast(str, event["severity"]),
            }
            for event in events
        ]

    @classmethod
    def _market_view_row_from_orm(
        cls,
        row: MarketView,
        sources: list[MarketViewSourceRow],
    ) -> MarketViewRow:
        """Project one immutable view and its ordered source citations."""
        return {
            "public_id": row.public_id,
            "research_round_public_id": row.research_round_public_id,
            "trigger": row.trigger,
            "status": row.status,
            "as_of": row.as_of,
            "submitted_at": row.submitted_at,
            "valid_until": row.valid_until,
            "regime": row.regime,
            "bias": row.bias,
            "confidence": row.confidence,
            "horizon_hours": row.horizon_hours,
            "key_risks": row.key_risks,
            "next_events": cls._market_view_next_events_from_orm(row.next_events),
            "rationale": row.rationale,
            "sources": sources,
        }

    async def _load_market_view_sources(
        self,
        session: AsyncSession,
        market_view_public_id: str,
    ) -> list[MarketViewSourceRow]:
        """Load source citations in the author's stable submitted order."""
        rows = (
            (
                await session.execute(
                    select(MarketViewSource)
                    .where(MarketViewSource.market_view_public_id == market_view_public_id)
                    .order_by(MarketViewSource.ordinal.asc())
                )
            )
            .scalars()
            .all()
        )
        return [self._market_view_source_row_from_orm(row) for row in rows]

    async def _begin_ai_research_round_create_transaction(self, s: AsyncSession) -> None:
        """Serialize global pending-slot replacement across processes.

        PostgreSQL explicitly enters ``READ COMMITTED`` before acquiring a
        transaction-scoped advisory lock in a plane-specific keyspace. The
        UPDATE following a wait therefore receives a fresh snapshot and sees
        the prior creator's committed pending row. SQLite opens with ``BEGIN
        IMMEDIATE`` so competing connections serialize before either reads or
        writes the slot. Unsupported dialects fail closed.
        """
        dialect = self.dialect_name
        if dialect == "postgresql":
            await s.execute(text("SET TRANSACTION ISOLATION LEVEL READ COMMITTED"))
            await s.execute(
                text(
                    "SELECT pg_advisory_xact_lock("
                    "hashtext('ai_research'), hashtext('pending_round'))"
                )
            )
            return
        if dialect == "sqlite":
            await s.execute(text("BEGIN IMMEDIATE"))
            return
        raise NotImplementedError(
            f"AI-research round creation lock not implemented for dialect={dialect}"
        )

    async def create_ai_research_round(self, row: AiResearchRoundInsertRow) -> str:
        """Atomically replace the pending research round with a new one."""
        created_at = row["created_at"]
        public_id = row.get("public_id", str(uuid7()))
        async with self.session() as s:
            await self._begin_ai_research_round_create_transaction(s)
            await s.execute(
                update(AiResearchRound)
                .where(AiResearchRound.status == "pending")
                .values(
                    status="superseded",
                    updated_at=created_at,
                    resolved_at=created_at,
                )
            )
            research_round = AiResearchRound(
                public_id=public_id,
                trigger=row["trigger"],
                status="pending",
                created_at=created_at,
                updated_at=created_at,
                resolved_at=None,
            )
            s.add(research_round)
            await s.commit()
            return research_round.public_id

    async def get_ai_research_round(self, round_public_id: str) -> AiResearchRoundRow | None:
        """Fetch one AI-research round by public identifier."""
        async with self.session() as s:
            row = (
                await s.execute(
                    select(AiResearchRound).where(AiResearchRound.public_id == round_public_id)
                )
            ).scalar_one_or_none()
            if row is None:
                return None
            return self._ai_research_round_row_from_orm(row)

    async def transition_ai_research_round_status(
        self,
        round_public_id: str,
        *,
        expected_status: str,
        new_status: str,
        transitioned_at: datetime,
    ) -> bool:
        """CAS a pending research round into supersession or expiry."""
        if expected_status != "pending":
            raise ValueError("AI-research rounds may transition only from pending")
        if new_status not in _AI_RESEARCH_MANUAL_TERMINAL_STATUSES:
            raise ValueError("AI-research round target status must be superseded or expired")
        async with self.session() as s:
            transitioned_public_id = (
                await s.execute(
                    update(AiResearchRound)
                    .where(
                        AiResearchRound.public_id == round_public_id,
                        AiResearchRound.status == expected_status,
                    )
                    .values(
                        status=new_status,
                        updated_at=transitioned_at,
                        resolved_at=transitioned_at,
                    )
                    .returning(AiResearchRound.public_id)
                )
            ).scalar_one_or_none()
            await s.commit()
            return transitioned_public_id is not None

    async def insert_market_view(
        self,
        row: MarketViewInsertRow,
        sources: list[MarketViewSourceInsertRow],
        *,
        submitted_at: datetime,
    ) -> str:
        """Complete a pending round while inserting its immutable artifact."""
        if not sources:
            raise ValueError("market view requires at least one source")
        if len(row["rationale"].encode("utf-8")) > 2048:
            raise ValueError("market view rationale must not exceed 2048 UTF-8 bytes")
        async with self.session() as s:
            research_round = (
                await s.execute(
                    select(AiResearchRound)
                    .where(AiResearchRound.public_id == row["research_round_public_id"])
                    .with_for_update()
                )
            ).scalar_one_or_none()
            if research_round is None or research_round.status != "pending":
                raise ValueError("market view requires a pending AI-research round")

            market_view_public_id = str(uuid7())
            serialized_events: list[JsonObject] = [
                {
                    "when_utc": event["when_utc"].isoformat(),
                    "name": event["name"],
                    "severity": event["severity"],
                }
                for event in row["next_events"]
            ]
            market_view = MarketView(
                public_id=market_view_public_id,
                research_round_public_id=research_round.public_id,
                trigger=research_round.trigger,
                status="completed",
                as_of=row["as_of"],
                submitted_at=submitted_at,
                valid_until=row["valid_until"],
                regime=row["regime"],
                bias=row["bias"],
                confidence=row["confidence"],
                horizon_hours=row["horizon_hours"],
                key_risks=row["key_risks"],
                next_events=serialized_events,
                rationale=row["rationale"],
            )
            s.add(market_view)
            for ordinal, source in enumerate(sources):
                s.add(
                    MarketViewSource(
                        public_id=str(uuid7()),
                        market_view_public_id=market_view_public_id,
                        ordinal=ordinal,
                        url=source["url"],
                        title=source["title"],
                        retrieved_at=source["retrieved_at"],
                    )
                )
            research_round.status = "completed"
            research_round.updated_at = submitted_at
            research_round.resolved_at = submitted_at
            await s.commit()
            return market_view_public_id

    async def get_market_view(self, market_view_public_id: str) -> MarketViewRow | None:
        """Fetch one immutable view and its ordered sources."""
        async with self.session() as s:
            row = (
                await s.execute(
                    select(MarketView).where(MarketView.public_id == market_view_public_id)
                )
            ).scalar_one_or_none()
            if row is None:
                return None
            sources = await self._load_market_view_sources(s, row.public_id)
            return self._market_view_row_from_orm(row, sources)

    async def get_latest_market_view(self, *, replay_at: datetime) -> MarketViewRow | None:
        """Return the freshest unexpired artifact visible at replay time."""
        async with self.session() as s:
            row = (
                await s.execute(
                    select(MarketView)
                    .where(
                        MarketView.as_of <= replay_at,
                        MarketView.submitted_at <= replay_at,
                        MarketView.valid_until > replay_at,
                    )
                    .order_by(
                        MarketView.as_of.desc(),
                        MarketView.submitted_at.desc(),
                        MarketView.id.desc(),
                    )
                    .limit(1)
                )
            ).scalar_one_or_none()
            if row is None:
                return None
            sources = await self._load_market_view_sources(s, row.public_id)
            return self._market_view_row_from_orm(row, sources)

    async def get_market_view_source(self, source_public_id: str) -> MarketViewSourceRow | None:
        """Fetch one source citation by public identifier."""
        async with self.session() as s:
            row = (
                await s.execute(
                    select(MarketViewSource).where(MarketViewSource.public_id == source_public_id)
                )
            ).scalar_one_or_none()
            if row is None:
                return None
            return self._market_view_source_row_from_orm(row)

